css:
*{box-sizing:border-box;margin:0;padding:0}

body{font-family:Arial,sans-serif;font-size:11.5px;background:#f4f6fb;color:#202020}

.navbar{display:none;}
        .web-footer{display:none;}

.header{
  background:#fff;
  color:#0D2B4E;
  padding:12px 20px;
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:8px;
  border-bottom:1px solid #e5e7ef;
}

.header .h1{
  font-size:16px;
  font-weight:800;
  letter-spacing:.3px;
  color:#0D2B4E;
}

.header .sub{
  font-size:10px;
  color:#595959;
  margin-top:3px;
}

.header .right{
  text-align:right;
  font-size:10px;
  color:#595959;
}
.gold-bar{height:3px;background:#B8860B}

.main-nav{
  background:#fff;
  border-bottom:2px solid #B8860B;
  padding:10px 16px 0;
  display:flex;
  gap:10px;
  overflow:visible;
  flex-wrap:wrap;
}

.mnav{
  position:relative;
  padding:11px 18px;
  font-size:11.5px;
  font-weight:800;
  cursor:pointer;
  color:#595959;
  border:1px solid transparent;
  border-bottom:none;
  border-radius:10px 10px 0 0;
  white-space:nowrap;
  background:#f7f8fb;
  transition:.18s ease;
}

.mnav:hover{
  color:#0D2B4E;
  background:#EEF2FB;
  border-color:#d8deea;
}

.mnav.on{
  color:#fff;
  background:#0D2B4E;
  border-color:#0D2B4E;
  box-shadow:0 -2px 8px rgba(13,43,78,.16);
}

.mnav.on::after{
  content:"";
  position:absolute;
  left:0;
  right:0;
  bottom:-3px;
  height:4px;
  background:#B8860B;
}


.mnav .cnt{
  background:#C00000;
  color:#fff;
  font-size:8.5px;
  padding:1px 5px;
  border-radius:8px;
  margin-left:5px;
}

.mnav.on .cnt{
  background:#fff;
  color:#C00000;
}

.content{padding:16px 20px;max-width:1280px;margin:0 auto}
.mode{display:none}.mode.on{display:block}

label.lbl{font-size:9.5px;font-weight:700;color:#0D2B4E;display:block;margin-bottom:4px;text-transform:uppercase;letter-spacing:.3px}
input[type=text],input[type=date],input[type=number],input[type=tel],select,textarea{
  width:100%;padding:7px 9px;border:1.5px solid #d0d5e0;border-radius:6px;font-size:11.5px;
  font-family:Arial,sans-serif;color:#202020;background:#fff}
input,select{height:33px}
textarea{min-height:60px;resize:vertical;padding:8px}
input:focus,select:focus,textarea:focus{border-color:#0D2B4E;outline:none}
input:disabled,select:disabled{background:#f0f0f0;color:#8C8C8C;cursor:not-allowed}

.card{background:#fff;border:1px solid #dde3f0;border-radius:9px;margin-bottom:16px;overflow:hidden}
.card-hdr{background:#0D2B4E;color:#fff;padding:10px 14px;font-size:12.5px;font-weight:800;display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:6px}
.card-hdr .badge{background:#B8860B;color:#fff;font-size:9px;padding:2px 8px;border-radius:10px;font-weight:700}
.card-body{padding:16px}

.step-bar{display:flex;align-items:flex-start;margin-bottom:18px;padding:14px;background:#fff;border-radius:9px;overflow-x:auto}
.step{display:flex;flex-direction:column;align-items:center;flex:1;min-width:84px;position:relative}
.step:not(:last-child)::after{content:'';position:absolute;top:14px;left:58%;width:84%;height:2px;background:#ddd;z-index:0}
.step.done:not(:last-child)::after{background:#1E7A34}
.sdot{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;border:2px solid #ccc;background:#f0f0f0;color:#8C8C8C;z-index:1;position:relative}
.sdot.done{background:#1E7A34;border-color:#1E7A34;color:#fff}
.sdot.active{background:#0D2B4E;border-color:#0D2B4E;color:#fff}
.slbl{font-size:7.8px;color:#8C8C8C;margin-top:4px;text-align:center;line-height:1.2}
.slbl.active{color:#0D2B4E;font-weight:700}
.wpanel{display:none}.wpanel.on{display:block}

.btn{padding:9px 18px;border-radius:6px;font-size:12px;font-weight:700;cursor:pointer;border:none}
.btn-n{background:#0D2B4E;color:#fff}.btn-n:hover{background:#1a3f6e}
.btn-g{background:#1E7A34;color:#fff}.btn-g:hover{background:#155a27}
.btn-r{background:#C00000;color:#fff}
.btn-o{background:#C96A00;color:#fff}
.btn-gy{background:#f0f0f0;color:#595959;border:1px solid #ddd}
.btn-outline{background:#fff;color:#0D2B4E;border:1.5px solid #0D2B4E}
.btn-sm{padding:6px 12px;font-size:10.5px}
.btn:disabled{opacity:.4;cursor:not-allowed}

.two-col{display:grid;grid-template-columns:1fr 1fr;gap:14px}
.three-col{display:grid;grid-template-columns:1fr 1fr 1fr;gap:14px}
@media(max-width:800px){.two-col,.three-col{grid-template-columns:1fr}}
.field-block{margin-bottom:14px}

.notice{border-radius:7px;padding:11px 14px;margin:8px 0;font-size:10.8px}
.notice-blue{background:#E7ECF2;border-left:3px solid #0D2B4E}
.notice-green{background:#E8F5EC;border-left:3px solid #1E7A34}
.notice-red{background:#FBE9E7;border-left:3px solid #C00000}
.notice-gold{background:#FFF8E7;border-left:3px solid #B8860B}
.notice-orange{background:#FFF3E0;border-left:3px solid #C96A00}

.sec{font-size:11.5px;font-weight:800;color:#0D2B4E;margin:16px 0 9px;border-left:3px solid #B8860B;padding-left:9px}

table{width:100%;border-collapse:collapse;font-size:9.8px}
th{background:#E7ECF2;color:#0D2B4E;font-weight:700;padding:7px 9px;border-bottom:1.5px solid #c5d0e0;text-align:left}
td{padding:7px 9px;border-bottom:1px solid #f0f0f0;vertical-align:middle}
tr:last-child td{border-bottom:none}
.tbl-wrap{overflow-x:auto;max-height:340px;overflow-y:auto}
.num{text-align:right;font-family:monospace}

.pill{display:inline-block;padding:2px 8px;border-radius:10px;font-size:8.3px;font-weight:700;white-space:nowrap}
.p-r{background:#FBE9E7;color:#C00000}.p-o{background:#FFF3E0;color:#C96A00}
.p-g{background:#E8F5EC;color:#1E7A34}.p-n{background:#E7ECF2;color:#0D2B4E}
.p-go{background:#FFF8E7;color:#B8860B}.p-gy{background:#f0f0f0;color:#595959}

/* AUTOCOMPLETE SEARCH */
.ac-wrap{position:relative}
.ac-list{position:absolute;top:100%;left:0;right:0;background:#fff;border:1.5px solid #0D2B4E;border-top:none;border-radius:0 0 8px 8px;max-height:240px;overflow-y:auto;z-index:50;box-shadow:0 6px 16px rgba(0,0,0,.12);display:none}
.ac-list.show{display:block}
.ac-item{padding:9px 12px;cursor:pointer;border-bottom:1px solid #f0f0f0;font-size:11.5px}
.ac-item:hover{background:#f0f4ff}
.ac-item:last-child{border-bottom:none}
.ac-item .acn{font-weight:700;color:#0D2B4E}
.ac-item .acm{color:#8C8C8C;font-size:10px;margin-left:6px}

/* CLIENT DETAIL PANEL — light green bordered internal window */
.client-panel{border:2px solid #1E7A34;background:#F2FAF5;border-radius:10px;margin-top:14px;overflow:hidden}
.client-panel-hdr{background:#E8F5EC;border-bottom:1.5px solid #1E7A34;padding:10px 14px;display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:6px}
.client-panel-hdr .cph-title{font-size:12.5px;font-weight:800;color:#1E7A34}
.client-panel-hdr .cph-branch{font-size:11.5px;font-weight:700;color:#0D2B4E}
.client-panel-body{padding:14px}
.info-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(130px,1fr));gap:8px}
.ibox{background:#fff;border:1px solid #d8ecdf;border-radius:6px;padding:7px 9px}
.ik{font-size:8.3px;color:#8C8C8C;text-transform:uppercase;margin-bottom:2px}
.iv{font-size:11.5px;font-weight:700;color:#0D2B4E}

/* NEW PACKAGE BUILDER — gold bordered internal window */
.builder-panel{border:2px solid #B8860B;background:#FFFBF0;border-radius:10px;margin-top:14px;overflow:hidden;display:none}
.builder-panel.show{display:block}
.builder-hdr{background:#FFF3D6;border-bottom:1.5px solid #B8860B;padding:10px 14px}
.builder-hdr .bph-title{font-size:12.5px;font-weight:800;color:#B8860B}
.builder-body{padding:14px}
.builder-row{display:grid;grid-template-columns:2.2fr 1fr 1fr 1fr auto;gap:8px;align-items:end;margin-bottom:10px}
@media(max-width:800px){.builder-row{grid-template-columns:1fr}}
.remove-row-btn{background:#FBE9E7;color:#C00000;border:1px solid #f0bdb6;border-radius:6px;height:33px;width:33px;cursor:pointer;font-weight:700}

.budget-bar-track{background:#eef0f5;border-radius:5px;height:18px;overflow:hidden;position:relative}
.budget-bar-fill{height:18px;transition:width .2s}
.budget-bar-fill.ok{background:#1E7A34}
.budget-bar-fill.warn{background:#C00000}

.plan-row{cursor:pointer}
.plan-row.disabled{opacity:.55;cursor:not-allowed;background:#fafafa}
.plan-row.selected td{background:#FFF8E7}
.chk-cell{width:32px;text-align:center}
.chk-box{width:18px;height:18px;border:2px solid #ccc;border-radius:4px;display:inline-block;cursor:pointer}
.chk-box.checked{background:#1E7A34;border-color:#1E7A34;position:relative}
.chk-box.checked::after{content:'\2713';color:#fff;font-size:12px;position:absolute;top:-3px;left:2px}
.chk-box.blocked{background:#eee;border-color:#ccc;cursor:not-allowed}

.chk-item{display:flex;align-items:flex-start;gap:8px;padding:9px 11px;border:1px solid #e5e5e5;border-radius:7px;font-size:11px;cursor:pointer;background:#fafafa;margin-bottom:6px}
.chk-item:hover{border-color:#0D2B4E;background:#f0f4ff}
.chk-item.on{border-color:#0D2B4E;background:#E7ECF2}
.chk-item input{flex-shrink:0;margin-top:2px;width:16px;height:16px}

.tiles{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;margin-bottom:16px}
.tile{border-radius:8px;padding:11px 13px;border:1px solid #e5e5e5}
.tile .tl{font-size:8.3px;color:#8C8C8C;text-transform:uppercase;letter-spacing:.3px;margin-bottom:4px;font-weight:700}
.tile .tv{font-size:16px;font-weight:800}
.t-pn{background:#E7ECF2;border-left:3px solid #0D2B4E}.t-pg{background:#FFF8E7;border-left:3px solid #B8860B}
.t-pr{background:#FBE9E7;border-left:3px solid #C00000}.t-pgr{background:#E8F5EC;border-left:3px solid #1E7A34}
.t-po{background:#FFF3E0;border-left:3px solid #C96A00}
.tv-n{color:#0D2B4E}.tv-r{color:#C00000}.tv-gr{color:#1E7A34}.tv-g{color:#B8860B}.tv-o{color:#C96A00}

.timeline{padding-left:18px;border-left:2px solid #e0e0e0;margin-top:8px}
.tl-item{position:relative;padding:6px 0 10px 14px}
.tl-dot{width:9px;height:9px;border-radius:50%;position:absolute;left:-5px;top:9px;border:2px solid #fff}

.glist-item{padding:11px 13px;border:1.5px solid #e0e0e0;border-radius:8px;margin-bottom:8px;cursor:pointer;background:#fff}
.glist-item:hover{border-color:#0D2B4E;background:#f8faff}
.glist-item.sel{border-color:#B8860B;background:#FFF8E7}

.fbar{background:#0D2B4E;border-radius:9px;padding:12px 15px;display:flex;flex-wrap:wrap;gap:9px;align-items:flex-end;margin-bottom:14px}
.fbar label.lbl{color:#B8860B}
.fbar select{background:#1a3a6e;border-color:#4a6a9a;color:#fff;height:30px;min-width:130px}
.fbar select option{background:#1a3a6e}
.apbtn{height:30px;padding:0 16px;background:#B8860B;color:#fff;border:none;border-radius:5px;font-size:11px;font-weight:700;cursor:pointer}

.otp-box{display:flex;gap:8px;justify-content:center;margin:18px 0}
.otp-box input{width:46px;height:54px;text-align:center;font-size:22px;font-weight:800;border:2px solid #d0d5e0;border-radius:8px}
.otp-box input:focus{border-color:#0D2B4E}

.modal-overlay{display:none;position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(13,43,78,.55);z-index:999;align-items:center;justify-content:center}
.modal-overlay.show{display:flex}
.modal-box{background:#fff;border-radius:10px;padding:26px;max-width:460px;text-align:center;box-shadow:0 8px 30px rgba(0,0,0,.25)}
.modal-box.wide{max-width:680px;text-align:left;max-height:85vh;overflow-y:auto}
.modal-box .mic{font-size:40px;margin-bottom:10px}
.modal-box .mtt{font-size:15px;font-weight:800;color:#0D2B4E;margin-bottom:8px}
.modal-box .mtx{font-size:11px;color:#595959;margin-bottom:16px;line-height:1.5}


/* ── EXTRA: approval, party cards, money panel, existing C2C classes ── */
.four-col{display:grid;grid-template-columns:1fr 1fr 1fr 1fr;gap:12px}
@media(max-width:900px){.four-col{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.four-col{grid-template-columns:1fr}}

/* hidden utility */
.hidden{display:none!important}

/* step bar extra */
.step.active{} 

/* approval panels */
.approval-block{background:#f8f9fc;border:1px solid #e0e6f0;border-radius:9px;padding:14px;margin-bottom:14px}
.activity-box{background:#E7ECF2;border-radius:7px;padding:10px 12px;margin-bottom:12px;font-size:10.5px}
.activity-box strong{display:block;color:#0D2B4E;margin-bottom:4px}
.rejection-box{background:#FBE9E7;border-radius:7px;padding:10px 12px;margin-bottom:12px;font-size:10.5px;border-left:3px solid #C00000}
.rejection-box strong{display:block;color:#C00000;margin-bottom:4px}

/* party cards */
.party-card{border-radius:9px;padding:14px;border:1.5px solid #e0e6f0;margin-bottom:10px}
.party-blue{background:#EEF2FB;border-color:#b5c4e0}
.party-green{background:#F2FAF5;border-color:#a8d8b5}
.party-head{display:flex;align-items:flex-start;gap:10px;margin-bottom:10px}
.party-head h3{font-size:11.5px;font-weight:800;color:#0D2B4E;margin:0}
.party-head p{font-size:10px;color:#595959;margin:0}
.party-badge{width:24px;height:24px;border-radius:50%;background:#0D2B4E;color:#fff;font-size:11px;font-weight:800;display:flex;align-items:center;justify-content:center;flex-shrink:0}
.party-badge-green{background:#1E7A34}

/* money panel */
.money-panel{display:grid;grid-template-columns:repeat(5,1fr);gap:10px;margin:14px 0}
@media(max-width:900px){.money-panel{grid-template-columns:1fr 1fr 1fr}}
.money-card{background:#f8f9fc;border:1px solid #e0e6f0;border-radius:8px;padding:10px 12px}
.money-card span{font-size:9px;color:#8C8C8C;text-transform:uppercase;letter-spacing:.2px;display:block;margin-bottom:4px}
.money-card strong{font-size:13px;font-weight:800;color:#0D2B4E;font-family:monospace}
.money-hl{border:2px solid #1E7A34;background:#E8F5EC}
.money-hl strong{color:#1E7A34}
.rule-note{font-size:10.5px;padding:9px 12px;border-radius:6px;background:#E8F5EC;color:#1E7A34;border-left:3px solid #1E7A34;margin-bottom:14px}
.rule-note.rule-danger{background:#FBE9E7;color:#C00000;border-color:#C00000}

/* total box */
.total-box{background:#E8F5EC;border-radius:8px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;margin:10px 0}
.total-box span{font-size:11.5px;font-weight:700;color:#1E7A34}
.total-box strong{font-size:15px;font-weight:800;color:#1E7A34;font-family:monospace}

/* divider */
.section-divider{display:flex;align-items:center;gap:12px;margin:20px 0}
.section-divider-line{flex:1;height:1px;background:#dde3f0}
.section-divider-label{font-size:10.5px;font-weight:800;color:#B8860B;text-transform:uppercase;letter-spacing:.5px;white-space:nowrap}

/* transferee existing plans (green border subpanel) */
.transferee-panel{border:2px solid #1E7A34;background:#F2FAF5;border-radius:10px;overflow:hidden;margin-top:12px}
.transferee-panel-hdr{background:#E8F5EC;border-bottom:1.5px solid #1E7A34;padding:9px 14px;display:flex;justify-content:space-between;align-items:center}
.transferee-panel-hdr .tph-title{font-size:11.5px;font-weight:800;color:#1E7A34}

/* create new transferee */
.new-client-box{border:2px solid #B8860B;background:#FFFBF0;border-radius:10px;overflow:hidden;margin-top:12px}
.new-client-hdr{background:#FFF3D6;border-bottom:1.5px solid #B8860B;padding:9px 14px;display:flex;justify-content:space-between;align-items:center}
.new-client-hdr .nch-title{font-size:12px;font-weight:800;color:#B8860B}

/* form topbar */
.form-topbar{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:14px;padding:10px 14px;background:#fff;border-radius:8px;border:1px solid #e0e6f0}
.form-topbar .cur-doc-label{font-size:10.5px;color:#595959}
.form-topbar .cur-doc-label strong{font-size:12px;color:#0D2B4E;display:block}

/* open plan btn */
.open-plan-btn{padding:4px 10px;background:#fff;border:1.5px solid #0D2B4E;border-radius:5px;font-size:10px;font-weight:700;cursor:pointer;color:#0D2B4E}
.open-plan-btn:hover{background:#0D2B4E;color:#fff}
.open-plan-btn:disabled{opacity:.4;cursor:not-allowed}

/* transfer qty/date inputs in table */
.qty-input{width:70px!important;height:28px!important;text-align:center;font-weight:700}
.date-input-sm{width:120px!important;height:28px!important}
.remove-row-btn-sm{background:#FBE9E7;color:#C00000;border:1px solid #f0bdb6;border-radius:5px;width:28px;height:28px;cursor:pointer;font-weight:700;font-size:12px}

/* row status */
.row-status{font-size:9px;font-weight:700;padding:2px 8px;border-radius:8px;display:inline-block}
.row-status.allowed{background:#E8F5EC;color:#1E7A34}
.row-status.blocked{background:#FBE9E7;color:#C00000}

/* plan row in invoiced plans table */
.plan-row-selectable{cursor:pointer}
.plan-row-selectable.plan-selected td{background:#FFF8E7}

/* submit status */
.submit-status{margin:10px 0;font-size:11px}

/* actions bar */
.actions-bar{display:flex;justify-content:flex-end;gap:10px;padding:14px 0 4px;flex-wrap:wrap}

/* pagination */
.pagination{display:flex;justify-content:space-between;align-items:center;padding:8px 0;font-size:10.5px}
.pagination-info{color:#595959}
.pagination-info span{margin-left:6px;color:#8C8C8C}
.pagination-actions{display:flex;gap:6px}
.page-btn{padding:5px 12px;border-radius:5px;border:1px solid #ddd;background:#fff;cursor:pointer;font-size:10.5px;font-weight:600;color:#0D2B4E}
.page-btn:disabled{opacity:.4;cursor:not-allowed}

/* chk-label */
.chk-label{display:flex;align-items:flex-start;gap:8px;cursor:pointer;font-size:11px}
.chk-label input{flex-shrink:0;margin-top:2px;width:15px;height:15px;cursor:pointer}

/* conv charge panel */
.conv-charge-panel{background:#f8f9fc;border:1px solid #e0e6f0;border-radius:8px;padding:12px;margin-top:12px}

/* ibox values */
.ibox-more{margin-top:8px}

/* step wpanel: existing cpc-stage-panel compatibility */
.cpc-stage-panel{display:none}
.cpc-stage-panel.active{display:block}


/* ── REVIEW SECTION ── */
#reviewBox { font-size: 10.5px; }
#reviewBox @media(max-width:700px) { grid-template-columns: 1fr !important; }

/* ── SEARCH RESULT LOADING SHIMMER ── */
@keyframes shimmer {
  0%{opacity:.4} 50%{opacity:1} 100%{opacity:.4}
}
[data-patient-meta] span[style*="Loading"] {
  animation: shimmer 1.2s infinite;
}

/* ── AC-LIST show/hide (new HTML uses .show class from design) ── */
.ac-list { display: none; }
.ac-list.show { display: block; }

/* ── SEARCH INPUT FOCUS GLOW ── */
#transferorSearch:focus, #transfereeSearch:focus {
  border-color: #0D2B4E;
  box-shadow: 0 0 0 3px rgba(13,43,78,.12);
}

/* ── ACTIVE PLAN ROW ── */
tr.plan-selected td { background: #FFF8E7 !important; }

/* ── REVIEW RESPONSIVE ── */
@media(max-width:700px) {
  #reviewBox > div { grid-template-columns: 1fr !important; }
}

/* ── TRANSFEROR CONFIRM FLOW ── */
.cpc-confirm-gate{
  background:#fff;
  border:1.5px solid #d8e2f0;
  border-left:4px solid #1E7A34;
  border-radius:10px;
  padding:14px 16px;
  margin:-4px 0 16px;
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:14px;
  box-shadow:0 3px 10px rgba(13,43,78,.06);
}

.cpc-confirm-title{
  font-size:13px;
  font-weight:800;
  color:#0D2B4E;
  margin-bottom:3px;
}

.cpc-confirm-sub{
  font-size:10.5px;
  color:#595959;
  line-height:1.5;
}

.cpc-confirm-gate-actions{
  display:flex;
  gap:8px;
  justify-content:flex-end;
  flex-wrap:wrap;
}

#cpcRequestFillingArea{
  animation:cpcFadeIn .18s ease;
}

@keyframes cpcFadeIn{
  from{opacity:0;transform:translateY(6px)}
  to{opacity:1;transform:translateY(0)}
}

@media(max-width:700px){
  .cpc-confirm-gate{
    flex-direction:column;
    align-items:flex-start;
  }

  .cpc-confirm-gate-actions{
    width:100%;
    justify-content:flex-start;
  }
