/* ── SIGNATURE CANVAS FIX ── */
.cpc-signature-storage,
textarea[data-signature-storage="1"]{
  display:none !important;
}

.cpc-signature-field{
  position:relative;
}

.cpc-signature-canvas{
  width:100%;
  height:120px;
  display:block;
  background:#fff;
  border:1.5px dashed #b8c4d6;
  border-radius:8px;
  cursor:crosshair;
  touch-action:none;
  margin-top:6px;
}

.cpc-signature-help{
  font-size:10px;
  color:#667085;
  margin-top:6px;
}

.cpc-signature-actions{
  display:flex;
  justify-content:flex-end;
  margin-top:6px;
}

.cpc-mini-btn{
  border:none;
  border-radius:6px;
  padding:5px 10px;
  font-size:10.5px;
  font-weight:700;
  cursor:pointer;
}

.cpc-mini-btn-danger{
  background:#FBE9E7;
  color:#C00000;
  border:1px solid #f0bdb6;
}

/* ── READONLY SUBMITTED SIGNATURE ── */
.cpc-signature-canvas.cpc-signature-readonly{
  cursor:not-allowed !important;
  pointer-events:none;
  background:#f8fafc;
  border-color:#cbd5e1;
  opacity:.96;
}

.cpc-signature-field.cpc-signature-field-readonly .cpc-signature-help{
  color:#8C8C8C;
}

/* ── APPROVAL HISTORY SIDE BY SIDE ── */
.cpc-approval-history-grid{
  display:grid;
  grid-template-columns:repeat(auto-fit, minmax(240px, 1fr));
  gap:12px;
  margin-top:8px;
}

.cpc-approval-history-row{
  background:#fff;
  border:1px solid #d8e2f0;
  border-left:4px solid #8C8C8C;
  border-radius:9px;
  padding:12px;
  font-size:10.8px;
  box-shadow:0 2px 8px rgba(13,43,78,.05);
}

.cpc-approval-history-row.approved{
  border-left-color:#1E7A34;
  background:#F2FAF5;
}

.cpc-approval-history-row.rejected{
  border-left-color:#C00000;
  background:#FFF5F5;
}

.cpc-approval-history-title{
  display:flex;
  justify-content:space-between;
  align-items:center;
  gap:8px;
  margin-bottom:10px;
  color:#0D2B4E;
  font-size:11.5px;
}

.cpc-approval-history-title span{
  background:#E8F5EC;
  color:#1E7A34;
  border-radius:12px;
  padding:2px 8px;
  font-size:9px;
  font-weight:800;
}

.cpc-approval-history-row.rejected .cpc-approval-history-title span{
  background:#FBE9E7;
  color:#C00000;
}

.cpc-history-line{
  display:flex;
  justify-content:space-between;
  gap:10px;
  padding:5px 0;
  border-top:1px solid rgba(13,43,78,.08);
}

.cpc-history-line span,
.cpc-history-remarks span{
  color:#667085;
  font-size:9px;
  font-weight:800;
  text-transform:uppercase;
  letter-spacing:.3px;
}

.cpc-history-line strong{
  color:#0D2B4E;
  text-align:right;
}

.cpc-history-remarks{
  border-top:1px solid rgba(13,43,78,.08);
  padding-top:7px;
  margin-top:4px;
}

.cpc-history-remarks p{
  margin:4px 0 0;
  color:#202020;
  line-height:1.45;
}

/* ── ALL REQUESTS DETAIL + TIMELINE ── */
#mode-1 > .two-col{
  grid-template-columns:340px 1fr;
  gap:16px;
}

.cpc-detail-loading,
.cpc-detail-empty{
