  padding:18px;
  text-align:center;
}

.cpc-detail-shell{
  font-size:11px;
}

.cpc-detail-head{
  background:#0D2B4E;
  color:#fff;
  border-radius:10px;
  padding:14px 16px;
  display:flex;
  justify-content:space-between;
  gap:12px;
  align-items:flex-start;
  margin-bottom:14px;
}

.cpc-detail-doc{
  font-size:10px;
  color:#b8c9d9;
  margin-bottom:3px;
  font-weight:700;
}

.cpc-detail-title{
  font-size:15px;
  font-weight:900;
  line-height:1.35;
}

.cpc-detail-title span{
  color:#B8860B;
  margin:0 6px;
}

.cpc-detail-chip-grid{
