}

/* Better Remove button style for Sessions To Be Transferred table */
.cpc-remove-transfer-row {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 5px;

  min-width: 78px;
  height: 30px;
  padding: 0 12px;

  border: 1px solid #f2b8b5 !important;
  border-radius: 999px !important;

  background: #fff5f5 !important;
  color: #b42318 !important;

  font-size: 10.5px;
  font-weight: 800;
  line-height: 1;
  cursor: pointer;

  box-shadow: 0 1px 2px rgba(180, 35, 24, 0.08);
  transition: all 0.16s ease;
}

.cpc-remove-transfer-row::before {
  content: "×";
  width: 16px;
  height: 16px;
  border-radius: 50%;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  background: #fce8e6;
  color: #b42318;

  font-size: 14px;
  font-weight: 900;
  line-height: 1;
}

.cpc-remove-transfer-row:hover {
  background: #b42318 !important;
  color: #fff !important;
  border-color: #b42318 !important;
  transform: translateY(-1px);
  box-shadow: 0 4px 10px rgba(180, 35, 24, 0.18);
}

.cpc-remove-transfer-row:hover::before {
  background: rgba(255,255,255,0.18);
  color: #fff;
}

.cpc-remove-transfer-row:active {
  transform: translateY(0);
  box-shadow: none;
}

.cpc-remove-transfer-row:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
  box-shadow: none;
}

/* Client search with clear X button */
.cpc-search-control {
  position: relative;
}

.cpc-search-control input {
  padding-right: 38px !important;
}

.cpc-clear-client-btn {
  position: absolute;
  right: 8px;
  top: 50%;
  transform: translateY(-50%);

  width: 22px;
  height: 22px;
  border-radius: 50%;

  border: 1px solid #d0d5e0;
  background: #f8fafc;
  color: #667085;

  display: inline-flex;
  align-items: center;
  justify-content: center;

  font-size: 16px;
  font-weight: 900;
  line-height: 1;
  cursor: pointer;
  transition: all .15s ease;
}

.cpc-clear-client-btn:hover {
  background: #FBE9E7;
  color: #C00000;
  border-color: #f0bdb6;
}

.cpc-readonly-input,
input[readonly].cpc-readonly-input,
input[readonly][data-field="client_full_name"],
input[readonly][data-field="branch"],
input[readonly][data-field="receiving_branch"],
#transfereeFullDisplayName[readonly] {
  background: #f8fafc !important;
  color: #0D2B4E !important;
  font-weight: 700;
  cursor: not-allowed;
}

.cpc-employee-link-wrap {
  position: relative;
}

.cpc-employee-results {
  position: absolute;
  top: 100%;
  left: 0;
  right: 0;
  z-index: 9999;
  background: #fff;
  border: 1.5px solid #0D2B4E;
  border-top: none;
  border-radius: 0 0 8px 8px;
  max-height: 240px;
  overflow-y: auto;
  box-shadow: 0 8px 18px rgba(13, 43, 78, 0.18);
}

.cpc-search-item {
  padding: 9px 12px;
  cursor: pointer;
  border-bottom: 1px solid #eef2f7;
  font-size: 11.5px;
}

.cpc-search-item:hover {
  background: #eef4ff;
}

.cpc-search-item strong {
  display: block;
  color: #0D2B4E;
  font-weight: 800;
}

.cpc-search-item span {
  display: block;
  margin-top: 2px;
  color: #667085;
  font-size: 10px;
}

/* ── COMPACT ALL REQUESTS LAYOUT ── */
#mode-1{
  --cpc-request-panel-height: min(620px, calc(100vh - 310px));
}

#mode-1 > .two-col{
  grid-template-columns:350px minmax(0, 1fr) !important;
  gap:16px;
  align-items:stretch !important;
}

/* LEFT SIDE REQUEST LIST */
#mode-1 > .two-col > div:first-child{
  display:flex;
  flex-direction:column;
  min-height:0;
}

#ag-list{
  flex:1;
  min-height:0;
  max-height:var(--cpc-request-panel-height);
  overflow-y:auto;
  overflow-x:hidden;
  padding-right:4px;
}

#ag-list::-webkit-scrollbar,
#ag-detail::-webkit-scrollbar{
  width:7px;
}

#ag-list::-webkit-scrollbar-thumb,
#ag-detail::-webkit-scrollbar-thumb{
  background:#c8d0dc;
  border-radius:10px;
}

#ag-list::-webkit-scrollbar-track,
#ag-detail::-webkit-scrollbar-track{
  background:#f1f4f8;
}

/* RIGHT SIDE DETAIL SCROLL AREA */
#mode-1 > .two-col > div:nth-child(2){
  min-height:0;
}

#mode-1 > .two-col > div:nth-child(2) .card{
  height:var(--cpc-request-panel-height);
  display:flex;
  flex-direction:column;
}

#mode-1 > .two-col > div:nth-child(2) .card-hdr{
  flex:0 0 auto;
}

#ag-detail{
  flex:1;
  min-height:0 !important;
  overflow-y:auto;
  overflow-x:hidden;
  padding:16px;
}

/* PAGINATION */
#requestPagination{
  flex:0 0 auto;
  padding-top:8px;
  margin-top:8px;
  border-top:1px solid #e2e8f0;
  background:#f4f6fb;
}

.pagination-info{
  font-size:10px;
  font-weight:800;
  color:#0D2B4E;
  display:flex;
  justify-content:space-between;
  align-items:center;
  margin-bottom:7px;
}

.pagination-info span{
  color:#8C8C8C;
  font-weight:700;
}

.pagination-actions{
  display:flex;
  gap:8px;
}

.page-btn{
  flex:1;
  height:30px;
  border:none;
  border-radius:6px;
  background:#0D2B4E;
  color:#fff;
  font-size:10.5px;
  font-weight:800;
  cursor:pointer;
}

.page-btn:disabled{
  opacity:.4;
  cursor:not-allowed;
}

/* MOBILE: normal stacked layout */
@media(max-width:900px){
  #mode-1{
    --cpc-request-panel-height:auto;
  }

  #mode-1 > .two-col{
    grid-template-columns:1fr !important;
  }

  #ag-list{
    max-height:none;
    overflow:visible;
  }

  #mode-1 > .two-col > div:nth-child(2) .card{
    height:auto;
  }

  #ag-detail{
