/* ============================================================
   C2C — P2P MATCHED ALL REQUESTS + APPROVAL DASHBOARD THEME
   ============================================================ */

.c2c-page .main-nav .mnav#navTab2 { order:1; }
.c2c-page .main-nav .mnav#navTab1 { order:2; }
.c2c-page .main-nav .mnav#navTab0 { order:3; }

.cpc-p2p-panel {
  --cpc-dashboard-height:min(760px, calc(100vh - 220px));
}

.cpc-p2p-fbar {
  display:flex;
  align-items:flex-end;
  flex-wrap:wrap;
  gap:16px;
  margin-bottom:16px;
  padding:14px 18px;
  border-radius:8px;
  background:#0D2B4E;
}

.cpc-p2p-label {
  display:block;
  margin-bottom:4px;
  color:#b8c9d9;
  font-size:9.5px;
  font-weight:700;
  letter-spacing:.05em;
  text-transform:uppercase;
}

.cpc-p2p-search-group {
  flex:0 1 330px;
  width:330px;
  max-width:330px;
  min-width:250px;
}

.cpc-p2p-filter-control {
  flex:0 0 auto;
  min-width:190px;
}

.cpc-p2p-branch-filter {
  min-width:170px;
}

.cpc-p2p-search-wrap {
  position:relative;
  width:100%;
}

.cpc-p2p-search-input {
  width:100% !important;
  height:38px !important;
  box-sizing:border-box;
  padding:0 42px 0 38px !important;
  border:1.5px solid #D1D5DB !important;
  border-radius:9px !important;
  background:#fff !important;
  color:#1F2937 !important;
  font-family:Inter,Arial,sans-serif;
  font-size:12.5px !important;
  font-weight:600;
  outline:none;
  transition:border-color .16s ease,box-shadow .16s ease;
}

.cpc-p2p-search-input::placeholder {
  color:#9CA3AF;
  font-weight:500;
}

.cpc-p2p-search-input:focus {
  border-color:#43A047 !important;
  box-shadow:0 0 0 3px rgba(67,160,71,.18);
}

.cpc-p2p-search-icon {
  position:absolute;
  left:13px;
  top:50%;
  transform:translateY(-50%);
  z-index:1;
  color:#6B7280;
  font-size:14px;
  line-height:1;
  pointer-events:none;
}

.cpc-p2p-search-clear {
  position:absolute;
  right:8px;
  top:50%;
  transform:translateY(-50%);
  display:inline-flex;
  align-items:center;
  justify-content:center;
  width:25px;
  height:25px;
  padding:0;
  border:1px solid #FCA5A5;
  border-radius:50%;
  background:#FEE2E2;
  color:#B91C1C;
  font-size:17px;
  font-weight:900;
  line-height:1;
  cursor:pointer;
}

.cpc-p2p-search-clear:hover {
  background:#FECACA;
  border-color:#EF4444;
}

.cpc-p2p-select {
  min-width:100%;
  height:38px !important;
  padding:0 10px !important;
  border:1px solid #D1D5DB !important;
  border-radius:7px !important;
  background:#fff !important;
  color:#1F2937 !important;
  font-size:12px !important;
}

.cpc-p2p-refresh-btn {
  height:38px;
  white-space:nowrap;
  background:#fff;
}

.cpc-p2p-all-layout {
  display:grid;
  grid-template-columns:350px minmax(0,1fr);
  gap:16px;
  align-items:stretch;
  min-height:0;
}

.cpc-p2p-list-column,
.cpc-p2p-approval-left {
  height:var(--cpc-dashboard-height);
  display:flex;
  flex-direction:column;
  min-width:0;
  min-height:0;
}

.cpc-p2p-request-list {
  flex:1;
  min-width:0;
  min-height:0;
  overflow-y:auto;
  overflow-x:hidden;
  padding-right:4px;
}

.cpc-p2p-detail-panel {
  height:var(--cpc-dashboard-height);
  overflow-y:auto;
  overflow-x:hidden;
  padding:18px;
  border:1px solid #E5E7EB;
  border-radius:10px;
  background:#fff;
}

.cpc-p2p-request-list::-webkit-scrollbar,
.cpc-p2p-detail-panel::-webkit-scrollbar {
  width:7px;
}

.cpc-p2p-request-list::-webkit-scrollbar-thumb,
.cpc-p2p-detail-panel::-webkit-scrollbar-thumb {
  border-radius:10px;
  background:#c8d0dc;
}

.cpc-p2p-request-list::-webkit-scrollbar-track,
.cpc-p2p-detail-panel::-webkit-scrollbar-track {
  background:#f1f4f8;
}

.cpc-p2p-request-item {
  margin-bottom:8px;
  padding:12px 14px;
  border:1px solid #E5E7EB;
  border-radius:8px;
  background:#fff;
  cursor:pointer;
  transition:border-color .15s ease,background .15s ease,box-shadow .15s ease;
}

.cpc-p2p-request-item:hover {
  border-color:#0D2B4E;
  box-shadow:0 4px 12px rgba(13,43,78,.08);
}

.cpc-p2p-request-item.active,
.cpc-p2p-request-item.sel {
  border-color:#0D2B4E;
  background:#F0F7EE;
  box-shadow:0 0 0 1px rgba(13,43,78,.05);
}

.cpc-p2p-request-top {
  display:flex;
  align-items:flex-start;
  justify-content:space-between;
  gap:8px;
}

.cpc-p2p-request-id {
  color:#0D2B4E;
  font-size:12px;
  font-weight:800;
  overflow-wrap:anywhere;
}

.cpc-p2p-request-flow {
  margin-top:5px;
  color:#374151;
  font-size:11px;
  font-weight:700;
  line-height:1.45;
}

.cpc-p2p-request-sub {
  margin-top:3px;
  color:#6B7280;
  font-size:10px;
  line-height:1.4;
}

.cpc-p2p-request-pending {
  margin-top:6px;
  color:#595959;
  font-size:10px;
}

.cpc-p2p-pagination {
  flex:0 0 auto;
  margin-top:8px;
  padding-top:8px;
  border-top:1px solid #E5E7EB;
}

.cpc-p2p-pagination .pagination-info {
  display:flex;
  align-items:center;
  justify-content:space-between;
  margin-bottom:7px;
  color:#0D2B4E;
  font-size:10px;
  font-weight:800;
}

.cpc-p2p-pagination .pagination-info span {
  color:#8C8C8C;
  font-weight:600;
}

.cpc-p2p-pagination .page-btn {
  min-height:30px;
  padding:5px 11px;
  border:1px solid #D1D5DB;
  border-radius:6px;
  background:#fff;
  color:#0D2B4E;
  font-size:10px;
  font-weight:700;
  cursor:pointer;
}

.cpc-p2p-pagination .page-btn:hover:not(:disabled) {
  border-color:#0D2B4E;
  background:#F8FAFC;
}

.cpc-p2p-pagination .page-btn:disabled {
  opacity:.45;
  cursor:not-allowed;
}

.cpc-p2p-approval-tiles {
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
  margin-bottom:18px;
}

.cpc-p2p-tile {
  padding:14px 16px;
  border:1px solid #E5E7EB;
  border-radius:8px;
}

.cpc-p2p-tile.pending {
  border-left:3px solid #0D2B4E;
  background:#E7ECF2;
}

.cpc-p2p-tile.total {
  border-left:3px solid #B8860B;
  background:#FFF8E7;
}

.cpc-p2p-tile.done {
  border-left:3px solid #1E7A34;
  background:#E8F5EC;
}

.cpc-p2p-tile-label {
  color:#8C8C8C;
  font-size:9px;
  letter-spacing:.05em;
  text-transform:uppercase;
}

.cpc-p2p-tile-value {
  margin-top:4px;
  font-size:24px;
  font-weight:900;
}

.cpc-p2p-tile.pending .cpc-p2p-tile-value { color:#0D2B4E; }
.cpc-p2p-tile.total .cpc-p2p-tile-value { color:#B8860B; }
.cpc-p2p-tile.done .cpc-p2p-tile-value { color:#1E7A34; }

.cpc-p2p-approval-layout {
  display:grid;
  grid-template-columns:350px minmax(0,1fr);
  gap:16px;
  align-items:stretch;
}

.cpc-p2p-detail-panel .cpc-detail-shell,
.cpc-p2p-detail-panel .cpc-approval-action-shell {
  max-width:none;
}

.cpc-p2p-loading,
.cpc-p2p-empty {
  padding:36px 18px;
  color:#8C8C8C;
  text-align:center;
}

.cpc-p2p-linked-highlight {
  animation:cpcP2PLinkedHighlight 1.8s ease;
}

@keyframes cpcP2PLinkedHighlight {
  0%,100% { box-shadow:none; }
  25%,75% { box-shadow:0 0 0 3px rgba(184,134,11,.3); }
}

@media (max-width:950px) {
  .cpc-p2p-all-layout,
  .cpc-p2p-approval-layout {
    grid-template-columns:320px minmax(0,1fr);
  }

  .cpc-p2p-approval-tiles {
    grid-template-columns:repeat(2,1fr);
  }
}

@media (max-width:760px) {
  .cpc-p2p-search-group {
    flex:1 1 100%;
    width:100%;
    max-width:100%;
    min-width:100%;
  }

  .cpc-p2p-filter-control {
    flex:1 1 calc(50% - 8px);
    min-width:150px;
  }

  .cpc-p2p-all-layout,
  .cpc-p2p-approval-layout {
    grid-template-columns:1fr;
  }

  .cpc-p2p-list-column,
  .cpc-p2p-approval-left,
  .cpc-p2p-detail-panel {
    height:auto;
    max-height:none;
  }

  .cpc-p2p-request-list {
    max-height:430px;
  }
}

@media (max-width:520px) {
  .cpc-p2p-approval-tiles {
    grid-template-columns:1fr;
  }

  .cpc-p2p-filter-control,
  .cpc-p2p-refresh-btn {
    flex:1 1 100%;
    width:100%;
  }
}
