  --c2c-theme-700:#2E7D32;
  --c2c-theme-600:#388E3C;
  --c2c-theme-500:#43A047;
  --c2c-gold:#B8860B;
  --c2c-bg:#F4F7F5;
  --c2c-soft:#F0F7EE;
  --c2c-border:#E2E8E4;
  --c2c-text:#1F2937;
  --c2c-muted:#64748B;
