  REJECTED: "Rejected"
};

function getApprovalStage() {
  let stage = String(getField("approval_stage") || "").trim() ||
    String(loadedDoc && loadedDoc.approval_stage || "").trim();

  const workflowStep = Number(currentWorkflowStep || 1);

  const validStages = [
    APPROVAL_STAGES.REQUEST_PENDING,
    APPROVAL_STAGES.CM_PENDING,
    APPROVAL_STAGES.OM_PENDING,
    APPROVAL_STAGES.AUDIT_PENDING,
    APPROVAL_STAGES.COO_PENDING,
    APPROVAL_STAGES.APPROVED,
    APPROVAL_STAGES.REJECTED
  ];

  if (validStages.includes(stage)) return stage;

  if (!stage || stage === "Branch Official Approval Pending") {
    if (workflowStep === 2) return APPROVAL_STAGES.CM_PENDING;
  }

  if (!stage || stage === "Management Approval Pending") {
    if (workflowStep === 3) return APPROVAL_STAGES.AUDIT_PENDING;
  }

  if (workflowStep >= 4) {
    const finalStatus = String(getField("final_approval_status") || "").trim();
    if (finalStatus === "Rejected") return APPROVAL_STAGES.REJECTED;
    if (finalStatus === "Approved") return APPROVAL_STAGES.APPROVED;
  }

  return APPROVAL_STAGES.REQUEST_PENDING;
}

function setApprovalStage(value) {
  setField("approval_stage", value);
  if (loadedDoc) loadedDoc.approval_stage = value;
}

function isCentreManagerStage() { return getApprovalStage() === APPROVAL_STAGES.CM_PENDING; }
function isOperationsManagerStage() { return getApprovalStage() === APPROVAL_STAGES.OM_PENDING; }
function isAuditStage() { return getApprovalStage() === APPROVAL_STAGES.AUDIT_PENDING; }
function isCooStage() { return getApprovalStage() === APPROVAL_STAGES.COO_PENDING; }

function isCompletedApprovalStage() {
  const stage = getApprovalStage();
  return stage === APPROVAL_STAGES.APPROVED || stage === APPROVAL_STAGES.REJECTED;
}

