function bindTransferorConfirmFlow() {
  prepareTransferorConfirmFlow();

  const confirmBtn = root.querySelector("#confirmTransferorForRequestBtn");
  if (confirmBtn && confirmBtn.dataset.bound !== "1") {
    confirmBtn.dataset.bound = "1";
    confirmBtn.addEventListener("click", confirmTransferorForRequest);
  }

  const changeBtn = root.querySelector("#changeTransferorForRequestBtn");
  if (changeBtn && changeBtn.dataset.bound !== "1") {
    changeBtn.dataset.bound = "1";
    changeBtn.addEventListener("click", function () {
      if (currentDocName) {
        frappe.msgprint("Transferor cannot be changed after the request is saved.");
        return;
      }

      transferorConfirmedForRequest = false;
      updateTransferorConfirmGate();

      frappe.show_alert({
        message: "Transferor unlocked. Search or select transferor again.",
        indicator: "orange"
      });

      setTimeout(function () {
        if (transferorSearch) transferorSearch.focus();
      }, 100);
    });
  }

  if (transferorSearch && transferorSearch.dataset.confirmGateBound !== "1") {
    transferorSearch.dataset.confirmGateBound = "1";
    transferorSearch.addEventListener("input", function () {
      if (currentDocName) return;
      transferorConfirmedForRequest = false;
      updateTransferorConfirmGate();
    });
  }

  if (invoicedPlanRows && invoicedPlanRows.dataset.confirmGateBound !== "1") {
    invoicedPlanRows.dataset.confirmGateBound = "1";

    invoicedPlanRows.addEventListener("change", function () {
      updateTransferorConfirmButton();
    });

    const planObserver = new MutationObserver(function () {
      updateTransferorConfirmButton();
    });

    planObserver.observe(invoicedPlanRows, {
      childList: true,
      subtree: true,
      attributes: true
    });
  }

  updateTransferorConfirmGate();
}

function prepareTransferorConfirmFlow() {
  if (cpcRequestAreaPrepared) return;

  const panel = root.querySelector('.cpc-stage-panel[data-stage="1"]');
  if (!panel) return;

  const directCards = Array.prototype.filter.call(panel.children, function (child) {
    return child.classList && child.classList.contains("card");
  });

  const transferorCard = directCards[0];
  if (!transferorCard) return;

  const gate = document.createElement("div");
  gate.id = "transferorConfirmGate";
  gate.className = "cpc-confirm-gate";
  gate.innerHTML = `
    <div class="cpc-confirm-gate-left">
      <div class="cpc-confirm-title">Confirm Transferor Before Filling Request</div>
      <div class="cpc-confirm-sub">
        Select transferor and at least one submitted invoiced Therapy Plan. After confirmation, transferee and conversion details will open.
      </div>
    </div>
    <div class="cpc-confirm-gate-actions">
      <button type="button" class="btn btn-gy" id="changeTransferorForRequestBtn">Change Transferor</button>
      <button type="button" class="btn btn-g" id="confirmTransferorForRequestBtn" disabled>
        ✓ Yes, Transferor Confirmed — Continue Request
      </button>
    </div>
  `;

  transferorCard.insertAdjacentElement("afterend", gate);

  const requestArea = document.createElement("div");
  requestArea.id = "cpcRequestFillingArea";

  let node = gate.nextSibling;
  while (node) {
    const next = node.nextSibling;
    requestArea.appendChild(node);
    node = next;
  }

  panel.appendChild(requestArea);
  cpcRequestAreaPrepared = true;
}

function confirmTransferorForRequest() {
  const transferorName = String(getField("client_full_name") || "").trim();
  const transferorId = String(getField("name1") || "").trim();
  const branch = String(getField("branch") || "").trim();

  if (!transferorName && !transferorId) {
    frappe.msgprint("Please select the transferor first.");
    if (transferorSearch) transferorSearch.focus();
    return;
  }

  if (!branch) {
    frappe.msgprint("Transferor branch is missing. Please reselect the transferor.");
    return;
  }

  if (!invoicedPlanOptions.length) {
    frappe.msgprint("No submitted invoiced Therapy Plan found for this transferor.");
    return;
  }

  if (!selectedConversionPlanNames.length) {
    frappe.msgprint("Please select at least one invoiced Therapy Plan before continuing.");
    return;
  }

  transferorConfirmedForRequest = true;

  if (!getField("transferor_full_name")) {
    setField("transferor_full_name", transferorName);
  }

  if (!getField("transferor_date")) {
    setField("transferor_date", frappe.datetime.get_today());
  }

  updateTransferorConfirmGate();
  renderReview();

  frappe.show_alert({
    message: "Transferor confirmed. Continue with transferee and conversion details.",
    indicator: "green"
  });

  setTimeout(function () {
    const area = root.querySelector("#cpcRequestFillingArea");
    if (area) area.scrollIntoView({ behavior: "smooth", block: "start" });
  }, 150);
}

function updateTransferorConfirmGate() {
  const gate = root.querySelector("#transferorConfirmGate");
  const area = root.querySelector("#cpcRequestFillingArea");
  const actionsBar = root.querySelector(".actions-bar");

  const isSavedOrApprovalDoc = !!currentDocName || Number(currentWorkflowStep || 1) > 1;
  const shouldShowRequestArea = isSavedOrApprovalDoc || transferorConfirmedForRequest;

  if (gate) {
    gate.classList.toggle("hidden", isSavedOrApprovalDoc);
  }

  if (area) {
    area.classList.toggle("hidden", !shouldShowRequestArea);
  }

  if (actionsBar && Number(currentWorkflowStep || 1) === 1 && !currentDocName) {
    actionsBar.classList.toggle("hidden", !transferorConfirmedForRequest);
  } else if (actionsBar) {
    actionsBar.classList.remove("hidden");
  }

  updateTransferorConfirmButton();

  if (!currentDocName && Number(currentWorkflowStep || 1) === 1 && !cpcSubmittedMode) {
      updateC2CFormStepbar(transferorConfirmedForRequest ? 2 : 1);
    }
}

function updateTransferorConfirmButton() {
  const btn = root.querySelector("#confirmTransferorForRequestBtn");
  if (!btn) return;

  const hasTransferor = !!String(getField("client_full_name") || getField("name1") || "").trim();
  const hasPlanOptions = invoicedPlanOptions.length > 0;

  const hasSelectedPlan = getSelectedInvoicedPlanOptions().some(function (option) {
      return hasTransferableSessions(option);
    });

  btn.disabled = !(hasTransferor && hasPlanOptions && hasSelectedPlan);

  if (!hasTransferor) {
    btn.textContent = "Select Transferor First";
  } else if (!hasPlanOptions) {
    btn.textContent = "No Invoiced Plan Available";
  } else if (!hasSelectedPlan) {
    btn.textContent = "Select Therapy Plan to Continue";
  } else {
    btn.textContent = "✓ Yes, Transferor Confirmed — Continue Request";
  }
}




function init() {
  bindListEvents();
  bindWorkflowStepTabs();
  bindConditionalFields();
  initC2CSupportingDocsState();
  bindC2CSupportingDocs();
  bindTermsToggle();
  bindClientSearch();
  bindClientClearButtons();
  enforceClientReadonlyFields();
  bindNewTransfereeCreate();
  bindNewTransfereeBranchChange();
  bindEmployeeLinkSearch();
  bindTableEvents();
  bindNoPastDateFields();
  bindRemarkWordLimits();
  enhanceSignatureFields();
  bindSignaturePads();
  bindTransferorConfirmFlow();
  bindC2CSubmittedActions();
  setTodayIfEmpty();

  c2cExternalRoute = readC2CExternalRoute();
  prepareC2CInitialView(c2cExternalRoute);

  /*
   * Start the page data load immediately.
   *
   * The old startup waited for the hidden All Requests branch selector
   * to finish its User Permission / Branch calls. When that auxiliary
   * request was delayed, the visible Approval Dashboard stayed empty
   * until the user changed a tab or clicked Refresh.
   *
   * ERPNext permissions still protect the initial request list. Once the
   * branch selector is ready we perform one quiet refresh so its resolved
   * branch value is applied without blocking the first render.
   */
  initializeC2CPageFromExternalRoute(
    c2cExternalRoute
  );

  if (requestBranchFilter) {
    loadRequestBranchFilter(function () {
      var route = c2cExternalRoute || {};

      /*
       * Exact redirected records already manage their own background list
       * refresh. Do not reopen or clear those selected detail panels here.
       */
      if (route.request) {
        return;
      }

      if (route.tab === "all") {
        loadRequests(null, {
          showListLoading: false,
          clearPagination: false
        });
        return;
      }

      refreshC2CApprovalDashboard({
        showLoading: false,
        clearDetail: false
      });
    });
  }

  /*
   * Startup watchdog: if an ERPNext call was slow or superseded, make sure
   * the visible Approval Dashboard cannot remain as an empty shell.
   */
  window.setTimeout(function () {
    var approvalMode = root.querySelector("#mode-2");
    var approvalList = root.querySelector("#approval-list");

    var approvalVisible = !!(
      approvalMode &&
      (
        approvalMode.classList.contains("on") ||
        window.getComputedStyle(approvalMode).display !== "none"
      )
    );

    if (!approvalVisible || !approvalList) {
      return;
    }

    var listText = String(
      approvalList.textContent || ""
    ).trim();

    var isOnlyLoadingState = /loading current approval requests|loading approval dashboard/i.test(
      listText
    );

    var hasRenderedState = !!(
      !isOnlyLoadingState &&
      (
        approvalList.querySelector(".cpc-approval-request-item") ||
        approvalList.querySelector(".pkg-detail-empty") ||
        approvalList.querySelector(".notice") ||
        listText
      )
    );

    if (!hasRenderedState) {
      refreshC2CApprovalDashboard({
        showLoading: true,
        clearDetail: false
      });
    }
  }, 1400);
}

function loadRequestBranchFilter(afterDone) {
  if (!requestBranchFilter) {
    if (typeof afterDone === "function") afterDone();
    return;
  }

  function finish() {
    if (typeof afterDone === "function") {
      afterDone();
    }
  }

  function uniqueBranches(values) {
    const seen = {};
    const result = [];

    (values || []).forEach(function (value) {
      const branch = String(value || "").trim();
      const key = branch.toLowerCase();

      if (!branch || seen[key]) return;

      seen[key] = true;
      result.push(branch);
    });

    return result.sort(function (a, b) {
      return a.localeCompare(b);
    });
  }

  function renderAllBranchOptions(branches) {
    branches = uniqueBranches(branches);

    let html = `<option value="">All Branches</option>`;

    branches.forEach(function (branch) {
      html += `
        <option value="${escapeHtml(branch)}">
          ${escapeHtml(branch)}
        </option>
      `;
    });

    requestBranchFilter.innerHTML = html;

    /*
     * IMPORTANT:
     * Empty value means All Branches everywhere in this page.
     * Keep this as the default every time the filter is loaded.
     */
    requestBranchFilter.value = "";
    requestBranchFilter.disabled = false;

    finish();
  }

  requestBranchFilter.innerHTML =
    `<option value="">Loading branches...</option>`;
  requestBranchFilter.value = "";
  requestBranchFilter.disabled = true;

  /*
   * Load the Branch list only to populate the optional branch choices.
   * Do NOT auto-select a login branch, User Permission branch, or Employee branch.
   * ERPNext permissions still control which C2C request records the user can fetch.
   */
  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Branch",
      fields: ["name"],
      order_by: "name asc",
      limit_page_length: 500
    },
    callback: function (r) {
      const branches = uniqueBranches(
        (r.message || []).map(function (row) {
          return row.name;
        })
      );

      renderAllBranchOptions(branches);
    },
    error: function (err) {
      void 0;

      /*
       * Even if Branch master cannot be read, All Branches must still work.
       */
      renderAllBranchOptions([]);
    }
  });
}

