    if (lbl) lbl.textContent = labels[i - 1];
  });
}

function updateC2CFormStepbar(stepNo) {
  stepNo = Number(stepNo || 1);

  setC2CStepLabels("form");

  [1, 2, 3].forEach(function (i) {
    const stepEl = root.querySelector("#wstep-" + i);
    if (!stepEl) return;

    const dot = stepEl.querySelector(".sdot");
    const lbl = stepEl.querySelector(".slbl");

    const isDone = i < stepNo;
    const isActive = i === stepNo;

    stepEl.classList.toggle("done", isDone);
    stepEl.classList.toggle("active", isActive);

    if (dot) {
      dot.classList.toggle("done", isDone);
      dot.classList.toggle("active", isActive);
    }

    if (lbl) {
      lbl.classList.toggle("active", isActive);
      lbl.classList.toggle("done", isDone);
    }
  });
}

