function fetchClientBranchAndEmail(patientName, branchFieldname, emailFieldname, afterDone) {
  if (!patientName || !branchFieldname) { if (afterDone) afterDone(""); return; }
  frappe.call({
    method: "frappe.client.get",
    args: { doctype: "Patient", name: patientName },
    callback: function (r) {
      const patient = r.message || {};
      let branch = getPatientBranch(patient);
      if (branch) {
        setField(branchFieldname, branch);
        if (emailFieldname) fetchBranchEmail(branch, emailFieldname);
        updateTransferType();
        if (afterDone) afterDone(branch);
        return;
      }
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Sales Invoice",
          filters: [["Sales Invoice","patient","=",patientName],["Sales Invoice","docstatus","=",1],["Sales Invoice","is_return","=",0]],
          fields: ["name","branch","posting_date"],
          order_by: "posting_date desc",
          limit_page_length: 1
        },
        callback: function (siRes) {
          const rows = siRes.message || [];
          branch = rows.length ? rows[0].branch || "" : "";
          if (branch) {
            setField(branchFieldname, branch);
            if (emailFieldname) fetchBranchEmail(branch, emailFieldname);
            updateTransferType();
          }
          if (afterDone) afterDone(branch);
        },
        error: function (err) { void 0; if (afterDone) afterDone(""); }
      });
    },
    error: function (err) { void 0; if (afterDone) afterDone(""); }
  });
}

function getPatientMobile(patient) {
