function updateTransferType() {
  const originalBranch = String(getField("branch") || "").trim();
  const receivingBranch = String(getField("receiving_branch") || "").trim();

  let transferType = "";

  if (originalBranch && receivingBranch) {
    if (c2cBranchMatches(receivingBranch, originalBranch)) {
      transferType = "Same Branch Transfer";
    } else {
      transferType = "";
    }
  }

  setField("transfer_type", transferType);

  if (transferTypeDisplay) {
    transferTypeDisplay.value = transferType;
  }

  updateNewTransfereeBranchNote();
}


function updateNewTransfereeBranchNote() {
  if (!newTransfereeBranchNote) return;

  const originalBranch = String(getField("branch") || "").trim();
  const selectedNewBranch = newTransfereeBranch
    ? String(newTransfereeBranch.value || "").trim()
    : "";

  if (!originalBranch) {
    newTransfereeBranchNote.textContent =
      "Select transferor first. New transferee will be created only in the same branch.";
    return;
  }

  if (selectedNewBranch) {
    if (c2cBranchMatches(selectedNewBranch, originalBranch)) {
      newTransfereeBranchNote.textContent =
        "New client will be created in the same branch: " + selectedNewBranch;
    } else {
      newTransfereeBranchNote.textContent =
        "Cross-branch transferee creation is not allowed. Please use same branch only.";
    }
    return;
  }

  newTransfereeBranchNote.textContent =
    "New transferee branch will be locked to transferor branch: " + originalBranch;
}


