function bindSignaturePads() {
  const canvases = root.querySelectorAll(".cpc-signature-canvas");

  canvases.forEach(function (canvas) {
    if (canvas.dataset.bound === "1") return;
    canvas.dataset.bound = "1";

    const fieldname = canvas.dataset.signatureCanvas;
    const storage = root.querySelector(`[data-field="${fieldname}"]`);
    if (!fieldname || !storage) return;

    const ctx = canvas.getContext("2d");
    let drawing = false;

    function isSignatureLocked() {
      return canvas.dataset.signatureReadonly === "1";
    }

    function resizeCanvas() {
      const savedValue = storage.value || "";
      const rect = canvas.getBoundingClientRect();
      const ratio = window.devicePixelRatio || 1;

      if (!rect.width || !rect.height) return;

      canvas.width = rect.width * ratio;
      canvas.height = rect.height * ratio;

      ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
      ctx.lineWidth = 2;
      ctx.lineCap = "round";
      ctx.lineJoin = "round";
      ctx.strokeStyle = "#101828";
      ctx.clearRect(0, 0, rect.width, rect.height);

      if (savedValue && savedValue.indexOf("data:image") === 0) {
        const img = new Image();
        img.onload = function () {
          ctx.clearRect(0, 0, rect.width, rect.height);
          ctx.drawImage(img, 0, 0, rect.width, rect.height);
        };
        img.src = savedValue;
      }
    }

    function getPoint(e) {
      const rect = canvas.getBoundingClientRect();
      if (e.touches && e.touches.length) {
        return {
          x: e.touches[0].clientX - rect.left,
          y: e.touches[0].clientY - rect.top
        };
      }
      return {
        x: e.clientX - rect.left,
        y: e.clientY - rect.top
      };
    }

    function startDrawing(e) {
      if (isSignatureLocked()) {
        e.preventDefault();
        return;
      }

      e.preventDefault();
      drawing = true;

      const p = getPoint(e);
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
    }

    function draw(e) {
      if (isSignatureLocked()) {
        e.preventDefault();
        drawing = false;
        return;
      }

      if (!drawing) return;

      e.preventDefault();
      const p = getPoint(e);
      ctx.lineTo(p.x, p.y);
      ctx.stroke();
      saveSignature();
    }

    function stopDrawing(e) {
      if (isSignatureLocked()) {
        e.preventDefault();
        drawing = false;
        return;
      }

      if (!drawing) return;

      e.preventDefault();
      drawing = false;
      saveSignature();
    }

    function saveSignature() {
      if (isSignatureLocked()) return;
      storage.value = canvas.toDataURL("image/png");
    }

    canvas.addEventListener("mousedown", startDrawing);
    canvas.addEventListener("mousemove", draw);
    canvas.addEventListener("mouseup", stopDrawing);
    canvas.addEventListener("mouseleave", stopDrawing);

    canvas.addEventListener("touchstart", startDrawing, { passive: false });
    canvas.addEventListener("touchmove", draw, { passive: false });
    canvas.addEventListener("touchend", stopDrawing, { passive: false });

    setTimeout(resizeCanvas, 150);

    window.addEventListener("resize", function () {
      setTimeout(resizeCanvas, 150);
    });
  });

  root.querySelectorAll(".cpc-clear-signature").forEach(function (btn) {
    if (btn.dataset.bound === "1") return;
    btn.dataset.bound = "1";

    btn.addEventListener("click", function () {
      if (btn.disabled) return;
      clearSignature(btn.dataset.clearSignature);
    });
  });

  updateSignatureAccessControl();
}


function redrawAllSignatures() {
  SIGNATURE_FIELDS.forEach(function (fieldname) { redrawSignature(fieldname); });
}

function clearSignature(fieldname) {
  const canvas = root.querySelector(`[data-signature-canvas="${fieldname}"]`);
  const storage = root.querySelector(`[data-field="${fieldname}"]`);

  if (!canvas || !storage) return;

  if (canvas.dataset.signatureReadonly === "1") {
    frappe.show_alert({
      message: "This signature is already submitted and cannot be changed.",
      indicator: "orange"
    });
    return;
  }

  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();

  ctx.clearRect(0, 0, rect.width, rect.height);
  storage.value = "";
}


function isSignatureFieldEditable(fieldname) {
  const stage = getApprovalStage();
  const finalStatus = String(getField("final_approval_status") || "").trim();
  const workflowStep = Number(currentWorkflowStep || 1);

  const isFinished =
    workflowStep >= 4 ||
    stage === APPROVAL_STAGES.APPROVED ||
    stage === APPROVAL_STAGES.REJECTED ||
    finalStatus === "Approved" ||
    finalStatus === "Rejected";

  if (isFinished) return false;

  // Request signatures are editable only while creating a new request.
  // Once the request is saved/submitted, transferor/transferee signatures are locked.
  if (fieldname === "transferor_signature" || fieldname === "transferee_signature") {
    return !currentDocName && workflowStep === 1;
  }

  // Centre Manager signature is editable only during Centre Manager pending stage.
  if (fieldname === "centre_manager_signature") {
    return workflowStep === 2 &&
      stage === APPROVAL_STAGES.CM_PENDING &&
      !String(getField("centre_manager_decision") || "").trim();
  }

  // Operations Manager signature is editable only during Operations Manager pending stage.
  if (fieldname === "operations_manager_signature") {
    return workflowStep === 2 &&
      stage === APPROVAL_STAGES.OM_PENDING &&
      !String(getField("operations_manager_decision") || "").trim();
  }

  // Audit signature is editable only during Audit pending stage.
  if (fieldname === "audit_team__corporate_team_signature") {
    return workflowStep === 3 &&
      stage === APPROVAL_STAGES.AUDIT_PENDING &&
      !String(getField("audit_team_decision") || "").trim();
  }

  // COO / Management signature is editable only during COO pending stage.
  if (fieldname === "operations_coo__management_signature") {
    return workflowStep === 3 &&
      stage === APPROVAL_STAGES.COO_PENDING &&
      !finalStatus;
  }

  return false;
}

function updateSignatureAccessControl() {
  SIGNATURE_FIELDS.forEach(function (fieldname) {
    const canvas = root.querySelector(`[data-signature-canvas="${fieldname}"]`);
    const storage = root.querySelector(`[data-field="${fieldname}"]`);
    const clearBtn = root.querySelector(`[data-clear-signature="${fieldname}"]`);

    if (!canvas || !storage) return;

    const editable = isSignatureFieldEditable(fieldname);
    const readonly = !editable;

    canvas.dataset.signatureReadonly = readonly ? "1" : "0";
    canvas.classList.toggle("cpc-signature-readonly", readonly);

    const fieldWrap = canvas.closest(".cpc-signature-field");
    if (fieldWrap) {
      fieldWrap.classList.toggle("cpc-signature-field-readonly", readonly);
    }
    canvas.setAttribute("aria-disabled", readonly ? "true" : "false");

    if (readonly) {
      canvas.title = "Submitted signature - view only";
    } else {
      canvas.title = "Draw signature here";
    }

    if (clearBtn) {
      clearBtn.disabled = readonly;
      clearBtn.classList.toggle("hidden", readonly);
    }

    const help = canvas.parentElement
      ? canvas.parentElement.querySelector(".cpc-signature-help")
      : null;

    if (help) {
      help.textContent = readonly
        ? "Submitted signature — view only. This cannot be edited."
        : "Signature captured below. Use Clear to redo the signature.";
    }
  });
}

