function activateC2CMode(modeIndex) {
  modeIndex = Number(modeIndex || 0);

  root.querySelectorAll(".mode").forEach(function (mode, index) {
    mode.classList.toggle("on", index === modeIndex);
  });

  root.querySelectorAll(".mnav").forEach(function (tab, index) {
