  });

  const formTopbar = root.querySelector("#formTopbar");

  if (formTopbar && modeIndex !== 0) {
    formTopbar.classList.add("hidden");
  }
}


function getC2CUrlParam(name) {
  try {
    return new URLSearchParams(window.location.search).get(name) || "";
  } catch (error) {
    return "";
  }
}


function normalizeC2CExternalRole(value) {
  value = String(value || "").trim().toLowerCase();

  if (
    value === "cm" ||
    value === "centre_manager" ||
    value === "center_manager" ||
    value === "centre manager" ||
    value === "center manager"
  ) {
    return "centre_manager";
  }

  if (
    value === "ops" ||
    value === "audit" ||
    value === "audit_team" ||
    value === "operations_manager" ||
    value === "operations manager"
  ) {
    return "audit_team";
  }

  if (
    value === "coo" ||
    value === "operations_coo" ||
    value === "management" ||
    value === "operations coo"
  ) {
    return "operations_coo";
  }

  return "";
}


function readC2CExternalRoute() {
  var requestedTab = String(getC2CUrlParam("tab") || "")
    .trim()
    .toLowerCase();

  var requestName = String(
    getC2CUrlParam("request") ||
    getC2CUrlParam("req") ||
    getC2CUrlParam("coo_request") ||
    ""
  ).trim();

  var role = normalizeC2CExternalRole(
    getC2CUrlParam("role")
  );

  if (
    requestedTab === "approval" ||
    requestedTab === "approvals" ||
    requestedTab === "2"
  ) {
    requestedTab = "approval";
  } else if (
    requestedTab === "all" ||
    requestedTab === "requests" ||
    requestedTab === "all_requests" ||
    requestedTab === "1" ||
    String(getC2CUrlParam("coo_view") || "").toLowerCase() === "all_requests"
  ) {
    requestedTab = "all";
  } else {
    requestedTab = "";
  }

  return {
    tab: requestedTab,
    role: role,
    request: requestName
  };
}


function setC2CApprovalRoleFromExternalRoute(role) {
  role = normalizeC2CExternalRole(role);

  var roleEl = root.querySelector("#approver-role");

  if (
    roleEl &&
    role &&
    Array.prototype.some.call(roleEl.options || [], function (option) {
      return option.value === role;
    })
  ) {
    roleEl.value = role;
  }

  return role;
}



function resetC2CExternalBranchFilterToAll() {
  if (!requestBranchFilter) {
    return;
  }

  var allOptionExists =
    Array.prototype.some.call(
      requestBranchFilter.options || [],
      function (option) {
        return String(
          option.value || ""
        ) === "";
      }
    );

  if (allOptionExists) {
    requestBranchFilter.value = "";
  }
}



function initializeC2CPageFromExternalRoute(route) {
  route = route || {};

  /*
   * COO / All Approvals links must not inherit an old branch selection.
   * Authorised management users receive the All Branches option.
   */
  if (
    route.tab === "approval" ||
    route.tab === "all" ||
    route.request
  ) {
    resetC2CExternalBranchFilterToAll();
  }

  /*
   * Redirected records are opened directly first.
   * Do not wait for the 500-row request list before showing the item.
   */
  if (route.tab === "approval") {
    var role =
      setC2CApprovalRoleFromExternalRoute(
        route.role
      ) ||
      "centre_manager";

    activateC2CMode(2);

    if (route.request) {
      openC2CApprovalRequest(
        route.request,
        role
      );
    } else {
      refreshC2CApprovalDashboard({
        showLoading: true,
        clearDetail: true
      });
    }

    return;
  }

  if (route.tab === "all") {
    activateC2CMode(1);

    if (route.request) {
      openC2CAllRequestsRequest(
        route.request
      );
    } else {
      loadRequests();
    }

    return;
  }

  /*
   * Older links may contain only ?request=...
   * Fetch the exact record once and route it according to its live state.
   */
  if (route.request) {
    fetchC2CRequestForDashboard(
      route.request,
      function (doc) {
        if (!doc || !doc.name) {
          activateC2CMode(1);

          var detailPanel =
            root.querySelector("#ag-detail");

          if (detailPanel) {
            detailPanel.innerHTML = `
              <div class="notice notice-red">
                Unable to open the selected C2C request:
                ${escapeHtml(route.request)}
              </div>
            `;
          }

          return;
        }

        var pendingRole =
          getPendingRoleForC2CRequest(doc);

        var isHistorical =
          isC2CRequestRejectedForDashboard(doc) ||
          isC2CProcessCompleted(doc) ||
          isC2CAutomationFailed(doc) ||
          !pendingRole;

        if (isHistorical) {
          openC2CAllRequestsRequest(
            route.request,
            doc
          );
          return;
        }

        openC2CApprovalRequest(
          route.request,
          pendingRole,
          doc
        );
      }
    );

    return;
  }

  /*
   * Normal page opening defaults to Approval Dashboard. Use the dashboard
   * refresh wrapper so the list is rendered explicitly after data arrives.
   */
  refreshC2CApprovalDashboard({
    showLoading: true,
    clearDetail: true
  });
}

function mergeC2CRequestIntoList(doc) {
  if (!doc || !doc.name) {
    return null;
  }

  var existingIndex = (allRequests || []).findIndex(function (row) {
    return row.name === doc.name;
  });

  var summary = Object.assign({}, doc, {
    current_tab_step: Number(doc.current_tab_step || 1),
    total_paid_amount: Number(doc.total_paid_amount || 0),
    balance_amount: Number(doc.balance_amount || 0)
  });

  if (existingIndex >= 0) {
    allRequests[existingIndex] = Object.assign(
      {},
      allRequests[existingIndex],
      summary
    );
  } else {
    allRequests.unshift(summary);
  }

  return summary;
}


function fetchC2CRequestForDashboard(requestName, callback) {
  requestName = String(requestName || "").trim();

  if (!requestName) {
    callback(null);
    return;
  }

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: DOCTYPE,
      name: requestName
    },
    callback: function (response) {
      var doc = response.message || null;

      if (doc && doc.name) {
        mergeC2CRequestIntoList(doc);
      }

      callback(doc);
    },
    error: function (error) {
      void 0;
      callback(null);
    }
  });
}



function openC2CAllRequestsRequest(
  requestName,
  prefetchedDoc
) {
  requestName = String(
    requestName || ""
  ).trim();

  if (!requestName) {
    activateC2CMode(1);
    loadRequests();
    return;
  }

  var statusEl = root.querySelector("#ag-status");

  if (statusEl) {
    statusEl.value = "";
  }

  if (requestSearchInput) {
    requestSearchInput.value = "";
  }

  if (requestBranchFilter) {
    requestBranchFilter.value = "";
  }

  c2cRoutedAllRequestName = requestName;
  c2cRoutedAllRequestDoc = null;
  c2cPreserveAllRequestDetail = true;

  c2cRoutedApprovalName = "";
  c2cRoutedApprovalDoc = null;
  c2cPreserveApprovalDetail = false;

  activateC2CMode(1);

  var listPanel = root.querySelector("#ag-list");
  var detailPanel = root.querySelector("#ag-detail");

  if (
    listPanel &&
    !String(listPanel.innerHTML || "").trim()
  ) {
    listPanel.innerHTML = `
      <div class="notice notice-blue">
        Loading request list...
      </div>
    `;
  }

  if (detailPanel) {
    detailPanel.dataset.docname = requestName;
    detailPanel.innerHTML = `
      <div class="cpc-detail-loading">
        Loading selected C2C request...
      </div>
    `;
  }

  function showExactRequest(doc) {
    if (!doc || !doc.name) {
      if (detailPanel) {
        detailPanel.removeAttribute("data-docname");
        detailPanel.innerHTML = `
          <div class="notice notice-red">
            Unable to find the selected C2C request:
            ${escapeHtml(requestName)}
          </div>
        `;
      }

      return;
    }

    mergeC2CRequestIntoList(doc);

    c2cRoutedAllRequestDoc = doc;
    c2cRoutedAllRequestName = doc.name;
    c2cPreserveAllRequestDetail = true;

    if (detailPanel) {
      renderC2CRequestDetailPanel(
        doc,
        detailPanel
      );

      detailPanel.dataset.docname = doc.name;
    }

    /*
     * Refresh the surrounding request list after the exact detail is ready.
     * Automatic list/detail rendering is suppressed until the full record
     * has been merged back into the refreshed summaries.
     */
    loadRequests(
      function () {
        mergeC2CRequestIntoList(doc);

        var rows =
          getBranchFilteredC2CRequests()
            .filter(function (row) {
              return c2cP2PMatchesStatusFilter(
                row,
                ""
              );
            })
            .filter(function (row) {
              return c2cP2PDoesRequestMatchSearch(
                row,
                ""
              );
            });

        var requestIndex =
          rows.findIndex(function (row) {
            return row.name === doc.name;
          });

        requestCurrentPage =
          requestIndex >= 0
            ? Math.floor(
                requestIndex /
                REQUESTS_PER_PAGE
              ) + 1
            : 1;

        renderAllRequestsPanel();

        window.requestAnimationFrame(
          function () {
            var selectedCard =
              root.querySelector(
                '.cpc-request-card[data-docname="' +
                cssEscapeC2CValue(doc.name) +
                '"]'
              );

            if (!selectedCard) return;

            selectedCard.classList.add("active");
            selectedCard.classList.add("sel");
            selectedCard.classList.add(
              "cpc-external-request-highlight"
            );

            selectedCard.scrollIntoView({
              behavior: "smooth",
              block: "center"
            });

            window.setTimeout(function () {
              selectedCard.classList.remove(
                "cpc-external-request-highlight"
              );
            }, 2600);
          }
        );
      },
      {
        showListLoading: false,
        clearPagination: false,
        skipAllRequestsRender: true,
        skipApprovalRender: true,
        resetPage: false,
        preserveExistingDataOnError: true,
        showListError: true
      }
    );
  }

  if (
    prefetchedDoc &&
    prefetchedDoc.name === requestName
  ) {
    showExactRequest(prefetchedDoc);
    return;
  }

  fetchC2CRequestForDashboard(
    requestName,
    showExactRequest
  );
}

function cssEscapeC2CValue(value) {
  value = String(value || "");

  if (
    window.CSS &&
    typeof window.CSS.escape === "function"
  ) {
    return window.CSS.escape(value);
  }

  return value.replace(/["\\]/g, "\\$&");
}



function openC2CApprovalRequest(
  requestName,
  role,
  prefetchedDoc
) {
  requestName = String(
    requestName || ""
  ).trim();

  role =
    normalizeC2CExternalRole(role) ||
    "centre_manager";

  setC2CApprovalRoleFromExternalRoute(
    role
  );

  activateC2CMode(2);

  if (!requestName) {
    refreshC2CApprovalDashboard({
      showLoading: true,
      clearDetail: true
    });
    return;
  }

  c2cRoutedApprovalName = requestName;
  c2cRoutedApprovalDoc = null;
  c2cPreserveApprovalDetail = true;

  c2cRoutedAllRequestName = "";
  c2cRoutedAllRequestDoc = null;
  c2cPreserveAllRequestDetail = false;

  var listPanel = root.querySelector("#approval-list");
  var actionPanel = root.querySelector(
    "#approval-action-panel"
  );

  if (listPanel) {
    listPanel.innerHTML = `
      <div class="notice notice-blue">
        Loading current approval requests...
      </div>
    `;
  }

  if (actionPanel) {
    actionPanel.dataset.docname = requestName;
    actionPanel.innerHTML = `
      <div class="cpc-approval-empty">
        Loading selected C2C approval request...
      </div>
    `;
  }

  function showExactApproval(doc) {
    if (!doc || !doc.name) {
      if (actionPanel) {
        actionPanel.removeAttribute("data-docname");
        actionPanel.innerHTML = `
          <div class="notice notice-red">
            Unable to open the selected C2C request:
            ${escapeHtml(requestName)}
          </div>
        `;
      }

      return;
    }

    var pendingRole =
      getPendingRoleForC2CRequest(doc);

    var isHistorical =
      isC2CRequestRejectedForDashboard(doc) ||
      isC2CProcessCompleted(doc) ||
      isC2CAutomationFailed(doc) ||
      !pendingRole;

    /*
     * Approved, rejected, completed and failed records belong in
     * All Requests, even when an older link says tab=approval.
     */
    if (isHistorical) {
      openC2CAllRequestsRequest(
        doc.name,
        doc
      );
      return;
    }

    if (pendingRole !== role) {
      role = pendingRole;

      setC2CApprovalRoleFromExternalRoute(
        role
      );
    }

    if (!canC2CViewApprovalRole(role)) {
      c2cPreserveApprovalDetail = false;
      c2cRoutedApprovalDoc = null;
      renderC2CApprovalAccessDenied(role);
      return;
    }

    mergeC2CRequestIntoList(doc);

    c2cRoutedApprovalDoc = doc;
    c2cRoutedApprovalName = doc.name;
    c2cPreserveApprovalDetail = true;

    /*
     * Render the full fetched record immediately.
     * Do not wait for or click a card in the pending-list DOM.
     */
    openC2CApprovalActionPanel(
      doc,
      role
    );

    if (actionPanel) {
      actionPanel.dataset.docname = doc.name;
    }

    /*
     * Load the surrounding queue afterward without clearing the detail.
     */
    loadRequests(
      function () {
        mergeC2CRequestIntoList(doc);

        var pendingRows =
          getBranchFilteredC2CRequests()
            .filter(function (row) {
              if (!row || !row.name) return false;
              if (c2cP2PIsRejected(row)) return false;
              if (c2cP2PIsCompleted(row)) return false;

              if (
                typeof isC2CAutomationFailed ===
                  "function" &&
                isC2CAutomationFailed(row)
              ) {
                return false;
              }

              return (
                getPendingRoleForC2CRequest(row) === role
              );
            });

        var requestIndex =
          pendingRows.findIndex(function (row) {
            return row.name === doc.name;
          });

        c2cP2PApprovalPage =
          requestIndex >= 0
            ? Math.floor(
                requestIndex /
                C2C_P2P_APPROVAL_PER_PAGE
              ) + 1
            : 1;

        renderApprovalDashboard();

        window.requestAnimationFrame(
          function () {
            var selectedItem =
              root.querySelector(
                '.cpc-approval-request-item' +
                '[data-docname="' +
                cssEscapeC2CValue(doc.name) +
                '"]'
              );

            if (!selectedItem) return;

            selectedItem.classList.add("active");
            selectedItem.classList.add("sel");
            selectedItem.classList.add(
              "cpc-external-request-highlight"
            );

            selectedItem.scrollIntoView({
              behavior: "smooth",
              block: "center"
            });

            window.setTimeout(function () {
              selectedItem.classList.remove(
                "cpc-external-request-highlight"
              );
            }, 2600);
          }
        );
      },
      {
        showListLoading: false,
        clearPagination: false,
        skipAllRequestsRender: true,
        skipApprovalRender: true,
        resetPage: false,
        preserveExistingDataOnError: true,
        showListError: true
      }
    );
  }

  if (
    prefetchedDoc &&
    prefetchedDoc.name === requestName
  ) {
    showExactApproval(prefetchedDoc);
    return;
  }

  fetchC2CRequestForDashboard(
    requestName,
    showExactApproval
  );
}


function loadRequests(afterLoad, options) {
  options = options || {};

  const requestSequence = ++c2cRequestLoadSequence;
  const listTarget = root.querySelector("#ag-list") || requestListBody;
  const approvalList = root.querySelector("#approval-list");

  if (
    listTarget &&
    options.showListLoading !== false
  ) {
    listTarget.innerHTML =
      "<div class='notice notice-blue' style='opacity:.7'>Loading requests...</div>";
  }

  if (
    approvalList &&
    options.showApprovalLoading === true
  ) {
    approvalList.innerHTML =
      "<div class='notice notice-blue' style='opacity:.7'>Loading pending approvals...</div>";
  }

  if (
    requestPagination &&
    options.clearPagination !== false
  ) {
    requestPagination.innerHTML = "";
  }

  /*
   * IMPORTANT:
   * Fetch the full ERPNext-permitted request set first.
   * Do NOT apply the shared branch dropdown in this get_list call.
   * All Requests and Approval Dashboard apply their own client-side filters.
   */
  const primaryFields = [
    "name",
    "owner",
    "creation",
    "modified",
    "modified_by",
    "docstatus",
    "idx",
    "date",
    "branch",
    "receiving_branch",
    "transfer_type",
    "client_full_name",
    "name1",
    "client_name",
    "transferee_full_name",
    "mobile_number",
    "phone_number",
    "original_invoice__bill_numbers",
    "total_paid_amount",
    "balance_amount",
    "conversion_charges_amount",
    "current_tab_step",
    "conversion_status",
    "approval_display_status",
    "approval_stage",
    "final_approval_status",
    "automation_status",
    "package_transfer_applied",
    "created_transfer_ledger_count",
    "centre_manager_decision",
    "centre_manager_name",
    "centre_manager_date",
    "audit_team_decision",
    "audit_team__corporate_team_name",
    "audit_team__corporate_team_date",
    "operations_coo__management_name",
    "operations_coo__management_date",
    "rejected_by_role",
    "rejected_by_name"
  ];

  function normalizeDecision(value) {
    value = String(value || "").trim();
    if (value === "Approve") return "Approved";
    if (value === "Reject") return "Rejected";
    return value;
  }

  function normalizeRows(rows) {
    return (rows || []).map(function (doc) {
      doc = doc || {};

      return Object.assign({}, doc, {
        name: doc.name || "",
        owner: doc.owner || "",
        creation: doc.creation || "",
        modified: doc.modified || "",
        modified_by: doc.modified_by || "",
        docstatus: Number(doc.docstatus || 0),
        idx: Number(doc.idx || 0),
        date: doc.date || "",
        branch: doc.branch || "",
        receiving_branch: doc.receiving_branch || "",
        transfer_type: doc.transfer_type || "",
        client_full_name: doc.client_full_name || "",
        name1: doc.name1 || "",
        client_name: doc.client_name || "",
        transferee_full_name: doc.transferee_full_name || "",
        mobile_number: doc.mobile_number || "",
        phone_number: doc.phone_number || "",
        original_invoice__bill_numbers:
          doc.original_invoice__bill_numbers || "",
        total_paid_amount: Number(doc.total_paid_amount || 0),
        balance_amount: Number(doc.balance_amount || 0),
        conversion_charges_amount:
          Number(doc.conversion_charges_amount || 0),
        current_tab_step: Number(doc.current_tab_step || 1),
        conversion_status: doc.conversion_status || "",
        approval_display_status: doc.approval_display_status || "",
        approval_stage: doc.approval_stage || "",
        final_approval_status:
          normalizeDecision(doc.final_approval_status),
        automation_status: doc.automation_status || "",
        package_conversion_applied:
          Number(doc.package_conversion_applied || 0),
        package_transfer_applied:
          Number(doc.package_transfer_applied || 0),
        created_transfer_ledger_count:
          Number(doc.created_transfer_ledger_count || 0),
        centre_manager_decision:
          normalizeDecision(doc.centre_manager_decision),
        centre_manager_name: doc.centre_manager_name || "",
        centre_manager_date: doc.centre_manager_date || "",
        audit_team_decision:
          normalizeDecision(doc.audit_team_decision),
        audit_team__corporate_team_name:
          doc.audit_team__corporate_team_name || "",
        audit_team__corporate_team_date:
          doc.audit_team__corporate_team_date || "",
        operations_coo__management_name:
          doc.operations_coo__management_name || "",
        operations_coo__management_date:
          doc.operations_coo__management_date || "",
        rejected_by_role: doc.rejected_by_role || "",
        rejected_by_name: doc.rejected_by_name || ""
      });
    });
  }

  function finishSuccess(rows, usedFallback) {
    if (requestSequence !== c2cRequestLoadSequence) return;

    allRequests = normalizeRows(rows);

    if (options.resetPage !== false) {
      requestCurrentPage = 1;
    }

    updateRequestNavBadge();

    void 0;

    if (!options.skipAllRequestsRender) {
      renderAllRequestsPanel();
    }

    const mode2 = root.querySelector("#mode-2");
    if (
      mode2 &&
      mode2.classList.contains("on") &&
      !options.skipApprovalRender
    ) {
      renderApprovalDashboard();
    }

    if (typeof afterLoad === "function") {
      afterLoad(allRequests);
    }
  }

  function finishError(err) {
    if (requestSequence !== c2cRequestLoadSequence) return;

    void 0;

    if (!options.preserveExistingDataOnError) {
      allRequests = [];
      updateRequestNavBadge();
    }

    if (
      listTarget &&
      options.showListError !== false
    ) {
      listTarget.innerHTML = `
        <div class="notice notice-red">
          Unable to load requests. Please check browser console for the ERPNext response.
        </div>
      `;
    }

    if (
      approvalList &&
      options.showApprovalError !== false
    ) {
      approvalList.innerHTML = `
        <div class="notice notice-red">
          Unable to load pending approvals.
        </div>
      `;
    }

    if (
      requestPagination &&
      options.clearPagination !== false
    ) {
      requestPagination.innerHTML = "";
    }

    if (typeof afterLoad === "function") {
      afterLoad(
        options.preserveExistingDataOnError
          ? allRequests
          : []
      );
    }
  }

  function fetchRows(fields, usedFallback) {
    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: DOCTYPE,
        fields: fields,
        order_by: "modified desc",
        limit_start: 0,
        limit_page_length: 5000
      },
      callback: function (r) {
        finishSuccess(r.message || [], usedFallback);
      },
      error: function (err) {
        if (requestSequence !== c2cRequestLoadSequence) return;

        if (!usedFallback) {
          void 0;
          fetchRows(["*"], true);
          return;
        }

        finishError(err);
      }
    });
  }

  fetchRows(primaryFields, false);
}

function refreshRequestBranchFilterFromRows() {
  if (!requestBranchFilter) return;

  const currentValue = requestBranchFilter.value || "";

  const branchMap = {};

  (allRequests || []).forEach(function (row) {
    if (row.branch) {
      branchMap[row.branch] = true;
    }

    if (row.receiving_branch) {
      branchMap[row.receiving_branch] = true;
    }
  });

  const branches = Object.keys(branchMap).sort();

  requestBranchFilter.innerHTML =
    '<option value="">All Branches</option>' +
    branches.map(function (branch) {
      return '<option value="' + escapeHtml(branch) + '">' + escapeHtml(branch) + '</option>';
    }).join("");

  if (currentValue && branchMap[currentValue]) {
    requestBranchFilter.value = currentValue;
  } else {
    requestBranchFilter.value = "";
  }
}



function updateRequestNavBadge() {
  const navBadge = root.querySelector("#nav-cnt");
  if (!navBadge) return;

  const pending = (allRequests || []).filter(function (row) {
    const finalStatus = String(row.final_approval_status || "").trim();
    const automationStatus = String(row.automation_status || "").trim();

    return finalStatus !== "Approved" &&
      finalStatus !== "Rejected" &&
      automationStatus !== "Process Completed";
  }).length;

  navBadge.textContent = pending;
}

function normalizeC2CBranchValue(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ");
}

function getSelectedRequestBranchFilter() {
  if (!requestBranchFilter) return "";
  return String(requestBranchFilter.value || "").trim();
}

function c2cRequestMatchesSelectedBranch(row) {
  const selectedBranch = getSelectedRequestBranchFilter();

  // Empty value means All Branches.
  if (!selectedBranch) return true;

  const selected = normalizeC2CBranchValue(selectedBranch);
  const fromBranch = normalizeC2CBranchValue(row && row.branch);
  const toBranch = normalizeC2CBranchValue(row && row.receiving_branch);

  return fromBranch === selected || toBranch === selected;
}

function getBranchFilteredC2CRequests() {
  return (allRequests || []).filter(function (row) {
    return c2cRequestMatchesSelectedBranch(row);
  });
}



