function renderC2CAllRequestDetail(docname, row) {
  const panel = root.querySelector("#ag-detail");
  if (!panel) return;

  if (!docname) {
    panel.innerHTML = `<div class="cpc-detail-empty">Request ID not found.</div>`;
    return;
  }

  panel.innerHTML = `
    <div class="cpc-detail-loading">
      Loading request details and approval timeline...
    </div>
  `;

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: DOCTYPE,
      name: docname
    },
    callback: function (r) {
      const doc = r.message || row || {};

    /* Sync full fetched status back into left-side cached list */
    allRequests = (allRequests || []).map(function (item) {
      if (item.name !== doc.name) return item;

      return Object.assign({}, item, {
        automation_status: doc.automation_status || item.automation_status || "",
        package_conversion_applied: Number(doc.package_conversion_applied || 0),
        package_transfer_applied: Number(doc.package_transfer_applied || 0),
        created_transfer_ledger_count: Number(doc.created_transfer_ledger_count || 0),
        approval_stage: doc.approval_stage || item.approval_stage || "",
        conversion_status: doc.conversion_status || item.conversion_status || "",
        approval_display_status: doc.approval_display_status || item.approval_display_status || "",
        final_approval_status: doc.final_approval_status || item.final_approval_status || ""
      });
    });

    renderC2CRequestDetailPanel(doc, panel);
    panel.dataset.docname = doc.name || docname;

    /* Update only the selected row status. Do not re-render full list here. */
    refreshC2CListItemStatus(doc);
    },
    error: function (err) {
      void 0;
      panel.innerHTML = `
        <div class="notice notice-red">
          Unable to load full request detail. Please try again.
        </div>
      `;
    }
  });
}



function renderC2CApprovalTimeline(doc) {
  const entries = buildC2CTimelineEntries(doc);

  if (!entries.length) {
    return `<div class="cpc-detail-empty">No approval activity found.</div>`;
  }

  return entries.map(function (entry, index) {
    const isLast = index === entries.length - 1;

    return `
      <div class="cpc-timeline-item">
        ${!isLast ? `<div class="cpc-timeline-line"></div>` : ``}

        <div class="cpc-timeline-dot" style="border-color:${entry.color};background:${entry.color}18">
          ${entry.icon}
        </div>

        <div class="cpc-timeline-content">
          <div class="cpc-timeline-title" style="color:${entry.color}">
            ${escapeHtml(entry.title)}
          </div>

          ${entry.desc ? `
            <div class="cpc-timeline-desc">${escapeHtml(entry.desc)}</div>
          ` : ``}

          <div class="cpc-timeline-meta">
            ${escapeHtml(c2cTimelineDisplayName(entry.by) || "System")}
            ${entry.time ? " · " + escapeHtml(formatDateTime(entry.time) || formatDate(entry.time)) : ""}
          </div>
        </div>
      </div>
    `;
  }).join("");
}

function buildC2CTimelineEntries(doc) {
  const entries = [];

  const transferRows = getC2CChildRows(doc, "remaining_sessions_package_details", REMAINING_CHILD_DOCTYPE);
  const totalTransferAmount = getC2CTransferAmount(transferRows);
  const transferSummary = getC2CTransferSummary(transferRows);

  entries.push({
    icon: "📋",
    color: "#0D2B4E",
    title: "Request Created",
    desc: "Transferor: " + (doc.client_full_name || "-") + " → Transferee: " + (doc.transferee_full_name || doc.client_name || "-"),
    by: doc.owner || "Staff",
    time: doc.creation || doc.date
  });

  if (
    Number(doc.current_tab_step || 1) > 1 ||
    doc.transferor_signature ||
    doc.transferee_signature ||
    transferRows.length
  ) {
    entries.push({
      icon: "📝",
      color: "#0D2B4E",
      title: "Request Details Submitted",
      desc: transferSummary + " | Amount: " + c2cMoney(totalTransferAmount),
      by: doc.modified_by || doc.owner || "Staff",
      time: doc.modified || doc.date
    });
  }

  pushC2CApprovalEntry(entries, {
    icon: "🏢",
    role: "Centre Manager",
    decision: doc.centre_manager_decision,
    name: doc.centre_manager_name,
    date: doc.centre_manager_date,
    actionDateTime:
      c2cTimelineApprovalActionTime(
        doc,
        "centre_manager"
      ),
    remarks: doc.centre_manager_remarks
  });

  pushC2CApprovalEntry(entries, {
    icon: "⚙️",
    role: "Operations Manager",
    decision: doc.operations_manager_decision,
    name: doc.operations_manager_name,
    date: doc.operations_manager_date,
    remarks: doc.operations_manager_remarks
  });

  pushC2CApprovalEntry(entries, {
    icon: "🔎",
    role: "Audit Team / Corporate Team",
    decision: doc.audit_team_decision,
    name: doc.audit_team__corporate_team_name,
    date: doc.audit_team__corporate_team_date,
    actionDateTime:
      c2cTimelineApprovalActionTime(
        doc,
        "audit_team"
      ),
    remarks: doc.audit_team_remarks
  });

const safeFinalStatus = getC2CSafeFinalApprovalStatus(doc);

pushC2CApprovalEntry(entries, {
  icon: "✅",
  role: "Operations COO / Management",
  decision: safeFinalStatus,
  name: doc.operations_coo__management_name,
  date: doc.operations_coo__management_date,
  remarks: doc.office_remarks_any
});

  const autoStatus = String(doc.automation_status || "").trim();
  const finalStatus = getC2CSafeFinalApprovalStatus(doc);
  const approvalStage = getC2CApprovalStageValue(doc);

  if (isC2CProcessCompleted(doc)) {
    entries.push({
      icon: "🏁",
      color: "#1E7A34",
      title: "Process Completed",
      desc: getC2CAutomationLogLine(doc) || "Package transfer automation completed.",
      by: "System",
      time: doc.modified
    });
  } else if (isC2CAutomationFailed(doc)) {
    entries.push({
      icon: "⚠️",
      color: "#B8860B",
      title: "Automation Failed",
      desc: getC2CAutomationLogLine(doc) || "Please check automation logs.",
      by: "System",
      time: doc.modified
    });
  } else if (finalStatus === "Approved") {
    entries.push({
      icon: "⏳",
      color: "#B8860B",
      title: "Awaiting System Processing",
      desc: autoStatus || "Final approval completed. Automation not completed yet.",
      by: "System",
      time: doc.modified
    });
  } else if (finalStatus !== "Rejected" && approvalStage && approvalStage !== APPROVAL_STAGES.APPROVED) {
    entries.push({
      icon: "⏳",
      color: "#B8860B",
      title: "Awaiting: " + approvalStage,
      desc: "Current pending approval stage.",
      by: "System",
      time: doc.modified
    });
  }

  if (doc.rejected_by_role || doc.rejected_by_name || doc.rejection_remarks) {
    entries.push({
      icon: "❌",
      color: "#C00000",
      title: "Rejection Details",
      desc: [
        doc.rejected_by_role ? "Role: " + doc.rejected_by_role : "",
        doc.rejected_by_name ? "By: " + doc.rejected_by_name : "",
        doc.rejection_remarks ? "Remarks: " + doc.rejection_remarks : ""
      ].filter(Boolean).join(" | "),
      by: doc.rejected_by_name || "Approver",
      time: doc.modified
    });
  }

  return entries;
}

function pushC2CApprovalEntry(entries, data) {
  const decision = String(data.decision || "").trim();

  if (!decision || decision === "Pending") return;

  const isRejected = decision === "Rejected";
  const color = isRejected ? "#C00000" : "#1E7A34";

  entries.push({
    icon: data.icon || "✓",
    color: color,
    title: data.role + " — " + decision,
    desc: data.remarks || "",
    by: data.name || data.role,
    time: data.date
  });
}

