// C2C SAFE STATUS HELPERS
// Required by request list + approval dashboard
// ============================================================

function getToday() {
  try {
    return frappe.datetime.get_today();
  } catch (e) {
    return new Date().toISOString().slice(0, 10);
  }
}


function isC2CFinalApprovalActuallyReached(doc) {
  if (!doc) return false;

  var step = Number(doc.current_tab_step || 1);
  var stage = String(doc.approval_stage || "").trim();
  var conversionStatus = String(doc.conversion_status || "").trim();
  var displayStatus = String(doc.approval_display_status || "").trim();
  var automationStatus = String(doc.automation_status || "").trim();
  var cooActionDateTime = String(doc.custom_coo_management_action_datetime || "").trim();
  var cooName = String(doc.operations_coo__management_name || "").trim();
  var cooDate = String(doc.operations_coo__management_date || "").trim();

  /*
   * Do NOT use final_approval_status itself as proof that final approval was
   * reached. A fresh optional Select can contain its first option (Approved)
   * even while the request is still at Centre Manager stage.
   */
  if (step >= 4) return true;
  if (stage === APPROVAL_STAGES.APPROVED) return true;
  if (stage === APPROVAL_STAGES.REJECTED) return true;
  if (conversionStatus === "Approved") return true;
  if (conversionStatus === "Rejected") return true;
  if (conversionStatus === "Completed") return true;
  if (/Approved\s*\/\s*Pending Package Transfer/i.test(displayStatus)) return true;
  if (/Rejected\s*\/\s*Skipped/i.test(displayStatus)) return true;
  if (/Process Completed/i.test(displayStatus)) return true;
  if (Number(doc.package_transfer_applied || 0) === 1) return true;
  if (automationStatus === "Process Completed") return true;
  if (automationStatus === "Skipped") return true;
  if (cooActionDateTime) return true;
  if (cooName && cooDate && !/Pending/i.test(stage)) return true;

  return false;
}


function getC2CSafeFinalApprovalStatus(doc) {
  if (!doc) return "";

  var finalStatus = String(doc.final_approval_status || "").trim();

  if (!finalStatus) return "";

  // Only trust final approval status when final stage is actually reached.
  // This prevents old/partial values from showing as final too early.
  if (!isC2CFinalApprovalActuallyReached(doc)) {
    return "";
  }

  if (finalStatus === "Approved") return "Approved";
  if (finalStatus === "Rejected") return "Rejected";

  return "";
}


function isC2CAwaitingSystemProcessing(doc) {
  if (!doc) return false;

  var safeFinalStatus = getC2CSafeFinalApprovalStatus(doc);
  var approvalStage = String(doc.approval_stage || "").trim();
  var conversionStatus = String(doc.conversion_status || "").trim();
  var automationStatus = String(doc.automation_status || "").trim();
  var transferApplied = Number(doc.package_transfer_applied || 0);

  if (transferApplied === 1) return false;
  if (automationStatus === "Process Completed") return false;
  if (automationStatus === "Failed") return false;
  if (automationStatus === "Skipped") return false;

  /* Pending Final Approval is also used at CM/Audit stages. */
  return safeFinalStatus === "Approved" ||
    approvalStage === APPROVAL_STAGES.APPROVED ||
    (conversionStatus === "Approved" && isC2CFinalApprovalActuallyReached(doc)) ||
    (automationStatus === "Processing" && isC2CFinalApprovalActuallyReached(doc));
}

function getC2CRequestStatusLabel(doc) {
  if (isC2CProcessCompleted(doc)) return "Process Completed";
  if (isC2CAutomationFailed(doc)) return "Automation Failed";

  const finalStatus = getC2CSafeFinalApprovalStatus(doc);
  const approvalStage = getC2CApprovalStageValue(doc);

  if (finalStatus === "Rejected") {
    return "Rejected";
  }

  if (isC2CAwaitingSystemProcessing(doc)) {
    return "Approved - Awaiting System Processing";
  }

  return approvalStage ||
    doc.conversion_status ||
    doc.approval_display_status ||
    getWorkflowLabel(doc.current_tab_step, finalStatus);
}

function getC2CRequestPillClass(doc) {
  if (isC2CProcessCompleted(doc)) return "p-g";
  if (isC2CAutomationFailed(doc)) return "p-r";

  const finalStatus = getC2CSafeFinalApprovalStatus(doc);

  if (finalStatus === "Rejected") {
    return "p-r";
  }

  if (isC2CAwaitingSystemProcessing(doc)) {
    return "p-o";
  }

  const label = String(getC2CRequestStatusLabel(doc) || "").toLowerCase();

  if (label.includes("reject") || label.includes("failed")) return "p-r";
  if (label.includes("pending") || label.includes("awaiting")) return "p-o";
  if (label.includes("approved")) return "p-g";

  return "p-n";
}

function getC2CChildRows(doc, fieldname, childDoctype) {
  if (!doc) return [];

  if (Array.isArray(doc[fieldname])) return doc[fieldname];

  let rows = [];

  Object.keys(doc).forEach(function (key) {
    if (!Array.isArray(doc[key])) return;

    doc[key].forEach(function (child) {
      if (child && child.doctype === childDoctype) rows.push(child);
    });
  });

  return rows;
}

function getC2CTransferAmount(rows) {
  return roundMoney((rows || []).reduce(function (sum, row) {
    return sum + Number(
      row.total_amount ||
      row.applied_amount ||
      row.balance_quantity_amount ||
      row.balance_amount ||
      0
    );
  }, 0));
}

function getC2CTransferSummary(rows) {
  rows = rows || [];

  const selectedRows = rows.filter(function (row) {
    return Number(row.converted_quantity || 0) > 0;
  });

  if (!selectedRows.length) return "No transfer rows saved yet.";

  const text = selectedRows.slice(0, 4).map(function (row) {
    return (row.therapy_plans_been_transferred || row.therapy_type || "Therapy") +
      " x" +
      Number(row.converted_quantity || 0);
  }).join(", ");

  if (selectedRows.length > 4) {
    return text + " +" + (selectedRows.length - 4) + " more";
  }

  return text;
}

function getC2CSourcePlans(packageRows, transferRows) {
  const names = [];

  (packageRows || []).forEach(function (row) {
    const plan = row.ses_erp_entry || row.seserp_entry || row.source_therapy_plan || "";
    if (plan && !names.includes(plan)) names.push(plan);
  });

  (transferRows || []).forEach(function (row) {
    const plan = row.source_therapy_plan || "";
    if (plan && !names.includes(plan)) names.push(plan);
  });

  return names.length ? names.join(", ") : "-";
}


// ============================================================
// C2C SALES INVOICE BILL VIEW
// P2P-style linked invoice buttons + Booked By
// Supports multiple source Therapy Plans and multiple invoices.
// ============================================================

var C2C_SALES_INVOICE_PRINT_FORMAT =
  "Consultaion Patient Sales Invoice";

var c2cLinkedInvoiceCache = {};
var c2cLinkedInvoicePending = {};

function getC2CSourcePlanList(doc) {
  doc = doc || {};

  var packageRows = getC2CChildRows(
    doc,
    "complete_package_details",
    COMPLETE_CHILD_DOCTYPE
  );

  var transferRows = getC2CChildRows(
    doc,
    "remaining_sessions_package_details",
    REMAINING_CHILD_DOCTYPE
  );

  var plans = [];

  function addPlan(value) {
    value = String(value || "").trim();
    if (!value || value === "-") return;
    if (plans.indexOf(value) === -1) {
      plans.push(value);
    }
  }

  (packageRows || []).forEach(function (row) {
    row = row || {};
    addPlan(
      row.ses_erp_entry ||
      row.seserp_entry ||
      row.source_therapy_plan ||
      row.therapy_plan ||
      row.therapy_plan_no ||
      row.plan_name ||
      ""
    );
  });

  (transferRows || []).forEach(function (row) {
    row = row || {};
    addPlan(
      row.source_therapy_plan ||
      row.therapy_plan ||
      row.ses_erp_entry ||
      row.seserp_entry ||
      row.therapy_plan_no ||
      ""
    );
  });

  if (!plans.length && doc.source_therapy_plans_text) {
    String(doc.source_therapy_plans_text || "")
      .split(/[,;\n]+/)
      .forEach(addPlan);
  }

  return plans;
}

function getC2CStoredInvoiceNameList(doc) {
  doc = doc || {};

  var raw = String(
    doc.original_invoice__bill_numbers || ""
  ).trim();

  if (!raw) return [];

  var out = [];

  raw.split(/[,;\n]+/).forEach(function (value) {
    value = String(value || "").trim();
    if (!value) return;
    if (out.indexOf(value) === -1) out.push(value);
  });

  return out;
}

function getC2CLinkedInvoiceCacheKey(doc) {
  var plans = getC2CSourcePlanList(doc)
    .slice()
    .sort();

  var storedInvoices = getC2CStoredInvoiceNameList(doc)
    .slice()
    .sort();

  return (
    plans.join("||") +
    "::" +
    storedInvoices.join("||")
  );
}

function getC2CSalesInvoicePrintUrl(invoiceName) {
  invoiceName = String(invoiceName || "").trim();
  if (!invoiceName) return "";

  return (
    window.location.origin +
    "/printview" +
    "?doctype=" + encodeURIComponent("Sales Invoice") +
    "&name=" + encodeURIComponent(invoiceName) +
    "&format=" + encodeURIComponent(
      C2C_SALES_INVOICE_PRINT_FORMAT
    ) +
    "&no_letterhead=0"
  );
}

function c2cInvoiceListFields() {
  return [
    "name",
    "posting_date",
    "therapy_plan_reference_id",
    "patient",
    "patient_name",
    "customer",
    "customer_name",
    "custom_referring_name",
    "ref_practitioner",
    "custom_healthcare_practitioner",
    "custom_doctor_name",
    "custom_doctor_id",
    "grand_total",
    "rounded_total",
    "outstanding_amount",
    "status"
  ];
}

function c2cUniqueInvoiceRows(invoices) {
  var seen = {};
  var unique = [];

  (invoices || []).forEach(function (invoice) {
    var name = String(invoice && invoice.name || "").trim();
    if (!name || seen[name]) return;
    seen[name] = true;
    unique.push(invoice);
  });

  return unique;
}

function fetchC2CLinkedSalesInvoices(doc, options) {
  doc = doc || {};
  options = options || {};

  var forceReload = options.forceReload === true;
  var sourcePlans = getC2CSourcePlanList(doc);
  var storedInvoiceNames = getC2CStoredInvoiceNameList(doc);
  var cacheKey = getC2CLinkedInvoiceCacheKey(doc);

  if (
    !sourcePlans.length &&
    !storedInvoiceNames.length
  ) {
    return Promise.resolve([]);
  }

  if (
    !forceReload &&
    cacheKey &&
    Object.prototype.hasOwnProperty.call(
      c2cLinkedInvoiceCache,
      cacheKey
    )
  ) {
    return Promise.resolve(
      c2cLinkedInvoiceCache[cacheKey]
    );
  }

  if (
    !forceReload &&
    cacheKey &&
    c2cLinkedInvoicePending[cacheKey]
  ) {
    return c2cLinkedInvoicePending[cacheKey];
  }

  var requestPromise = new Promise(function (resolve, reject) {
    var settled = false;

    var timeoutId = window.setTimeout(function () {
      if (settled) return;
      settled = true;
      reject(
        new Error(
          "Linked Sales Invoice request timed out."
        )
      );
    }, 20000);

    function finish(invoices) {
      if (settled) return;
      settled = true;
      window.clearTimeout(timeoutId);

      var uniqueInvoices =
        c2cUniqueInvoiceRows(invoices || []);

      if (cacheKey) {
        c2cLinkedInvoiceCache[cacheKey] =
          uniqueInvoices;
      }

      resolve(uniqueInvoices);
    }

    function fail(error) {
      if (settled) return;
      settled = true;
      window.clearTimeout(timeoutId);
      reject(
        error ||
        new Error(
          "Unable to fetch linked Sales Invoices."
        )
      );
    }

    function fetchByStoredInvoiceNames() {
      if (!storedInvoiceNames.length) {
        finish([]);
        return;
      }

      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Sales Invoice",
          filters: [
            ["Sales Invoice", "docstatus", "=", 1],
            ["Sales Invoice", "is_return", "=", 0],
            ["Sales Invoice", "name", "in", storedInvoiceNames]
          ],
          fields: c2cInvoiceListFields(),
          order_by: "posting_date desc, creation desc",
          limit_page_length: 500
        },
        callback: function (r) {
          finish(r.message || []);
        },
        error: function (error) {
          void 0;
          fail(error);
        }
      });
    }

    if (!sourcePlans.length) {
      fetchByStoredInvoiceNames();
      return;
    }

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Sales Invoice",
        filters: [
          ["Sales Invoice", "docstatus", "=", 1],
          ["Sales Invoice", "is_return", "=", 0],
          [
            "Sales Invoice",
            "therapy_plan_reference_id",
            "in",
            sourcePlans
          ]
        ],
        fields: c2cInvoiceListFields(),
        order_by: "posting_date desc, creation desc",
        limit_page_length: 500
      },
      callback: function (r) {
        var invoices = r.message || [];

        // C2C stores the selected invoice number(s) on the request.
        // Use those only as a fallback for old records where the
        // Therapy Plan link was not populated on Sales Invoice.
        if (!invoices.length && storedInvoiceNames.length) {
          fetchByStoredInvoiceNames();
          return;
        }

        finish(invoices);
      },
      error: function (error) {
        void 0;

        if (storedInvoiceNames.length) {
          fetchByStoredInvoiceNames();
        } else {
          fail(error);
        }
      }
    });
  });

  if (cacheKey) {
    c2cLinkedInvoicePending[cacheKey] =
      requestPromise;
  }

  requestPromise.then(
    function () {
      if (cacheKey) {
        delete c2cLinkedInvoicePending[cacheKey];
      }
    },
    function () {
      if (cacheKey) {
        delete c2cLinkedInvoicePending[cacheKey];
      }
    }
  );

  return requestPromise;
}

function closeC2CSalesInvoiceBillModal() {
  var modal = document.getElementById(
    "c2cSalesInvoiceBillModal"
  );

  if (modal && modal.parentNode) {
    modal.parentNode.removeChild(modal);
  }

  document.body.classList.remove(
    "pkg-bill-modal-open"
  );
}

function openC2CSalesInvoiceBillModal(invoice) {
  invoice = invoice || {};

  var invoiceName = String(
    typeof invoice === "string"
      ? invoice
      : invoice.name || ""
  ).trim();

  if (!invoiceName) {
    frappe.msgprint({
      title: "Invoice Missing",
      indicator: "red",
      message: "Sales Invoice number is missing."
    });
    return;
  }

  var printUrl =
    getC2CSalesInvoicePrintUrl(invoiceName);

  if (!printUrl) {
    frappe.msgprint({
      title: "Unable to Open Bill",
      indicator: "red",
      message:
        "Unable to create the Sales Invoice bill URL."
    });
    return;
  }

  closeC2CSalesInvoiceBillModal();

  var modal = document.createElement("div");
  modal.id = "c2cSalesInvoiceBillModal";
  modal.className = "pkg-native-bill-modal";

  modal.innerHTML = `
    <div
      class="pkg-native-bill-backdrop"
      data-c2c-bill-close="1"
    ></div>

    <div
      class="pkg-native-bill-dialog"
      role="dialog"
      aria-modal="true"
      aria-label="Sales Invoice Bill"
    >
      <div class="pkg-native-bill-header">
        <div>
          <div class="pkg-native-bill-title">
            Sales Invoice Bill
          </div>
          <div class="pkg-native-bill-invoice">
            ${escapeHtml(invoiceName)}
          </div>
        </div>

        <div class="pkg-native-bill-header-actions">
          <button
            type="button"
            class="pkg-native-bill-close"
            data-c2c-bill-close="1"
            aria-label="Close bill"
            title="Close"
          >
            ×
          </button>
        </div>
      </div>

      <div class="pkg-native-bill-body">
        <div class="pkg-native-bill-loader">
          Loading ${escapeHtml(invoiceName)}...
        </div>

        <iframe
          class="pkg-native-bill-iframe"
          src="${escapeHtml(printUrl)}"
          title="Sales Invoice ${escapeHtml(invoiceName)}"
        ></iframe>
      </div>
    </div>
  `;

  document.body.appendChild(modal);
  document.body.classList.add(
    "pkg-bill-modal-open"
  );

  var iframe = modal.querySelector(
    ".pkg-native-bill-iframe"
  );
  var loader = modal.querySelector(
    ".pkg-native-bill-loader"
  );

  if (iframe) {
    iframe.addEventListener("load", function () {
      if (loader) loader.style.display = "none";

      try {
        var iframeDocument =
          iframe.contentDocument ||
          iframe.contentWindow.document;

        if (!iframeDocument) return;

        var actionBanner =
          iframeDocument.querySelector(
            ".action-banner"
          );

        if (actionBanner) actionBanner.remove();

        var printGutter =
          iframeDocument.querySelector(
            ".print-format-gutter"
          );

        if (printGutter) {
          printGutter.style.paddingTop = "20px";
        }
      } catch (error) {
        void 0;
      }
    });
  }

  modal.addEventListener("click", function (event) {
    var closeButton = event.target.closest(
      "[data-c2c-bill-close='1']"
    );

    if (!closeButton) return;

    event.preventDefault();
    event.stopPropagation();
    closeC2CSalesInvoiceBillModal();
  });

  function handleBillEscape(event) {
    if (event.key !== "Escape") return;

    closeC2CSalesInvoiceBillModal();
    document.removeEventListener(
      "keydown",
      handleBillEscape
    );
  }

  document.addEventListener(
    "keydown",
    handleBillEscape
  );
}

function renderC2CApprovalBillButtons(invoices, holder) {
  if (!holder) return;

  invoices = invoices || [];

  if (!invoices.length) {
    holder.innerHTML = `
      <div class="pkg-no-linked-bill">
        No submitted Sales Invoice is linked
        to the Therapy Plan(s) in this conversion.
      </div>
    `;
    return;
  }

  holder.innerHTML = `
    <div class="pkg-bill-button-list">
      ${invoices.map(function (invoice) {
        var invoiceName = String(
          invoice.name || ""
        ).trim();

        var planName = String(
          invoice.therapy_plan_reference_id ||
          invoice.custom_therapy_plan_reference_id ||
          invoice.therapy_plan ||
          "No Therapy Plan"
        ).trim();

        var invoiceDate = invoice.posting_date
          ? formatDate(invoice.posting_date)
          : "—";

        return `
          <button
            type="button"
            class="pkg-view-bill-btn"
            data-c2c-invoice="${escapeHtml(invoiceName)}"
            title="View Sales Invoice ${escapeHtml(invoiceName)}"
          >
            <span class="pkg-view-bill-icon">▣</span>

            <span class="pkg-view-bill-text">
              <strong>
                View Sales Invoice — ${escapeHtml(invoiceName)}
              </strong>

              <small class="pkg-view-bill-plan">
                ${escapeHtml(planName)}
              </small>

              <small class="pkg-view-bill-date">
                Invoice Dt: ${escapeHtml(invoiceDate)}
              </small>
            </span>
          </button>
        `;
      }).join("")}
    </div>
  `;

  holder.onclick = function (event) {
    var billButton = event.target.closest(
      ".pkg-view-bill-btn"
    );

    if (
      !billButton ||
      !holder.contains(billButton)
    ) {
      return;
    }

    event.preventDefault();
    event.stopPropagation();

    var invoiceName = String(
      billButton.getAttribute(
        "data-c2c-invoice"
      ) || ""
    ).trim();

    if (!invoiceName) {
      frappe.msgprint(
        "Sales Invoice number is missing."
      );
      return;
    }

    openC2CSalesInvoiceBillModal({
      name: invoiceName
    });
  };
}

function loadC2CApprovalInvoiceButtons(
  doc,
  panel,
  options
) {
  if (!doc || !panel) {
    return Promise.resolve([]);
  }

  options = options || {};

  var holder = panel.querySelector(
    ".pkg-approval-bill-actions"
  );

  if (!holder) {
    return Promise.resolve([]);
  }

  var loadToken =
    String(Date.now()) +
    "-" +
    String(Math.random());

  holder.setAttribute(
    "data-c2c-invoice-load-token",
    loadToken
  );

  holder.innerHTML = `
    <div class="pkg-bill-loading">
      Loading linked Sales Invoice(s)...
    </div>
  `;

  var invoicePromise =
    fetchC2CLinkedSalesInvoices(
      doc,
      {
        forceReload:
          options.forceReload === true
      }
    );

  invoicePromise
    .then(function (invoices) {
      if (
        !holder.isConnected ||
        holder.getAttribute(
          "data-c2c-invoice-load-token"
        ) !== loadToken
      ) {
        return;
      }

      renderC2CApprovalBillButtons(
        invoices,
        holder
      );
    })
    .catch(function (error) {
      void 0;

      if (
        !holder.isConnected ||
        holder.getAttribute(
          "data-c2c-invoice-load-token"
        ) !== loadToken
      ) {
        return;
      }

      holder.innerHTML = `
        <div class="pkg-no-linked-bill is-error">
          <div>
            Unable to load linked Sales Invoice bills.
          </div>

          <button
            type="button"
            class="btn btn-sm pkg-retry-linked-bills"
            style="margin-top:8px"
          >
            Retry Invoice Loading
          </button>
        </div>
      `;

      var retryButton = holder.querySelector(
        ".pkg-retry-linked-bills"
      );

      if (retryButton) {
        retryButton.addEventListener(
          "click",
          function (event) {
            event.preventDefault();
            event.stopPropagation();

            loadC2CApprovalInvoiceButtons(
              doc,
              panel,
              { forceReload: true }
            );
          }
        );
      }
    });

  return invoicePromise;
}

function c2cUniqueTextList(list) {
  var out = [];
  var seen = {};

  (list || []).forEach(function (value) {
    value = String(value || "").trim();
    if (!value) return;

    var key = value.toLowerCase();
    if (seen[key]) return;

    seen[key] = 1;
    out.push(value);
  });

  return out;
}

function c2cGetInvoiceBookedByName(invoice) {
  invoice = invoice || {};

  return String(
    invoice.custom_referring_name ||
    invoice.referring_name ||
    invoice.ref_practitioner ||
    invoice.custom_healthcare_practitioner ||
    invoice.custom_doctor_name ||
    invoice.custom_doctor_id ||
    ""
  ).trim();
}

function c2cFetchBookedByFromSourcePlans(doc) {
  return fetchC2CLinkedSalesInvoices(doc)
    .then(function (rows) {
      rows = rows || [];

      var bookedByNames = rows
        .map(function (invoice) {
          return c2cGetInvoiceBookedByName(
            invoice
          );
        })
        .filter(Boolean);

      bookedByNames =
        c2cUniqueTextList(bookedByNames);

      var invoices = rows.map(function (invoice) {
        return {
          name: String(
            invoice.name || ""
          ).trim(),
          plan: String(
            invoice.therapy_plan_reference_id ||
            invoice.custom_therapy_plan_reference_id ||
            invoice.therapy_plan ||
            "No Therapy Plan"
          ).trim(),
          date: invoice.posting_date
            ? formatDate(invoice.posting_date)
            : "—"
        };
      }).filter(function (invoice) {
        return !!invoice.name;
      });

      return {
        bookedBy: bookedByNames.join(", "),
        invoices: invoices
      };
    })
    .catch(function (error) {
      void 0;

      return {
        bookedBy: "",
        invoices: []
      };
    });
}

function renderC2CDetailBranchDateBookedBy(doc) {
  doc = doc || {};

  var branchFlow =
    String(doc.branch || "—").trim() +
    " → " +
    String(doc.receiving_branch || "—").trim();

  var requestDate = c2cP2PFormatDateTime(
    doc.creation ||
    doc.date ||
    doc.modified ||
    ""
  );

  return `
    <div class="pkg-detail-header-meta">
      <div class="pkg-detail-branch-date-row">
        <span class="pkg-detail-branch-name">
          ${escapeHtml(branchFlow || "—")}
        </span>

        <span class="pkg-detail-meta-separator">·</span>

        <span class="pkg-detail-request-date-label">
          REQ.DT:
        </span>

        <span class="pkg-detail-request-date-value">
          ${escapeHtml(requestDate || "—")}
        </span>
      </div>

      <div class="pkg-detail-booked-row">
        <span class="pkg-detail-booked-by">
          Booked by: Loading...
        </span>

        <div class="pkg-detail-linked-invoices">
          <span class="pkg-detail-invoices-loading">
            Loading linked invoices...
          </span>
        </div>
      </div>
    </div>
  `;
}

function updateC2CBookedByInDetailHeader(doc, panel) {
  if (!doc || !panel) return;

  var bookedByHolder = panel.querySelector(
    ".pkg-detail-booked-by"
  );

  var invoicesHolder = panel.querySelector(
    ".pkg-detail-linked-invoices"
  );

  if (!bookedByHolder) return;

  bookedByHolder.textContent =
    "Booked by: Loading...";

  if (invoicesHolder) {
    invoicesHolder.innerHTML = `
      <span class="pkg-detail-invoices-loading">
        Loading linked invoices...
      </span>
    `;
  }

  c2cFetchBookedByFromSourcePlans(doc)
    .then(function (result) {
      result = result || {};

      if (!bookedByHolder.isConnected) {
        return;
      }

      var bookedBy = String(
        result.bookedBy || ""
      ).trim();

      var invoices = result.invoices || [];

      bookedByHolder.textContent =
        "Booked by: " +
        (bookedBy || "—");

      bookedByHolder.style.display =
        "inline-flex";

      if (!invoicesHolder) return;

      if (!invoices.length) {
        invoicesHolder.innerHTML = `
          <span class="pkg-detail-no-invoices">
            No linked invoices
          </span>
        `;
        return;
      }

      invoicesHolder.innerHTML = `
        <span class="pkg-detail-invoices-label">
          Invoices:
        </span>

        ${invoices.map(function (invoice) {
          return `
            <span
              class="pkg-detail-invoice-chip"
              title="${escapeHtml(
                invoice.plan +
                " · " +
                invoice.name +
                " · " +
                invoice.date
              )}"
            >
              <span class="pkg-detail-invoice-plan">
                ${escapeHtml(invoice.plan)}
              </span>

              <span class="pkg-detail-invoice-chip-separator">/</span>

              <span class="pkg-detail-invoice-number">
                ${escapeHtml(invoice.name)}
              </span>

              <span class="pkg-detail-invoice-chip-separator">/</span>

              <strong class="pkg-detail-invoice-chip-date">
                ${escapeHtml(invoice.date)}
              </strong>
            </span>
          `;
        }).join("")}
      `;
    });
}

function renderC2CTransferRowsTable(rows) {
  rows = (rows || []).filter(function (row) {
    return Number(row.converted_quantity || 0) > 0;
  });

  if (!rows.length) {
    return `
      <div class="cpc-detail-empty">
        No transferred therapy rows found.
      </div>
    `;
  }

  return `
    <div class="cpc-mini-table-wrap">
      <table class="cpc-mini-table">
        <thead>
          <tr>
            <th>Therapy</th>
            <th>Source Plan</th>
            <th>Qty</th>
            <th>Start Date</th>
            <th>Amount</th>
          </tr>
        </thead>
        <tbody>
          ${rows.map(function (row) {
            return `
              <tr>
                <td>${escapeHtml(row.therapy_plans_been_transferred || "-")}</td>
                <td>${escapeHtml(row.source_therapy_plan || "-")}</td>
                <td>${escapeHtml(row.converted_quantity || "0")}</td>
                <td>${escapeHtml(formatDate(row.start_date))}</td>
                <td><b>${escapeHtml(c2cMoney(row.total_amount || 0))}</b></td>
              </tr>
            `;
          }).join("")}
        </tbody>
      </table>
    </div>
  `;
}

function getC2CAutomationLogLine(doc) {
  const log = String(doc.package_conversion_log || doc.automation_log || "").trim();
  if (!log) return "";
  return log.split(/\r?\n/)[0];
}

function c2cInfoChip(label, value) {
  return `
    <div class="cpc-info-chip">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(value === undefined || value === null || value === "" ? "-" : value)}</strong>
    </div>
  `;
}

function c2cMoney(value) {
  if (typeof formatCurrency === "function") {
    return formatCurrency(value || 0);
  }

  return "₹" + Number(value || 0).toLocaleString("en-IN", {
    maximumFractionDigits: 2
  });
}

function renderRequestList() {
  if (!requestListBody) return;
  const keyword = (requestSearchInput && requestSearchInput.value || "").toLowerCase().trim();
  const selectedBranch = requestBranchFilter ? requestBranchFilter.value || "" : "";
  let rows = allRequests || [];

  if (selectedBranch) {
    rows = rows.filter(function (row) { return String(row.branch || "") === String(selectedBranch) || String(row.receiving_branch || "") === String(selectedBranch); });
  }

  if (keyword) {
    rows = rows.filter(function (row) {
      return [row.name, row.date, row.branch, row.receiving_branch, row.transfer_type, row.client_full_name, row.client_name, row.mobile_number, row.phone_number, maskMobile(row.mobile_number), maskMobile(row.phone_number), row.approval_display_status, row.approval_stage, getWorkflowLabel(row.current_tab_step, row.final_approval_status), row.automation_status, row.final_approval_status, row.office_remarks_any].join(" ").toLowerCase().includes(keyword);
    });
  }

  if (!rows.length) {
    requestListBody.innerHTML = "<div class='notice notice-blue'>No requests found.</div>";
    renderRequestPagination(0);
    return;
  }

  const totalPages = Math.ceil(rows.length / REQUESTS_PER_PAGE);
  if (requestCurrentPage > totalPages) requestCurrentPage = totalPages;
  if (requestCurrentPage < 1) requestCurrentPage = 1;

  const startIndex = (requestCurrentPage - 1) * REQUESTS_PER_PAGE;
  const paginatedRows = rows.slice(startIndex, startIndex + REQUESTS_PER_PAGE);

  const agListEl = root.querySelector("#ag-list");
  const listHtml = paginatedRows.map(function (row) {
    const automationStatus = String(row.automation_status || "").trim();
    const isProcessCompleted = automationStatus === "Process Completed";
    const label = isProcessCompleted ? "Process Completed" : row.approval_display_status || row.conversion_status || getWorkflowLabel(row.current_tab_step, row.final_approval_status);
    const isDone = Number(row.current_tab_step || 1) >= 4 || isProcessCompleted;
    const isRejected = row.final_approval_status === "Rejected";
    const pillCls = isRejected ? "p-r" : isDone ? "p-g" : "p-o";
    return `<div class="glist-item" data-docname="${escapeHtml(row.name)}">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <strong style="color:#0D2B4E;font-size:11.5px">${escapeHtml(row.name||"-")}</strong>
        <span class="pill ${pillCls}">${escapeHtml(label)}</span>
      </div>
      <div style="font-size:10.5px;margin-top:4px">
        <strong>${escapeHtml(row.client_full_name||"-")}</strong>
        <span style="color:#8C8C8C"> → ${escapeHtml(row.transferee_full_name||row.client_name||"-")}</span>
      </div>
      <div style="font-size:9.5px;color:#8C8C8C;margin-top:2px">
        ${escapeHtml(row.branch||"-")} → ${escapeHtml(row.receiving_branch||"-")} · ${escapeHtml(formatDate(row.date))}
      </div>
    </div>`;
  }).join("");
  if (agListEl) {
    agListEl.innerHTML = listHtml;
    agListEl.querySelectorAll(".glist-item").forEach(function(item){
      item.addEventListener("click", function(){
        agListEl.querySelectorAll(".glist-item").forEach(function(i){ i.classList.remove("sel"); });
        item.classList.add("sel");
        const dn = item.dataset.docname;
        const agDetail = root.querySelector("#ag-detail");
        if(agDetail){
          const row = paginatedRows.find(function(r){ return r.name===dn; });
          const label = row ? (row.approval_display_status || row.conversion_status || getWorkflowLabel(row.current_tab_step, row.final_approval_status)) : "";
          const isDone = row && (Number(row.current_tab_step||1)>=4 || String(row.automation_status||"")==="Process Completed");
          agDetail.innerHTML = `<div>
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
              <strong style="font-size:13px;color:#0D2B4E">${escapeHtml(dn)}</strong>
              <span class="pill ${isDone?"p-g":"p-o"}">${escapeHtml(label)}</span>
            </div>
            <div class="notice notice-blue" style="margin-bottom:12px;line-height:1.8">
              <strong>Transferor:</strong> ${escapeHtml(row?row.client_full_name:"-")} · ${escapeHtml(maskMobile(row?row.mobile_number:""))}<br>
              <strong>Transferee:</strong> ${escapeHtml(row?(row.transferee_full_name||row.client_name):"-")} · ${escapeHtml(maskMobile(row?row.phone_number:""))}<br>
              <strong>Branch:</strong> ${escapeHtml(row?row.branch:"-")} → ${escapeHtml(row?row.receiving_branch:"-")}<br>
              <strong>Date:</strong> ${escapeHtml(formatDate(row?row.date:""))} &nbsp;|&nbsp; <strong>Modified:</strong> ${escapeHtml(formatDateTime(row?row.modified:""))}
            </div>
            <button class="btn btn-n btn-sm" onclick="openRequestFromList('${escapeHtml(dn)}')">${isDone?"📄 View Full Request":"✏️ Open & Continue"}</button>
          </div>`;
        }
      });
    });
  } else if (requestListBody) {
    requestListBody.innerHTML = "<p style='padding:12px;color:#595959'>Use the All Requests tab to view list.</p>";
  }

  renderRequestPagination(rows.length);
}

function renderRequestPagination(totalRows) {
  if (!requestPagination) return;
  const totalPages = Math.ceil(Number(totalRows || 0) / REQUESTS_PER_PAGE);
  if (!totalRows || totalPages <= 1) { requestPagination.innerHTML = ""; return; }

  requestPagination.innerHTML = `
    <div class="cpc-pagination-info">Showing page ${requestCurrentPage} of ${totalPages}<span>(${totalRows} requests)</span></div>
    <div class="cpc-pagination-actions">
      <button type="button" class="cpc-page-btn" id="requestPrevPage" ${requestCurrentPage <= 1 ? "disabled" : ""}>Previous</button>
      <button type="button" class="cpc-page-btn" id="requestNextPage" ${requestCurrentPage >= totalPages ? "disabled" : ""}>Next</button>
    </div>`;

  const prevBtn = root.querySelector("#requestPrevPage");
  const nextBtn = root.querySelector("#requestNextPage");
  if (prevBtn) prevBtn.addEventListener("click", function () { if (requestCurrentPage > 1) { requestCurrentPage--; renderRequestList(); } });
  if (nextBtn) nextBtn.addEventListener("click", function () { if (requestCurrentPage < totalPages) { requestCurrentPage++; renderRequestList(); } });
}

function openRequestFromList(docname) {
  frappe.call({
    method: "frappe.client.get",
    args: { doctype: DOCTYPE, name: docname },
    callback: function (r) {
      if (!r.message) { frappe.msgprint("Request not found."); return; }
      fillFormFromDoc(r.message);
      if (currentWorkflowStep >= 4) { showStage(1); } else { showStage(currentWorkflowStep); }
      showFormView();
    },
    error: function (err) { void 0; frappe.msgprint("Unable to open this request."); }
  });
}

function startNewRequest() {
  loadedDoc = null;
  currentDocName = null;
  currentWorkflowStep = 1;
  transferorConfirmedForRequest = false;

  hideC2CSubmittedView();

  resetForm();
  enforceFixedTodayDateFields(true);
  showStage(1);
  showFormView();
  updateTransferorConfirmGate();
  updateC2CFormStepbar(1);
}

// ============================================================
// STAGES
// ============================================================

function showStage(step) {
  step = Number(step || 1);
  if (!canOpenStepTab(step)) { frappe.msgprint("This step is locked until the previous approval step is completed."); return; }

  const stageToShow = step;

  if (!cpcSubmittedMode) {
      const isNewFormFilling = !currentDocName && Number(currentWorkflowStep || 1) === 1;
      setC2CStepLabels(isNewFormFilling ? "form" : "approval");
    }
  root.querySelectorAll(".cpc-stage-panel").forEach(function (panel) { panel.classList.toggle("active", Number(panel.dataset.stage) === stageToShow); });
  [1,2,3].forEach(function(i){
    var stepEl = root.querySelector("#wstep-"+i);
    if(!stepEl) return;
    var dot = stepEl.querySelector(".sdot");
    var lbl = stepEl.querySelector(".slbl");
    var isDone = (i < currentWorkflowStep || currentWorkflowStep >= 4);
    var isActive = (i === stageToShow);
    stepEl.classList.toggle("done", isDone && !isActive);
    stepEl.classList.toggle("active", isActive);
    if(dot){ dot.classList.toggle("done", isDone && !isActive); dot.classList.toggle("active", isActive); }
    if(lbl){ lbl.classList.toggle("active", isActive); }
    if(!stepEl.dataset.stepBound){
      stepEl.dataset.stepBound="1";
      stepEl.style.cursor="pointer";
      stepEl.addEventListener("click", function(){
        if(!canOpenStepTab(i)){ frappe.msgprint("This step is locked until the previous step is completed."); return; }
        showStage(i);
      });
    }
  });

  if (currentDocLabel) currentDocLabel.textContent = currentDocName || "New Request";
  if (heroStatusText) {
    heroStatusText.textContent = loadedDoc && loadedDoc.conversion_status ? loadedDoc.conversion_status : getWorkflowLabel(currentWorkflowStep, loadedDoc ? loadedDoc.final_approval_status : getField("final_approval_status"));
  }

  enforceFixedTodayDateFields(false);
  applyStepAccessControl(stageToShow);
  applyApprovalStageVisibility(stageToShow);

  if (submitStatus) { submitStatus.className = "cpc-submit-status"; submitStatus.style.display = "none"; submitStatus.innerHTML = ""; }
  if (stageToShow === 1) renderReview();
  if (stageToShow === 1) updateTransferorConfirmGate();

  setTimeout(function () {
    redrawAllSignatures();
    enforceFixedTodayDateFields(false);
    applyStepAccessControl(stageToShow);
    applyApprovalStageVisibility(stageToShow);
    updateSignatureAccessControl();
  }, 150);
}

function applyApprovalStageVisibility(stageToShow) {
  let approvalStage = getApprovalStage();
  root.querySelectorAll("[data-approval-panel]").forEach(function (panel) { panel.classList.add("hidden"); });

  const workflowStep = Number(currentWorkflowStep || 1);
  const finalApprovalStatus = String(getField("final_approval_status") || "").trim();
  const isFinishedRequest = workflowStep >= 4 || approvalStage === APPROVAL_STAGES.APPROVED || approvalStage === APPROVAL_STAGES.REJECTED || finalApprovalStatus === "Approved" || finalApprovalStatus === "Rejected";
  const isPastStep = Number(stageToShow || 1) < workflowStep;

  if (isFinishedRequest || isPastStep) {
    if (stageToShow === 2) {
      const cmPanel = root.querySelector('[data-approval-panel="centre_manager"]');
      const omPanel = root.querySelector('[data-approval-panel="operations_manager"]');

      if (cmPanel) cmPanel.classList.remove("hidden");
      if (omPanel) omPanel.classList.remove("hidden");

      renderStep2ApprovalHistory();

      setTimeout(function () { redrawAllSignatures(); }, 200);
    }
    if (stageToShow === 3) {
      const auditPanel = root.querySelector('[data-approval-panel="audit_team"]');
      const cooPanel = root.querySelector('[data-approval-panel="operations_coo"]');

      if (auditPanel) auditPanel.classList.remove("hidden");
      if (cooPanel && isFinishedRequest) cooPanel.classList.remove("hidden");

      renderFullApprovalHistory();
      renderRejectionSummary();

      setTimeout(function () { redrawAllSignatures(); }, 200);
    }
    updateApprovalActionButtons(stageToShow);
    return;
  }

  if (stageToShow === 2 && (!approvalStage || approvalStage === APPROVAL_STAGES.REQUEST_PENDING || approvalStage === "Branch Official Approval Pending")) {
    approvalStage = APPROVAL_STAGES.CM_PENDING; setApprovalStage(approvalStage);
  }
  if (stageToShow === 3 && (!approvalStage || approvalStage === APPROVAL_STAGES.REQUEST_PENDING || approvalStage === "Management Approval Pending" || approvalStage === "Branch Official Approval Pending")) {
    approvalStage = APPROVAL_STAGES.AUDIT_PENDING; setApprovalStage(approvalStage);
  }

  if (stageToShow === 2) {
      renderStep2ApprovalHistory();

      if (approvalStage === APPROVAL_STAGES.CM_PENDING) {
        showOnlyApprovalPanel("centre_manager");
      }
      else if (approvalStage === APPROVAL_STAGES.OM_PENDING) {
      approvalStage = APPROVAL_STAGES.AUDIT_PENDING;
      setApprovalStage(approvalStage);
      showOnlyApprovalPanel("audit_team");
    }
    }

  if (stageToShow === 3) {
      renderFullApprovalHistory();

      if (approvalStage === APPROVAL_STAGES.AUDIT_PENDING) {
        showOnlyApprovalPanel("audit_team");
      }
      else if (approvalStage === APPROVAL_STAGES.COO_PENDING) {
        showOnlyApprovalPanel("operations_coo");
        autoFillFinalCooFromLogin();
        renderRejectionSummary();
      }
    }

  updateApprovalActionButtons(stageToShow);
  setTimeout(function () { redrawAllSignatures(); }, 200);
}

function updateApprovalActionButtons(stageToShow) {
  const editable = isStageEditable(stageToShow);
  const stage = getApprovalStage();

  const isApprovalStage =
    stage === APPROVAL_STAGES.CM_PENDING ||
    stage === APPROVAL_STAGES.AUDIT_PENDING ||
    stage === APPROVAL_STAGES.COO_PENDING;

  const stageMatchesCurrentStep =
    (
      stageToShow === 2 &&
      (
        stage === APPROVAL_STAGES.CM_PENDING 
      )
    ) ||
    (
      stageToShow === 3 &&
      (
        stage === APPROVAL_STAGES.AUDIT_PENDING ||
        stage === APPROVAL_STAGES.COO_PENDING
      )
    );

  const shouldShowApprovalButtons =
    editable && isApprovalStage && stageMatchesCurrentStep;

  /*
    Submit button is only for Step 1 request submission.
    Do not show Save button during approval stages.
  */
  if (submitBtn) {
    const showSubmitRequestButton =
      editable &&
      Number(stageToShow || 1) === 1 &&
      !shouldShowApprovalButtons;

    submitBtn.classList.toggle("hidden", !showSubmitRequestButton);
    submitBtn.classList.toggle("cpc-hidden", !showSubmitRequestButton);
    submitBtn.style.display = showSubmitRequestButton ? "" : "none";
    submitBtn.disabled = !showSubmitRequestButton;

    if (showSubmitRequestButton) {
      submitBtn.textContent = "Submit Request";
    }
  }

  if (approveBtn) {
    approveBtn.classList.toggle("hidden", !shouldShowApprovalButtons);
    approveBtn.classList.toggle("cpc-hidden", !shouldShowApprovalButtons);
    approveBtn.style.display = shouldShowApprovalButtons ? "" : "none";
    approveBtn.disabled = !shouldShowApprovalButtons;

    if (stage === APPROVAL_STAGES.COO_PENDING) {
      approveBtn.textContent = "Final Approve";
    } else if (
      stage === APPROVAL_STAGES.OM_PENDING &&
      getField("centre_manager_decision") === "Rejected"
    ) {
      approveBtn.textContent = "Forward to COO";
    } else {
      approveBtn.textContent = "Approve";
    }
  }

  if (rejectBtn) {
    rejectBtn.classList.toggle("hidden", !shouldShowApprovalButtons);
    rejectBtn.classList.toggle("cpc-hidden", !shouldShowApprovalButtons);
    rejectBtn.style.display = shouldShowApprovalButtons ? "" : "none";
    rejectBtn.disabled = !shouldShowApprovalButtons;

    if (stage === APPROVAL_STAGES.COO_PENDING) {
      rejectBtn.textContent = "Final Reject";
    } else if (
      stage === APPROVAL_STAGES.OM_PENDING &&
      getField("centre_manager_decision") === "Rejected"
    ) {
      rejectBtn.textContent = "Support Rejection";
    } else {
      rejectBtn.textContent = "Reject";
    }
  }
}


function getStepModeLabel(step) {
  step = Number(step || 1);
  const workflowStep = Number(currentWorkflowStep || 1);
  if (workflowStep >= 4) return "View Only";
  if (step < workflowStep) return "View Only";
  if (step === workflowStep) return "Editable";
  return "Locked";
}

function isStageEditable(step) {
  step = Number(step || 1);
  const workflowStep = Number(currentWorkflowStep || 1);
  if (workflowStep >= 4) return false;
  return step === workflowStep;
}

function applyStepAccessControl(step) {
  step = Number(step || 1);
  const panel = root.querySelector(`.cpc-stage-panel[data-stage="${step}"]`);
  if (!panel) return;
  const editable = isStageEditable(step);
  panel.classList.toggle("cpc-stage-readonly", !editable);
  panel.classList.toggle("cpc-stage-editable", editable);
  panel.querySelectorAll("input, select, textarea").forEach(function (el) { applyReadonlyToField(el, !editable); });
  panel.querySelectorAll("button").forEach(function (btn) {
    if (btn.classList.contains("cpc-remove-transfer-row")) { btn.disabled = !editable; return; }
    if (btn.classList.contains("cpc-select-plan-btn")) { btn.disabled = !editable; return; }
    if (btn.classList.contains("cpc-open-plan-btn")) { btn.disabled = false; return; }
    if (btn.classList.contains("cpc-work-step")) { btn.disabled = false; return; }
    btn.disabled = !editable;
  });
  panel.querySelectorAll(".cpc-signature-canvas").forEach(function (canvas) { canvas.classList.toggle("cpc-signature-disabled", !editable); });
  panel.querySelectorAll(".cpc-clear-signature").forEach(function (btn) { btn.disabled = !editable; btn.classList.toggle("hidden", !editable); });
    if (submitBtn) {
      const showSubmitRequestButton =
        editable &&
        Number(step || 1) === 1;

      submitBtn.textContent = "Submit Request";
      submitBtn.disabled = !showSubmitRequestButton;
      submitBtn.classList.toggle("hidden", !showSubmitRequestButton);
      submitBtn.classList.toggle("cpc-hidden", !showSubmitRequestButton);
      submitBtn.style.display = showSubmitRequestButton ? "" : "none";
    } 

    applyFetchedReadonlyAgain();
}

function applyReadonlyToField(el, readonly) {
  if (!el) return;
  const fixedFieldname = el.dataset ? el.dataset.field : "";
  if (fixedFieldname && FIXED_TODAY_DATE_FIELDS.includes(fixedFieldname)) {
    const today = frappe.datetime.get_today();
    if (!el.value) el.value = today;
    el.setAttribute("readonly", "readonly"); el.setAttribute("min", today); el.setAttribute("max", today);
    el.classList.add("cpc-fixed-date-input");
    return;
  }
  const tag = (el.tagName || "").toUpperCase();
  const type = String(el.type || "").toLowerCase();
  if (readonly) {
    if (tag === "SELECT" || type === "checkbox" || type === "file") { el.disabled = true; el.dataset.stepReadonly = "1"; }
    else { el.setAttribute("readonly", "readonly"); el.dataset.stepReadonly = "1"; }
    el.classList.add("cpc-readonly-input");
    return;
  }
  if (el.dataset.stepReadonly === "1") {
    if (tag === "SELECT" || type === "checkbox" || type === "file") el.disabled = false;
    else el.removeAttribute("readonly");
    delete el.dataset.stepReadonly;
    el.classList.remove("cpc-readonly-input");
  }
}

function applyFetchedReadonlyAgain() {
  FETCHED_PARENT_FIELDS.forEach(function (fieldname) {
    const el = root.querySelector(`[data-field="${fieldname}"]`);
    if (!el) return;
    el.setAttribute("readonly", "readonly"); el.classList.add("cpc-readonly-input");
    if (el.tagName === "SELECT") { el.setAttribute("disabled", "disabled"); el.dataset.disabledFetched = "1"; }
  });
}

function getConversionStatus(step, finalStatus, approvalStage) {
  approvalStage = String(approvalStage || getApprovalStage() || "").trim();
  if (approvalStage === APPROVAL_STAGES.CM_PENDING) return "Centre Manager Approval Pending";
  if (approvalStage === APPROVAL_STAGES.OM_PENDING) return "Operations Manager Approval Pending";
  if (approvalStage === APPROVAL_STAGES.AUDIT_PENDING) return "Audit Team Approval Pending";
  if (approvalStage === APPROVAL_STAGES.COO_PENDING) return "Operations COO Final Decision Pending";
  if (approvalStage === APPROVAL_STAGES.APPROVED) return "Approved";
  if (approvalStage === APPROVAL_STAGES.REJECTED) return "Rejected";
  step = Number(step || 1);
  if (step <= 1) return "Request Details Pending";
  if (step === 2) return "Branch Official Approval Pending";
  if (step === 3) return "Management Approval Pending";
  if (finalStatus === "Approved") return "Approved";
  if (finalStatus === "Rejected") return "Rejected";
  return "Completed";
}

function getWorkflowLabel(step, finalStatus) { return getConversionStatus(step, finalStatus); }
function getSubmitButtonLabel(step) { step = Number(step || 1); if (step <= 1) return "Submit Request"; return "Save"; }

function getNextStep(step) {
  const stage = getApprovalStage();
  if (stage === APPROVAL_STAGES.CM_PENDING) return 2;
  if (stage === APPROVAL_STAGES.OM_PENDING) return 3;
  if (stage === APPROVAL_STAGES.AUDIT_PENDING) return 3;
  if (stage === APPROVAL_STAGES.COO_PENDING) return 4;
  step = Number(step || 1);
  if (step >= 3) return 4;
  return step + 1;
}

// ============================================================
// SAVE FLOW
// ============================================================

function saveCurrentStage(actionButton) {
  const activeButton = actionButton || submitBtn || approveBtn || rejectBtn;
  if (!activeButton) return;
  if (isSavingRequest) return;
  if (!validateStage(currentWorkflowStep)) { forceResetSubmitButton(); return; }

  isSavingRequest = true;
  activeButton.disabled = true;
  activeButton.dataset.originalText = activeButton.textContent || "";

  if (activeApprovalAction === "Approved" && getApprovalStage() === APPROVAL_STAGES.COO_PENDING) activeButton.textContent = "Final Approving...";
  else if (activeApprovalAction === "Rejected" && getApprovalStage() === APPROVAL_STAGES.COO_PENDING) activeButton.textContent = "Final Rejecting...";
  else activeButton.textContent = "Saving...";

  if (submitBtn && submitBtn !== activeButton) submitBtn.disabled = true;
  if (approveBtn && approveBtn !== activeButton) approveBtn.disabled = true;
  if (rejectBtn && rejectBtn !== activeButton) rejectBtn.disabled = true;

  clearTimeout(saveWatchdogTimer);
  saveWatchdogTimer = setTimeout(function () {
    if (isSavingRequest) { void 0; showError("Save did not complete. Please check the message above and try again."); forceResetSubmitButton(); }
  }, 30000);

  try {
    if (!currentDocName) createRequest(); else updateRequest();
  } catch (err) {
    void 0;
    showError("Something went wrong before saving. Please try again.");
    forceResetSubmitButton();
  }
}

function createRequest() {

  const attachmentValidation =
    validateC2CMandatoryAttachments();


  if (!attachmentValidation.ok) {

    isSavingRequest = false;

    clearTimeout(
      saveWatchdogTimer
    );


    frappe.msgprint({
      title:
        "Mandatory Documents Required",

      indicator:
        "red",

      message:
        attachmentValidation.message
    });


    forceResetSubmitButton();

    return;
  }


  const doc =
    collectFormDataForStage(1);


  doc.doctype =
    DOCTYPE;

  doc.current_tab_step =
    2;

  doc.approval_stage =
    APPROVAL_STAGES.CM_PENDING;

  doc.conversion_status =
    getConversionStatus(
      2,
      "",
      doc.approval_stage
    );

  /* A new request is never finally approved. */
  doc.final_approval_status = "";
  doc.centre_manager_decision = "";
  doc.operations_manager_decision = "";
  doc.audit_team_decision = "";
  doc.approval_display_status = APPROVAL_STAGES.CM_PENDING;
  doc.automation_status = "Not Started";

  // Preserve the exact branch-requested transfer table before approvals.
  doc.custom_branch_requested_transfer_snapshot =
    c2cSerializeFinalTableSnapshot(
      doc.remaining_sessions_package_details || []
    );


  frappe.call({

    method:
      "frappe.client.insert",

    args: {
      doc: doc
    },


    callback:
      function (r) {

        const created =
          r.message;


        if (
          !created ||
          !created.name
        ) {

          showError(
            "Request was not created."
          );

          return;
        }


        if (submitStatus) {

          submitStatus.className =
            "cpc-submit-status";

          submitStatus.innerHTML =
            "Uploading supporting documents...";

          submitStatus.style.display =
            "block";
        }


        uploadC2CSupportingDocs(
          created.name
        )


        .then(
          function (uploadedDocs) {

            return (
              saveC2CAttachmentChildRows(
                created.name,
                uploadedDocs
              )
            );

          }
        )


        .then(
          function (savedRows) {

            created[
              C2C_ATTACHMENT_CHILD_FIELD
            ] =
              savedRows || [];


            currentDocName =
              created.name;

            currentWorkflowStep =
              2;


            // Email only after documents are saved
            sendStepEmail(
              currentDocName,
              2
            );


            isSavingRequest =
              false;


            clearTimeout(
              saveWatchdogTimer
            );


            showC2CSubmittedView(
              created
            );


            loadRequests();

          }
        )


        .catch(
          function (err) {

            void 0;


            const msg =
              typeof err === "string"
                ? err
                : getFrappeErrorMessage(
                    err,
                    "Unable to upload/save supporting documents."
                  );


            showError(
              "Request could not finish supporting-document upload: " +
              msg
            );

          }
        );

      },


    error:
      function (err) {

        void 0;


        showError(
          getFrappeErrorMessage(
            err,
            "Unable to create request. Please check required fields or permissions."
          )
        );


        resetSubmitButton();
      }

  });
}


function applyApprovalDecisionToDoc(doc, stageData) {
  const stage = getApprovalStage();
  const action = activeApprovalAction;

  if (!action) return;

  const actionDateTime =
    frappe.datetime &&
    typeof frappe.datetime.now_datetime === "function"
      ? frappe.datetime.now_datetime()
      : new Date().toISOString().slice(0, 19).replace("T", " ");

  if (stage === APPROVAL_STAGES.CM_PENDING) {
    doc.centre_manager_decision = action;
    c2cSetApprovalActionDateTime(
      doc,
      "centre_manager",
      actionDateTime
    );

    if (action === "Rejected") {
      doc.rejected_by_role = "Centre Manager";
      doc.rejected_by_name = getSelectedApprovalName("centre_manager_name");
      doc.rejection_remarks = getField("centre_manager_remarks");

      // TERMINAL REJECTION RULE:
      // Centre Manager rejection stops the workflow.
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.approval_display_status = "Centre Manager Rejected / Process Stopped";
      doc.final_approval_status = "Rejected";
      doc.conversion_status = "Rejected";
      doc.automation_status = "Skipped";
      doc.current_tab_step = 2;
    } else {
      // Centre Manager approval moves to Audit Team.
      doc.approval_display_status = APPROVAL_STAGES.AUDIT_PENDING;
      doc.approval_stage = APPROVAL_STAGES.AUDIT_PENDING;
      doc.current_tab_step = 3;
      doc.final_approval_status = "";
      doc.automation_status = "Pending Final Approval";
    }
  }

  else if (stage === APPROVAL_STAGES.AUDIT_PENDING || stage === APPROVAL_STAGES.OM_PENDING) {
    autoFillAuditFromLogin();

    doc.audit_team__corporate_team_name = getCurrentAuditApproverId();
    doc.audit_team__corporate_team_date = frappe.datetime.get_today();
    doc.audit_team_decision = action;
    c2cSetApprovalActionDateTime(
      doc,
      "audit_team",
      actionDateTime
    );

    if (action === "Rejected") {
      doc.rejected_by_role = "Audit Team / Corporate Team";
      doc.rejected_by_name = getCurrentAuditApproverName();
      doc.rejection_remarks = getField("audit_team_remarks");

      // TERMINAL REJECTION RULE:
      // Audit rejection stops the workflow and does not go to COO.
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.approval_display_status = "Audit Team Rejected / Process Stopped";
      doc.final_approval_status = "Rejected";
      doc.conversion_status = "Rejected";
      doc.automation_status = "Skipped";
      doc.current_tab_step = 3;
    } else {
      doc.approval_display_status = APPROVAL_STAGES.COO_PENDING;
      doc.approval_stage = APPROVAL_STAGES.COO_PENDING;
      doc.current_tab_step = 3;
      doc.final_approval_status = "";
      doc.automation_status = "Pending Final Approval";
    }
  }

  else if (stage === APPROVAL_STAGES.COO_PENDING) {
    doc.final_approval_status = action;
    doc.current_tab_step = 4;
    c2cSetApprovalActionDateTime(
      doc,
      "operations_coo",
      actionDateTime
    );

    if (action === "Approved") {
      doc.approval_stage = APPROVAL_STAGES.APPROVED;
      doc.approval_display_status = "Approved / Pending Package Transfer";
      doc.automation_status = "Pending Final Approval";
      doc.conversion_status = "Approved";
    } else {
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.approval_display_status = "Rejected / Skipped";
      doc.automation_status = "Skipped";
      doc.conversion_status = "Rejected";

      doc.rejected_by_role = "Operations COO / Management";
      doc.rejected_by_name = getLoggedInFinalCooName();
      doc.rejection_remarks = getField("office_remarks_any");
    }
  }
}


function updateRequest() {
  frappe.call({
    method: "frappe.client.get",
    args: { doctype: DOCTYPE, name: currentDocName },
    callback: function (r) {
      try {
        const doc = r.message;
        if (!doc) { showError("Unable to load existing request for update."); forceResetSubmitButton(); return; }
        const stageData = collectFormDataForStage(currentWorkflowStep);
        Object.keys(stageData).forEach(function (key) { doc[key] = stageData[key]; });
        applyApprovalDecisionToDoc(doc, stageData);
        if (!activeApprovalAction) {
          const nextStep = getNextStep(currentWorkflowStep);
          doc.current_tab_step = nextStep;
          doc.conversion_status = getConversionStatus(nextStep, stageData.final_approval_status || doc.final_approval_status, doc.approval_stage);
        }
        frappe.call({
          method: "frappe.client.save",
          args: { doc: doc },
          callback: function (saveResult) {
            try {
              const saved = saveResult.message;
              if (!saved || !saved.name) { showError("Save failed. No saved document was returned from the server."); forceResetSubmitButton(); return; }
              const nextStep = Number(saved.current_tab_step || getNextStep(currentWorkflowStep));
              activeApprovalAction = "";
              loadedDoc = saved; currentWorkflowStep = nextStep;
              if (
                nextStep <= 3 &&
                String(saved.approval_stage || "") !== APPROVAL_STAGES.REJECTED &&
                String(saved.conversion_status || "") !== "Rejected"
              ) {
                sendStepEmail(currentDocName, nextStep);
              }
              showSuccess(getSaveSuccessMessage(nextStep));
              setTimeout(function () { showListView(); loadRequests(); }, 700);
            } catch (callbackErr) {
              void 0;
              showError("Saved response could not be processed. Please refresh and check the request.");
              forceResetSubmitButton();
            }
          },
          error: function (err) {
            void 0;
            const msg = getFrappeErrorMessage(err, "Unable to save this step. Please check the entered details.");
            isSavingRequest = false; clearTimeout(saveWatchdogTimer);
            frappe.msgprint(msg); showError(msg);
            setTimeout(function () { forceResetSubmitButton(); }, 500);
          }
        });
      } catch (err) {
        void 0;
        showError("Something went wrong while preparing the request for saving.");
        forceResetSubmitButton();
      }
    },
    error: function (err) { void 0; showError("Unable to fetch the request before saving."); forceResetSubmitButton(); }
  });
}

function stripHtml(value) { return String(value || "").replace(/<[^>]*>/g, ""); }

function getFrappeErrorMessage(err, fallbackMessage) {
  let msg = fallbackMessage || "Something went wrong.";
  try {
    if (err && err.message) { msg = err.message; }
    else if (err && err._server_messages) {
      const serverMessages = JSON.parse(err._server_messages);
      if (Array.isArray(serverMessages) && serverMessages.length) {
        msg = serverMessages.map(function (item) { try { const parsed = JSON.parse(item); return parsed.message || item; } catch (e) { return item; } }).join("<br>");
      }
    } else if (err && err.exc) { msg = err.exc; }
  } catch (e) { void 0; }
  return stripHtml(msg);
}

function fetchBranchEmail(branchName, targetFieldname) {
  branchName = String(branchName || "").trim();
  if (!branchName || !targetFieldname) { if (targetFieldname) setField(targetFieldname, ""); return; }

  const branchEmailMap = {
    "Banjara Hills": "banjarahills@lifescc.com", "Dilsukhnagar": "dilsukhnagar@lifescc.com",
    "Nellore": "nellore@lifescc.com", "Vizag": "vizag@lifescc.com", "Madhapur": "madhapur@lifescc.com",
    "Gachibowli": "gachibowli@lifescc.com", "Kukatpally": "kukatpally@lifescc.com",
    "SR Nagar": "srnagar@lifescc.com", "Vijayawada": "vijayawada@lifescc.com",
    "Testing Branch": "yaswanthkumaryy1234@gmail.com",
    "Himayathnagar": "himayatnagar@lifescc.com", "Himayatnagar": "himayatnagar@lifescc.com",
    "Chandanagar": "chandhanagar@lifescc.com", "Chandhanagar": "chandhanagar@lifescc.com"
  };

  function applyEmail(email) {
