function getSaveSuccessMessage(nextStep) {
  const stage = loadedDoc && loadedDoc.approval_stage ? loadedDoc.approval_stage : getApprovalStage();
  if (stage === APPROVAL_STAGES.CM_PENDING) return "Request submitted successfully. Next step is pending with Centre Manager Approval.";
  if (stage === APPROVAL_STAGES.OM_PENDING) { const cmDecision = getField("centre_manager_decision"); return cmDecision === "Rejected" ? "Centre Manager rejection saved. Operations Manager review is pending." : "Centre Manager approval saved. Operations Manager review is pending."; }
  if (stage === APPROVAL_STAGES.AUDIT_PENDING) return "Operations Manager approval saved. Next step is pending with Audit Team / Corporate Team.";
  if (stage === APPROVAL_STAGES.COO_PENDING) return "Review saved. Final decision is pending with Operations COO / Management.";
  if (stage === APPROVAL_STAGES.APPROVED) return "Final approval saved. Request has been approved.";
  if (stage === APPROVAL_STAGES.REJECTED) return "Rejection saved. Workflow stopped; no further approval is required.";
  return "Saved successfully.";
}

function sendStepEmail(docname, nextStep) {
  frappe.call({
    method: "send_client_conversion_step_email",
    args: { docname: docname, next_step: nextStep },
    callback: function (r) {
      if (r.message && r.message.status === "sent") frappe.show_alert({ message: "Email sent to: " + r.message.to, indicator: "green" });
      else if (r.message && r.message.status === "missing_email") frappe.show_alert({ message: "Next step opened, but Branch Email is empty.", indicator: "orange" });
    },
    error: function (err) { void 0; frappe.show_alert({ message: "Next step opened, but email failed.", indicator: "orange" }); }
  });
}

function resetSubmitButton() {
  isSavingRequest = false; clearTimeout(saveWatchdogTimer);
  [submitBtn, approveBtn, rejectBtn].forEach(function (btn) {
    if (!btn) return;
    btn.disabled = false;
    if (btn.dataset && btn.dataset.originalText) { btn.textContent = btn.dataset.originalText; delete btn.dataset.originalText; }
  });
  if (submitBtn) {
    const editable = isStageEditable(currentWorkflowStep);
    submitBtn.disabled = !editable; submitBtn.textContent = getSubmitButtonLabel(currentWorkflowStep); submitBtn.classList.toggle("hidden", !editable);
  }
  updateApprovalActionButtons(currentWorkflowStep);
}

function forceResetSubmitButton() {
  isSavingRequest = false; clearTimeout(saveWatchdogTimer);
  [submitBtn, approveBtn, rejectBtn].forEach(function (btn) {
    if (!btn) return;
    btn.disabled = false;
    if (btn.dataset && btn.dataset.originalText) { btn.textContent = btn.dataset.originalText; delete btn.dataset.originalText; }
  });
  if (submitBtn) submitBtn.textContent = getSubmitButtonLabel(currentWorkflowStep);
  updateApprovalActionButtons(currentWorkflowStep);
}

function showSuccess(message) {
  isSavingRequest = false; clearTimeout(saveWatchdogTimer);
  if (submitStatus) { submitStatus.className = "cpc-submit-status success"; submitStatus.innerHTML = escapeHtml(message || "Saved successfully."); submitStatus.style.display = "block"; }
  resetSubmitButton();
}

function showError(message) {
  isSavingRequest = false; clearTimeout(saveWatchdogTimer);
  if (submitStatus) { submitStatus.className = "cpc-submit-status error"; submitStatus.innerHTML = escapeHtml(message || "Something went wrong."); submitStatus.style.display = "block"; }
  forceResetSubmitButton();
  setTimeout(function () { isSavingRequest = false; forceResetSubmitButton(); }, 300);
  setTimeout(function () { isSavingRequest = false; forceResetSubmitButton(); }, 1200);
}

