// C2C SUPPORTING DOCUMENTS
// ============================================================

function initC2CSupportingDocsState() {
  c2cSupportingAttachments = C2C_REQUIRED_DOCUMENTS.map(function (row) {
    return {
      id: row.key,
      document_name: row.document_name,
      is_mandatory: 1,
      fixed: true,
      saved: false,

      file: null,
      file_url: "",
      file_name: "",
      file_size: 0,
      file_type: "",
      remarks: ""
    };
  });

  c2cCurrentAttachmentRowId = "";
}


function bindC2CSupportingDocs() {
  const fileInput =
    root.querySelector("#c2cAttachmentInput");

  const rowsBox =
    root.querySelector("#c2cAttachmentRows");

  const addBtn =
    root.querySelector("#c2cAddOptionalAttachmentBtn");


  // Add optional row
  if (
    addBtn &&
    addBtn.dataset.boundC2COptionalAttach !== "1"
  ) {
    addBtn.dataset.boundC2COptionalAttach = "1";

    addBtn.addEventListener("click", function () {
      addC2COptionalAttachmentRow();
    });
  }


  // Hidden file input
  if (
    fileInput &&
    fileInput.dataset.boundC2CAttachInput !== "1"
  ) {
    fileInput.dataset.boundC2CAttachInput = "1";

    fileInput.addEventListener("change", function () {
      const file =
        fileInput.files &&
        fileInput.files[0]
          ? fileInput.files[0]
          : null;

      fileInput.value = "";

      if (!file || !c2cCurrentAttachmentRowId) {
        return;
      }

      setC2CAttachmentFile(
        c2cCurrentAttachmentRowId,
        file
      );
    });
  }


  // Attachment table events
  if (
    rowsBox &&
    rowsBox.dataset.boundC2CAttachRows !== "1"
  ) {
    rowsBox.dataset.boundC2CAttachRows = "1";


    rowsBox.addEventListener("click", function (e) {

      const uploadBtn =
        e.target.closest(".c2c-attachment-upload");

      const removeBtn =
        e.target.closest(".c2c-attachment-remove");


      if (uploadBtn) {
        c2cCurrentAttachmentRowId =
          uploadBtn.dataset.id || "";

        if (fileInput) {
          fileInput.click();
        }

        return;
      }


      if (removeBtn) {
        const removeId =
          removeBtn.dataset.id || "";

        c2cSupportingAttachments =
          (c2cSupportingAttachments || []).filter(
            function (item) {
              return (
                item.fixed ||
                item.id !== removeId
              );
            }
          );

        renderC2CSupportingDocs();
      }
    });


    rowsBox.addEventListener("input", function (e) {
      const id =
        e.target.dataset.id || "";

      if (
        e.target.classList.contains(
          "c2c-attachment-remarks"
        )
      ) {
        updateC2CAttachmentRow(
          id,
          "remarks",
          e.target.value || ""
        );
      }

      if (
        e.target.classList.contains(
          "c2c-attachment-document-name"
        )
      ) {
        updateC2CAttachmentRow(
          id,
          "document_name",
          e.target.value || ""
        );
      }
    });
  }


  renderC2CSupportingDocs();
}


function addC2COptionalAttachmentRow() {
  if (currentDocName) {
    return;
  }

  c2cSupportingAttachments =
    c2cSupportingAttachments || [];


  if (
    c2cSupportingAttachments.length >=
    C2C_ATTACHMENT_MAX_TOTAL_ROWS
  ) {
    frappe.msgprint(
      "Maximum " +
      C2C_ATTACHMENT_MAX_TOTAL_ROWS +
      " document rows are allowed."
    );

    return;
  }


  c2cSupportingAttachments.push({
    id:
      "optional_" +
      Date.now() +
      "_" +
      Math.floor(Math.random() * 100000),

    document_name: "",
    is_mandatory: 0,
    fixed: false,
    saved: false,

    file: null,
    file_url: "",
    file_name: "",
    file_size: 0,
    file_type: "",
    remarks: ""
  });


  renderC2CSupportingDocs();
}


function updateC2CAttachmentRow(
  rowId,
  fieldname,
  value
) {
  (c2cSupportingAttachments || []).forEach(
    function (item) {

      if (item.id === rowId) {
        item[fieldname] = value;
      }

    }
  );
}


function setC2CAttachmentFile(
  rowId,
  file
) {
  const error =
    validateC2CAttachmentFile(file);


  if (error) {
    frappe.msgprint({
      title: "Invalid Attachment",
      indicator: "red",
      message: error
    });

    return;
  }


  let found = false;


  (c2cSupportingAttachments || []).forEach(
    function (item) {

      if (item.id === rowId) {
        item.file = file;
        item.file_url = "";

        item.file_name =
          file.name || "";

        item.file_size =
          file.size || 0;

        item.file_type =
          getC2CAttachmentType(file);

        found = true;
      }

    }
  );


  if (!found) {
    frappe.msgprint(
      "Attachment row not found. Please refresh and try again."
    );

    return;
  }


  renderC2CSupportingDocs();
}


function validateC2CMandatoryAttachments() {
  const rows =
    c2cSupportingAttachments || [];

  const missing = [];


  C2C_REQUIRED_DOCUMENTS.forEach(
    function (requiredRow) {

      const row = rows.find(function (item) {
        return item.id === requiredRow.key;
      });

      if (!row || !row.file) {
        missing.push(
          requiredRow.document_name
        );
      }

    }
  );


  if (missing.length) {
    return {
      ok: false,

      message:
        "Please attach these mandatory documents:<br><br>" +

        missing.map(function (name) {
          return "• " + escapeHtml(name);
        }).join("<br>")
    };
  }


  const optionalWithoutName = [];


  rows.forEach(function (row, idx) {

    if (
      !row.is_mandatory &&
      row.file &&
      !String(
        row.document_name || ""
      ).trim()
    ) {
      optionalWithoutName.push(idx + 1);
    }

  });


  if (optionalWithoutName.length) {
    return {
      ok: false,

      message:
        "Please enter Document Name for extra attachment row(s): " +
        optionalWithoutName.join(", ")
    };
  }


  return {
    ok: true,
    message: ""
  };
}


function validateC2CAttachmentFile(file) {

  const name =
    String(
      file && file.name || ""
    ).toLowerCase();

  const type =
    String(
      file && file.type || ""
    ).toLowerCase();


  const allowedExt =
    /\.(pdf|jpg|jpeg|png|webp)$/i.test(
      name
    );


  const allowedMime = [
    "application/pdf",
    "image/jpeg",
    "image/jpg",
    "image/png",
    "image/webp"
  ].indexOf(type) !== -1;


  if (!allowedExt && !allowedMime) {
    return (
      "Only PDF, JPG, JPEG, PNG, or WEBP files are allowed."
    );
  }


  const maxBytes =
    C2C_ATTACHMENT_MAX_SIZE_MB *
    1024 *
    1024;


  if (
    Number(file.size || 0) >
    maxBytes
  ) {
    return (
      "File size cannot exceed " +
      C2C_ATTACHMENT_MAX_SIZE_MB +
      " MB."
    );
  }


  return "";
}


function getC2CAttachmentType(file) {

  const name =
    String(
      file && file.name || ""
    ).toLowerCase();

  const type =
    String(
      file && file.type || ""
    ).toLowerCase();


  if (
    type === "application/pdf" ||
    name.endsWith(".pdf")
  ) {
    return "PDF";
  }


  return "Image";
}


function formatC2CFileSize(bytes) {

  bytes = Number(bytes || 0);


  if (!bytes) {
    return "";
  }


  if (bytes < 1024) {
    return bytes + " B";
  }


  if (bytes < 1024 * 1024) {
    return (
      Math.round(bytes / 1024) +
      " KB"
    );
  }


  return (
    Math.round(
      (
        bytes /
        (1024 * 1024)
      ) * 10
    ) / 10 +
    " MB"
  );
}


function renderC2CSupportingDocs() {

