      "#c2cAddOptionalAttachmentBtn"
    );


  if (!rowsBox) {
    return;
  }


  const rows =
    c2cSupportingAttachments || [];


  // Existing/saved requests = view only
  const readonly =
    !!currentDocName;


  if (addBtn) {
    addBtn.style.display =
      readonly
        ? "none"
        : "";
  }


  // ==========================================================
  // SAVED REQUEST - READ ONLY
  // ==========================================================
  if (readonly) {

    if (countBox) {

      countBox.textContent =
        rows.length
          ? rows.length +
