          </td>
        </tr>
      `;

      return;
    }


    rowsBox.innerHTML =
      rows.map(function (item, idx) {

        const fileUrl =
          item.file_url || "";

        const fileName =
          item.file_name ||
          item.document_name ||
          "View File";


        return `
          <tr>

            <td>
              ${idx + 1}
            </td>

            <td>
              <strong>
                ${escapeHtml(
                  item.document_name || "-"
                )}
              </strong>
            </td>

            <td>
              ${
                item.is_mandatory
                  ? '<span style="font-weight:700;color:#C00000">Yes</span>'
                  : "No"
              }
            </td>

