              ${
                fileUrl
                  ? `
                    <a
                      href="${escapeHtml(fileUrl)}"
                      target="_blank"
                      rel="noopener"
                    >
                      ${escapeHtml(fileName)}
                    </a>
                  `
                  : "—"
              }
            </td>

            <td>
              ${escapeHtml(
                item.file_type || "—"
              )}
            </td>

            <td>
              ${escapeHtml(
                item.remarks || "—"
              )}
            </td>

            <td>
              ${
                fileUrl
                  ? `
                    <a
                      class="btn btn-outline btn-sm"
                      href="${escapeHtml(fileUrl)}"
                      target="_blank"
                      rel="noopener"
                    >
                      View
                    </a>
                  `
                  : "—"
              }
            </td>

          </tr>
        `;
      }).join("");


    return;
  }


  // ==========================================================
  // NEW REQUEST - EDITABLE
  // ==========================================================

  let pending = 0;


  C2C_REQUIRED_DOCUMENTS.forEach(
    function (requiredRow) {

      const row =
        rows.find(function (item) {
          return (
