      countBox.textContent =
        pending +
        " mandatory file(s) pending";

      countBox.style.color =
        "#C00000";

    } else {

      countBox.textContent =
        "All mandatory files attached";

      countBox.style.color =
        "#1E7A34";
    }

  }


  rowsBox.innerHTML =
    rows.map(function (item, idx) {

      const documentNameHtml =
        item.fixed
          ? `
            <strong>
              ${escapeHtml(
                item.document_name
              )}
            </strong>
          `
          : `
