function loadC2CSupportingDocsFromDoc(doc) {

  const savedRows =
    doc &&
    Array.isArray(
      doc[
        C2C_ATTACHMENT_CHILD_FIELD
      ]
    )
      ? doc[
          C2C_ATTACHMENT_CHILD_FIELD
        ]
      : [];


  c2cSupportingAttachments =
    savedRows.map(
      function (row, idx) {

        const required =
          C2C_REQUIRED_DOCUMENTS.find(
            function (item) {
              return (
                item.document_name ===
                row.document_name
              );
            }
          );


        return {

          id:
            required
              ? required.key
              : "saved_" + idx,

          document_name:
            row.document_name || "",

          is_mandatory:
            Number(
              row.is_mandatory || 0
            ),

          fixed:
            !!required,

          saved: true,

          file: null,

          file_url:
            row.attachment || "",

          file_name:
            row.file_name || "",

          file_size: 0,

          file_type:
            row.file_type || "",

          remarks:
            row.remarks || ""
        };

      }
    );


  c2cCurrentAttachmentRowId = "";

  renderC2CSupportingDocs();
}


