// UPLOAD FILES
// ============================================================

function uploadC2CSupportingDocs(
  docname
) {

  const rows =
    (
      c2cSupportingAttachments ||
      []
    ).filter(
      function (item) {
        return item.file;
      }
    );


  if (!rows.length) {
    return Promise.resolve([]);
  }


  return Promise.all(
    rows.map(
      function (item) {
        return uploadSingleC2CAttachment(
          docname,
          item
        );
      }
    )
  );
}


function uploadSingleC2CAttachment(
  docname,
  item
) {

  return new Promise(
    function (resolve, reject) {

      const formData =
        new FormData();


      formData.append(
        "file",
        item.file,
        item.file_name ||
        item.file.name
      );

      formData.append(
        "is_private",
        "1"
      );

      formData.append(
        "folder",
        "Home/Attachments"
      );

      formData.append(
        "doctype",
        DOCTYPE
      );

      formData.append(
        "docname",
        docname
      );


      const xhr =
        new XMLHttpRequest();


      xhr.open(
        "POST",
        "/api/method/upload_file",
        true
      );


      const csrfToken =
        (
          window.frappe &&
          frappe.csrf_token
        ) ||
        window.csrf_token ||
        "";


      if (csrfToken) {
        xhr.setRequestHeader(
          "X-Frappe-CSRF-Token",
          csrfToken
        );
      }


      xhr.onreadystatechange =
        function () {

          if (
            xhr.readyState !== 4
          ) {
            return;
          }


          let response = {};


          try {

            response =
              JSON.parse(
                xhr.responseText ||
                "{}"
              );

          } catch (e) {

            reject(
              "Unable to read upload response for " +
              (
                item.file_name ||
                "file"
              )
            );

            return;
          }


          if (
            xhr.status >= 200 &&
            xhr.status < 300 &&
            response.message
          ) {

            resolve({

              document_name:
                item.document_name,

              is_mandatory:
                item.is_mandatory
                  ? 1
                  : 0,

              file_url:
                response.message
                  .file_url ||
                "",

              file_name:
                response.message
                  .file_name ||
                item.file_name ||
                "",

              file_type:
                item.file_type || "",

              remarks:
                item.remarks || ""
            });


          } else {

            reject(
              response.exception ||
              response.message ||
              (
                "Upload failed for " +
                (
                  item.file_name ||
                  "file"
                )
              )
            );

          }

        };


      xhr.onerror =
        function () {

          reject(
            "Network error while uploading " +
            (
              item.file_name ||
              "file"
            )
          );

        };


      xhr.send(formData);
    }
  );
}


function saveC2CAttachmentChildRows(
  docname,
  uploadedDocs
) {

  uploadedDocs =
    uploadedDocs || [];


  return new Promise(
    function (resolve, reject) {

      frappe.call({

        method:
          "frappe.client.get",

        args: {
          doctype: DOCTYPE,
          name: docname
        },


        callback:
          function (r) {

            const savedDoc =
              r.message;


            if (!savedDoc) {

              reject(
                "Unable to reload saved request for supporting-document update."
              );

              return;
            }


            if (
              Number(savedDoc.current_tab_step || 1) <= 2 &&
              !String(savedDoc.centre_manager_decision || "").trim()
            ) {
              savedDoc.final_approval_status = "";
              savedDoc.centre_manager_decision = "";
              savedDoc.operations_manager_decision = "";
              savedDoc.audit_team_decision = "";
              savedDoc.approval_stage = APPROVAL_STAGES.CM_PENDING;
              savedDoc.approval_display_status = APPROVAL_STAGES.CM_PENDING;
              savedDoc.conversion_status = APPROVAL_STAGES.CM_PENDING;
              savedDoc.automation_status = "Not Started";
            }


            savedDoc[
              C2C_ATTACHMENT_CHILD_FIELD
            ] = [];


            uploadedDocs.forEach(
              function (fileRow) {

                savedDoc[
                  C2C_ATTACHMENT_CHILD_FIELD
                ].push({

                  doctype:
                    C2C_ATTACHMENT_CHILD_DOCTYPE,

                  document_name:
                    fileRow.document_name,

                  attachment:
                    fileRow.file_url,

                  file_name:
                    fileRow.file_name,

                  file_type:
                    fileRow.file_type,

                  is_mandatory:
                    fileRow.is_mandatory
                      ? 1
                      : 0,

                  remarks:
                    fileRow.remarks ||
                    "",

                  uploaded_by:
                    frappe.session &&
                    frappe.session.user
                      ? frappe.session.user
                      : "",

                  uploaded_on:
                    frappe.datetime &&
                    frappe.datetime
                      .now_datetime
                      ? frappe.datetime
                          .now_datetime()
                      : ""
                });

              }
            );


            frappe.call({

              method:
                "frappe.client.save",

              args: {
                doc: savedDoc
              },


              callback:
                function (
                  saveResult
                ) {

                  resolve(
                    saveResult.message &&
                    saveResult.message[
                      C2C_ATTACHMENT_CHILD_FIELD
                    ]
                      ? saveResult.message[
                          C2C_ATTACHMENT_CHILD_FIELD
                        ]
                      : uploadedDocs
                  );

                },


              error:
                function (err) {

                  reject(
                    getFrappeErrorMessage(
                      err,
                      "Supporting document child-table save failed."
                    )
                  );

                }
            });

          },


        error:
          function (err) {

            reject(
              getFrappeErrorMessage(
                err,
                "Unable to reload saved request."
              )
            );

          }

      });

    }
  );
}


