function validateStage(step) {
  step = Number(step || 1);

  if (step === 1) {
      ensureBranchEmailFields();
        syncDeclarationNames();
        enforceClientReadonlyFields();
    if (!getField("date")) { frappe.msgprint("Please select Date."); return false; }
    if (!getField("branch")) { frappe.msgprint("Please select Branch."); return false; }
    if (!getField("client_full_name")) { frappe.msgprint("Please select Transferor."); return false; }
    if (!getField("client_name")) { frappe.msgprint("Please select Transferee."); return false; }
    if (!validateDifferentTransferorTransferee()) return false;
    if (!getField("receiving_branch")) { frappe.msgprint("Please select or auto-fetch Receiving Branch."); return false; }
    const fromBranch = String(getField("branch") || "").trim();
    const toBranch = String(getField("receiving_branch") || "").trim();

    if (!c2cBranchMatches(toBranch, fromBranch)) {
      frappe.msgprint({
        title: "Cross Branch Transfer Not Allowed",
        indicator: "red",
        message:
          "Transferor branch is <b>" + escapeHtml(fromBranch) + "</b>.<br>" +
          "Transferee branch is <b>" + escapeHtml(toBranch || "missing") + "</b>.<br><br>" +
          "Please select a transferee from the same branch only."
      });
      return false;
    }
    if (!getField("branch_email")) { frappe.msgprint("From Branch Email is missing. Please check Branch master email."); return false; }
    if (!getField("receiving_branch_email")) { frappe.msgprint("To Branch Email is missing. Please check Receiving Branch master email."); return false; }
    updateTransferType();
    if (!getField("transfer_type")) { frappe.msgprint("Unable to identify transfer type. Please reselect transferor and transferee."); return false; }
    if (Number(getField("conversion_charges_applied") || 0) === 1) {
      if (!normalizeConversionChargesAmount(true)) return false;
      const chargeAmount = Number(getField("conversion_charges_amount") || 0);
      if (!Number.isInteger(chargeAmount) || chargeAmount <= 0) { frappe.msgprint("Please enter a valid Conversion Charges Amount. Only whole rupee amount is allowed."); return false; }
    }
    if (!selectedConversionPlanNames.length) {
  frappe.msgprint(
    "Please select at least one invoiced Therapy Plan for conversion."
  );
  return false;
}

if (!validateTransferRowsBeforeSave()) {
  return false;
}


// MANDATORY SUPPORTING DOCUMENT VALIDATION
const attachmentValidation =
  validateC2CMandatoryAttachments();

if (!attachmentValidation.ok) {

  frappe.msgprint({
    title: "Mandatory Documents Required",
    indicator: "red",
    message: attachmentValidation.message
  });

  return false;
}


if (
  !root.querySelector("#transferorConsent").checked ||
  !root.querySelector("#transfereeConsent").checked
) {
  frappe.msgprint(
    "Please confirm both declarations before submitting."
  );

  return false;
}

    if (!validateRequiredSignature("transferor_signature", "Transferor Signature")) return false;
    if (!validateRequiredSignature("transferee_signature", "Transferee Signature")) return false;
    const conversionReason = String(getField("reason__remarks_of__conversion") || "").trim();

if (!conversionReason) {
  frappe.msgprint({
    title: "Reason Required",
    indicator: "red",
    message: "Reason / Remarks of Conversion is mandatory before submitting the request."
  });

  const reasonEl = root.querySelector('[data-field="reason__remarks_of__conversion"]');
  if (reasonEl) {
    reasonEl.focus();
    reasonEl.classList.add("cpc-field-error");
    setTimeout(function () {
      reasonEl.classList.remove("cpc-field-error");
    }, 1800);
  }

  return false;
}

if (!validateMaxWords("reason__remarks_of__conversion", "Reason / Remarks of Conversion", 400)) return false;
    if (!validateMaxWords("stores_remark", "Stores Remark", 400)) return false;
  }

  if (step === 2) {
    const stage = getApprovalStage();
    if (stage === APPROVAL_STAGES.CM_PENDING) {
      if (!getSelectedEmployeeId("centre_manager_name")) { frappe.msgprint("Please select Centre Manager Name from the dropdown list."); return false; }
      if (!getField("centre_manager_date")) { frappe.msgprint("Please select Centre Manager Date."); return false; }
      if (!isTodayOrFutureDate(getField("centre_manager_date"))) { frappe.msgprint("Centre Manager Date cannot be a past date."); return false; }
      if (!validateRequiredSignature("centre_manager_signature", "Centre Manager Signature")) return false;
      if (!validateRequiredRemarks("centre_manager_remarks", "Centre Manager Remarks")) return false;
    }
    if (!activeApprovalAction) { frappe.msgprint("Please click Approve or Reject."); return false; }
  }

  if (step === 3) {
    const stage = getApprovalStage();
    if (stage === APPROVAL_STAGES.AUDIT_PENDING) {
      if (!isAllowedAuditUser()) {
          frappe.msgprint("Only authorised Audit / Corporate Team users can approve this stage.");
          return false;
        }

        autoFillAuditFromLogin();

        if (!getField("audit_team__corporate_team_name")) {
          frappe.msgprint("Audit Team / Corporate Team user could not be identified from login.");
          return false;
        }
      if (!getField("audit_team__corporate_team_date")) { frappe.msgprint("Please select Audit Team / Corporate Team Date."); return false; }
      if (!isTodayOrFutureDate(getField("audit_team__corporate_team_date"))) { frappe.msgprint("Audit Team / Corporate Team Date cannot be a past date."); return false; }
      if (!validateRequiredSignature("audit_team__corporate_team_signature", "Audit Team / Corporate Team Signature")) return false;
      if (!validateRequiredRemarks("audit_team_remarks", "Audit Team Remarks")) return false;
    }
    if (stage === APPROVAL_STAGES.COO_PENDING) {
      if (!isLoggedInFinalCooUser()) { frappe.msgprint("Only authorised Operations COO / Management users can complete final approval."); return false; }
      autoFillFinalCooFromLogin();
      if (!getField("operations_coo__management_name")) { frappe.msgprint("Operations COO / Management Name could not be identified from logged-in user."); return false; }
      if (!getField("operations_coo__management_date")) { frappe.msgprint("Operations COO / Management Date is required."); return false; }
      if (!isTodayOrFutureDate(getField("operations_coo__management_date"))) { frappe.msgprint("Operations COO / Management Date cannot be a past date."); return false; }
      if (!validateRequiredSignature("operations_coo__management_signature", "Operations COO / Management Signature")) return false;
      if (!validateRequiredRemarks("office_remarks_any", "Final Approval Remarks")) return false;
    }
    if (!activeApprovalAction) { frappe.msgprint("Please click Approve or Reject."); return false; }
  }

  return true;
}

