function collectFormDataForStage(step) {
  step = Number(step || 1);
  const data = {};

  if (step === 1) {
    collectFieldsInto(data, ["date","branch","receiving_branch","transfer_type","branch_email","receiving_branch_email","client_full_name","name1","gender","mobile_number","original_invoice__bill_numbers","reason__remarks_of__conversion","started_date","total_paid_amount","products__kits_on__client_name_from","stores","balance_amount","conversion_charges_applied","conversion_charges_amount","stores_remark","client_name","client_id__new_card_no","phone_number","email_id","dob","client_gender","any_allergy_or__contraindication_to_note","if_yes_specify","client_address","relationship_to_transferor","relation","id_proof_type_and_number","id_proof_number","is_transferee_an_existing_life_client","if_yes_existing_client_id","medical_condition_if_any","approval_stage","centre_manager_decision","operations_manager_decision","audit_team_decision","rejected_by_role","rejected_by_name","rejection_remarks","transferors_declaration","transferor_full_name","transferor_signature","transferor_date","transferees_declaration","transferee_full_name","transferee_signature","transferee_date"]);
    data.complete_package_details = collectPackageRows();
    data.remaining_sessions_package_details = collectRemainingPackageRows();
    if (Number(data.conversion_charges_applied || 0) === 1) {
      data.conversion_charges_amount = Number(conversionChargesAmount ? conversionChargesAmount.value || 0 : 0);
    } else {
      data.conversion_charges_amount = 0;
    }
  }

  if (step === 2) {
    collectFieldsInto(data, ["approval_stage","centre_manager_name","centre_manager_signature","centre_manager_date","centre_manager_decision","centre_manager_remarks","operations_manager_name","operations_manager_signature","operations_manager_date","operations_manager_decision","operations_manager_remarks","rejected_by_role","rejected_by_name","rejection_remarks"]);
  }

  if (step === 3) {
    collectFieldsInto(data, ["approval_stage","audit_team__corporate_team_name","audit_team__corporate_team_signature","audit_team__corporate_team_date","audit_team_decision","audit_team_remarks","operations_coo__management_name","operations_coo__management_signature","operations_coo__management_date","final_approval_status","office_remarks_any","rejected_by_role","rejected_by_name","rejection_remarks"]);
  }

  return data;
}

function collectFieldsInto(target, fieldnames) {
  fieldnames.forEach(function (fieldname) {
    const input = root.querySelector(`[data-field="${fieldname}"]`);
    if (input && input.dataset && input.dataset.employeeId) target[fieldname] = String(input.dataset.employeeId || "").trim();
    else target[fieldname] = getField(fieldname);
  });
}

function collectPackageRows() {
  const rows = [];
  if (!packageRows) return rows;
  packageRows.querySelectorAll("tr").forEach(function (tr) {
    const row = { doctype: COMPLETE_CHILD_DOCTYPE };
    tr.querySelectorAll("[data-child-field]").forEach(function (input) { row[input.dataset.childField] = input.value || ""; });
    const hasValue = Object.keys(row).some(function (key) { return key !== "doctype" && row[key]; });
    if (hasValue) rows.push(row);
  });
  return rows;
}

function collectRemainingPackageRows() {
  const rows = [];
  if (!remainingPackageRows) return rows;
  remainingPackageRows.querySelectorAll("tr").forEach(function (tr) {
    if (tr.querySelector(".cpc-empty-row")) return;
    const row = { doctype: REMAINING_CHILD_DOCTYPE };
    tr.querySelectorAll("[data-remaining-field]").forEach(function (input) { row[input.dataset.remainingField] = input.value || ""; });
    const convertedQty = Number(row.converted_quantity || 0);
    if (convertedQty > 0 && row.therapy_plans_been_transferred) rows.push(row);
  });
  return rows;
}

