function fillFormFromDoc(doc) {
  const savedDocName = doc.name;
  let savedWorkflowStep = Number(doc.current_tab_step || 1);
  if (savedWorkflowStep < 1) savedWorkflowStep = 1;
  if (savedWorkflowStep > 4) savedWorkflowStep = 4;

  resetForm();
  currentDocName = savedDocName; currentWorkflowStep = savedWorkflowStep; loadedDoc = doc;

  if (!doc.approval_stage || doc.approval_stage === "Branch Official Approval Pending" || doc.approval_stage === "Management Approval Pending") {
    if (savedWorkflowStep <= 1) doc.approval_stage = APPROVAL_STAGES.REQUEST_PENDING;
    else if (savedWorkflowStep === 2) {
      doc.approval_stage = doc.centre_manager_decision
        ? APPROVAL_STAGES.AUDIT_PENDING
        : APPROVAL_STAGES.CM_PENDING;
    }
    else if (savedWorkflowStep === 3) doc.approval_stage = doc.final_approval_status ? doc.final_approval_status : (doc.audit_team_decision === "Approved" || doc.audit_team_decision === "Rejected") ? APPROVAL_STAGES.COO_PENDING : APPROVAL_STAGES.AUDIT_PENDING;
    else doc.approval_stage = doc.final_approval_status || APPROVAL_STAGES.APPROVED;
  }

  setField("approval_stage", doc.approval_stage);
  if (currentDocLabel) currentDocLabel.textContent = currentDocName || "New Request";

  root.querySelectorAll("[data-field]").forEach(function (el) {
    const fieldname = el.dataset.field;
    if (!fieldname) return;
    if (doc[fieldname] !== undefined && doc[fieldname] !== null) {
      if (el.type === "checkbox") el.checked = Number(doc[fieldname] || 0) === 1;
      else el.value = doc[fieldname];
    }
  });

  refreshTransferorAlternateMobileFromPatient(doc.name1);

  loadEmployeeDisplayNames(doc);

  if (transferorSearch) transferorSearch.value = doc.name1 || doc.client_full_name || "";
  if (transfereeSearch) transfereeSearch.value = doc.client_name || "";
  if (transfereeFullDisplayName) transfereeFullDisplayName.value = doc.client_name || "";
  if (doc.client_name) loadPatientDisplayName(doc.client_name, transfereeFullDisplayName);

  renderCompletePackageRows(
  doc.complete_package_details || []
);

renderRemainingPackageRows(
  doc.remaining_sessions_package_details || []
);


// LOAD SAVED SUPPORTING DOCUMENTS
loadC2CSupportingDocsFromDoc(doc);


if (doc.client_name) {
  fetchTransfereeExistingPlans(
    doc.client_name
  );
}
  else renderTransfereeExistingPlans([]);

  applyConditionalVisibility();
  renderReview();

  transferorConfirmedForRequest = true;
updateTransferorConfirmGate();

  setTimeout(function () {
      enhanceSignatureFields();
      bindSignaturePads();
      redrawAllSignatures();

      makeFetchedParentFieldsReadonly();
      enforceFixedTodayDateFields(false);

      if (currentWorkflowStep >= 4) applyStepAccessControl(1);
      else applyStepAccessControl(currentWorkflowStep);

      updateSignatureAccessControl();
    }, 200);
}

function makeFetchedParentFieldsReadonly() {
  FETCHED_PARENT_FIELDS.forEach(function (fieldname) {
    const el = root.querySelector(`[data-field="${fieldname}"]`);
