function countWords(value) { return String(value || "").trim().split(/\s+/).filter(function (word) { return word.length > 0; }).length; }

function validateMaxWords(fieldname, label, maxWords) {
  const value = getField(fieldname);
  const wordCount = countWords(value);
  if (wordCount > maxWords) { frappe.msgprint(label + " cannot exceed " + maxWords + " words. Current words: " + wordCount); return false; }
  return true;
}

function validateRequiredRemarks(fieldname, label) {
  const value = String(getField(fieldname) || "").trim();
  if (!value) { frappe.msgprint(label + " is required."); return false; }
  return validateMaxWords(fieldname, label, 400);
}

