function normalizeC2CBranchName(branch) {
  branch = String(branch || "").trim().toLowerCase();

  const aliases = {
    "himayathnagar": "himayatnagar",
    "himayatnagar": "himayatnagar",
    "chandhanagar": "chandanagar",
