    "s r nagar": "sr nagar"
  };

  return aliases[branch] || branch;
}

function c2cBranchMatches(actualBranch, allowedBranch) {
  actualBranch = String(actualBranch || "").trim();
  allowedBranch = String(allowedBranch || "").trim();

  if (!actualBranch || !allowedBranch) return false;

  const allowed = normalizeC2CBranchName(allowedBranch);

  const branchParts = actualBranch
    .split(/[,|;\n]/)
    .map(function (x) {
      return normalizeC2CBranchName(x);
    })
    .filter(Boolean);

  return branchParts.indexOf(allowed) !== -1;
}


function validateTransferorBranchForLoggedInUser(transferorBranch) {
  if (isC2CPrivilegedUser()) return true;

  const allowedBranch = getC2CLoggedInBranch();

  if (!allowedBranch) {
    frappe.msgprint("Your login is not mapped with any branch. Please contact admin.");
    return false;
  }

  if (!c2cBranchMatches(transferorBranch, allowedBranch)) {
    frappe.msgprint({
      title: "Wrong Transferor Branch",
      indicator: "red",
      message:
        "You are logged in for <b>" + allowedBranch + "</b> branch.<br>" +
        "Transferor client belongs to <b>" + (transferorBranch || "another branch") + "</b>.<br><br>" +
        "Please select transferor client from your own branch only."
    });

    return false;
  }

  return true;
}

