function searchPatients(keyword, resultBox, type) {
  keyword = String(keyword || "").trim();

  if (!keyword || keyword.length < 2) {
    resultBox.innerHTML = "";
    resultBox.classList.remove("show");
    resultBox.style.display = "none";
    return;
  }

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Patient",

      // Only safe / existing Patient fields
      fields: [
        "name",
        "patient_name",
        "first_name",
        "sex",
        "mobile",
        "phone",
        "email",
        "dob",
        "branch_name",
        "modified"
      ],

      // Do not add branch filter here.
      // ERPNext permissions will already restrict branch users.
      filters: [],

      or_filters: [
        ["Patient", "name", "like", "%" + keyword + "%"],
        ["Patient", "patient_name", "like", "%" + keyword + "%"],
        ["Patient", "first_name", "like", "%" + keyword + "%"],
        ["Patient", "mobile", "like", "%" + keyword + "%"],
        ["Patient", "phone", "like", "%" + keyword + "%"]
      ],

      order_by: "modified desc",
      limit_page_length: 20
    },

    callback: function (r) {
      const rows = (r.message || []).map(function (row) {
        row.display_name = row.patient_name || row.first_name || row.name || "";
        row.mobile_display = row.mobile || row.phone || "";
        row.branch_display = row.branch_name || "";
        row.email_display = row.email || "";
        row.address_display = "";
        return row;
      });

      renderC2CPatientResultsFromApi(rows, resultBox, type);
    },

    error: function (err) {
      void 0;

      resultBox.innerHTML = `
        <div class="ac-item">
          <div style="font-weight:700;color:#C00000">Unable to search clients</div>
          <div style="font-size:10px;color:#595959;margin-top:2px">
            ${escapeHtml(getFrappeErrorMessage(err, "Please check Patient search fields."))}
          </div>
        </div>
      `;

      resultBox.classList.add("show");
      resultBox.style.display = "block";
    }
  });
}

function renderC2CPatientResultsFromApi(rows, resultBox, type) {
  rows = rows || [];

  if (!resultBox) return;

  if (!rows.length) {
    if (type === "transferee") {
      resultBox.innerHTML = `
        <div class="ac-item" style="color:#595959">
          <div style="font-weight:700;color:#0D2B4E">No matching client found</div>
          <div style="font-size:10px;margin-top:2px">Try searching by mobile number or client ID</div>
        </div>
        <div class="ac-item" data-create-new-transferee="1" style="cursor:pointer;border-top:2px solid #1E7A34">
          <div style="font-weight:800;color:#1E7A34">+ Create New Transferee</div>
          <div style="font-size:10px;color:#595959;margin-top:2px">Create a new Patient record with mandatory details</div>
        </div>
      `;

      resultBox.classList.add("show");
      resultBox.style.display = "block";

      const createBtn = resultBox.querySelector("[data-create-new-transferee]");
      if (createBtn) {
        createBtn.addEventListener("mousedown", function (e) {
          e.preventDefault();
          openNewTransfereeCreateBox();
          hideSearchResults();
        });
      }

      return;
    }

    resultBox.innerHTML = `
      <div class="ac-item" style="color:#595959">
        <div style="font-weight:700;color:#0D2B4E">No matching client found</div>
        <div style="font-size:10px;margin-top:2px">Try searching by mobile number or client ID</div>
      </div>
    `;

    resultBox.classList.add("show");
    resultBox.style.display = "block";
    return;
  }

  resultBox.innerHTML = rows.map(function (row, idx) {
    const patientId = row.name || "";
    const displayName = row.display_name || row.patient_name || row.first_name || patientId;
    const mobile = row.mobile_display || row.mobile || row.phone || "";
    const branch = row.branch_display || row.branch_name || "";

    return `
      <div class="ac-item c2c-api-patient-item" data-idx="${idx}" style="cursor:pointer">
        <div style="display:flex;align-items:center;justify-content:space-between;gap:8px">
          <div>
            <div class="acn">${escapeHtml(displayName)}</div>
            <div class="acm" style="margin-top:2px">
              ${escapeHtml(patientId)}
              ${mobile ? " · " + escapeHtml(mobile) : ""}
              ${branch ? " · " + escapeHtml(branch) : ""}
            </div>
          </div>
          <span style="background:#0D2B4E;color:#fff;font-size:8.5px;padding:2px 8px;border-radius:10px;font-weight:700;white-space:nowrap">
            Select
          </span>
        </div>
      </div>
    `;
  }).join("");

  resultBox.classList.add("show");
  resultBox.style.display = "block";

  resultBox.querySelectorAll(".c2c-api-patient-item").forEach(function (item) {
    item.addEventListener("mousedown", function (e) {
      e.preventDefault();

      const idx = Number(item.dataset.idx || 0);
      const patient = rows[idx];

      if (!patient || !patient.name) {
        frappe.msgprint("Selected client data not found. Please search again.");
        return;
      }

      selectC2CPatientFromApi(patient, type);
      hideSearchResults();
    });
  });
}


function selectC2CPatientFromApi(patient, type) {
  if (!patient || !patient.name) return;

  const selectedPatientId = String(patient.name || "").trim();

  if (type === "transferor" && !currentDocName) {
    transferorConfirmedForRequest = false;
    updateTransferorConfirmGate();
  }

