function normalizeC2CClientId(value) {
  return String(value || "").trim().toLowerCase();
}

function isSameC2CClient(transferorId, transfereeId) {
  transferorId = normalizeC2CClientId(transferorId);
  transfereeId = normalizeC2CClientId(transfereeId);

  return !!(transferorId && transfereeId && transferorId === transfereeId);
}

function showSameC2CClientError(message) {
  frappe.msgprint({
    title: "Same Client Not Allowed",
    indicator: "red",
    message: message || "Transferor and Transferee cannot be the same client. Please select a different client."
  });
}

function validateDifferentTransferorTransferee() {
  const transferorId = getField("name1");
  const transfereeId = getField("client_name");

  if (isSameC2CClient(transferorId, transfereeId)) {
    showSameC2CClientError();
    return false;
  }

  return true;
}

