function getValidActiveConsultationPractitioner(practitionerId) {
  return new Promise(function (resolve, reject) {
    practitionerId = String(practitionerId || "").trim();

    if (!practitionerId) {
      resolve(null);
      return;
    }

    frappe.call({
      method: "frappe.client.get_list",
      args: {
        doctype: "Healthcare Practitioner",
        fields: [
          "name",
          "practitioner_name",
          "status",
          "practitioner_type",
          "employee",
          "designation",
          "department"
        ],
        filters: [
          [
            "Healthcare Practitioner",
            "name",
            "=",
            practitionerId
          ],
          [
            "Healthcare Practitioner",
            "status",
            "=",
            "Active"
          ]
        ],
        limit_page_length: 1
      },

      callback: function (r) {
        const rows = r.message || [];
        resolve(rows.length ? rows[0] : null);
      },

      error: function (err) {
        reject(err);
      }
    });
  });
}


