async function uploadNewTransfereePdForms(
  patientName,
  files
) {
  patientName = String(patientName || "").trim();

  // ========================================================
  // BASIC VALIDATION
  // ========================================================

  if (!patientName) {
    throw new Error(
      "Patient name is missing for PD Form upload."
    );
  }

  files = Array.isArray(files)
    ? files
    : [];

  if (files.length < 2) {
    throw new Error(
      "Minimum 2 PD Form images are required."
    );
  }

  if (files.length > 5) {
    throw new Error(
      "Maximum 5 PD Form images are allowed."
    );
  }

  const allowedTypes = [
    "image/jpeg",
    "image/png"
  ];

  const maxFileSize =
    5 * 1024 * 1024;

  const uploadedFiles = [];


  // ========================================================
  // STEP 1: VALIDATE + UPLOAD EACH IMAGE
  // ========================================================

  for (let i = 0; i < files.length; i++) {
    const file = files[i];

    if (!file) {
      continue;
    }

    if (!allowedTypes.includes(file.type)) {
      throw new Error(
        "Only JPG, JPEG and PNG images are allowed: " +
        file.name
      );
    }

    if (file.size > maxFileSize) {
      throw new Error(
        "PD Form image must be 5 MB or less: " +
        file.name
      );
    }

    const formData =
      new FormData();

    formData.append(
      "file",
      file
    );

    formData.append(
      "is_private",
      "0"
    );

    formData.append(
      "folder",
      "Home"
    );

    // Attach File record to Patient
    formData.append(
      "doctype",
      "Patient"
    );

    formData.append(
      "docname",
      patientName
    );

    let response;

    try {
      response =
        await fetch(
          "/api/method/upload_file",
          {
            method: "POST",

            body:
              formData,

            headers: {
              "X-Frappe-CSRF-Token":
                frappe.csrf_token
            }
          }
        );
    } catch (networkError) {
      void 0;

      throw new Error(
        "Network error while uploading: " +
        file.name
      );
    }

    let data = null;

    try {
      data =
        await response.json();
    } catch (jsonError) {
      void 0;

      throw new Error(
        "Invalid server response while uploading: " +
        file.name
      );
    }

    if (
      !response.ok ||
      !data ||
      data.exc ||
      data.exception ||
      !data.message
    ) {
      void 0;

      throw new Error(
        "Unable to upload PD Form image: " +
        file.name
      );
    }

    const uploaded =
      data.message || {};

    const fileUrl =
      String(
        uploaded.file_url || ""
      ).trim();

    if (!fileUrl) {
      void 0;

      throw new Error(
        "Uploaded PD Form image has no file URL: " +
        file.name
      );
    }

    uploadedFiles.push({
      file_name:
        uploaded.file_name ||
        file.name,

      file_url:
        fileUrl,

      file_id:
        uploaded.name || ""
    });
  }


  // ========================================================
  // STEP 2: RELOAD PATIENT
  // ========================================================

  const patientResponse =
    await frappe.call({
      method:
        "frappe.client.get",

      args: {
        doctype:
          "Patient",

        name:
          patientName
      }
    });

  const patientDoc =
    patientResponse &&
    patientResponse.message
      ? patientResponse.message
      : null;

  if (!patientDoc) {
    throw new Error(
      "Unable to reload Patient after PD Form upload."
    );
  }

  if (
    !Array.isArray(
      patientDoc.custom_pd_form
    )
  ) {
    patientDoc.custom_pd_form = [];
  }


  // ========================================================
  // STEP 3: ADD CHILD ROWS
  // Exact child field confirmed = pd_form
  // ========================================================

  uploadedFiles.forEach(
    function (uploaded) {
      const fileUrl =
        String(
          uploaded.file_url || ""
        ).trim();

      if (!fileUrl) {
        return;
      }

      // Avoid duplicate child rows
      const alreadyExists =
        patientDoc.custom_pd_form.some(
          function (row) {
            return (
              String(
                row &&
                row.pd_form
                  ? row.pd_form
                  : ""
              ).trim() ===
              fileUrl
            );
          }
        );

      if (alreadyExists) {
        return;
      }

      patientDoc.custom_pd_form.push({
        doctype:
          "PD Form",

        pd_form:
          fileUrl
      });
    }
  );


  // ========================================================
  // STEP 4: MAKE SURE CHILD ROWS EXIST BEFORE SAVE
  // ========================================================

  if (
    patientDoc.custom_pd_form.length < 2
  ) {
    void 0;

    throw new Error(
      "Unable to prepare minimum 2 PD Form child rows."
    );
  }


  // ========================================================
  // STEP 5: SAVE PATIENT
  // ========================================================

  let saveResponse;

  try {
    saveResponse =
      await frappe.call({
        method:
          "frappe.client.save",

        args: {
          doc:
            patientDoc
        }
      });
  } catch (saveError) {
    void 0;

    throw saveError;
  }

  const savedPatient =
    saveResponse &&
    saveResponse.message
      ? saveResponse.message
      : null;

  if (!savedPatient) {
    throw new Error(
      "PD Form images uploaded, but PD Form child rows could not be saved."
    );
  }


  // ========================================================
  // STEP 6: VERIFY SAVED PATIENT
  // ========================================================

  const verifyResponse =
    await frappe.call({
      method:
        "frappe.client.get",

      args: {
        doctype:
          "Patient",

        name:
          patientName
      }
    });

  const verifiedPatient =
    verifyResponse &&
    verifyResponse.message
      ? verifyResponse.message
      : null;

  const savedRows =
    verifiedPatient &&
    Array.isArray(
      verifiedPatient.custom_pd_form
    )
      ? verifiedPatient.custom_pd_form
      : [];


  // ========================================================
  // STEP 7: VERIFY EACH UPLOADED FILE EXISTS IN CHILD TABLE
  // ========================================================

  const missingFiles =
    uploadedFiles.filter(
      function (uploaded) {
        return !savedRows.some(
          function (row) {
            return (
              String(
                row &&
                row.pd_form
                  ? row.pd_form
                  : ""
              ).trim() ===
              String(
                uploaded.file_url || ""
              ).trim()
            );
          }
        );
      }
    );

  void 0;


  if (missingFiles.length) {
    void 0;

    throw new Error(
      missingFiles.length +
      " PD Form image(s) were uploaded but not saved in the PD Form table."
    );
  }


  // ========================================================
  // SUCCESS
  // ========================================================

  return {
    success:
      true,

    patient:
      patientName,

    uploaded_files:
      uploadedFiles,

    pd_form_rows:
      savedRows,

    uploaded_count:
      uploadedFiles.length,

    saved_count:
      savedRows.length
  };
}


function bindPdFormImageUploader() {
  if (
    addPdFormImagesBtn &&
    addPdFormImagesBtn.dataset.bound !== "1"
  ) {
    addPdFormImagesBtn.dataset.bound = "1";

    addPdFormImagesBtn.addEventListener(
      "click",
      function () {
        if (newTransfereePdForm) {
          newTransfereePdForm.click();
        }
      }
    );
  }

  if (
    newTransfereePdForm &&
    newTransfereePdForm.dataset.bound !== "1"
  ) {
    newTransfereePdForm.dataset.bound = "1";

    newTransfereePdForm.addEventListener(
      "change",
      function () {
        const selected = Array.from(
          newTransfereePdForm.files || []
        );

        const availableSlots =
          5 - newTransfereePdFiles.length;

        if (selected.length > availableSlots) {
          frappe.show_alert({
            message:
              "Only " +
              availableSlots +
              " more PD Form image" +
              (availableSlots === 1 ? "" : "s") +
              " can be added.",
            indicator: "orange"
          });
        }

        selected.forEach(function (file) {
          if (newTransfereePdFiles.length >= 5) {
            return;
          }

          const duplicate = newTransfereePdFiles.some(
            function (existing) {
              return (
                existing.name === file.name &&
                existing.size === file.size &&
                existing.lastModified === file.lastModified
              );
            }
          );

          if (!duplicate) {
            newTransfereePdFiles.push(file);
          }
        });

        newTransfereePdForm.value = "";

        renderPdFormImageTable();
      }
    );
  }

  if (
    newTransfereePdFormRows &&
    newTransfereePdFormRows.dataset.bound !== "1"
  ) {
    newTransfereePdFormRows.dataset.bound = "1";

    newTransfereePdFormRows.addEventListener(
      "click",
      function (e) {
        const btn = e.target.closest(
          ".c2c-pd-remove-btn"
        );

        if (!btn) return;

        const index = Number(
          btn.dataset.index
        );

        if (
          Number.isNaN(index) ||
          index < 0 ||
          index >= newTransfereePdFiles.length
        ) {
          return;
        }

        newTransfereePdFiles.splice(
          index,
          1
        );

        renderPdFormImageTable();
      }
    );
  }

  renderPdFormImageTable();
}

function formatPdFileSize(bytes) {
  bytes = Number(bytes || 0);

  if (bytes < 1024) {
    return bytes + " B";
  }

  if (bytes < 1024 * 1024) {
    return (
      (bytes / 1024).toFixed(1) +
      " KB"
    );
  }

  return (
    (bytes / (1024 * 1024)).toFixed(2) +
    " MB"
  );
}

function renderPdFormImageTable() {
  if (!newTransfereePdFormRows) {
    return;
  }

  if (!newTransfereePdFiles.length) {
    newTransfereePdFormRows.innerHTML = `
      <tr class="c2c-pd-empty-row">
        <td colspan="5">
          No PD Form images selected.
        </td>
      </tr>
    `;

    if (newTransfereePdFormCount) {
      newTransfereePdFormCount.textContent =
        "0 / 5 images";

      newTransfereePdFormCount.style.color =
        "#C00000";
    }

    return;
  }

  newTransfereePdFormRows.innerHTML =
    newTransfereePdFiles
      .map(function (file, index) {
        const validType = [
          "image/jpeg",
          "image/png"
        ].includes(file.type);

        const validSize =
          file.size <= 5 * 1024 * 1024;

        const isValid =
          validType && validSize;

        let statusText = "Ready";

        if (!validType) {
          statusText = "Invalid type";
        } else if (!validSize) {
          statusText = "Over 5 MB";
        }

        return `
          <tr>
            <td>${index + 1}</td>

            <td>
              <div class="c2c-pd-file-name">
                ${escapeHtml(file.name)}
              </div>
            </td>

            <td>
              ${escapeHtml(
                formatPdFileSize(file.size)
              )}
            </td>

            <td>
              <span class="${
                isValid
                  ? "c2c-pd-status-ok"
                  : "c2c-pd-status-error"
              }">
                ${
                  isValid
                    ? "✓ " + statusText
                    : "⚠ " + statusText
                }
              </span>
            </td>

            <td>
              <button
                type="button"
                class="c2c-pd-remove-btn"
                data-index="${index}"
              >
                Remove
              </button>
            </td>
          </tr>
        `;
      })
      .join("");

  if (newTransfereePdFormCount) {
    const count =
      newTransfereePdFiles.length;

    newTransfereePdFormCount.textContent =
      count + " / 5 images";

    newTransfereePdFormCount.style.color =
      count >= 2 && count <= 5
        ? "#15803d"
        : "#C00000";
  }
}

