      if (!submittedInvoices.length) { frappe.show_alert({ message: "No submitted Sales Invoice found for this client.", indicator: "orange" }); fetchBranchFromSalesInvoice(patientName); return; }
      fetchFullInvoices(submittedInvoices).then(function (fullInvoices) {
        const validInvoices = fullInvoices.filter(function (invoice) { return Number(invoice.docstatus || 0) === 1 && Number(invoice.is_return || 0) === 0; });
        const planNames = [];
        validInvoices.forEach(function (invoice) {
          const planName = getInvoiceTherapyPlanReference(invoice);
          if (planName && !planNames.includes(planName)) planNames.push(planName);
        });
        if (!planNames.length) { frappe.show_alert({ message: "Submitted invoices found, but no linked Therapy Plan reference found.", indicator: "orange" }); renderInvoicedPlanOptions([]); renderCompletePackageRows([]); renderRemainingPackageRows([]); updateOriginalTotalBalanceAmount([]); return; }
        fetchFullInvoicedPlans(planNames).then(function (plans) { buildAndRenderInvoicedPlanOptions(validInvoices, plans); });
      });
    },
    error: function (err) { void 0; frappe.show_alert({ message: "Unable to fetch submitted Sales Invoices.", indicator: "red" }); }
  });
}

