function fetchFullInvoices(invoiceRows) {
  const calls = invoiceRows.map(function (invoice) {
    return new Promise(function (resolve) {
      frappe.call({ method: "frappe.client.get", args: { doctype: "Sales Invoice", name: invoice.name }, callback: function (r) { resolve(r.message || invoice); }, error: function () { resolve(invoice); } });
    });
  });
  return Promise.all(calls);
}

function fetchFullInvoicedPlans(planNames) {
  const calls = planNames.map(function (planName) {
    return new Promise(function (resolve) {
      frappe.call({ method: "frappe.client.get", args: { doctype: "Therapy Plan", name: planName }, callback: function (r) { resolve(r.message || null); }, error: function () { resolve(null); } });
    });
  });
  return Promise.all(calls).then(function (plans) { return plans.filter(Boolean); });
}

function getInvoiceTherapyPlanReference(invoice) {
  if (!invoice) return "";
  if (invoice.therapy_plan_reference_id) return invoice.therapy_plan_reference_id;
  if (invoice.custom_therapy_plan_reference_id) return invoice.custom_therapy_plan_reference_id;
  if (invoice.therapy_plan) return invoice.therapy_plan;
  if (invoice.custom_therapy_plan) return invoice.custom_therapy_plan;
  const items = invoice.items || [];
  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    if (item.therapy_plan_reference_id) return item.therapy_plan_reference_id;
    if (item.custom_therapy_plan_reference_id) return item.custom_therapy_plan_reference_id;
    if (item.therapy_plan) return item.therapy_plan;
    if (item.custom_therapy_plan) return item.custom_therapy_plan;
  }
  return "";
}

function buildAndRenderInvoicedPlanOptions(invoices, plans) {
  invoicedPlanOptions = [];
  plans.forEach(function (plan) {
    const planInvoices = invoices.filter(function (invoice) { return getInvoiceTherapyPlanReference(invoice) === plan.name; });
    if (!planInvoices.length) return;
    const invoiceAmount = planInvoices.reduce(function (sum, inv) { return sum + Number(inv.rounded_total || inv.grand_total || 0); }, 0);
    const outstanding = planInvoices.reduce(function (sum, inv) { return sum + Number(inv.outstanding_amount || 0); }, 0);
    const paidAmount = Math.max(invoiceAmount - outstanding, 0);
    const therapyRows = getTherapyRowsFromPlan(plan);
    const totalBooked = therapyRows.reduce(function (sum, row) { return sum + Number(row.booked_quantity || 0); }, 0);
    const totalAvailed = therapyRows.reduce(function (sum, row) { return sum + Number(row.availed_quantity || 0); }, 0);
    const totalRemaining = Math.max(totalBooked - totalAvailed, 0);
    invoicedPlanOptions.push({
      plan: plan,
      invoices: planInvoices,
      plan_name: plan.name,

      therapy_name: therapyRows
        .map(function (row) { return row.therapy_type; })
        .filter(Boolean)
        .join(", "),

      invoice_names: planInvoices.map(function (inv) { return inv.name; }),

      branch: planInvoices[0] && planInvoices[0].branch
        ? planInvoices[0].branch
        : plan.branch || "",

      invoice_amount: invoiceAmount,
      paid_amount: paidAmount,
      outstanding_amount: outstanding,

      total_booked: totalBooked,
      total_availed: totalAvailed,
      total_remaining: totalRemaining,

      can_transfer: totalRemaining > 0,

      start_date: plan.start_date || "",
      due_date: plan.due_date || ""
    });
  });

  renderInvoicedPlanOptions(invoicedPlanOptions);
  if (!invoicedPlanOptions.length) { frappe.show_alert({ message: "No submitted invoiced Therapy Plan found for this client.", indicator: "orange" }); return; }
  frappe.show_alert({ message: "Submitted invoiced Therapy Plans loaded. Select one or more plans to convert.", indicator: "green" });
}

function hasTransferableSessions(option) {
  return Number(option && option.total_remaining || 0) > 0;
}

function getPlanCompletedReason(option) {
  const booked = Number(option && option.total_booked || 0);
  const availed = Number(option && option.total_availed || 0);
  const remaining = Number(option && option.total_remaining || 0);

  if (booked > 0 && remaining <= 0 && availed >= booked) {
    return "All sessions completed";
  }

  if (remaining <= 0) {
    return "No balance sessions available";
  }

  return "";
}

function renderInvoicedPlanOptions(options) {
  if (!invoicedPlanRows) return;

  if (!options.length) {
    invoicedPlanRows.innerHTML = `
      <tr>
        <td colspan="9" class="cpc-empty-row">
          No submitted invoiced Therapy Plans found.
        </td>
      </tr>
    `;
    return;
  }

  // Safety: remove any previously selected plan that has no remaining sessions
  selectedConversionPlanNames = selectedConversionPlanNames.filter(function (planName) {
    const option = options.find(function (row) {
      return row.plan_name === planName;
    });

    return option && hasTransferableSessions(option);
  });

  invoicedPlanRows.innerHTML = options.map(function (option) {
    const canTransfer = hasTransferableSessions(option);
    const selected = canTransfer && selectedConversionPlanNames.includes(option.plan_name);
    const completedReason = getPlanCompletedReason(option);

    return `
      <tr
        class="cpc-invoiced-plan-row ${selected ? "cpc-selected-plan-row" : ""} ${!canTransfer ? "cpc-plan-not-transferable" : ""}"
        data-plan="${escapeHtml(option.plan_name)}"
        role="checkbox"
        aria-checked="${selected ? "true" : "false"}"
        aria-disabled="${canTransfer ? "false" : "true"}"
        tabindex="${canTransfer ? "0" : "-1"}"
        title="${canTransfer ? "Click anywhere on this row to select or deselect this Therapy Plan" : escapeHtml(completedReason || "No transferable sessions available")}"
      >
        <td>
          <label class="cpc-plan-checkbox-wrap">
            <input
              type="checkbox"
              class="cpc-plan-select-checkbox"
              data-plan="${escapeHtml(option.plan_name)}"
              ${selected ? "checked" : ""}
              ${!canTransfer ? "disabled" : ""}
            >
            <span>${canTransfer ? (selected ? "Selected" : "Select") : "Completed"}</span>
          </label>
        </td>

        <td>
          <b>${escapeHtml(option.plan_name)}</b><br>
          <small>${escapeHtml(option.branch || "")}</small>
        </td>

        <td>${escapeHtml(option.therapy_name || "-")}</td>

        <td>${escapeHtml(option.invoice_names.join(", "))}</td>

        <td>${escapeHtml(formatCurrency(option.invoice_amount))}</td>

        <td>${escapeHtml(formatCurrency(option.paid_amount))}</td>

        <td><b>${escapeHtml(formatCurrency(option.outstanding_amount))}</b></td>

        <td>
          ${escapeHtml(getAvailedTotalDisplay(option))}<br>
          <small class="${canTransfer ? "cpc-fetched-note" : "cpc-danger-note"}">
            ${canTransfer
              ? "Remaining: " + escapeHtml(option.total_remaining || 0)
              : escapeHtml(completedReason || "No transferable sessions")}
          </small>
        </td>

        <td>${escapeHtml(formatDate(option.start_date))} to ${escapeHtml(formatDate(option.due_date))}</td>
      </tr>
    `;
  }).join("");
}

function toggleInvoicedPlanForConversion(planName, checked) {
  planName = String(planName || "").trim();
  if (!planName) return;

  const option = invoicedPlanOptions.find(function (row) {
    return row.plan_name === planName;
  });

  if (checked && (!option || !hasTransferableSessions(option))) {
    selectedConversionPlanNames = selectedConversionPlanNames.filter(function (name) {
      return name !== planName;
    });

    renderInvoicedPlanOptions(invoicedPlanOptions);

    frappe.msgprint({
      title: "Plan Cannot Be Selected",
      indicator: "orange",
      message: "This Therapy Plan cannot be selected because all sessions are already completed. Only plans with balance sessions can be converted."
    });

    return;
  }

  if (checked) {
    if (!selectedConversionPlanNames.includes(planName)) {
      selectedConversionPlanNames.push(planName);
    }
  } else {
    selectedConversionPlanNames = selectedConversionPlanNames.filter(function (name) {
      return name !== planName;
    });
  }

  selectedConversionPlanName = selectedConversionPlanNames.length
    ? selectedConversionPlanNames[0]
    : null;

  loadSelectedInvoicedPlansForConversion();
}


function getSelectedInvoicedPlanOptions() {
  return invoicedPlanOptions.filter(function (option) { return selectedConversionPlanNames.includes(option.plan_name); });
}

function loadSelectedInvoicedPlansForConversion() {
  const selectedOptions = getSelectedInvoicedPlanOptions();
  if (!selectedOptions.length) {
    selectedConversionPlanName = null; selectedConversionPaidAmount = 0; selectedConversionAvailedValue = 0; selectedConversionAvailablePaid = 0;
    setField("started_date", ""); setField("stores", ""); setField("total_paid_amount", 0); setField("balance_amount", 0); setField("original_invoice__bill_numbers", "");
    renderCompletePackageRows([]); renderRemainingPackageRows([]); updateOriginalTotalBalanceAmount([]); updateTransferredTotalAmount(); updateConversionMoneyPanel();
    renderInvoicedPlanOptions(invoicedPlanOptions); renderReview(); return;
  }

  selectedConversionPlanName = selectedOptions[0].plan_name;
  const allInvoiceNames = []; let totalPaid = 0; let totalOutstanding = 0;
  selectedOptions.forEach(function (option) {
    totalPaid += Number(option.paid_amount || 0); totalOutstanding += Number(option.outstanding_amount || 0);
    (option.invoice_names || []).forEach(function (invoiceName) { if (invoiceName && !allInvoiceNames.includes(invoiceName)) allInvoiceNames.push(invoiceName); });
  });

  const firstOption = selectedOptions[0];
  setField("started_date", firstOption.start_date || ""); setField("stores", firstOption.due_date || "");
  setField("branch", firstOption.branch || getField("branch"));
  setField("total_paid_amount", roundMoney(totalPaid)); setField("balance_amount", roundMoney(totalOutstanding));
  setField("original_invoice__bill_numbers", allInvoiceNames.join(", "));
  fillPackageTablesFromSelectedInvoicedPlans(selectedOptions);
  renderInvoicedPlanOptions(invoicedPlanOptions); makeFetchedParentFieldsReadonly(); renderReview();
  frappe.show_alert({ message: selectedOptions.length + " Therapy Plan(s) selected for conversion.", indicator: "green" });
}

function selectInvoicedPlanForConversion(planName) {
  const alreadySelected = selectedConversionPlanNames.includes(planName);
  toggleInvoicedPlanForConversion(planName, !alreadySelected);
}

function roundMoney(value) { return Math.round((Number(value || 0) + Number.EPSILON) * 100) / 100; }

function getInvoiceItemGrossAmountForTherapy(therapyType, invoices) {
  therapyType = String(therapyType || "").trim().toLowerCase();
  let total = 0;
  (invoices || []).forEach(function (invoice) {
    (invoice.items || []).forEach(function (item) {
      const names = [item.item_code, item.item_name, item.description].join(" ").toLowerCase();
      if (!therapyType || !names.includes(therapyType)) return;
      const taxable = Number(item.net_amount || item.base_net_amount || item.amount || item.base_amount || 0);
      const gst = Number(item.cgst_amount || 0) + Number(item.sgst_amount || 0) + Number(item.igst_amount || 0) + Number(item.cess_amount || 0);
      total += taxable + gst;
    });
  });
  // Fallback: if no exact item match found, use total invoice gross amount
  if (total === 0 && invoices && invoices.length) {
    (invoices || []).forEach(function (invoice) {
      total += Number(invoice.rounded_total || invoice.grand_total || 0);
    });
  }
  return roundMoney(total);
}

function getSelectedConversionPaidAmount(option) {
  if (!option) return 0;
  if (option.paid_amount !== undefined && option.paid_amount !== null) return roundMoney(option.paid_amount);
  return roundMoney(Math.max(Number(option.invoice_amount || 0) - Number(option.outstanding_amount || 0), 0));
}

function updateC2CTransferValueStatus() {

  const box =
    root.querySelector(
      "#c2cTransferValueStatus"
    );

  const textEl =
    root.querySelector(
      "#c2cTransferValueStatusText"
    );


  if (!box || !textEl) {
    return;
  }


  const available =
    roundMoney(
      selectedConversionAvailablePaid ||
      0
    );


  const applied =
    roundMoney(
      getCurrentAppliedConversionAmount()
    );


  const pendingValue =
    roundMoney(
      available - applied
    );


  box.classList.remove(
    "notice-blue",
    "notice-green",
    "notice-red"
  );


  // Nothing selected yet
  if (
    !selectedConversionPlanNames.length
  ) {

    box.classList.add(
      "notice-blue"
    );

    textEl.textContent =
      "Select source Therapy Plan(s) to calculate pending value available for package conversion.";

    return;
  }


  // No value available
  if (available <= 0) {

    box.classList.add(
      "notice-red"
    );

    textEl.textContent =
      "No paid balance value is available for package conversion.";

    return;
  }


  // Over limit
  if (pendingValue < 0) {

    box.classList.add(
      "notice-red"
    );

    textEl.textContent =
      "⚠ Package conversion value exceeded by " +
      formatCurrency(
        Math.abs(
          pendingValue
        )
      ) +
      ".";

    return;
  }


  // Allowed
  box.classList.add(
    "notice-green"
  );


  textEl.textContent =
    "✓ Pending Value Available for Package Conversion: " +
    formatCurrency(
      pendingValue
    );
}


function updateConversionMoneyPanel() {

  const applied =
    getCurrentAppliedConversionAmount();


  const remaining =
    Math.max(
      selectedConversionAvailablePaid -
      applied,
      0
    );


  const paidEl =
    root.querySelector(
      "#paidAmountForConversion"
    );

  const availedEl =
    root.querySelector(
      "#availedValueForConversion"
    );

  const availableEl =
    root.querySelector(
      "#availablePaidForConversion"
    );

  const appliedEl =
    root.querySelector(
      "#appliedConversionAmount"
    );

  const remainingEl =
    root.querySelector(
      "#remainingPaidAfterConversion"
    );

  const noteEl =
    root.querySelector(
      "#conversionRuleNote"
    );


  if (paidEl) {
    paidEl.textContent =
      formatCurrency(
        selectedConversionPaidAmount
      );
  }


  if (availedEl) {
    availedEl.textContent =
      formatCurrency(
        selectedConversionAvailedValue
      );
  }


  if (availableEl) {
    availableEl.textContent =
      formatCurrency(
        selectedConversionAvailablePaid
      );
  }


  if (appliedEl) {
    appliedEl.textContent =
      formatCurrency(applied);
  }


  if (remainingEl) {
