    ) {

      noteEl.classList.add(
        "rule-danger"
      );

      noteEl.textContent =
        "Blocked: Applied conversion amount is more than the paid balance available.";

    } else {

      noteEl.classList.remove(
        "rule-danger"
      );

      noteEl.textContent =
        "Allowed: Applied conversion amount must stay within the paid balance available.";
    }

  }


  // NEW P2P-STYLE STATUS LINE
  updateC2CTransferValueStatus();
}


function getCurrentAppliedConversionAmount() {
  let total = 0;
  if (!remainingPackageRows) return 0;
  remainingPackageRows.querySelectorAll("tr").forEach(function (tr) {
    if (tr.querySelector(".cpc-empty-row")) return;
    const amountInput = tr.querySelector('[data-remaining-field="total_amount"]');
    total += Number(amountInput ? amountInput.value || 0 : 0);
  });
  return roundMoney(total);
}

function getAppliedAmountExcludingRow(excludeTr) {
  let total = 0;
  if (!remainingPackageRows) return 0;
  remainingPackageRows.querySelectorAll("tr").forEach(function (tr) {
    if (tr === excludeTr) return;
    if (tr.querySelector(".cpc-empty-row")) return;
    const amountInput = tr.querySelector('[data-remaining-field="total_amount"]');
    total += Number(amountInput ? amountInput.value || 0 : 0);
  });
  return roundMoney(total);
}

function updateTransferRowStatus(tr) {
  if (!tr) return;
  const statusEl = tr.querySelector(".cpc-transfer-status");
  if (!statusEl) return;
  const applied = getCurrentAppliedConversionAmount();
  if (applied > selectedConversionAvailablePaid) { statusEl.className = "cpc-transfer-status blocked"; statusEl.textContent = "Blocked"; }
  else { statusEl.className = "cpc-transfer-status allowed"; statusEl.textContent = "Allowed"; }
}

function refreshAllTransferRowStatuses() {
  if (!remainingPackageRows) return;
  remainingPackageRows.querySelectorAll("tr").forEach(function (tr) { if (tr.querySelector(".cpc-empty-row")) return; updateTransferRowStatus(tr); });
}

function fillPackageTablesFromSelectedInvoicedPlan(option) { fillPackageTablesFromSelectedInvoicedPlans([option]); }

function fillPackageTablesFromSelectedInvoicedPlans(selectedOptions) {
  const completeRows = []; const remainingRows = [];
  selectedConversionPaidAmount = 0; selectedConversionAvailedValue = 0; selectedConversionAvailablePaid = 0;
  selectedOptions = selectedOptions || [];

  if (!selectedOptions.length) { renderCompletePackageRows([]); renderRemainingPackageRows([]); updateOriginalTotalBalanceAmount([]); updateTransferredTotalAmount(); updateConversionMoneyPanel(); return; }

  selectedOptions.forEach(function (option) {
    const plan = option.plan; const invoices = option.invoices || []; const therapyRows = getTherapyRowsFromPlan(plan);
    selectedConversionPaidAmount += Number(option.paid_amount || 0);
    therapyRows.forEach(function (therapyRow) {
      const booked = Number(therapyRow.booked_quantity || 0); const availed = Number(therapyRow.availed_quantity || 0); const balance = Math.max(booked - availed, 0);
      const therapyGrossAmount = getInvoiceItemGrossAmountForTherapy(therapyRow.therapy_type, invoices);
      const grossUnitPrice = booked ? roundMoney(therapyGrossAmount / booked) : 0;
      const availedValue = roundMoney(availed * grossUnitPrice);
      selectedConversionAvailedValue += availedValue;
      completeRows.push({ complete_package_details_therapy_plans: therapyRow.therapy_type + " (" + plan.name + ")", booked_quantity: booked, availed_quantity: availed, balance_quantity: balance, balance_quantity_amount: 0, remarks: "Source Plan: " + plan.name + " | GST inclusive price considered from submitted Sales Invoice", ses_erp_entry: plan.name, seserp_entry: plan.name });
      if (balance <= 0) return;
      remainingRows.push({ therapy_plans_been_transferred: therapyRow.therapy_type + " (" + plan.name + ")", converted_quantity: 0, original_balance_quantity: balance, max_quantity: balance, start_date: frappe.datetime.get_today(), validity_exp_dt: plan.due_date || "", total_amount: 0, balance_quantity_amount: 0, balance_due: 0, unit_transfer_amount: grossUnitPrice, unit_outstanding_amount: 0, source_therapy_plan: plan.name, source_therapy_row_name: therapyRow.row_name || "", source_invoice: option.invoice_names && option.invoice_names.length ? option.invoice_names[0] : "", source_sessions_before: booked, source_completed_before: availed, source_balance_before: balance, source_sessions_after: booked, source_balance_after: balance });
    });
  });

  selectedConversionPaidAmount = roundMoney(selectedConversionPaidAmount);
  selectedConversionAvailedValue = roundMoney(selectedConversionAvailedValue);
  selectedConversionAvailablePaid = roundMoney(Math.max(selectedConversionPaidAmount - selectedConversionAvailedValue, 0));
  renderCompletePackageRows(completeRows); renderRemainingPackageRows(remainingRows); updateConversionMoneyPanel();
  if (!remainingRows.length) frappe.show_alert({ message: "Selected Therapy Plans have no pending sessions to transfer.", indicator: "orange" });
}

function getTherapyRowsFromPlan(plan) {
  const rows = [];
  const possibleChildTables = [plan.therapy_plan_details, plan.therapy_details, plan.services, plan.items];
  for (let i = 0; i < possibleChildTables.length; i++) {
    const childRows = possibleChildTables[i];
    if (Array.isArray(childRows) && childRows.length) {
      childRows.forEach(function (detail) {
        const therapyType = detail.therapy_type || detail.therapy_plan_template || detail.service || detail.item_name || detail.item || detail.item_code || detail.therapy || "";
        const booked = Number(detail.no_of_sessions || detail.sessions || detail.qty || detail.quantity || detail.total_sessions || 0);
        const availed = Number(detail.sessions_completed || detail.completed_sessions || detail.total_sessions_completed || detail.completed_quantity || detail.completed_qty || detail.availed_quantity || detail.availed_sessions || detail.sessions_availed || detail.used_sessions || detail.consumed_sessions || detail.no_of_sessions_completed || detail.custom_sessions_completed || detail.custom_completed_sessions || 0);
        if (!therapyType && !booked) return;
        if (!booked) return; // Skip rows with 0 booked — rely on plan-level fallback
        rows.push({ row_name: detail.name || "", therapy_type: therapyType || plan.name, booked_quantity: booked, availed_quantity: availed });
      });
      if (rows.length) return rows;
    }
  }
  rows.push({ row_name: "", therapy_type: getTherapyTypeNameFromPlan(plan), booked_quantity: Number(plan.total_sessions || 0), availed_quantity: Number(plan.total_sessions_completed || 0) });
  return rows;
}

function normalizeForMatch(value) { return String(value || "").toLowerCase().replace(/\s+/g, " ").trim(); }

function getTherapyTypeNameFromPlan(plan) {
  if (!plan) return "";
  if (plan.therapy_type) return plan.therapy_type;
  if (plan.therapy_plan_template) return plan.therapy_plan_template;
  if (plan.template) return plan.template;
  if (plan.item_name) return plan.item_name;
  if (plan.item) return plan.item;
  const childTables = [plan.therapy_plan_details, plan.therapy_details, plan.services, plan.items];
  for (let i = 0; i < childTables.length; i++) {
    const rows = childTables[i];
    if (Array.isArray(rows) && rows.length) {
      const names = rows.map(function (row) { return row.therapy_type || row.therapy_plan_template || row.service || row.item_name || row.item || row.item_code || row.therapy || ""; }).filter(Boolean);
      if (names.length) return names.join(", ");
    }
  }
  return plan.name || "";
}

