function enhanceSignatureFields() {
  SIGNATURE_FIELDS.forEach(function (fieldname) {
    const storage = root.querySelector(`[data-field="${fieldname}"]`);
    if (!storage) return;

    const fieldWrap =
      storage.closest(".field-block") ||
      storage.closest(".cpc-field") ||
      storage.parentElement;

    if (!fieldWrap) return;

    storage.classList.add("hidden");
    storage.setAttribute("data-signature-storage", "1");

    if (fieldWrap.dataset.signatureEnhanced === "1") return;

    fieldWrap.dataset.signatureEnhanced = "1";
    fieldWrap.classList.add("cpc-signature-field");

    const canvas = document.createElement("canvas");
    canvas.className = "cpc-signature-canvas";
    canvas.dataset.signatureCanvas = fieldname;

    const help = document.createElement("div");
    help.className = "cpc-signature-help";
    help.textContent = "Signature captured below. Use Clear to redo the signature.";

    const actions = document.createElement("div");
    actions.className = "cpc-signature-actions";

    const clearBtn = document.createElement("button");
    clearBtn.type = "button";
    clearBtn.className = "cpc-mini-btn cpc-mini-btn-danger cpc-clear-signature";
    clearBtn.dataset.clearSignature = fieldname;
    clearBtn.textContent = "Clear";

    actions.appendChild(clearBtn);

    fieldWrap.insertBefore(canvas, storage);
    fieldWrap.insertBefore(help, storage);
    fieldWrap.insertBefore(actions, storage);
  });
}


function redrawSignature(fieldname) {
  const canvas = root.querySelector(`[data-signature-canvas="${fieldname}"]`);
  const storage = root.querySelector(`[data-field="${fieldname}"]`);

  if (!storage) return;

  storage.classList.add("hidden");

  if (!canvas) return;

  const value = String(storage.value || "").trim();
  const ctx = canvas.getContext("2d");
  const rect = canvas.getBoundingClientRect();
  const ratio = window.devicePixelRatio || 1;

  const width = rect.width || 500;
  const height = rect.height || 120;

  canvas.width = width * ratio;
  canvas.height = height * ratio;

  ctx.setTransform(ratio, 0, 0, ratio, 0, 0);
  ctx.lineWidth = 2;
  ctx.lineCap = "round";
  ctx.lineJoin = "round";
  ctx.strokeStyle = "#101828";
  ctx.clearRect(0, 0, width, height);

  if (value && value.indexOf("data:image") === 0) {
    const img = new Image();
    img.onload = function () {
      ctx.clearRect(0, 0, width, height);
      ctx.drawImage(img, 0, 0, width, height);
    };
    img.src = value;
  }
}


