function loadNewTransfereeBranches() {
  if (!newTransfereeBranch) return;

  const branch = String(getField("branch") || "").trim();

  if (!branch) {
    newTransfereeBranch.innerHTML = `<option value="">Select transferor first</option>`;
    newTransfereeBranch.disabled = true;
    return;
  }

  newTransfereeBranch.innerHTML =
    `<option value="${escapeHtml(branch)}">${escapeHtml(branch)}</option>`;

  newTransfereeBranch.value = branch;
  newTransfereeBranch.disabled = true;

  updateNewTransfereeBranchNote();
}


