function bindConditionalFields() {
  if (allergySelect && allergySpecifyWrap) allergySelect.addEventListener("change", applyConditionalVisibility);
  if (relationshipSelect && relationWrap) relationshipSelect.addEventListener("change", applyConditionalVisibility);
  if (existingLifeClientSelect && existingClientIdWrap) existingLifeClientSelect.addEventListener("change", applyConditionalVisibility);
  if (conversionChargesApplied && conversionChargesAmountWrap) conversionChargesApplied.addEventListener("change", applyConditionalVisibility);

  if (conversionChargesAmount) {
    conversionChargesAmount.addEventListener("input", function () {
      let value = String(conversionChargesAmount.value || "").trim();
      if (!value) { conversionChargesAmount.value = ""; if (currentWorkflowStep === 1) renderReview(); return; }
      if (value.includes("-") || value.includes(".") || value.includes("+") || value.includes("e") || value.includes("E")) {
        conversionChargesAmount.value = "";
        frappe.msgprint("Conversion Charges Amount should be a positive whole rupee amount. Negative values and decimal values are not allowed.");
        if (currentWorkflowStep === 1) renderReview(); return;
      }
      value = value.replace(/\D/g, "");
      if (value) value = String(parseInt(value, 10));
      conversionChargesAmount.value = value === "0" ? "" : value;
      if (currentWorkflowStep === 1) renderReview();
    });
    conversionChargesAmount.addEventListener("change", function () { normalizeConversionChargesAmount(true); if (currentWorkflowStep === 1) renderReview(); });
  }

  root.querySelectorAll("[data-field]").forEach(function (el) {
    el.addEventListener("input", function () { if (currentWorkflowStep === 1) renderReview(); });
    el.addEventListener("change", function () { if (currentWorkflowStep === 1) renderReview(); });
  });
}

function applyConditionalVisibility() {
  if (allergySpecifyWrap && allergySelect) allergySpecifyWrap.classList.toggle("hidden", allergySelect.value !== "Yes");
  if (relationWrap && relationshipSelect) relationWrap.classList.toggle("hidden", relationshipSelect.value !== "Other");
  if (existingClientIdWrap && existingLifeClientSelect) existingClientIdWrap.classList.toggle("hidden", existingLifeClientSelect.value !== "Yes");
  if (conversionChargesApplied && conversionChargesAmountWrap) {
    const checked = conversionChargesApplied.checked;
    conversionChargesAmountWrap.classList.toggle("hidden", !checked);
    if (!checked && conversionChargesAmount) conversionChargesAmount.value = "";
  }
}

function bindTableEvents() {
  if (packageRows) {
    packageRows.addEventListener("click", function (e) {
      const openBtn = e.target.closest(".cpc-open-plan-btn");
      if (!openBtn) return;
      const planName = openBtn.dataset.plan;
      if (planName) window.location.href = "/app/therapy-plan/" + encodeURIComponent(planName);
    });
  }

  if (invoicedPlanRows) {
    invoicedPlanRows.addEventListener("click", function (e) {
      const planCheckbox = e.target.closest(".cpc-plan-select-checkbox");

      // Direct checkbox/label interaction: use the checkbox's actual state.
      if (planCheckbox) {
        toggleInvoicedPlanForConversion(
          planCheckbox.dataset.plan,
          planCheckbox.checked
        );
        return;
      }

      const selectBtn = e.target.closest(".cpc-select-plan-btn");
      if (selectBtn) {
        selectInvoicedPlanForConversion(selectBtn.dataset.plan);
        return;
      }

      const openPlanBtn = e.target.closest(".cpc-open-plan-btn");
      if (openPlanBtn && openPlanBtn.dataset.plan) {
        frappe.set_route("Form", "Therapy Plan", openPlanBtn.dataset.plan);
        return;
      }

      // Do not treat clicks on another interactive control as a row selection.
      if (e.target.closest("a, button, input, select, textarea, label, [role='button']")) {
        return;
      }

      const planRow = e.target.closest(
        ".cpc-invoiced-plan-row[data-plan]"
      );

      if (!planRow || planRow.classList.contains("cpc-plan-not-transferable")) {
        return;
      }

      // Clicking anywhere on an available row selects/deselects its checkbox.
      selectInvoicedPlanForConversion(planRow.dataset.plan);
    });

    invoicedPlanRows.addEventListener("keydown", function (e) {
      if (e.key !== "Enter" && e.key !== " ") return;

      const planRow = e.target.closest(
        ".cpc-invoiced-plan-row[data-plan]"
      );

      if (!planRow || planRow.classList.contains("cpc-plan-not-transferable")) {
        return;
      }

      e.preventDefault();
      selectInvoicedPlanForConversion(planRow.dataset.plan);
    });
  }

  if (openSelectedOriginalPlanBtn && openSelectedOriginalPlanBtn.dataset.boundOpenSelectedPlan !== "1") {
    openSelectedOriginalPlanBtn.dataset.boundOpenSelectedPlan = "1";
    openSelectedOriginalPlanBtn.addEventListener("click", function () {
      const planId = openSelectedOriginalPlanBtn.dataset.plan || "";
      if (!planId) { frappe.msgprint("Please select a therapy plan row first."); return; }
      frappe.set_route("Form", "Therapy Plan", planId);
    });
  }

  if (remainingPackageRows) {
    remainingPackageRows.addEventListener("click", function (e) {
      const removeBtn = e.target.closest(".cpc-remove-transfer-row");
      if (!removeBtn) return;
      if (!isStageEditable(1)) { frappe.msgprint("This step is view-only. You cannot remove transferred sessions."); return; }
      const tr = removeBtn.closest("tr");
      if (tr) tr.remove();
      updateTransferredTotalAmount(); updateConversionMoneyPanel(); refreshAllTransferRowStatuses();
      if (!remainingPackageRows.querySelector("tr")) renderRemainingPackageRows([]);
    });

    remainingPackageRows.addEventListener("input", function (e) {
      const qtyInput = e.target.closest('[data-remaining-field="converted_quantity"]');
      if (!qtyInput) return;
      if (!isStageEditable(1)) return;
      enforceConvertedQuantityLimit(qtyInput);
    });

    remainingPackageRows.addEventListener("change", function (e) {
      const dateInput = e.target.closest('[data-remaining-field="start_date"]');
      if (!dateInput) return;
      if (!isStageEditable(1)) return;
      validateTransferDate(dateInput);
    });
  }
}

