// TRANSFEREE EXISTING PLANS
// ============================================================

function fetchTransfereeExistingPlans(patientName) {
  if (!transfereeExistingPlanRows || !patientName) { renderTransfereeExistingPlans([]); return; }
  frappe.call({
    method: "frappe.client.get_list",
    args: { doctype: "Therapy Plan", filters: { patient: patientName }, fields: ["name","start_date","due_date","therapy_plan_template","total_sessions","total_sessions_completed"], order_by: "modified desc", limit_page_length: 50 },
    callback: function (r) {
      const plans = r.message || [];
      if (!plans.length) { renderTransfereeExistingPlans([]); return; }
      fetchTransfereePlanTherapyDetails(plans, function (enrichedPlans) { fetchTransfereeInvoiceBalances(patientName, enrichedPlans); });
    },
    error: function (err) { void 0; renderTransfereeExistingPlans([]); }
  });
}

function fetchTransfereePlanTherapyDetails(plans, callback) {
  if (!plans || !plans.length) { callback([]); return; }
  let completed = 0;
  plans.forEach(function (plan) {
    frappe.call({
      method: "frappe.client.get",
      args: { doctype: "Therapy Plan", name: plan.name },
      callback: function (r) {
        completed++;
        const fullPlan = r.message || {};
        plan.included_therapy_types = extractTherapyTypesFromPlan(fullPlan);
        if (completed === plans.length) callback(plans);
      },
      error: function (err) {
        completed++;
        void 0;
        plan.included_therapy_types = [];
        if (completed === plans.length) callback(plans);
      }
    });
  });
}

function extractTherapyTypesFromPlan(plan) {
  const possibleTables = ["therapy_plan_details","therapy_plan_detail","therapy_details","plan_details","details"];
  let rows = [];
  possibleTables.forEach(function (tableField) { if (!rows.length && Array.isArray(plan[tableField])) rows = plan[tableField]; });
  if (!rows.length) return [];
  return rows.map(function (row) {
    const therapyName = row.therapy_type || row.therapy || row.service || row.healthcare_service_unit || row.item_code || row.item_name || row.treatment || row.template || "";
    const sessions = row.no_of_sessions || row.sessions || row.number_of_sessions || row.qty || row.quantity || row.total_sessions || "";
    if (!therapyName) return "";
    return sessions ? therapyName + " - " + sessions : therapyName;
  }).filter(function (value) { return value; });
}

function fetchTransfereeInvoiceBalances(patientName, plans) {
  frappe.call({
    method: "frappe.client.get_list",
    args: { doctype: "Sales Invoice", filters: [["Sales Invoice","patient","=",patientName],["Sales Invoice","docstatus","=",1],["Sales Invoice","is_return","=",0]], fields: ["name","outstanding_amount","rounded_total","grand_total"], limit_page_length: 100 },
    callback: function (r) {
      const invoices = r.message || [];
      if (!invoices.length) { plans.forEach(function (plan) { plan.invoice_amount = 0; plan.paid_amount = 0; plan.balance_amount = 0; }); renderTransfereeExistingPlans(plans); return; }
      fetchFullInvoicesAndMapBalances(invoices, plans);
    },
    error: function (err) { void 0; plans.forEach(function (plan) { plan.balance_amount = 0; }); renderTransfereeExistingPlans(plans); }
  });
}

function fetchFullInvoicesAndMapBalances(invoices, plans) {
  const invoiceMap = {}; let completed = 0;
  invoices.forEach(function (invoiceRow) {
    frappe.call({
      method: "frappe.client.get",
      args: { doctype: "Sales Invoice", name: invoiceRow.name },
      callback: function (r) {
        completed++;
        const invoice = r.message || {};
        const planName = getInvoiceTherapyPlanReference(invoice);
        if (planName) {
          if (!invoiceMap[planName]) invoiceMap[planName] = { invoice_amount: 0, outstanding_amount: 0 };
          invoiceMap[planName].invoice_amount += Number(invoice.rounded_total || invoice.grand_total || 0);
          invoiceMap[planName].outstanding_amount += Number(invoice.outstanding_amount || 0);
        }
        if (completed === invoices.length) {
          plans.forEach(function (plan) {
            const mapped = invoiceMap[plan.name] || { invoice_amount: 0, outstanding_amount: 0 };
            plan.invoice_amount = mapped.invoice_amount || 0; plan.balance_amount = mapped.outstanding_amount || 0;
            plan.paid_amount = Math.max(Number(plan.invoice_amount || 0) - Number(plan.balance_amount || 0), 0);
          });
          renderTransfereeExistingPlans(plans);
        }
      },
      error: function (err) {
        completed++;
        void 0;
        if (completed === invoices.length) {
          plans.forEach(function (plan) {
            const mapped = invoiceMap[plan.name] || { invoice_amount: 0, outstanding_amount: 0 };
            plan.invoice_amount = mapped.invoice_amount || 0; plan.balance_amount = mapped.outstanding_amount || 0;
            plan.paid_amount = Math.max(Number(plan.invoice_amount || 0) - Number(plan.balance_amount || 0), 0);
          });
          renderTransfereeExistingPlans(plans);
        }
      }
    });
  });
}

function renderTransfereeExistingPlans(rows) {
  if (!transfereeExistingPlanRows) return;
  if (!rows || !rows.length) { transfereeExistingPlanRows.innerHTML = `<tr><td colspan="5" class="cpc-empty-row">No existing therapy plans found for transferee.</td></tr>`; return; }
  transfereeExistingPlanRows.innerHTML = rows.map(function (row) {
    const total = Number(row.total_sessions || 0); const completed = Number(row.total_sessions_completed || 0);
    const sessionsUsedText = completed + " / " + total;
    const paidAmount = Number(row.paid_amount || 0); const invoiceAmount = Number(row.invoice_amount || 0);
    const paidInvoiceText = (invoiceAmount === 0 && paidAmount === 0) ? "No Invoice Linked" : formatCurrency(paidAmount) + " / " + formatCurrency(invoiceAmount);
    const includedTherapies = row.included_therapy_types && row.included_therapy_types.length ? row.included_therapy_types : [];
    const therapyHtml = includedTherapies.length ? includedTherapies.map(function (item) { return `<div class="cpc-plan-therapy-line">${escapeHtml(item)}</div>`; }).join("") : `<div class="cpc-plan-therapy-line muted">No therapy type details found</div>`;
    return `<tr>
      <td><strong>${escapeHtml(row.name || "-")}</strong><br><small>${escapeHtml(row.therapy_plan_template || "")}</small><div class="cpc-plan-therapy-list">${therapyHtml}</div></td>
      <td><strong>${escapeHtml(sessionsUsedText)}</strong></td>
      <td><strong>${escapeHtml(paidInvoiceText)}</strong></td>
      <td>${escapeHtml(formatDate(row.start_date))}</td>
      <td>${escapeHtml(formatDate(row.due_date))}</td>
    </tr>`;
  }).join("");
}

// ============================================================
// TRANSFER ROW VALIDATION / TOTALS
// ============================================================

function enforceConvertedQuantityLimit(input) {
  if (!input) return;
  const tr = input.closest("tr");
  const maxQty = Number(input.dataset.maxQty || input.getAttribute("max") || 0);
  let value = Number(input.value || 0);
  if (value < 0) value = 0;
  if (maxQty && value > maxQty) { value = maxQty; frappe.show_alert({ message: "Converted Qty cannot exceed available balance sessions.", indicator: "orange" }); }
  input.value = value;
  if (tr) recalculateTransferRowAmount(tr);
  updateTransferredTotalAmount(); refreshAllTransferRowStatuses();
}

function recalculateTransferRowAmount(tr) {
  if (!tr) return;
  const qtyInput = tr.querySelector('[data-remaining-field="converted_quantity"]');
  const amountInput = tr.querySelector('[data-remaining-field="total_amount"]');
  const balanceAmountInput = tr.querySelector('[data-remaining-field="balance_quantity_amount"]');
  const balanceDueInput = tr.querySelector('[data-remaining-field="balance_due"]');
  const sourceSessionsBeforeInput = tr.querySelector('[data-remaining-field="source_sessions_before"]');
  const sourceCompletedBeforeInput = tr.querySelector('[data-remaining-field="source_completed_before"]');
  const sourceSessionsAfterInput = tr.querySelector('[data-remaining-field="source_sessions_after"]');
  const sourceBalanceAfterInput = tr.querySelector('[data-remaining-field="source_balance_after"]');
  if (!qtyInput || !amountInput) return;

  let qty = Number(qtyInput.value || 0);
  const maxQty = Number(qtyInput.dataset.maxQty || qtyInput.getAttribute("max") || 0);
  const unitTransferAmount = Number(qtyInput.dataset.unitTransferAmount || 0);
  if (qty < 0) qty = 0;
  if (maxQty && qty > maxQty) qty = maxQty;

  const otherAppliedAmount = getAppliedAmountExcludingRow(tr);
  const allowedForThisRow = Math.max(selectedConversionAvailablePaid - otherAppliedAmount, 0);
  let requestedAmount = roundMoney(qty * unitTransferAmount);

  if (requestedAmount > allowedForThisRow) {
    const allowedQty = unitTransferAmount ? Math.floor(allowedForThisRow / unitTransferAmount) : 0;
    qty = Math.max(allowedQty, 0); requestedAmount = roundMoney(qty * unitTransferAmount);
    frappe.show_alert({ message: "Blocked: selected sessions exceed paid balance available.", indicator: "red" });
  }

  qtyInput.value = qty; amountInput.value = requestedAmount;
  if (balanceAmountInput) balanceAmountInput.value = 0;
  if (balanceDueInput) balanceDueInput.value = 0;

  const sourceSessionsBefore = Number(sourceSessionsBeforeInput ? sourceSessionsBeforeInput.value || 0 : 0);
  const sourceCompletedBefore = Number(sourceCompletedBeforeInput ? sourceCompletedBeforeInput.value || 0 : 0);
  if (sourceSessionsAfterInput) sourceSessionsAfterInput.value = Math.max(sourceSessionsBefore - qty, 0);
  if (sourceBalanceAfterInput) { const sessionsAfter = Number(sourceSessionsAfterInput ? sourceSessionsAfterInput.value || 0 : 0); sourceBalanceAfterInput.value = Math.max(sessionsAfter - sourceCompletedBefore, 0); }

  updateTransferredTotalAmount(); updateConversionMoneyPanel(); refreshAllTransferRowStatuses();
}

function validateTransferDate(input) {
  if (!input) return true;
  const value = input.value || "";
  if (!value) return true;
  const today = frappe.datetime.get_today();
  if (value < today) { input.value = today; frappe.msgprint("Past dates are not allowed."); return false; }
  return true;
}

function validateTransferRowsBeforeSave() {
  if (!remainingPackageRows) return true;
  const rows = remainingPackageRows.querySelectorAll("tr");
  let hasValidRow = false;

  for (let i = 0; i < rows.length; i++) {
    const tr = rows[i];
    if (tr.querySelector(".cpc-empty-row")) continue;
    const therapyInput = tr.querySelector('[data-remaining-field="therapy_plans_been_transferred"]');
    const qtyInput = tr.querySelector('[data-remaining-field="converted_quantity"]');
    const startDateInput = tr.querySelector('[data-remaining-field="start_date"]');
    const sourcePlanInput = tr.querySelector('[data-remaining-field="source_therapy_plan"]');
    const therapy = therapyInput ? therapyInput.value : "";
    const qty = qtyInput ? Number(qtyInput.value || 0) : 0;
    const maxQty = qtyInput ? Number(qtyInput.dataset.maxQty || qtyInput.getAttribute("max") || 0) : 0;
    if (!therapy) continue;
    if (!sourcePlanInput || !sourcePlanInput.value) { frappe.msgprint("Source Therapy Plan is missing for one transferred session row. Please reselect the invoiced Therapy Plan."); return false; }
    if (qty <= 0) { frappe.msgprint("Converted Qty must be greater than 0."); return false; }
    if (maxQty && qty > maxQty) { frappe.msgprint("Converted Qty cannot exceed available balance quantity."); return false; }
    if (!startDateInput || !startDateInput.value) { frappe.msgprint("Please select Start Date for all transferred sessions."); return false; }
    if (!validateTransferDate(startDateInput)) return false;
    hasValidRow = true;
  }

  if (!hasValidRow) { frappe.msgprint("Please add at least one transferable session row."); return false; }
  return true;
}

function updateOriginalTotalBalanceAmount(rows) {
  const totalEl = root.querySelector("#originalTotalBalanceAmount");
  if (!totalEl) return;
  let total = 0;
  if (Array.isArray(rows)) rows.forEach(function (row) { total += Number(row.balance_quantity_amount || 0); });
  totalEl.textContent = formatCurrency(total);
}

function updateTransferredTotalAmount() {
  const totalEl = root.querySelector("#transferredTotalAmount");
  const total = getCurrentAppliedConversionAmount();
  if (totalEl) totalEl.textContent = formatCurrency(total);
  updateConversionMoneyPanel();
}

