function bindNoPastDateFields() {
  enforceFixedTodayDateFields(false);
  FIXED_TODAY_DATE_FIELDS.forEach(function (fieldname) {
    const input = root.querySelector(`[data-field="${fieldname}"]`);
    if (!input) return;
    input.addEventListener("change", function () {
      const today = frappe.datetime.get_today();
      if (input.value !== today) { input.value = today; frappe.msgprint("This date is fixed with the current date."); }
    });
  });
}

function isTodayOrFutureDate(value) { if (!value) return false; return value >= frappe.datetime.get_today(); }

function bindRemarkWordLimits() {
  const remarkFields = ["reason__remarks_of__conversion","stores_remark","centre_manager_remarks","operations_manager_remarks","audit_team_remarks","office_remarks_any"];
  remarkFields.forEach(function (fieldname) {
    const input = root.querySelector(`[data-field="${fieldname}"]`);
    if (!input || input.dataset.wordLimitBound === "1") return;
    input.dataset.wordLimitBound = "1";
    input.addEventListener("input", function () {
      const words = String(input.value || "").trim().split(/\s+/).filter(Boolean);
      if (words.length > 400) { input.value = words.slice(0, 400).join(" "); frappe.show_alert({ message: "Maximum 400 words allowed for remarks.", indicator: "orange" }); }
    });
  });
}

function limitWords(el, maxWords) {
  const words = String(el.value || "").trim().split(/\s+/).filter(Boolean);
  if (words.length <= maxWords) return;
  el.value = words.slice(0, maxWords).join(" ");
  frappe.show_alert({ message: "Remarks are limited to " + maxWords + " words.", indicator: "orange" });
}

