function getReviewScopeSummary() {
  let totalBookedQty = 0, totalAvailedQty = 0, totalBalanceQty = 0, transferRowCount = 0, totalTransferQty = 0;
  let sourcePlanNames = [];

  if (packageRows) {
    packageRows.querySelectorAll("tr").forEach(function (tr) {
      if (tr.querySelector(".cpc-empty-row")) return;
      const bookedInput = tr.querySelector('[data-child-field="booked_quantity"]');
      const availedInput = tr.querySelector('[data-child-field="availed_quantity"]');
      const balanceInput = tr.querySelector('[data-child-field="balance_quantity"]');
      const sourcePlanInput = tr.querySelector('[data-child-field="ses_erp_entry"], [data-child-field="seserp_entry"]');
      totalBookedQty += Number(bookedInput ? bookedInput.value || 0 : 0);
      totalAvailedQty += Number(availedInput ? availedInput.value || 0 : 0);
      totalBalanceQty += Number(balanceInput ? balanceInput.value || 0 : 0);
      const sourcePlan = sourcePlanInput ? String(sourcePlanInput.value || "").trim() : "";
      if (sourcePlan && !sourcePlanNames.includes(sourcePlan)) sourcePlanNames.push(sourcePlan);
    });
  }

  if (remainingPackageRows) {
    remainingPackageRows.querySelectorAll("tr").forEach(function (tr) {
      if (tr.querySelector(".cpc-empty-row")) return;
      const qtyInput = tr.querySelector('[data-remaining-field="converted_quantity"]');
      const sourcePlanInput = tr.querySelector('[data-remaining-field="source_therapy_plan"]');
      const qty = Number(qtyInput ? qtyInput.value || 0 : 0);
      const sourcePlan = sourcePlanInput ? String(sourcePlanInput.value || "").trim() : "";
      if (sourcePlan && !sourcePlanNames.includes(sourcePlan)) sourcePlanNames.push(sourcePlan);
      if (qty > 0) { transferRowCount++; totalTransferQty += qty; }
    });
  }

  const selectedPlanCount = selectedConversionPlanNames && selectedConversionPlanNames.length ? selectedConversionPlanNames.length : sourcePlanNames.length;
  const appliedAmount = getCurrentAppliedConversionAmount();
  const availablePaid = roundMoney(selectedConversionAvailablePaid || 0);

  return { selectedPlanCount: selectedPlanCount || 0, totalBookedQty: totalBookedQty || 0, totalAvailedQty: totalAvailedQty || 0, totalBalanceQty: totalBalanceQty || 0, transferRowCount: transferRowCount || 0, totalTransferQty: totalTransferQty || 0, remainingSessionsAfterTransfer: Math.max(totalBalanceQty - totalTransferQty, 0), appliedAmount: roundMoney(appliedAmount), availablePaid: availablePaid };
}

