function enforceFixedTodayDateFields(forceToday) {
  const today = frappe.datetime.get_today();
  FIXED_TODAY_DATE_FIELDS.forEach(function (fieldname) {
    const el = root.querySelector(`[data-field="${fieldname}"]`);
    if (!el) return;
