function getField(fieldname) {
  const el = root.querySelector(`[data-field="${fieldname}"]`);
  if (!el) return "";
  if (el.type === "checkbox") return el.checked ? 1 : 0;
  if (el.dataset && el.dataset.employeeId) return el.dataset.employeeId;
  return String(el.value || "").trim();
}

function setField(fieldname, value) {
  const el = root.querySelector(`[data-field="${fieldname}"]`);
  if (!el) return;
  if (el.type === "checkbox") el.checked = Number(value || 0) === 1;
  else el.value = value === undefined || value === null ? "" : value;
  if (fieldname === "conversion_charges_applied") applyConditionalVisibility();
}

function normalizeConversionChargesAmount(showMessage) {
  if (!conversionChargesAmount) return true;
  let rawValue = String(conversionChargesAmount.value || "").trim();
  if (!rawValue) return true;
  rawValue = rawValue.replace(/[^\d.]/g, "");
  if (!rawValue) { conversionChargesAmount.value = ""; return true; }
  if (rawValue.indexOf(".") !== -1) { conversionChargesAmount.value = ""; if (showMessage) frappe.msgprint("Conversion Charges Amount should be a whole rupee amount. Decimal values are not allowed."); return false; }
  let amount = parseInt(rawValue, 10);
  if (!amount || amount <= 0) { conversionChargesAmount.value = ""; if (showMessage) frappe.msgprint("Conversion Charges Amount should be greater than 0."); return false; }
  conversionChargesAmount.value = String(amount);
  return true;
}

function loadPatientDisplayName(patientName, targetInput) {
  if (!patientName || !targetInput) return;
  frappe.call({
    method: "frappe.client.get",
    args: { doctype: "Patient", name: patientName },
    callback: function (r) {
      const patient = r.message;
      if (!patient) return;
      targetInput.value = patient.patient_name || patient.first_name || patient.name || patientName;
    },
    error: function () { targetInput.value = patientName; }
  });
}

function mapCategory(value) {
  value = String(value || "").toLowerCase();
  if (value.includes("skin")) return "Skin"; if (value.includes("hair")) return "Hair";
  if (value.includes("laser")) return "Laser"; if (value.includes("slim")) return "Slimming";
  if (value.includes("cs")) return "CS"; if (value.includes("ht")) return "HT";
  return "";
}

function maskMobile(value) {
  const digits = String(value || "").replace(/\D/g, "");
  if (!digits) return "";
  if (digits.length < 6) return digits;
  return digits.slice(0, 3) + "****" + digits.slice(-3);
}

function formatDate(value) {
  if (!value) return "-";
  let datePart = String(value).trim();
  if (datePart.includes(" ")) datePart = datePart.split(" ")[0];
  if (datePart.includes("T")) datePart = datePart.split("T")[0];
  const parts = datePart.split("-");
  if (parts.length !== 3) return value;
  const monthNames = { "01":"Jan","02":"Feb","03":"Mar","04":"Apr","05":"May","06":"Jun","07":"Jul","08":"Aug","09":"Sep","10":"Oct","11":"Nov","12":"Dec" };
  const shortMonth = monthNames[parts[1]];
  if (!shortMonth) return value;
  return parts[2] + "-" + shortMonth + "-" + parts[0].slice(-2);
}

function formatDateTime(value) { if (!value) return "-"; return formatDate(value); }

function formatCurrency(value) {
  const num = Number(value || 0);
  return "₹" + num.toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function escapeHtml(value) {
  return String(value === undefined || value === null ? "" : value)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#039;");
}

function bindTermsToggle() {
