// ============================================================
// C2C APPROVAL DASHBOARD - P2P STYLE FUNCTIONALITY
// Purpose:
// Approval Dashboard should behave like P2P:
// - role based pending list
// - select request
// - review details + timeline
// - approve / reject directly from dashboard
// - save latest doc using frappe.client.save
// - refresh dashboard after action
//
// C2C stage flow:
// Centre Manager Approved -> Audit Team -> COO Final
// Centre Manager Rejected -> workflow stops immediately.
// Audit Team Rejected -> workflow stops immediately.
// COO final rejection stops automation.
// COO final approval triggers After Save automation.
// ============================================================

function getC2CApprovalStageValue(doc) {
  doc = doc || {};

  function normalizeDecision(value) {
    value = String(value || "").trim();
    if (value === "Approve") return "Approved";
    if (value === "Reject") return "Rejected";
    return value;
  }

  function clean(value) {
    return String(value || "").trim();
  }

  const approvalStage = clean(doc.approval_stage);
  const displayStatus = clean(doc.approval_display_status);
  const conversionStatus = clean(doc.conversion_status);
  const automationStatus = clean(doc.automation_status);
  const finalStatus = normalizeDecision(doc.final_approval_status);
  const centreDecision = normalizeDecision(doc.centre_manager_decision);
  const auditDecision = normalizeDecision(doc.audit_team_decision);
  const step = Number(doc.current_tab_step || 1);

  const stageText = [approvalStage, displayStatus, conversionStatus]
    .filter(Boolean)
    .join(" | ");

  if (
    automationStatus === "Process Completed" ||
    displayStatus === "Process Completed" ||
    conversionStatus === "Completed" ||
    Number(doc.package_transfer_applied || 0) === 1
  ) {
    return APPROVAL_STAGES.APPROVED;
  }

  if (finalStatus === "Approved" && isC2CFinalApprovalActuallyReached(doc)) {
    return APPROVAL_STAGES.APPROVED;
  }

  if (finalStatus === "Rejected" && isC2CFinalApprovalActuallyReached(doc)) {
    return APPROVAL_STAGES.REJECTED;
  }

  // Any explicit terminal rejection must win before pending-stage inference.
  // This also makes older forwarded CM/Audit rejections obey the new stop rule.
  if (
    centreDecision === "Rejected" ||
    auditDecision === "Rejected" ||
    approvalStage === APPROVAL_STAGES.REJECTED ||
    conversionStatus === "Rejected" ||
    /Rejected.*Process\s*Stopped/i.test(displayStatus) ||
    (automationStatus === "Skipped" && /Rejected/i.test(displayStatus))
  ) {
    return APPROVAL_STAGES.REJECTED;
  }

  if (
    auditDecision === "Approved" ||
    auditDecision === "Rejected" ||
    /Operations\s*COO.*Pending/i.test(stageText) ||
    /COO.*Pending/i.test(stageText) ||
    /Final\s*Decision.*Pending/i.test(stageText) ||
    approvalStage === APPROVAL_STAGES.COO_PENDING ||
    displayStatus === APPROVAL_STAGES.COO_PENDING
  ) {
    return APPROVAL_STAGES.COO_PENDING;
  }

  if (
    centreDecision === "Approved" ||
    centreDecision === "Rejected" ||
    /Audit.*(?:Pending|Review)/i.test(stageText) ||
    /Operations\s*Manager.*Pending/i.test(stageText) ||
    /Management\s*Approval\s*Pending/i.test(stageText) ||
    approvalStage === APPROVAL_STAGES.AUDIT_PENDING ||
    approvalStage === APPROVAL_STAGES.OM_PENDING ||
    displayStatus === APPROVAL_STAGES.AUDIT_PENDING ||
    displayStatus === APPROVAL_STAGES.OM_PENDING ||
    step >= 3
  ) {
    return APPROVAL_STAGES.AUDIT_PENDING;
  }

  if (
    /Centre\s*Manager.*Pending/i.test(stageText) ||
    /Center\s*Manager.*Pending/i.test(stageText) ||
    /Branch\s*Official.*Pending/i.test(stageText) ||
    approvalStage === APPROVAL_STAGES.CM_PENDING ||
    displayStatus === APPROVAL_STAGES.CM_PENDING ||
    step >= 2
  ) {
    return APPROVAL_STAGES.CM_PENDING;
  }

  if (
    approvalStage === APPROVAL_STAGES.REJECTED ||
    conversionStatus === "Rejected" ||
    /^Rejected$/i.test(displayStatus)
  ) {
    return APPROVAL_STAGES.REJECTED;
  }

  return approvalStage || displayStatus || conversionStatus || APPROVAL_STAGES.REQUEST_PENDING;
}

function getPendingRoleForC2CRequest(doc) {
  doc = doc || {};

  function normalizeDecision(value) {
    value = String(value || "").trim();
    if (value === "Approve") return "Approved";
    if (value === "Reject") return "Rejected";
    return value;
  }

  const finalStatus = normalizeDecision(doc.final_approval_status);
  const finalReached = isC2CFinalApprovalActuallyReached(doc);

  if (
    ((finalStatus === "Approved" || finalStatus === "Rejected") && finalReached) ||
    isC2CProcessCompleted(doc) ||
    isC2CAutomationFailed(doc)
  ) {
    return "";
  }

  const stage = getC2CApprovalStageValue(doc);

  if (stage === APPROVAL_STAGES.CM_PENDING) return "centre_manager";
  if (stage === APPROVAL_STAGES.AUDIT_PENDING || stage === APPROVAL_STAGES.OM_PENDING) return "audit_team";
  if (stage === APPROVAL_STAGES.COO_PENDING) return "operations_coo";

  return "";
}

function isC2CRequestRejectedForDashboard(doc) {
  var stage = getC2CApprovalStageValue(doc);
  var finalStatus = String(doc.final_approval_status || "").trim();

  return stage === APPROVAL_STAGES.REJECTED ||
    (finalStatus === "Rejected" && isC2CFinalApprovalActuallyReached(doc));
}


function isC2CProcessCompleted(doc) {
  var automationStatus = String(doc.automation_status || "").trim();
  var displayStatus = String(doc.approval_display_status || "").trim();
  var conversionStatus = String(doc.conversion_status || "").trim();

  return automationStatus === "Process Completed" ||
    displayStatus === "Process Completed" ||
    conversionStatus === "Completed" ||
    Number(doc.package_transfer_applied || 0) === 1;
}


function isC2CAutomationFailed(doc) {
  return String(doc.automation_status || "").trim() === "Failed";
}

function showApprovalDashboard(options) {
  options = options || {};

  /*
   * Approval Dashboard has no visible branch selector.
   * Do not inherit a branch selection from All Requests for management reviewers.
   */
  if (
    requestBranchFilter &&
    !requestBranchFilter.disabled &&
    Array.prototype.some.call(
      requestBranchFilter.options || [],
      function (option) {
        return String(option.value || "") === "";
      }
    )
  ) {
    requestBranchFilter.value = "";
  }

  activateC2CMode(2);

  const actionPanel = root.querySelector("#approval-action-panel");

  if (actionPanel && options.clearDetail !== false) {
    actionPanel.innerHTML = `
      <div class="cpc-approval-empty">
        Loading approval dashboard...
      </div>
    `;
  }

  if (options.skipReload) {
    renderApprovalDashboard();
  } else {
    refreshC2CApprovalDashboard({
      showLoading: false,
      clearDetail: options.clearDetail !== false
    });
  }

  window.scrollTo({
    top: 0,
    behavior: "smooth"
  });
}


function refreshC2CApprovalDashboard(options) {
  options = options || {};

  activateC2CMode(2);

  var actionPanel = root.querySelector("#approval-action-panel");
  var listEl = root.querySelector("#approval-list");

  if (options.showLoading !== false && listEl) {
    listEl.innerHTML = `
      <div class="notice notice-blue">
        Loading current approval requests...
      </div>
    `;
  }

  if (options.clearDetail !== false && actionPanel) {
    actionPanel.innerHTML = `
      <div class="cpc-approval-empty">
        Loading approval dashboard...
      </div>
    `;
  }

  loadRequests(function (rows) {
    /*
     * Do not depend only on loadRequests() detecting the active CSS class.
     * The Approval Dashboard can be visibly active while another startup
     * routine is still synchronising tab classes. Render it explicitly.
     */
    renderApprovalDashboard();

    if (typeof options.afterLoad === "function") {
      options.afterLoad(rows || []);
    }
  }, {
    /* The All Requests panel is hidden while this dashboard is loading. */
    skipAllRequestsRender: true,
    showListLoading: false,
    clearPagination: false
  });
}



