    `;
  }
}



// ============================================================
// C2C APPROVAL DASHBOARD - AUDIT / COO FINAL TABLE EDITING
// P2P-style approval override editor.
// Audit / COO may:
// - change Therapy Type
// - increase or decrease sessions
// - edit the final amount
// - add a new Therapy Type
// - exceed the branch-requested value as an approval override
// The original Branch / Audit versions remain stored in snapshots.
// ============================================================

function c2cFinalTableSnapshotRow(row) {
  row = row || {};

  var qty = Number(row.converted_quantity || 0);
  var explicitAmount = Number(
    row.total_amount ||
    row.applied_amount ||
    row.balance_quantity_amount ||
    row.balance_amount ||
    0
  );

  var unit = Number(row.unit_transfer_amount || 0);

  if (!unit && qty > 0 && explicitAmount > 0) {
    unit = explicitAmount / qty;
  }

  var sourceSessionsBefore = Number(row.source_sessions_before || 0);
  var sourceCompletedBefore = Number(row.source_completed_before || 0);
  var sourceBalanceBefore = Number(
    row.source_balance_before ||
    row.original_balance_quantity ||
    row.max_quantity ||
    Math.max(sourceSessionsBefore - sourceCompletedBefore, 0) ||
    0
  );

  var totalAmount = roundMoney(
    explicitAmount > 0
      ? explicitAmount
      : (qty * unit)
  );

  var hasSourceRow = !!String(row.source_therapy_row_name || "").trim();
  var sourceDeductQty = hasSourceRow
    ? Math.min(qty, Math.max(sourceBalanceBefore, 0))
    : 0;

  var sourceSessionsAfter = hasSourceRow
    ? Math.max(sourceSessionsBefore - sourceDeductQty, sourceCompletedBefore)
    : Number(row.source_sessions_after || 0);

  var sourceBalanceAfter = hasSourceRow
    ? Math.max(sourceSessionsAfter - sourceCompletedBefore, 0)
    : Number(row.source_balance_after || 0);

  return {
    name: String(row.name || "").trim(),
    doctype: REMAINING_CHILD_DOCTYPE,

    therapy_plans_been_transferred:
      String(row.therapy_plans_been_transferred || row.therapy_type || "").trim(),

    converted_quantity: qty,
    original_balance_quantity: Number(
      row.original_balance_quantity ||
      row.max_quantity ||
      sourceBalanceBefore ||
      0
    ),
    max_quantity: Number(
      row.max_quantity ||
      row.original_balance_quantity ||
      sourceBalanceBefore ||
      0
    ),

    start_date: String(row.start_date || "").trim(),
    validity_exp_dt: String(row.validity_exp_dt || "").trim(),

    total_amount: totalAmount,
    balance_quantity_amount: totalAmount,
    balance_due: Number(row.balance_due || 0),
    unit_transfer_amount: unit,
    unit_outstanding_amount: Number(row.unit_outstanding_amount || 0),

    source_therapy_plan: String(row.source_therapy_plan || "").trim(),
    source_therapy_row_name: String(row.source_therapy_row_name || "").trim(),
    source_invoice: String(row.source_invoice || "").trim(),

    source_sessions_before: sourceSessionsBefore,
    source_completed_before: sourceCompletedBefore,
    source_balance_before: sourceBalanceBefore,
    source_sessions_after: sourceSessionsAfter,
    source_balance_after: sourceBalanceAfter
  };
}

function c2cNormalizeFinalTableRows(rows) {
  return (rows || [])
    .map(c2cFinalTableSnapshotRow)
    .filter(function (row) {
      return (
        Number(row.converted_quantity || 0) > 0 &&
        !!String(row.therapy_plans_been_transferred || "").trim()
      );
    });
}

function c2cSerializeFinalTableSnapshot(rows) {
  try {
    return JSON.stringify(c2cNormalizeFinalTableRows(rows));
  } catch (e) {
    void 0;
    return "[]";
  }
}

function c2cParseFinalTableSnapshot(value) {
  value = String(value || "").trim();
  if (!value) return [];

  try {
    var parsed = JSON.parse(value);
    return Array.isArray(parsed)
      ? c2cNormalizeFinalTableRows(parsed)
      : [];
  } catch (e) {
    void 0;
    return [];
  }
}

function c2cFinalTableRowKey(row) {
  row = row || {};

  return [
    String(row.source_therapy_plan || "").trim(),
    String(row.source_therapy_row_name || "").trim(),
    String(row.therapy_plans_been_transferred || "").trim(),
    String(row.source_invoice || "").trim()
  ].join("||");
}

function c2cFinalTableSourceKey(row) {
  row = row || {};

  var sourcePlan = String(row.source_therapy_plan || "").trim();
  var sourceRow = String(row.source_therapy_row_name || "").trim();

  if (!sourcePlan || !sourceRow) return "";
  return sourcePlan + "||" + sourceRow;
}

function c2cApprovalTherapyDisplay(value, sourcePlan) {
  value = String(value || "").trim();
  sourcePlan = String(sourcePlan || "").trim();

  if (sourcePlan) {
    var suffix = " (" + sourcePlan + ")";
    if (value.endsWith(suffix)) {
      value = value.slice(0, -suffix.length).trim();
    }
  }

  return value;
}

function c2cApprovalTherapyKey(value) {
  value = String(value || "").trim();

  // Strip only an appended Therapy Plan document suffix.
  // Preserve valid Therapy Type names such as "BCA (Body Composition)".
  value = value.replace(/\s*\(HLC-THP-[^)]+\)\s*$/i, "").trim();

  return value.toLowerCase().replace(/\s+/g, " ");
}

function c2cFinalTableComparable(rows) {
  return c2cNormalizeFinalTableRows(rows)
    .map(function (row) {
      return {
        source: c2cFinalTableSourceKey(row),
        therapy: c2cApprovalTherapyKey(row.therapy_plans_been_transferred),
        qty: Number(row.converted_quantity || 0),
        amount: roundMoney(getC2CTransferAmount([row])),
        start_date: String(row.start_date || "").trim()
      };
    })
    .sort(function (a, b) {
      return JSON.stringify(a).localeCompare(JSON.stringify(b));
    });
}

function c2cFinalTableHasChanged(baseRows, editedRows) {
  return JSON.stringify(c2cFinalTableComparable(baseRows)) !==
    JSON.stringify(c2cFinalTableComparable(editedRows));
}

function c2cGetBranchRequestedFinalRows(doc, fallbackRows) {
  var saved = c2cParseFinalTableSnapshot(
    doc && doc.custom_branch_requested_transfer_snapshot
  );

  if (saved.length) return saved;
  return c2cNormalizeFinalTableRows(fallbackRows || []);
}

function c2cGetAuditReviewedFinalRows(doc, fallbackRows) {
  var saved = c2cParseFinalTableSnapshot(
    doc && doc.custom_audit_approved_transfer_snapshot
  );

  if (saved.length) return saved;
  return c2cGetBranchRequestedFinalRows(doc, fallbackRows);
}

function c2cGetFinalTableEditorBaseRows(doc, role, fallbackRows) {
  if (role === "operations_coo") {
    return c2cGetAuditReviewedFinalRows(doc, fallbackRows);
  }

  return c2cGetBranchRequestedFinalRows(doc, fallbackRows);
}

function c2cGetFinalTableBudget(doc, fallbackRows) {
  var branchRows = c2cGetBranchRequestedFinalRows(doc, fallbackRows);
  return getC2CTransferAmount(branchRows);
}

function c2cFinalTableVersionActor(doc, stage) {
  doc = doc || {};
  stage = String(stage || "").trim().toLowerCase();

  if (stage === "audit") {
    return {
      name:
        String(
          doc.audit_team__corporate_team_name ||
          "Audit Team"
        ).trim(),
      date:
        String(
          doc.custom_audit_team_action_datetime ||
          doc.audit_team__corporate_team_date ||
          ""
        ).trim()
    };
  }

  if (stage === "coo") {
    return {
      name:
        String(
          doc.operations_coo__management_name ||
          "COO / Management"
        ).trim(),
      date:
        String(
          doc.custom_coo_management_action_datetime ||
          doc.operations_coo__management_date ||
          ""
        ).trim()
    };
  }

  return {
    name: "",
    date: ""
  };
}


