function c2cGetEffectiveApprovedFinalRows(doc, fallbackRows) {
  doc = doc || {};

  var cooRows = c2cParseFinalTableSnapshot(
    doc.custom_coo_final_transfer_snapshot
  );

  if (cooRows.length) {
    return cooRows;
  }

  var auditRows = c2cParseFinalTableSnapshot(
    doc.custom_audit_approved_transfer_snapshot
  );

  if (auditRows.length) {
    return auditRows;
  }

  var liveRows = c2cNormalizeFinalTableRows(
    fallbackRows || []
  );

  if (liveRows.length) {
    return liveRows;
  }

  return c2cGetBranchRequestedFinalRows(
    doc,
    fallbackRows
  );
}


function c2cGetSavedApprovalOverrideInfo(doc, fallbackRows) {
  doc = doc || {};

  var hasBranchSnapshot = !!String(
    doc.custom_branch_requested_transfer_snapshot || ""
  ).trim();

  var branchRows = c2cGetBranchRequestedFinalRows(
    doc,
    fallbackRows
  );

  var approvedRows = c2cGetEffectiveApprovedFinalRows(
    doc,
    fallbackRows
  );

  var branchValue = roundMoney(
    getC2CTransferAmount(branchRows)
  );

  var approvedValue = roundMoney(
    getC2CTransferAmount(approvedRows)
  );

  var overrideAmount = roundMoney(
    Math.max(
      approvedValue - branchValue,
      0
    )
  );

  /*
   * A reliable historical override needs the permanent Branch snapshot.
   * For legacy requests without that snapshot, do not invent an override
   * by comparing the already-mutated live table with itself.
   */
  if (!hasBranchSnapshot) {
    overrideAmount = 0;
  }

  var cooRows = c2cParseFinalTableSnapshot(
    doc.custom_coo_final_transfer_snapshot
  );

  var auditRows = c2cParseFinalTableSnapshot(
    doc.custom_audit_approved_transfer_snapshot
  );

  var stage = String(
    doc.custom_final_transfer_table_edited_stage || ""
  ).trim();

  if (!stage) {
    if (cooRows.length) {
      stage = "COO / Management Approval";
    } else if (auditRows.length) {
      stage = "Audit Team Approval";
    }
  }

  var actor = String(
    doc.custom_final_transfer_table_edited_by || ""
  ).trim();

  var actionDate = String(
    doc.custom_final_transfer_table_edited_on || ""
  ).trim();

  var stageLower = stage.toLowerCase();
  var editReason = "";

  if (stageLower.indexOf("coo") !== -1) {
    actor = actor || String(
      doc.operations_coo__management_name || ""
    ).trim();

    actionDate = actionDate || String(
      doc.custom_coo_management_action_datetime ||
      doc.operations_coo__management_date ||
      ""
    ).trim();

    editReason = String(
      doc.custom_coo_table_edit_remarks || ""
    ).trim();
  } else if (stageLower.indexOf("audit") !== -1) {
    actor = actor || String(
      doc.audit_team__corporate_team_name || ""
    ).trim();

    actionDate = actionDate || String(
      doc.custom_audit_team_action_datetime ||
      doc.audit_team__corporate_team_date ||
      ""
    ).trim();

    editReason = String(
      doc.custom_audit_table_edit_remarks || ""
    ).trim();
  } else if (cooRows.length) {
    actor = actor || String(
      doc.operations_coo__management_name || ""
    ).trim();

    actionDate = actionDate || String(
      doc.custom_coo_management_action_datetime ||
      doc.operations_coo__management_date ||
      ""
    ).trim();

    editReason = String(
      doc.custom_coo_table_edit_remarks || ""
    ).trim();
  } else if (auditRows.length) {
    actor = actor || String(
      doc.audit_team__corporate_team_name || ""
    ).trim();

    actionDate = actionDate || String(
      doc.custom_audit_team_action_datetime ||
      doc.audit_team__corporate_team_date ||
      ""
    ).trim();

    editReason = String(
      doc.custom_audit_table_edit_remarks || ""
    ).trim();
  }

  return {
    hasOverride: overrideAmount > 0,
    branchValue: branchValue,
    approvedValue: approvedValue,
    overrideAmount: overrideAmount,
    stage: stage,
    actor: actor,
    actionDate: actionDate,
    editReason: editReason
  };
}


function c2cRenderRequestDetailOverrideSummary(doc, fallbackRows) {
