function c2cRenderFinalTableVersionHistory(doc, fallbackRows) {
  doc = doc || {};

  var branchRows =
    c2cGetBranchRequestedFinalRows(
      doc,
      fallbackRows
    );

  var auditRows =
    c2cParseFinalTableSnapshot(
      doc.custom_audit_approved_transfer_snapshot
    );

  var cooRows =
    c2cParseFinalTableSnapshot(
      doc.custom_coo_final_transfer_snapshot
    );

  /*
   * Treat the saved version snapshots as the source of truth.
   * The explicit edited flags are retained, but older records may have a
   * snapshot even when the Check flag was never populated. In that case,
   * compare the versions exactly like P2P and still show the edited table.
   */
  var auditEdited =
    !!auditRows.length &&
    (
      Number(
        doc.custom_audit_transfer_table_edited || 0
      ) === 1 ||
      c2cFinalTableHasChanged(
        branchRows,
        auditRows
      )
    );

  var cooBaseRows =
    auditRows.length
      ? auditRows
      : branchRows;

  var cooEdited =
    !!cooRows.length &&
    (
      Number(
        doc.custom_coo_transfer_table_edited || 0
      ) === 1 ||
      c2cFinalTableHasChanged(
        cooBaseRows,
        cooRows
      )
    );

  var auditDecision =
    String(
      doc.audit_team_decision || ""
    ).trim();

  var cooDecision =
    String(
      getC2CSafeFinalApprovalStatus(doc) || ""
    ).trim();

  var auditActed =
    !!auditRows.length ||
    auditDecision === "Approved" ||
    auditDecision === "Rejected";

  var cooActed =
    !!cooRows.length ||
    (
      isC2CFinalApprovalActuallyReached(doc) &&
      (
        cooDecision === "Approved" ||
        cooDecision === "Rejected"
      )
    ) ||
    (
      isC2CProcessCompleted(doc) &&
      (
        String(doc.operations_coo__management_name || "").trim() ||
        String(doc.operations_coo__management_date || "").trim() ||
        String(doc.custom_coo_management_action_datetime || "").trim()
      )
    );

  var finalVersionClass =
    cooRows.length && cooEdited
      ? "coo"
      : auditRows.length && auditEdited
        ? "audit"
        : "branch";

  var auditActor =
    c2cFinalTableVersionActor(
      doc,
      "audit"
    );

  var cooActor =
    c2cFinalTableVersionActor(
      doc,
      "coo"
    );

  var html = `
    <div class="c2c-final-history-label">
      Transfer Table Version History
    </div>

    <div class="c2c-package-version-stack">
      ${c2cRenderFinalTableVersionTable({
        title: "Branch Requested Transfer Table",
        subtitle:
          "Original session / service transfer table submitted by the branch. This version remains unchanged.",
        badge: "Original Request",
        versionClass: "branch",
        isFinal:
          finalVersionClass === "branch",
        rows: branchRows
      })}
  `;

  if (auditActed) {
    if (
      auditRows.length &&
      auditEdited
    ) {
      html +=
        c2cRenderFinalTableVersionTable({
          title:
            "Audit Team Approved Transfer Table",
          subtitleHtml:
            "Transfer table edited and approved by " +
            c2cUserDisplayNameMarkup(
              auditActor.name || "",
              "Audit Team"
            ) +
            (
              auditActor.date
                ? " on " +
                  escapeHtml(
                    c2cP2PFormatDateTime(
                      auditActor.date
                    )
                  )
                : ""
            ),
          badge: "Edited by Audit",
          editRemarks:
            doc.custom_audit_table_edit_remarks ||
            "",
          versionClass: "audit",
          isFinal:
            finalVersionClass === "audit",
          rows: auditRows
        });
    } else {
      html +=
        c2cRenderFinalTableVersionStatus({
          versionClass: "audit",
          message:
            "Audit Team approved without transfer-table changes",
          actor:
            auditActor.name ||
            "Audit Team",
          date:
            auditActor.date || ""
        });
    }
  }

  if (cooActed) {
    if (
      cooRows.length &&
      cooEdited
    ) {
      html +=
        c2cRenderFinalTableVersionTable({
          title:
            "COO / Management Final Transfer Table",
          subtitleHtml:
            "Final transfer table edited and approved by " +
            c2cUserDisplayNameMarkup(
              cooActor.name || "",
              "COO / Management"
            ) +
            (
              cooActor.date
                ? " on " +
                  escapeHtml(
                    c2cP2PFormatDateTime(
                      cooActor.date
                    )
                  )
                : ""
            ),
          badge:
            "Final Edited Version",
          editRemarks:
            doc.custom_coo_table_edit_remarks ||
            "",
          versionClass: "coo",
          isFinal:
            finalVersionClass === "coo",
          rows: cooRows
        });
    } else {
      html +=
        c2cRenderFinalTableVersionStatus({
          versionClass: "coo",
          message:
            "COO / Management approved without transfer-table changes",
          actor:
            cooActor.name ||
            "COO / Management",
          date:
            cooActor.date || ""
        });
    }
  }

  html += `
    </div>
  `;

  return html;
}


function c2cRenderFinalTableEditorRows(rows) {
  // Do not filter blank/new rows here. + Add Therapy Type intentionally
  // creates a blank row that must stay visible until the reviewer selects
  // a Therapy Type. Validation happens before approval.
  rows = (rows || []).map(c2cFinalTableSnapshotRow);

  if (!rows.length) {
    return `
      <tr>
        <td colspan="6" class="c2c-final-editor-empty">
          No therapy rows available.
        </td>
      </tr>
    `;
  }

  return rows.map(function (row, index) {
    var qty = Number(row.converted_quantity || 0);
    var sourceBalance = Number(row.source_balance_before || 0);
    var amount = getC2CTransferAmount([row]);
    var isAddedOverride = !String(row.source_therapy_row_name || "").trim();

    return `
      <tr data-c2c-final-edit-row="${index}">
        <td>
          <div class="c2c-final-therapy-search-wrap">
            <input
              type="text"
              class="c2c-final-edit-therapy"
              data-index="${index}"
              value="${escapeHtml(c2cApprovalTherapyDisplay(
                row.therapy_plans_been_transferred || "",
                row.source_therapy_plan || ""
              ))}"
              placeholder="Search Therapy Type..."
              autocomplete="off"
            >
            <div
              class="c2c-final-therapy-dropdown"
              data-index="${index}"
              style="display:none"
            ></div>
          </div>
          <div class="c2c-final-locked-note">
            ${isAddedOverride ? "Approval override / added therapy" : "Source identity retained"}
          </div>
        </td>

        <td>
          ${
            isAddedOverride
              ? `<strong>—</strong>`
              : `<strong>${escapeHtml(row.source_therapy_plan || "-")}</strong>`
          }
          <div class="c2c-final-locked-note">
            ${
              isAddedOverride
                ? "No source plan — added during approval"
                : "Source plan protected"
            }
          </div>
        </td>

        <td>
          <input
            type="text"
            inputmode="numeric"
            pattern="[0-9]*"
            class="c2c-final-edit-qty"
            data-index="${index}"
            value="${escapeHtml(String(qty || 1))}"
          >
          <div class="c2c-final-locked-note">
            ${
              isAddedOverride
                ? "Approval override sessions allowed"
                : "Source balance: " + escapeHtml(String(sourceBalance || 0)) + " · Extra sessions allowed by approval"
            }
          </div>
        </td>

        <td>${escapeHtml(formatDate(row.start_date || ""))}</td>

        <td>
          <input
            type="text"
            inputmode="decimal"
            class="c2c-final-edit-amount-input"
            data-index="${index}"
            value="${escapeHtml(String(roundMoney(amount || 0)))}"
          >
          <div class="c2c-final-locked-note">No negative amount</div>
        </td>

        <td>
          <button
            type="button"
            class="c2c-final-remove-row"
            data-index="${index}"
          >
            Remove
          </button>
        </td>
      </tr>
    `;
  }).join("");
}

function c2cRenderFinalTableReviewBlock(doc, role, transferRows) {
  transferRows = c2cNormalizeFinalTableRows(transferRows);

  if (role !== "audit_team" && role !== "operations_coo") {
    return transferRows.length
      ? renderC2CTransferRowsTable(transferRows)
      : `<div class="cpc-detail-empty">No transferred therapy rows found.</div>`;
  }

  var baseRows = c2cGetFinalTableEditorBaseRows(doc, role, transferRows);
  var availableValue = c2cGetFinalTableBudget(doc, transferRows);
  var currentTotal = getC2CTransferAmount(baseRows);
  var overrideAmount = Math.max(currentTotal - availableValue, 0);

  return `
    <div class="c2c-final-review-wrap">
      ${c2cRenderFinalTableVersionHistory(
        doc,
        transferRows
      )}

      <div class="c2c-final-edit-lock">
        <div>
          <div class="c2c-final-edit-lock-title">
            Need to change the final transfer table?
          </div>
          <div class="c2c-final-edit-lock-sub">
            Editing is locked by default. Audit / COO can change Therapy Type,
            sessions and amount, add a Therapy Type, increase sessions beyond the
            original source balance, or approve a value override above the Branch-requested amount.
          </div>
        </div>

        <button
          type="button"
          class="btn btn-outline c2c-enable-final-edit-btn"
          id="c2cEnableFinalTableEditBtn"
        >
          Enable Final Table Editing
        </button>
      </div>

      <div
        class="c2c-final-editor-wrap"
        id="c2cFinalTableEditorWrap"
        style="display:none"
      >
        <div class="c2c-final-editor-head">
          <div>
            <strong>
              ${role === "audit_team"
                ? "Audit Team Final Table Edit"
                : "COO / Management Final Table Edit"}
            </strong>
            <span>
              You are editing ${
                role === "operations_coo"
                  ? "a copy of the Audit Team approved transfer table"
                  : "a copy of the original Branch requested transfer table"
              }. Earlier versions remain visible above for comparison.
            </span>
          </div>
        </div>

        <div class="c2c-final-override-strip">
          <div>
            <span>Branch Requested Value</span>
            <strong>${escapeHtml(c2cP2PMoney(availableValue))}</strong>
          </div>
          <div>
            <span>Edited Final Total</span>
            <strong id="c2cFinalEditedValue">${escapeHtml(c2cP2PMoney(currentTotal))}</strong>
          </div>
          <div>
            <span>Override Amount</span>
            <strong
              id="c2cFinalOverrideAmount"
              class="${overrideAmount > 0 ? "is-override" : ""}"
            >${escapeHtml(c2cP2PMoney(overrideAmount))}</strong>
          </div>
        </div>

        <div
          id="c2cFinalOverrideBanner"
          class="c2c-final-override-banner"
          style="${overrideAmount > 0 ? "" : "display:none"}"
        >
          ⚠ Approval Override: Edited final package value is above the Branch-requested transfer value.
        </div>

        <div class="cpc-mini-table-wrap c2c-final-editor-table-wrap">
          <table class="cpc-mini-table c2c-final-editor-table">
            <thead>
              <tr>
                <th>Therapy Type</th>
                <th>Source Plan</th>
                <th>New Sessions</th>
                <th>Start Date</th>
                <th>Amount</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody id="c2cFinalTableEditorBody">
              ${c2cRenderFinalTableEditorRows(baseRows)}
            </tbody>
          </table>
        </div>

        <div class="c2c-final-add-row-bar">
          <button
            type="button"
            class="btn btn-outline"
            id="c2cAddApprovalTherapyBtn"
          >
            + Add Therapy Type
          </button>
        </div>

        <div class="field-block c2c-final-edit-reason-wrap">
          <label class="lbl">
            Reason for editing final table
            <span style="color:#C00000">*</span>
          </label>

          <textarea
            id="c2cFinalTableEditReason"
            rows="3"
            maxlength="500"
            placeholder="Explain the Therapy Type / sessions / amount / override change"
          ></textarea>

          <div class="c2c-final-edit-reason-help">
            Required only when Therapy Type, sessions, amount or rows are changed.
          </div>
        </div>
      </div>
    </div>
  `;
}

function c2cCleanApprovalSessionValue(value) {
  value = String(value == null ? "" : value).replace(/[^\d]/g, "");
  value = value.replace(/^0+/, "");
  if (!value) value = "0";
  var n = parseInt(value, 10);
  if (isNaN(n) || n < 0) n = 0;
  return String(n);
}

function c2cCleanApprovalAmountValue(value) {
  value = String(value == null ? "" : value).replace(/[^\d.]/g, "");
  var parts = value.split(".");
  var whole = parts[0] || "";
  var decimal = parts.length > 1 ? parts.slice(1).join("") : "";
  whole = whole.replace(/^0+(?=\d)/, "");
  if (decimal.length > 2) decimal = decimal.slice(0, 2);
  return parts.length > 1 ? whole + "." + decimal : whole;
}

function c2cUpdateFinalEditorSummary(panel, state) {
  if (!panel || !state) return;

  var total = getC2CTransferAmount(state.rows);
  var overrideAmount = Math.max(total - Number(state.availableValue || 0), 0);

  var totalEl = panel.querySelector("#c2cFinalEditedValue");
  var overrideEl = panel.querySelector("#c2cFinalOverrideAmount");
  var bannerEl = panel.querySelector("#c2cFinalOverrideBanner");

  if (totalEl) totalEl.textContent = c2cP2PMoney(total);

  if (overrideEl) {
    overrideEl.textContent = c2cP2PMoney(overrideAmount);
    overrideEl.classList.toggle("is-override", overrideAmount > 0);
  }

  if (bannerEl) {
    bannerEl.style.display = overrideAmount > 0 ? "block" : "none";
  }
}

function c2cFindApprovalTherapyRateFields(t) {
  t = t || {};
  return Number(
    t.rate ||
    t.minimum_price ||
    t.custom_min_amount ||
    t.custom_plan_amount ||
    0
  );
}

function c2cPositionApprovalTherapyDropdown(input, dropdown) {
  if (!input || !dropdown) return;

  var rect = input.getBoundingClientRect();
  var viewportW = window.innerWidth || document.documentElement.clientWidth || 0;
  var viewportH = window.innerHeight || document.documentElement.clientHeight || 0;

  var desiredWidth = Math.max(rect.width, 260);
  var left = rect.left;

  // Keep the floating dropdown inside the visible viewport.
  if (left + desiredWidth > viewportW - 12) {
    left = Math.max(12, viewportW - desiredWidth - 12);
  }

  var maxHeight = 280;
  var spaceBelow = viewportH - rect.bottom - 12;
  var spaceAbove = rect.top - 12;
  var openAbove = spaceBelow < 180 && spaceAbove > spaceBelow;

  dropdown.style.position = "fixed";
  dropdown.style.zIndex = "999999";
  dropdown.style.left = Math.round(left) + "px";
  dropdown.style.right = "auto";
  dropdown.style.width = Math.round(desiredWidth) + "px";
  dropdown.style.maxWidth = "calc(100vw - 24px)";

  if (openAbove) {
    dropdown.style.top = "auto";
    dropdown.style.bottom = Math.max(12, Math.round(viewportH - rect.top + 4)) + "px";
    dropdown.style.maxHeight = Math.max(120, Math.min(maxHeight, spaceAbove - 8)) + "px";
  } else {
    dropdown.style.bottom = "auto";
    dropdown.style.top = Math.round(rect.bottom + 4) + "px";
    dropdown.style.maxHeight = Math.max(120, Math.min(maxHeight, spaceBelow - 8)) + "px";
  }
}

function c2cRefreshVisibleApprovalTherapyDropdowns() {
  document.querySelectorAll('.c2c-final-therapy-dropdown').forEach(function (dropdown) {
    if (!dropdown || dropdown.style.display === "none") return;

    var index = dropdown.getAttribute("data-index");
    var panel = dropdown.closest('.c2c-approval-action-panel') || root || document;
    var input = panel.querySelector(
      '.c2c-final-edit-therapy[data-index="' + index + '"]'
    );

    if (input) {
      c2cPositionApprovalTherapyDropdown(input, dropdown);
    }
  });
}

if (!window.__c2cApprovalTherapyDropdownFloatingBound) {
  window.__c2cApprovalTherapyDropdownFloatingBound = true;

  window.addEventListener("resize", function () {
    c2cRefreshVisibleApprovalTherapyDropdowns();
  });

  // Capture scroll events from the table wrapper / approval detail panel too.
  window.addEventListener("scroll", function () {
    c2cRefreshVisibleApprovalTherapyDropdowns();
  }, true);
}

function c2cGetUsedApprovalTherapyKeys(state, excludeIndex) {
  var used = {};

  ((state && state.rows) || []).forEach(function (row, rowIndex) {
    if (Number(rowIndex) === Number(excludeIndex)) return;

    var key = c2cApprovalTherapyKey(
      row && row.therapy_plans_been_transferred
    );

    if (key) used[key] = 1;
  });

  return used;
}

function c2cSearchApprovalTherapyType(q, dropdown, input, row, panel, state, index) {
  if (!dropdown || !input || !row) return;

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Therapy Type",
      fields: ["name"],
      filters: [["Therapy Type", "name", "like", "%" + q + "%"]],
      order_by: "name asc",
      limit_page_length: 20
    },
    callback: function (r) {
      var rows = r.message || [];
      var usedTherapyKeys = c2cGetUsedApprovalTherapyKeys(state, index);

      rows = rows.filter(function (therapy) {
        var key = c2cApprovalTherapyKey(therapy && therapy.name);
        return key && !usedTherapyKeys[key];
      });

      if (!rows.length) {
        dropdown.innerHTML = `
          <div class="c2c-final-therapy-dd-empty">
            No additional Therapy Type available. Matching Therapy Types already present in the final table are excluded.
          </div>
        `;
        dropdown.style.display = "block";
        c2cPositionApprovalTherapyDropdown(input, dropdown);
        return;
      }

      dropdown.innerHTML = rows.map(function (therapy) {
        return `
          <button
            type="button"
            class="c2c-final-therapy-dd-item"
            data-value="${escapeHtml(therapy.name)}"
            data-index="${index}"
          >
            ${escapeHtml(therapy.name)}
          </button>
        `;
      }).join("");

      dropdown.style.display = "block";
      c2cPositionApprovalTherapyDropdown(input, dropdown);
    },
    error: function () {
      dropdown.innerHTML = `
        <div class="c2c-final-therapy-dd-empty">Therapy Type search failed.</div>
      `;
      dropdown.style.display = "block";
      c2cPositionApprovalTherapyDropdown(input, dropdown);
    }
  });
}

function c2cFetchApprovalTherapyRate(therapyName, panel, state, index) {
  if (!therapyName || !panel || !state || !state.rows[index]) return;

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: "Therapy Type",
      name: therapyName
    },
    callback: function (r) {
      var therapy = r.message || {};
      var rate = c2cFindApprovalTherapyRateFields(therapy);
      var row = state.rows[index];
      if (!row) return;

      if (rate > 0) {
        var qty = Number(row.converted_quantity || 1);
        row.unit_transfer_amount = rate;
        row.total_amount = roundMoney(rate * qty);
        row.balance_quantity_amount = row.total_amount;
      }

      var body = panel.querySelector("#c2cFinalTableEditorBody");
      if (body) body.innerHTML = c2cRenderFinalTableEditorRows(state.rows);
      c2cUpdateFinalEditorSummary(panel, state);
    }
  });
}

function bindC2CFinalTableEditor(panel, doc, role, transferRows) {
  if (!panel) return;
  if (role !== "audit_team" && role !== "operations_coo") return;

  var enableBtn = panel.querySelector("#c2cEnableFinalTableEditBtn");
  var editorWrap = panel.querySelector("#c2cFinalTableEditorWrap");
  var editorBody = panel.querySelector("#c2cFinalTableEditorBody");
  var addBtn = panel.querySelector("#c2cAddApprovalTherapyBtn");

  if (!enableBtn || !editorWrap || !editorBody) return;

  var baseRows = c2cGetFinalTableEditorBaseRows(doc, role, transferRows);

  var state = {
    role: role,
    enabled: false,
    baseRows: c2cNormalizeFinalTableRows(baseRows),
    rows: c2cNormalizeFinalTableRows(baseRows),
    availableValue: c2cGetFinalTableBudget(doc, transferRows)
  };

  panel.__c2cFinalTableState = state;

  function renderRows() {
    editorBody.innerHTML = c2cRenderFinalTableEditorRows(state.rows);
    c2cUpdateFinalEditorSummary(panel, state);
  }

  function getAnchorRow() {
    return state.rows.find(function (row) {
      return !!String(row.source_therapy_plan || "").trim();
    }) || state.baseRows.find(function (row) {
      return !!String(row.source_therapy_plan || "").trim();
    }) || null;
  }

  enableBtn.addEventListener("click", function () {
    if (state.enabled) return;

    var unlock = function () {
      state.enabled = true;
      editorWrap.style.display = "block";
      enableBtn.disabled = true;
      enableBtn.textContent = "Final Table Editing Enabled";
      enableBtn.classList.add("is-enabled");

      editorWrap.scrollIntoView({
        behavior: "smooth",
        block: "nearest"
      });

      frappe.show_alert({
        message: "P2P-style final table editing enabled. Approval overrides are allowed.",
        indicator: "orange"
      });
    };

    if (typeof frappe !== "undefined" && typeof frappe.confirm === "function") {
      frappe.confirm(
        "Enable final table editing? Therapy Type, sessions and amount can be changed, new Therapy Types can be added, and values above the Branch-requested amount will be recorded as an approval override.",
        unlock
      );
    } else {
      unlock();
    }
  });

  if (addBtn) {
    addBtn.addEventListener("click", function () {
      if (!state.enabled) return;

      var anchor = getAnchorRow();

      var today = "";
      try {
        today = frappe.datetime.get_today();
      } catch (e) {}

      state.rows.push(c2cFinalTableSnapshotRow({
        therapy_plans_been_transferred: "",
        converted_quantity: 1,
        start_date: (anchor && anchor.start_date) || today,
        validity_exp_dt: (anchor && anchor.validity_exp_dt) || "",
        total_amount: 0,
        balance_quantity_amount: 0,
        unit_transfer_amount: 0,

        // Approval-added Therapy Types are intentionally source-less.
        // The backend uses the request's existing source-backed rows only as
        // an internal template/category anchor; no source Therapy Plan or
        // source invoice is stored against this new override row.
        source_therapy_plan: "",
        source_therapy_row_name: "",
        source_invoice: "",

        source_sessions_before: 0,
        source_completed_before: 0,
        source_balance_before: 0,
        source_sessions_after: 0,
        source_balance_after: 0
      }));

      renderRows();

      var inputs = editorBody.querySelectorAll(".c2c-final-edit-therapy");
      if (inputs.length) inputs[inputs.length - 1].focus();
    });
  }

  editorBody.addEventListener("input", function (event) {
    if (!state.enabled) return;

    var therapyInput = event.target.closest(".c2c-final-edit-therapy");
    if (therapyInput) {
      var therapyIndex = Number(therapyInput.dataset.index || 0);
      var therapyRow = state.rows[therapyIndex];
      if (!therapyRow) return;

      therapyRow.therapy_plans_been_transferred = String(therapyInput.value || "").trim();
      var dropdown = editorBody.querySelector(
        '.c2c-final-therapy-dropdown[data-index="' + therapyIndex + '"]'
      );
      var q = String(therapyInput.value || "").trim();

      if (q.length < 2) {
        if (dropdown) dropdown.style.display = "none";
      } else {
        c2cSearchApprovalTherapyType(
          q,
          dropdown,
          therapyInput,
          therapyRow,
          panel,
          state,
          therapyIndex
        );
      }

      return;
    }

    var qtyInput = event.target.closest(".c2c-final-edit-qty");
    if (qtyInput) {
      var qtyIndex = Number(qtyInput.dataset.index || 0);
      var qtyRow = state.rows[qtyIndex];
      if (!qtyRow) return;

      qtyInput.value = c2cCleanApprovalSessionValue(qtyInput.value);
      qtyRow.converted_quantity = Number(qtyInput.value || 0);
      c2cUpdateFinalEditorSummary(panel, state);
      return;
    }

    var amountInput = event.target.closest(".c2c-final-edit-amount-input");
    if (amountInput) {
      var amountIndex = Number(amountInput.dataset.index || 0);
      var amountRow = state.rows[amountIndex];
      if (!amountRow) return;

      amountInput.value = c2cCleanApprovalAmountValue(amountInput.value);
      var amount = Number(amountInput.value || 0);
      amountRow.total_amount = amount;
      amountRow.balance_quantity_amount = amount;
      amountRow.unit_transfer_amount = Number(amountRow.converted_quantity || 0) > 0
        ? amount / Number(amountRow.converted_quantity || 1)
        : 0;
      c2cUpdateFinalEditorSummary(panel, state);
    }
  });

  editorBody.addEventListener("blur", function (event) {
    if (!state.enabled) return;

    var qtyInput = event.target.closest(".c2c-final-edit-qty");
    if (qtyInput) {
      var index = Number(qtyInput.dataset.index || 0);
      var row = state.rows[index];
      if (!row) return;

      var qty = Number(c2cCleanApprovalSessionValue(qtyInput.value) || 0);
      if (qty < 1) qty = 1;
      row.converted_quantity = qty;
      qtyInput.value = String(qty);
      c2cUpdateFinalEditorSummary(panel, state);
      return;
    }

    var amountInput = event.target.closest(".c2c-final-edit-amount-input");
    if (amountInput) {
      var amountIndex = Number(amountInput.dataset.index || 0);
      var amountRow = state.rows[amountIndex];
      if (!amountRow) return;

      var amount = roundMoney(Number(amountInput.value || 0));
      if (amount < 0) amount = 0;
      amountRow.total_amount = amount;
      amountRow.balance_quantity_amount = amount;
      amountRow.unit_transfer_amount = Number(amountRow.converted_quantity || 0) > 0
        ? amount / Number(amountRow.converted_quantity || 1)
        : 0;
      amountInput.value = String(amount);
      c2cUpdateFinalEditorSummary(panel, state);
    }
  }, true);

  editorBody.addEventListener("click", function (event) {
    if (!state.enabled) return;

    var therapyChoice = event.target.closest(".c2c-final-therapy-dd-item[data-value]");
    if (therapyChoice) {
      var choiceIndex = Number(therapyChoice.dataset.index || 0);
      var choiceRow = state.rows[choiceIndex];
      if (!choiceRow) return;

      var selectedName = String(therapyChoice.dataset.value || "").trim();
      var selectedKey = c2cApprovalTherapyKey(selectedName);
      var usedKeys = c2cGetUsedApprovalTherapyKeys(state, choiceIndex);

      if (selectedKey && usedKeys[selectedKey]) {
        frappe.msgprint({
          title: "Therapy Type Already Added",
          indicator: "orange",
          message:
            "<b>" + escapeHtml(selectedName) +
            "</b> is already present in the final table. Please select a different Therapy Type."
        });
        return;
      }

      choiceRow.therapy_plans_been_transferred = selectedName;

      // If this row was created with + Add Therapy Type, keep it source-less.
      if (!String(choiceRow.source_therapy_row_name || "").trim()) {
        choiceRow.source_therapy_plan = "";
        choiceRow.source_invoice = "";
      }

      var input = editorBody.querySelector(
        '.c2c-final-edit-therapy[data-index="' + choiceIndex + '"]'
      );
      var dropdown = editorBody.querySelector(
        '.c2c-final-therapy-dropdown[data-index="' + choiceIndex + '"]'
      );

      if (input) input.value = selectedName;
      if (dropdown) dropdown.style.display = "none";

      c2cFetchApprovalTherapyRate(
        selectedName,
        panel,
        state,
        choiceIndex
      );
      return;
    }

    var removeBtn = event.target.closest(".c2c-final-remove-row");
    if (!removeBtn) return;

    var index = Number(removeBtn.dataset.index || 0);

    if (state.rows.length <= 1) {
      frappe.msgprint(
        "At least one Therapy Type must remain in the final table."
      );
      return;
    }

    state.rows.splice(index, 1);
    renderRows();
  });
}

function getC2CDashboardFinalTableEditState(panel, row, role) {
  if (role !== "audit_team" && role !== "operations_coo") {
    return {
      ok: true,
      enabled: false,
      changed: false,
      reason: "",
      rows: c2cNormalizeFinalTableRows(
        getC2CChildRows(
          row || {},
          "remaining_sessions_package_details",
          REMAINING_CHILD_DOCTYPE
        )
      ),
      total: 0,
      overrideAmount: 0
    };
  }

  var state = panel && panel.__c2cFinalTableState;

  if (!state) {
    var fallbackRows = getC2CChildRows(
      row || {},
      "remaining_sessions_package_details",
      REMAINING_CHILD_DOCTYPE
    );

    var baseRows = c2cGetFinalTableEditorBaseRows(
      row || {},
      role,
      fallbackRows
    );

    return {
      ok: true,
      enabled: false,
      changed: false,
      reason: "",
      rows: c2cNormalizeFinalTableRows(baseRows),
      total: getC2CTransferAmount(baseRows),
      overrideAmount: Math.max(
        getC2CTransferAmount(baseRows) - c2cGetFinalTableBudget(row || {}, fallbackRows),
        0
      )
    };
  }

  var reasonEl = panel.querySelector("#c2cFinalTableEditReason");
  var reason = reasonEl ? String(reasonEl.value || "").trim() : "";

  // Validate the raw editor rows before normalization. This is important
  // because a newly-added row may still be waiting for a Therapy Type.
  var editorRows = (state.rows || []).map(c2cFinalTableSnapshotRow);

  if (!editorRows.length) {
    return {
      ok: false,
      message: "At least one Therapy Type must remain in the final table."
    };
  }

  var seen = {};

  for (var i = 0; i < editorRows.length; i++) {
    var currentRow = editorRows[i];
    var therapy = String(currentRow.therapy_plans_been_transferred || "").trim();
    var therapyKey = c2cApprovalTherapyKey(therapy);
    var qty = Number(currentRow.converted_quantity || 0);
    var amount = getC2CTransferAmount([currentRow]);

    if (!therapy) {
      return {
        ok: false,
        message: "Row " + (i + 1) + ": Therapy Type is required."
      };
    }

    if (!Number.isInteger(qty) || qty <= 0) {
      return {
        ok: false,
        message: "Row " + (i + 1) + ": Sessions must be a whole number greater than 0."
      };
    }

    if (!Number.isFinite(amount) || amount < 0) {
      return {
        ok: false,
        message: "Row " + (i + 1) + ": Amount cannot be negative."
      };
    }

    var sourceIdentity = c2cFinalTableSourceKey(currentRow);
    var isApprovalAddedRow = !String(
      currentRow.source_therapy_row_name || ""
    ).trim();

    // A Therapy Type added during Audit / COO approval must be new to the
    // final table. It cannot duplicate an existing branch/source row or a
    // second approval-added row.
    if (isApprovalAddedRow) {
      for (var j = 0; j < editorRows.length; j++) {
        if (j === i) continue;

        var otherTherapyKey = c2cApprovalTherapyKey(
          editorRows[j] && editorRows[j].therapy_plans_been_transferred
        );

        if (therapyKey && therapyKey === otherTherapyKey) {
          return {
            ok: false,
            message:
              "Therapy Type already exists in the final table: " +
              therapy +
              ". Please select a different Therapy Type."
          };
        }
      }

      // Approval-added rows must remain source-less.
      currentRow.source_therapy_plan = "";
      currentRow.source_invoice = "";
    }

    var duplicateKey = sourceIdentity
      ? "SOURCE::" + sourceIdentity
      : "OVERRIDE::" + therapyKey;

    if (seen[duplicateKey]) {
      return {
        ok: false,
        message: "Duplicate final-table row found: " + therapy
      };
    }

    seen[duplicateKey] = true;
  }

  var rows = c2cNormalizeFinalTableRows(editorRows);

  var changed = state.enabled && c2cFinalTableHasChanged(state.baseRows, rows);

  if (changed && !reason) {
    return {
      ok: false,
      message: "Please enter Reason for editing final table.",
      focusEl: reasonEl
    };
  }

  var total = getC2CTransferAmount(rows);
  var overrideAmount = Math.max(total - Number(state.availableValue || 0), 0);

  return {
    ok: true,
    enabled: !!state.enabled,
    changed: !!changed,
    reason: reason,
    rows: rows,
    total: total,
    overrideAmount: overrideAmount
  };
}

function c2cApplyFinalTableRowsToDoc(doc, requestedRows) {
  doc = doc || {};

  var currentRows = getC2CChildRows(
    doc,
    "remaining_sessions_package_details",
    REMAINING_CHILD_DOCTYPE
  );

  var currentByFullKey = {};
  var currentBySourceKey = {};

  (currentRows || []).forEach(function (row) {
    currentByFullKey[c2cFinalTableRowKey(row)] = row;

    var sourceKey = c2cFinalTableSourceKey(row);
    if (sourceKey) currentBySourceKey[sourceKey] = row;
  });

  var applied = c2cNormalizeFinalTableRows(requestedRows).map(function (snapshotRow, index) {
    var fullKey = c2cFinalTableRowKey(snapshotRow);
    var sourceKey = c2cFinalTableSourceKey(snapshotRow);
    var current = currentByFullKey[fullKey] ||
      (sourceKey ? currentBySourceKey[sourceKey] : null) ||
      {};

    var out = {};

    Object.keys(current || {}).forEach(function (fieldname) {
      out[fieldname] = current[fieldname];
    });

    Object.keys(snapshotRow || {}).forEach(function (fieldname) {
      if (fieldname === "name" && !snapshotRow[fieldname]) return;
      out[fieldname] = snapshotRow[fieldname];
    });

    out.doctype = REMAINING_CHILD_DOCTYPE;
    out.idx = index + 1;

    var qty = Number(out.converted_quantity || 0);
    var amount = getC2CTransferAmount([out]);

    out.balance_quantity_amount = roundMoney(amount);
    out.total_amount = roundMoney(amount);
    out.unit_transfer_amount = qty > 0 ? amount / qty : 0;

    var hasSourceRow = !!String(out.source_therapy_row_name || "").trim();
    var sourceSessionsBefore = Number(out.source_sessions_before || 0);
    var sourceCompletedBefore = Number(out.source_completed_before || 0);
    var sourceBalanceBefore = Number(
      out.source_balance_before ||
      Math.max(sourceSessionsBefore - sourceCompletedBefore, 0) ||
      0
    );

    var sourceDeductQty = hasSourceRow
      ? Math.min(qty, Math.max(sourceBalanceBefore, 0))
      : 0;

    if (hasSourceRow) {
      out.source_sessions_after = Math.max(
        sourceSessionsBefore - sourceDeductQty,
        sourceCompletedBefore
      );
      out.source_balance_after = Math.max(
        out.source_sessions_after - sourceCompletedBefore,
        0
      );
    } else {
      out.source_sessions_before = 0;
      out.source_completed_before = 0;
      out.source_balance_before = 0;
      out.source_sessions_after = 0;
      out.source_balance_after = 0;
    }

    return out;
  });

  doc.remaining_sessions_package_details = applied;
  return applied;
}

function applyC2CFinalTableReviewToDoc(
  doc,
  role,
  editState,
  approverName,
  approverId
) {
  if (role !== "audit_team" && role !== "operations_coo") return;

  editState = editState || {};

  var currentRows = getC2CChildRows(
    doc,
    "remaining_sessions_package_details",
    REMAINING_CHILD_DOCTYPE
  );

  if (!String(doc.custom_branch_requested_transfer_snapshot || "").trim()) {
    doc.custom_branch_requested_transfer_snapshot =
      c2cSerializeFinalTableSnapshot(currentRows);
  }

  var finalRows = c2cNormalizeFinalTableRows(
    editState.rows && editState.rows.length
      ? editState.rows
      : c2cGetFinalTableEditorBaseRows(doc, role, currentRows)
  );

  if (!finalRows.length) {
    throw new Error("At least one Therapy Type must remain in the final table.");
  }

  var appliedRows = c2cApplyFinalTableRowsToDoc(doc, finalRows);
  var serialized = c2cSerializeFinalTableSnapshot(appliedRows);
  var changed = !!editState.changed;
  var reason = String(editState.reason || "").trim();

  if (role === "audit_team") {
    doc.custom_audit_approved_transfer_snapshot = serialized;
    doc.custom_audit_transfer_table_edited = changed ? 1 : 0;
    doc.custom_audit_table_edit_remarks = changed ? reason : "";
  }

  if (role === "operations_coo") {
    doc.custom_coo_final_transfer_snapshot = serialized;
    doc.custom_coo_transfer_table_edited = changed ? 1 : 0;
    doc.custom_coo_table_edit_remarks = changed ? reason : "";
  }

  if (changed) {
    var now = "";

    try {
      now = frappe.datetime && typeof frappe.datetime.now_datetime === "function"
        ? frappe.datetime.now_datetime()
        : "";
    } catch (e) {}

    if (!now) {
      now = new Date().toISOString().slice(0, 19).replace("T", " ");
    }

    doc.custom_final_transfer_table_edited_stage =
      role === "audit_team" ? "Audit Team" : "COO / Management";

    doc.custom_final_transfer_table_edited_by = String(
      (frappe.session && frappe.session.user) ||
      approverId ||
      approverName ||
      ""
    ).trim();

    doc.custom_final_transfer_table_edited_on = now;
  }
}


