// ============================================================
// SAVE APPROVAL - P2P STYLE
// ============================================================

function doC2CDashboardApproval(row, action, role, panel) {
  var cfg = getC2CApprovalRoleConfig(role);

  var approverEl = panel.querySelector("#c2cDashApproverName");
  var remarksEl = panel.querySelector("#c2cDashApprovalRemarks");
  var statusEl = panel.querySelector("#c2cDashApprovalStatus");
  var approveBtn = panel.querySelector("#c2cDashApproveBtn");
  var rejectBtn = panel.querySelector("#c2cDashRejectBtn");

  var remarks = remarksEl ? String(remarksEl.value || "").trim() : "";
  var approverName = approverEl ? String(approverEl.value || "").trim() : "";
  var approverId = "";

  if (approverEl) {
    if (approverEl.tagName === "SELECT") {
      var opt = approverEl.options[approverEl.selectedIndex];

      approverId = opt
        ? String(opt.dataset.employeeId || opt.value || "").trim()
        : "";
    } else {
      approverId = String(
        approverEl.dataset.employeeId ||
        approverEl.value ||
        ""
      ).trim();
    }
  }

  function resetButtons(message) {
    if (approveBtn) {
      approveBtn.disabled = false;
      approveBtn.textContent = approveBtn.dataset.originalText || "✓ Approve";
    }

    if (rejectBtn) {
      rejectBtn.disabled = false;
      rejectBtn.textContent = rejectBtn.dataset.originalText || "✕ Reject";
    }

    if (statusEl) {
      statusEl.textContent = message || "";
      statusEl.style.color = message ? "#C00000" : "";
    }
  }

  function setBusy(message) {
    if (approveBtn) {
      approveBtn.disabled = true;
      approveBtn.textContent = message || "Saving...";
    }

    if (rejectBtn) {
      rejectBtn.disabled = true;
    }

    if (statusEl) {
      statusEl.textContent = message || "Saving...";
      statusEl.style.color = "#0D2B4E";
    }
  }

  if (!row || !row.name) {
    resetButtons("Request is missing. Please refresh and try again.");
    return;
  }

  if (!cfg) {
    resetButtons("Invalid approval role selected.");
    return;
  }

  // ------------------------------------------------------------
  // AUDIT LOGIN VALIDATION
  // ------------------------------------------------------------
  if (role === "audit_team") {
  if (!isAllowedAuditUser()) {
    resetButtons("You are not authorised for Audit / Corporate Team approval.");

    frappe.msgprint({
      title: "Access Denied",
      indicator: "red",
      message: "Only authorised Audit / Corporate Team users can approve this stage."
    });

    return;
  }

  approverName = getCurrentAuditApproverName();
  approverId = getCurrentAuditApproverId();

  if (!approverName || !approverId) {
    resetButtons("Audit approver could not be detected from logged-in user.");
    return;
  }
}

  // ------------------------------------------------------------
  // COO LOGIN VALIDATION
  // ------------------------------------------------------------
  if (role === "operations_coo") {
    if (!isLoggedInFinalCooUser()) {
      resetButtons("You are not authorised for COO / Management approval.");

      frappe.msgprint({
        title: "Access Denied",
        indicator: "red",
        message: "Only authorised Operations COO / Management users can complete final approval."
      });

      return;
    }

    approverName = getLoggedInFinalCooName();
    approverId = approverName;
  }

  // ------------------------------------------------------------
  // CENTRE MANAGER VALIDATION
  // ------------------------------------------------------------
  if (role === "centre_manager") {
    if (!approverName) {
      resetButtons("Please select Centre Manager / ACM name before saving approval.");

      if (approverEl) approverEl.focus();
      return;
    }

    if (!approverId) {
      resetButtons("Please select Centre Manager / ACM from the dropdown list.");

      if (approverEl) approverEl.focus();
      return;
    }
  }

  if (!approverName) {
    resetButtons("Approver name is missing.");
    return;
  }

  if (action === "Rejected" && !remarks) {
    resetButtons("Remarks required for rejection.");

    if (remarksEl) remarksEl.focus();
    return;
  }

  var finalTableEditState =
    getC2CDashboardFinalTableEditState(
      panel,
      row,
      role
    );

  if (!finalTableEditState.ok) {
    resetButtons(
      finalTableEditState.message ||
      "Please check the final transfer table."
    );

    if (finalTableEditState.focusEl) {
      finalTableEditState.focusEl.focus();
    }

    return;
  }

  setBusy(action === "Approved" ? "Saving approval..." : "Saving rejection...");

  frappe.call({
    method: "frappe.client.get",
    args: {
      doctype: DOCTYPE,
      name: row.name
    },
    callback: function (r) {
      var latestDoc = r.message || {};

      if (!latestDoc.name) {
        resetButtons("Unable to fetch latest request.");
        return;
      }

      var currentPendingRole = getPendingRoleForC2CRequest(latestDoc);

      if (currentPendingRole !== role) {
        resetButtons("This request is no longer pending for the selected role. Please refresh.");

        frappe.msgprint({
          title: "Stage Changed",
          indicator: "orange",
          message: "This request has already moved to another stage. Please refresh the dashboard."
        });

        return;
      }

      try {
        applyC2CFinalTableReviewToDoc(
          latestDoc,
          role,
          finalTableEditState,
          approverName,
          approverId
        );
      } catch (editErr) {
        void 0;

        resetButtons(
          editErr && editErr.message
            ? editErr.message
            : "Unable to apply final table changes."
        );

        frappe.msgprint({
          title: "Final Table Not Saved",
          indicator: "red",
          message:
            editErr && editErr.message
              ? editErr.message
              : "Unable to apply final table changes."
        });

        return;
      }

      applyC2CDashboardApprovalToDoc(
        latestDoc,
        action,
        role,
        approverName,
        approverId,
        remarks
      );

      frappe.call({
        method: "frappe.client.save",
        args: {
          doc: latestDoc
        },
        callback: function (saveResult) {
          var saved = saveResult.message || {};
          var successMessage = getC2CDashboardSuccessMessage(action, role);

          if (statusEl) {
            statusEl.textContent = successMessage;
            statusEl.style.color = action === "Approved" ? "#1E7A34" : "#C00000";
          }

          replaceC2CDashboardActionWithDone(panel, action, role, saved);

          frappe.show_alert({
            message: successMessage,
            indicator: action === "Approved" ? "green" : "red"
          });

          if (typeof sendStepEmail === "function") {
            try {
              var nextStep = Number(saved.current_tab_step || latestDoc.current_tab_step || 0);

              if (action === "Approved" && nextStep && nextStep <= 4) {
                sendStepEmail(saved.name || latestDoc.name, nextStep);
              }
            } catch (e) {}
          }

          loadRequests();

          setTimeout(function () {
            renderApprovalDashboard();
          }, 700);

          // When opened from LIFE Approvals Report, return after the
          // approval/rejection has been saved successfully.
          lifeC2CReturnToApprovalsReport(
            saved.name || latestDoc.name || row.name,
            action,
            role
          );
        },
        error: function (err) {
          void 0;

          var msg = "Unable to save approval.";

          if (typeof getFrappeErrorMessage === "function") {
            msg = getFrappeErrorMessage(err, "Unable to save approval.");
          }

          resetButtons(msg);

          frappe.msgprint({
            title: "Approval Not Saved",
            indicator: "red",
            message: msg
          });
        }
      });
    },
    error: function (err) {
      void 0;

      resetButtons("Unable to fetch latest request before approval.");

      frappe.msgprint({
        title: "Unable to Load Request",
        indicator: "red",
        message: "Could not fetch the latest request. Please refresh and try again."
      });
    }
  });
}

// ============================================================
// APPLY APPROVAL TO LATEST DOC
// ============================================================

function applyC2CDashboardApprovalToDoc(doc, action, role, approverName, approverId, remarks) {
  var cfg = getC2CApprovalRoleConfig(role);

  var today = "";
  var actionDateTime = "";

  try {
    today = frappe.datetime.get_today();
    actionDateTime =
      frappe.datetime &&
      typeof frappe.datetime.now_datetime === "function"
        ? frappe.datetime.now_datetime()
        : "";
  } catch (e) {
    today = new Date().toISOString().slice(0, 10);
  }

  if (!actionDateTime) {
    actionDateTime =
      new Date()
        .toISOString()
        .slice(0, 19)
        .replace("T", " ");
  }

  if (!cfg) return;

  doc[cfg.nameField] = approverId || approverName || "";
  doc[cfg.dateField] = today;
  doc[cfg.remarksField] = remarks || "";
  doc[cfg.decisionField] = action;

  c2cSetApprovalActionDateTime(
    doc,
    role,
    actionDateTime
  );

  if (role === "centre_manager") {
    if (action === "Approved") {
      doc.current_tab_step = 3;
      doc.approval_stage = APPROVAL_STAGES.AUDIT_PENDING;
      doc.approval_display_status = APPROVAL_STAGES.AUDIT_PENDING;
      doc.final_approval_status = "";
      doc.automation_status = "Pending Final Approval";
    } else {
      doc.rejected_by_role = "Centre Manager";
      doc.rejected_by_name = approverName;
      doc.rejection_remarks = remarks;

      // TERMINAL REJECTION RULE:
      // Do not forward a Centre Manager rejection to Audit.
      doc.current_tab_step = 2;
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.approval_display_status = "Centre Manager Rejected / Process Stopped";
      doc.final_approval_status = "Rejected";
      doc.conversion_status = "Rejected";
      doc.automation_status = "Skipped";
    }
  }

  else if (role === "audit_team") {
    // Store User ID/email in audit_team__corporate_team_name
    doc.audit_team__corporate_team_name = approverId || getCurrentAuditApproverId();

    if (action === "Approved") {
      doc.current_tab_step = 3;
      doc.approval_stage = APPROVAL_STAGES.COO_PENDING;
      doc.approval_display_status = APPROVAL_STAGES.COO_PENDING;
      doc.final_approval_status = "";
      doc.automation_status = "Pending Final Approval";
    } else {
      doc.rejected_by_role = "Audit Team / Corporate Team";
      doc.rejected_by_name = approverName;
      doc.rejection_remarks = remarks;

      // TERMINAL REJECTION RULE:
      // Do not forward an Audit rejection to COO / Management.
      doc.current_tab_step = 3;
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.approval_display_status = "Audit Team Rejected / Process Stopped";
      doc.final_approval_status = "Rejected";
      doc.conversion_status = "Rejected";
      doc.automation_status = "Skipped";
    }
  }

  else if (role === "operations_coo") {
    doc.current_tab_step = 4;

    if (action === "Approved") {
      doc.approval_stage = APPROVAL_STAGES.APPROVED;
      doc.final_approval_status = "Approved";
      doc.approval_display_status = "Approved / Pending Package Transfer";
      doc.automation_status = "Pending Final Approval";
      doc.conversion_status = "Approved";
    } else {
      doc.approval_stage = APPROVAL_STAGES.REJECTED;
      doc.final_approval_status = "Rejected";
      doc.approval_display_status = "Rejected / Skipped";
      doc.automation_status = "Skipped";
      doc.conversion_status = "Rejected";

      doc.rejected_by_role = "Operations COO / Management";
      doc.rejected_by_name = approverName;
      doc.rejection_remarks = remarks;
    }
  }
}


