function bindC2CDashboardApproverControl(panel, row, role) {
  if (role !== "centre_manager") return;

  var approverEl = panel.querySelector("#c2cDashApproverName");
  var resultBox = panel.querySelector("#c2cDashApproverResults");

  if (!approverEl || !resultBox) return;

  var approvalBranch = row.branch || "";
  var timer = null;

  function runSearch() {
    clearTimeout(timer);

    var q = String(approverEl.value || "").trim();

    approverEl.dataset.employeeId = "";

    timer = setTimeout(function () {
      searchC2CDashboardCentreManagers(q, approvalBranch, resultBox, approverEl);
    }, 200);
  }

  approverEl.addEventListener("input", function () {
    runSearch();
  });

  approverEl.addEventListener("focus", function () {
    runSearch();
  });

  approverEl.addEventListener("click", function () {
    runSearch();
  });
}

function searchC2CDashboardCentreManagers(q, branch, resultBox, approverEl) {
  q = String(q || "").trim();
  branch = String(branch || "").trim();

  var allowedDesignations = [
    "ACM",
    "ACM(TRAINEE)",
    "CM(TRAINEE)",
    "Assistant Centre Manager",
    "Assistant Center Manager",
    "Center Manager",
    "Centre Manager"
  ];

  if (!branch) {
    resultBox.innerHTML = `
      <div class="ac-item">
        <span class="acm">Branch is missing. Please check transferor branch.</span>
      </div>
    `;
    resultBox.style.display = "block";
    resultBox.classList.add("show");
    return;
  }

  resultBox.innerHTML = `
    <div class="ac-item">
      <span class="acm">Searching...</span>
    </div>
  `;

  resultBox.style.display = "block";
  resultBox.classList.add("show");

  var filters = [
    ["Employee", "status", "=", "Active"],
    ["Employee", "designation", "in", allowedDesignations],
    ["Employee", "branch", "=", branch]
  ];

  // Only apply name filter when user types something.
  // If q is empty, all active ACM / CM employees for the branch will show.
  if (q) {
    filters.push(["Employee", "employee_name", "like", "%" + q + "%"]);
  }

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Employee",
      fields: [
        "name",
        "employee_name",
        "designation",
        "branch",
        "user_id",
        "status"
      ],
      filters: filters,
      limit_page_length: 30,
      order_by: "employee_name asc"
    },
    callback: function (r) {
      var rows = r.message || [];

      if (!rows.length) {
        resultBox.innerHTML = `
          <div class="ac-item">
            <span class="acm">No active ACM / CM found for ${escapeHtml(branch || "-")}.</span>
          </div>
        `;
        resultBox.style.display = "block";
        resultBox.classList.add("show");
        return;
      }

      resultBox.innerHTML = rows.map(function (emp) {
        return `
          <div
            class="ac-item"
            data-employee="${escapeHtml(emp.name || "")}"
            data-label="${escapeHtml(emp.employee_name || emp.name || "")}"
          >
            <strong>${escapeHtml(emp.employee_name || emp.name || "-")}</strong>
            <div class="acm">
              ${escapeHtml(emp.designation || "-")}
              · ${escapeHtml(emp.branch || "-")}
              ${emp.user_id ? " · " + escapeHtml(emp.user_id) : ""}
            </div>
          </div>
        `;
      }).join("");

      resultBox.style.display = "block";
      resultBox.classList.add("show");

      resultBox.querySelectorAll(".ac-item[data-employee]").forEach(function (item) {
        item.addEventListener("click", function () {
          approverEl.value = item.dataset.label || "";
          approverEl.dataset.employeeId = item.dataset.employee || item.dataset.label || "";

          resultBox.innerHTML = "";
          resultBox.style.display = "none";
          resultBox.classList.remove("show");
        });
      });
    },
    error: function () {
      resultBox.innerHTML = `
        <div class="ac-item">
          <span style="color:#C00000">Employee search failed.</span>
        </div>
      `;
      resultBox.style.display = "block";
      resultBox.classList.add("show");
    }
  });
}



// ============================================================
// TIMELINE + DONE CARD
// ============================================================

function c2cTimelineDisplayText(value) {
  return String(value || "")
    .replace(/Operations Manager Approval Pending/g, "Audit Team Approval Pending")
    .replace(/Operations Manager/g, "Audit Team")
    .replace(/Audit Team \/ Corporate Team/g, "Audit Team")
    .replace(/Operations COO \/ Management/g, "COO / Management");
}

function c2cTimelineDisplayName(value) {
  value = String(value || "").trim();
  if (!value) return "";

  /* Employee Link values (HR-EMP-xxxx) */
  if (typeof c2cEmployeeDisplayNameCache !== "undefined") {
    var employeeDisplayName =
      c2cEmployeeDisplayNameCache[value] ||
      c2cEmployeeDisplayNameCache[value.toUpperCase()] ||
      "";

    if (employeeDisplayName) return employeeDisplayName;
  }

  /* ERPNext User IDs are normally email addresses. Show User.full_name. */
  if (typeof c2cUserDisplayNameCache !== "undefined") {
    var userDisplayName =
      c2cUserDisplayNameCache[value] ||
      c2cUserDisplayNameCache[value.toLowerCase()] ||
      "";

    if (userDisplayName) return userDisplayName;
  }

  if (typeof c2cGetBootUserDisplayName === "function") {
    var bootDisplayName = c2cGetBootUserDisplayName(value);
    if (bootDisplayName) return bootDisplayName;
  }

  return value;
}

function c2cTimelineActionLabel(entry) {
  entry = entry || {};

  if (entry.action) {
    return String(entry.action || "").trim();
  }

  var title = String(entry.title || "");

  if (/Rejected|Failed/i.test(title)) return /Failed/i.test(title) ? "Failed" : "Rejected";
  if (/Approved|Authorised|Completed/i.test(title)) {
    return /Completed/i.test(title) ? "Completed" : "Approved";
  }
  if (/Submitted|Created/i.test(title)) return "Submitted";
  if (/Processing|Awaiting|Waiting/i.test(title)) return /Processing/i.test(title) ? "Processing" : "";

  return "";
}

function c2cTimelineActionClass(action) {
  action = String(action || "");

  if (/Rejected|Failed/i.test(action)) return "is-rejected";
  if (/Approved|Authorised|Completed/i.test(action)) return "is-approved";
  if (/Submitted/i.test(action)) return "is-submitted";
  if (/Processing/i.test(action)) return "is-processing";

  return "";
}

function c2cTimelineDescriptionHtml(entry) {
  entry = entry || {};

  var text = c2cTimelineDisplayText(entry.desc || "")
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .trim();

  if (!text) return "";

  text = text
    .replace(/\n{3,}/g, "\n\n")
    .replace(/^\s*Remarks\s*:-\s*/i, "");

  var action = c2cTimelineActionLabel(entry);
  var showRemarksLabel = /Approved|Rejected/i.test(action);

  return `
    <div class="pkg-remarks-rendered">
      ${
        showRemarksLabel
          ? '<span class="pkg-timeline-remarks-label">Remarks:-</span> '
          : ""
      }
      ${escapeHtml(text).replace(/\n/g, "<br>")}
    </div>
  `;
}

function c2cTimelineFormatDateTime(value) {
  value = String(value || "").trim();
  if (!value) return "-";

  /* C2C approval date fields are Date fields. Do not invent 12:00 AM. */
  if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
    return formatDate(value);
  }

  return c2cP2PFormatDateTime(value);
}

function c2cTimelineHasClockTime(value) {
  return /\d{2}:\d{2}/.test(String(value || ""));
}

function c2cTimelineTaken(startValue, endValue) {
  /* Exact duration is shown only when both values contain clock time. */
  if (!c2cTimelineHasClockTime(startValue) || !c2cTimelineHasClockTime(endValue)) {
    return "";
  }

  var start = c2cP2PParseDateTime(startValue);
  var end = c2cP2PParseDateTime(endValue);

  if (!start || !end) return "";

  var elapsed = end.getTime() - start.getTime();
  if (!Number.isFinite(elapsed) || elapsed < 0) return "";

  return c2cP2PFormatDuration(elapsed);
}

/*
 * Exact C2C approval timing
 * ------------------------------------------------------------
 * The existing approval fields (centre_manager_date,
 * audit_team__corporate_team_date and
 * operations_coo__management_date) are Date fields, so they
 * cannot store the hour/minute needed for P2P-style durations.
 *
 * Add these three hidden/read-only Datetime fields to the C2C
 * DocType:
 *   custom_centre_manager_action_datetime
 *   custom_audit_team_action_datetime
 *   custom_coo_management_action_datetime
 *
 * The helpers below also recognise a few older alias names if
 * they already exist on the site.
 */
function c2cSetApprovalActionDateTime(doc, role, value) {
  doc = doc || {};
  role = String(role || "").trim().toLowerCase();
  value = String(value || "").trim();

  if (!value) return;

  var fieldMap = {
    centre_manager: [
      "custom_centre_manager_action_datetime",
      "centre_manager_approval_datetime",
      "centre_manager_datetime"
    ],
    audit_team: [
      "custom_audit_team_action_datetime",
      "audit_team_approval_datetime",
      "audit_team__corporate_team_datetime"
    ],
    operations_coo: [
      "custom_coo_management_action_datetime",
      "operations_coo__management_datetime",
      "coo_management_approval_datetime",
      "coo_management_datetime"
    ]
  };

  var fields = fieldMap[role] || [];

  for (var i = 0; i < fields.length; i++) {
    var fieldname = fields[i];

    if (
      Object.prototype.hasOwnProperty.call(
        doc,
        fieldname
      )
    ) {
      doc[fieldname] = value;
      return;
    }
  }
}

function c2cTimelineApprovalActionTime(doc, role) {
  doc = doc || {};
  role = String(role || "").trim().toLowerCase();

  var candidates = [];

  if (role === "centre_manager") {
    candidates = [
      doc.custom_centre_manager_action_datetime,
      doc.centre_manager_approval_datetime,
      doc.centre_manager_datetime,
      doc.centre_manager_approved_on,
      c2cTimelineHasClockTime(doc.centre_manager_date)
        ? doc.centre_manager_date
        : ""
    ];
  }
  else if (role === "audit_team") {
    candidates = [
      doc.custom_audit_team_action_datetime,
      doc.audit_team_approval_datetime,
      doc.audit_team__corporate_team_datetime,
      doc.audit_team_approved_on,
      c2cTimelineHasClockTime(
        doc.audit_team__corporate_team_date
      )
        ? doc.audit_team__corporate_team_date
        : ""
    ];
  }
  else if (role === "operations_coo") {
    candidates = [
      doc.custom_coo_management_action_datetime,
      doc.operations_coo__management_datetime,
      doc.coo_management_approval_datetime,
      doc.coo_management_datetime,
      c2cTimelineHasClockTime(
        doc.operations_coo__management_date
      )
        ? doc.operations_coo__management_date
        : ""
    ];
  }

  for (var i = 0; i < candidates.length; i++) {
    if (c2cTimelineHasClockTime(candidates[i])) {
      return String(candidates[i] || "").trim();
    }
  }

  return "";
}

function c2cTimelineStageStart(doc, role) {
  doc = doc || {};
  role = String(role || "").trim().toLowerCase();

  if (role === "centre_manager") {
    return doc.creation || "";
  }

  if (role === "audit_team") {
    return c2cTimelineApprovalActionTime(
      doc,
      "centre_manager"
    );
  }

  if (role === "operations_coo") {
    return c2cTimelineApprovalActionTime(
      doc,
      "audit_team"
    );
  }

  return "";
}

function c2cPushP2PTimelineApprovalEntry(entries, doc, config) {
  config = config || {};

  var decision = String(config.decision || "").trim();
  if (!decision || decision === "Pending") return;

  var rejected = decision === "Rejected";
  var action = rejected ? "Rejected" : "Approved";
  var approver =
    c2cTimelineDisplayName(config.name) ||
    config.role ||
    "Approver";
  var roleKey = config.roleKey || "";

  /*
   * Exact timestamp is used for duration calculation.
   * Legacy date-only values remain available for display, but
   * we deliberately do not fabricate a time for old requests.
   */
  var exactActionDate =
    config.actionDateTime ||
    c2cTimelineApprovalActionTime(
      doc,
      roleKey
    );

  var displayDate =
    exactActionDate ||
    config.date ||
    doc.modified ||
    "";

  entries.push({
    icon: rejected ? "❌" : (config.icon || "✅"),
    color: rejected ? "#C00000" : "#1E7A34",
    title:
      c2cTimelineDisplayText(config.role || "Approver") +
      " — " + action +
      (approver ? " by " + approver : ""),
    action: action,
    desc: config.remarks || "",
    by: approver,
    time: displayDate,
    taken:
      exactActionDate
        ? c2cTimelineTaken(
            c2cTimelineStageStart(
              doc,
              roleKey
            ),
            exactActionDate
          )
        : "",
    takenFor:
      rejected
        ? "rejection"
        : "approval"
  });
}

function buildC2CDashboardTimeline(doc) {
  doc = doc || {};

  var entries = [];
  var transferRows = getC2CChildRows(
    doc,
    "remaining_sessions_package_details",
    REMAINING_CHILD_DOCTYPE
  );

  var transferSummary = getC2CTransferSummary(transferRows);
  var totalTransferAmount = getC2CTransferAmount(transferRows);

  entries.push({
    icon: "📋",
    color: "#0D2B4E",
    title: "Request Submitted",
    action: "Submitted",
    desc:
      "Transferor: " + (doc.client_full_name || doc.name1 || "-") +
      " → Transferee: " +
      (doc.transferee_full_name || doc.client_name || "-"),
    by: doc.owner || "Staff",
    time: doc.creation || doc.date || doc.modified
  });

  if (
    Number(doc.current_tab_step || 1) > 1 ||
    doc.transferor_signature ||
    doc.transferee_signature ||
    transferRows.length
  ) {
    entries.push({
      icon: "📝",
      color: "#0D2B4E",
      title: "Request Details Submitted",
      action: "Submitted",
      desc:
        (transferSummary || "Transfer details recorded") +
        " | Amount: " + c2cP2PMoney(totalTransferAmount),
      by: doc.modified_by || doc.owner || "Staff",
      time: doc.modified || doc.date || doc.creation
    });
  }

  c2cPushP2PTimelineApprovalEntry(entries, doc, {
    icon: "🏢",
    role: "Centre Manager",
    roleKey: "centre_manager",
    decision: doc.centre_manager_decision,
    name: doc.centre_manager_name,
    date: doc.centre_manager_date,
    remarks: doc.centre_manager_remarks
  });

  /* Old C2C records may contain an Operations Manager stage.
     Use it only when the current Audit Team fields are empty,
     so the timeline never shows the Audit stage twice. */
  if (!String(doc.audit_team_decision || "").trim()) {
    c2cPushP2PTimelineApprovalEntry(entries, doc, {
      icon: "✅",
      role: "Audit Team",
      roleKey: "audit_team",
      decision: doc.operations_manager_decision,
      name: doc.operations_manager_name,
      date: doc.operations_manager_date,
      actionDateTime:
        c2cTimelineApprovalActionTime(
          doc,
          "audit_team"
        ),
      remarks: doc.operations_manager_remarks
    });
  }

  c2cPushP2PTimelineApprovalEntry(entries, doc, {
    icon: "✅",
    role: "Audit Team",
    roleKey: "audit_team",
    decision: doc.audit_team_decision,
    name: doc.audit_team__corporate_team_name,
    date: doc.audit_team__corporate_team_date,
    remarks: doc.audit_team_remarks
  });

  var finalStatus = getC2CSafeFinalApprovalStatus(doc);

  /*
   * Safety fallback for completed requests. Some older/server-updated rows
   * can have Process Completed persisted by db.set_value while the final
   * Select value returned to the browser is stale/blank. If the request is
   * completed and we have clear COO evidence, render the COO approval rather
   * than leaving the timeline at "Awaiting COO".
   */
  if (
    !finalStatus &&
    isC2CProcessCompleted(doc) &&
    (
      String(doc.operations_coo__management_name || "").trim() ||
      String(doc.operations_coo__management_date || "").trim() ||
      String(doc.custom_coo_management_action_datetime || "").trim() ||
      String(doc.custom_coo_final_transfer_snapshot || "").trim()
    )
  ) {
    finalStatus = "Approved";
  }

  c2cPushP2PTimelineApprovalEntry(entries, doc, {
    icon: "👑",
    role: "COO / Management",
    roleKey: "operations_coo",
    decision: finalStatus,
    name: doc.operations_coo__management_name,
    date: doc.operations_coo__management_date,
    actionDateTime:
      c2cTimelineApprovalActionTime(
        doc,
        "operations_coo"
      ),
    remarks: doc.office_remarks_any
  });

  var automationStatus = String(doc.automation_status || "").trim();
  var approvalStage = getC2CApprovalStageValue(doc);

  if (isC2CProcessCompleted(doc)) {
    entries.push({
      icon: "🏁",
      color: "#0D2B4E",
      title: "Process Completed",
      action: "Completed",
      desc:
        getC2CAutomationLogLine(doc) ||
        "Package transfer automation completed successfully.",
      by: "System",
      time: doc.modified
    });
  } else if (isC2CAutomationFailed(doc)) {
    entries.push({
      icon: "⚠️",
      color: "#C00000",
      title: "Automation Failed",
      action: "Failed",
      desc:
        getC2CAutomationLogLine(doc) ||
        "Package transfer automation failed. Please check the server log.",
      by: "System",
      time: doc.modified
    });
  } else if (finalStatus === "Approved") {
    entries.push({
      icon: "⏳",
      color: "#B8860B",
      title: "Waiting for Package Transfer Update",
      action: automationStatus === "Processing" ? "Processing" : "",
      desc:
        automationStatus ||
        "Final approval is completed. Automation will process the package transfer.",
      by: "System",
      time: doc.modified
    });
  } else if (finalStatus !== "Rejected" && approvalStage) {
    entries.push({
      icon: "⏳",
      color: "#B8860B",
      title: "Awaiting: " + c2cTimelineDisplayText(approvalStage),
      desc: "Current pending approval stage.",
      by: "System",
      time: doc.modified
    });
  }

  if (!entries.length) {
    return '<div class="pkg-approval-empty-msg">No activity yet.</div>';
  }

  return `
    <div class="pkg-timeline pkg-timeline-p2p-pattern">
      ${entries.map(function (entry) {
        var action = c2cTimelineActionLabel(entry);
        var actionClass = c2cTimelineActionClass(action);

        return `
          <div class="pkg-timeline-item">
            <div
              class="pkg-timeline-dot"
              style="background:${escapeHtml(entry.color || "#0D2B4E")};"
            ></div>

            <div class="pkg-timeline-content">
              <div
                class="pkg-timeline-title"
                style="color:${escapeHtml(entry.color || "#0D2B4E")};"
              >
                <span class="pkg-timeline-icon">${escapeHtml(entry.icon || "•")}</span>
                ${escapeHtml(c2cTimelineDisplayText(entry.title || ""))}
              </div>

              ${entry.desc ? c2cTimelineDescriptionHtml(entry) : ""}

              <div class="pkg-timeline-by">
                <span class="pkg-timeline-person">
                  ${escapeHtml(c2cTimelineDisplayName(entry.by) || "System")}
                </span>

                ${
                  action
                    ? `
                      <span class="pkg-timeline-action ${escapeHtml(actionClass)}">
                        ${escapeHtml(action)}
                      </span>
                    `
                    : ""
                }

                <span class="pkg-timeline-sep">·</span>

                <span class="pkg-timeline-time-text">
                  ${escapeHtml(c2cTimelineFormatDateTime(entry.time || ""))}
                </span>

                ${
                  entry.taken
                    ? `
                      <span class="pkg-timeline-taken ${
                        entry.takenFor === "rejection"
                          ? "is-rejection"
                          : "is-approval"
                      }">
                        [taken ${escapeHtml(entry.taken)} for ${
                          entry.takenFor === "rejection"
                            ? "rejection"
                            : "approval"
                        }]
                      </span>
                    `
                    : ""
                }
              </div>
            </div>
          </div>
        `;
      }).join("")}
    </div>
  `;
}

function replaceC2CDashboardActionWithDone(panel, action, role, saved) {
