          ${isRejected ? "Rejected" : "Approved"}
        </div>

        <div class="cpc-approval-done-msg">
          ${escapeHtml(getC2CDashboardSuccessMessage(action, role))}
        </div>
      </div>
    </div>
  `;
}


function getC2CDashboardSuccessMessage(action, role) {
  if (action === "Rejected") {
    if (role === "centre_manager") {
      return "Centre Manager rejection saved. Workflow stopped; no further approval is required.";
    }

    if (role === "audit_team") {
      return "Audit rejection saved. Workflow stopped; the request will not go to COO / Management.";
    }

    if (role === "operations_coo") {
      return "Final rejection saved. Package transfer automation skipped.";
    }
  }

  if (role === "centre_manager") {
    return "Centre Manager approval saved. Request moved to Audit / Corporate Team.";
  }

  if (role === "audit_team") {
    return "Audit / Corporate Team approval saved. Request moved to COO / Management.";
  }

  if (role === "operations_coo") {
    return "COO / Management final approval saved. Package transfer automation will run.";
  }

  return "Approval saved.";
}


