/* ============================================================
   C2C — P2P UI / DISPLAY IMPORT
   Only dashboard presentation and dashboard navigation defaults
   are overridden. Existing request fetching and form workflow stay intact.
   ============================================================ */

var c2cP2PApprovalPage = 1;
var C2C_P2P_APPROVAL_PER_PAGE = 10;

function prepareC2CInitialView(route) {
  route = route || {};

  if (route.tab === "approval") {
    setC2CApprovalRoleFromExternalRoute(route.role);
    activateC2CMode(2);
    return;
  }

  if (route.tab === "all") {
    activateC2CMode(1);
    return;
  }

  /* P2P behaviour: normal opening defaults to Approval Dashboard. */
  activateC2CMode(2);
}

function c2cP2PParseDateTime(value) {
  value = String(value || "").trim();
  if (!value) return null;

  var normalized = value.replace(" ", "T").replace(/(\.\d{3})\d+/, "$1");

  if (/^\d{4}-\d{2}-\d{2}$/.test(normalized)) {
    normalized += "T00:00:00";
  }

  var parsed = new Date(normalized);
  return isNaN(parsed.getTime()) ? null : parsed;
}

function c2cP2PFormatDateTime(value) {
  var date = c2cP2PParseDateTime(value);

  if (!date) {
    return typeof formatDate === "function"
      ? formatDate(value)
      : String(value || "-");
  }

  var months = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun",
    "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"
  ];

  var day = String(date.getDate()).padStart(2, "0");
  var month = months[date.getMonth()];
  var year = String(date.getFullYear()).slice(-2);
  var hours = date.getHours();
  var minutes = String(date.getMinutes()).padStart(2, "0");
  var ampm = hours >= 12 ? "PM" : "AM";

  hours = hours % 12;
  if (hours === 0) hours = 12;

  return (
    day + "-" + month + "-" + year +
    " " + hours + ":" + minutes + " " + ampm
  );
}

function c2cP2PFormatDuration(milliseconds) {
  var totalMinutes = Math.max(
    Math.floor(Number(milliseconds || 0) / 60000),
    0
  );

  if (totalMinutes < 1) return "<1m";

  var days = Math.floor(totalMinutes / 1440);
  var hours = Math.floor((totalMinutes % 1440) / 60);
  var minutes = totalMinutes % 60;
  var parts = [];

  if (days) parts.push(days + "d");
  if (hours) parts.push(hours + "h");
  if (!days && minutes) parts.push(minutes + "m");

  return parts.join(" ") || "<1m";
}

function c2cP2PIsRejected(row) {
  row = row || {};

  const finalStatus = String(row.final_approval_status || "").trim();
  const stage = String(row.approval_stage || "").trim();
  const conversionStatus = String(row.conversion_status || "").trim();
  const displayStatus = String(row.approval_display_status || "").trim();

  /*
   * Terminal rejection rule:
   * rejection by Centre Manager, Audit Team, or COO stops the workflow.
   */
  return (
    String(row.centre_manager_decision || "").trim() === "Rejected" ||
    String(row.audit_team_decision || "").trim() === "Rejected" ||
    (finalStatus === "Rejected" && isC2CFinalApprovalActuallyReached(row)) ||
    stage === APPROVAL_STAGES.REJECTED ||
    conversionStatus === "Rejected" ||
    /Rejected.*Process\s*Stopped/i.test(displayStatus) ||
    /Rejected\s*\/\s*Skipped/i.test(displayStatus)
  );
}

function c2cP2PIsCompleted(row) {
  row = row || {};

  return (
    (typeof isC2CProcessCompleted === "function" &&
      isC2CProcessCompleted(row)) ||
    String(row.automation_status || "").trim() === "Process Completed" ||
    String(row.approval_display_status || "").trim() === "Process Completed" ||
    String(row.conversion_status || "").trim() === "Completed"
  );
}

function c2cP2PCompactStatus(row) {
  row = row || {};

  var stage = typeof getC2CApprovalStageValue === "function"
    ? String(getC2CApprovalStageValue(row) || "")
    : String(row.approval_stage || "");

  var displayStatus = String(
    row.approval_display_status ||
    row.conversion_status ||
    stage ||
    ""
  );

  if (c2cP2PIsRejected(row)) return "Rejected";
  if (c2cP2PIsCompleted(row)) return "Process Completed";

  if (
    String(row.automation_status || "").trim() === "Failed"
  ) {
    return "Automation Failed";
  }

  if (
    getC2CSafeFinalApprovalStatus(row) === "Approved" ||
    stage === APPROVAL_STAGES.APPROVED
  ) {
    return "Approved";
  }

  if (/COO|Management/i.test(stage + " " + displayStatus)) {
    return "COO Pending";
  }

  if (/Audit Team|Operations Manager|Operations Head/i.test(stage + " " + displayStatus)) {
    return "Audit Pending";
  }

  if (/Centre Manager|Branch Official/i.test(stage + " " + displayStatus)) {
    return "CM Pending";
  }

  return displayStatus || "Request Pending";
}

function c2cP2PStagePillClass(row) {
  var status = c2cP2PCompactStatus(row);

  if (/Rejected/i.test(status)) return "pkg-pill-rejected";
  if (/Automation Failed/i.test(status)) return "pkg-pill-failed";
  if (/Process Completed/i.test(status)) return "pkg-pill-completed";
  if (/^Approved$/i.test(status)) return "pkg-pill-approved";
  if (/CM Pending/i.test(status)) return "pkg-pill-cm-pending";
  if (/Audit Pending/i.test(status)) return "pkg-pill-audit-pending";
  if (/COO Pending/i.test(status)) return "pkg-pill-coo-pending";

  return "pkg-pill-cm-pending";
}

function c2cP2PProcessInfo(row) {
  row = row || {};

  var start =
    c2cP2PParseDateTime(row.creation) ||
    c2cP2PParseDateTime(row.date) ||
    c2cP2PParseDateTime(row.modified);

  if (!start) {
    return {
      label: "",
      cls: "",
      title: ""
    };
  }

  var rejected = c2cP2PIsRejected(row);
  var completed = c2cP2PIsCompleted(row);
  var approvedOnly =
    getC2CSafeFinalApprovalStatus(row) === "Approved" &&
    !completed;

  var end = (rejected || completed)
    ? (c2cP2PParseDateTime(row.modified) || new Date())
    : new Date();

  var durationMs = Math.max(end.getTime() - start.getTime(), 0);
  var durationText = c2cP2PFormatDuration(durationMs);
  var hours = durationMs / 3600000;

  if (rejected) {
    return {
      label: "Rejected in " + durationText,
      cls: "is-rejected",
      title: "Time from request creation until the final recorded rejection"
    };
  }

  if (completed) {
    return {
      label: "Completed in " + durationText,
      cls: "is-completed",
      title: "Time from request creation until process completion"
    };
  }

  if (approvedOnly) {
    return {
      label: "Processing " + durationText,
      cls: hours <= 24
        ? "is-pending-green"
        : (hours <= 48 ? "is-pending-yellow" : "is-pending-red"),
      title: "Final approval is saved and package-transfer processing is pending"
    };
  }

  return {
    label: "Pending " + durationText,
    cls: hours <= 24
      ? "is-pending-green"
      : (hours <= 48 ? "is-pending-yellow" : "is-pending-red"),
    title: "Time pending from request creation until now"
  };
}

function c2cP2PMoney(value) {
  return "₹" + Number(value || 0).toLocaleString("en-IN", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2
  });
}

function c2cP2PShortText(value, maxLength) {
  value = String(value || "").trim();
  maxLength = Number(maxLength || 42);

  return value.length <= maxLength
    ? value
    : value.slice(0, Math.max(maxLength - 1, 1)) + "…";
}

function c2cP2PDoesRequestMatchSearch(row, keyword) {
  keyword = String(keyword || "").trim().toLowerCase();
  if (!keyword) return true;

  return [
    row && row.name,
    row && row.client_full_name,
    row && row.name1,
    row && row.transferee_full_name,
    row && row.client_name,
    row && row.mobile_number,
    row && row.phone_number,
    row && row.branch,
    row && row.receiving_branch,
    row && row.transfer_type,
    row && row.original_invoice__bill_numbers,
    row && row.approval_display_status,
    row && row.approval_stage,
    row && row.conversion_status,
    row && row.final_approval_status,
    row && row.automation_status,
    c2cP2PCompactStatus(row)
  ]
    .join(" ")
    .toLowerCase()
    .includes(keyword);
}

function c2cP2PMatchesStatusFilter(row, filterValue) {
  filterValue = String(filterValue || "").trim();
  if (!filterValue) return true;

  var stage = typeof getC2CApprovalStageValue === "function"
    ? String(getC2CApprovalStageValue(row) || "")
    : String(row.approval_stage || "");

  var statusLabel = typeof getC2CRequestStatusLabel === "function"
    ? String(getC2CRequestStatusLabel(row) || "")
    : c2cP2PCompactStatus(row);

  var finalStatus = String(row.final_approval_status || "").trim();
  var automationStatus = String(row.automation_status || "").trim();
  var displayStatus = String(row.approval_display_status || "").trim();
  var conversionStatus = String(row.conversion_status || "").trim();

  if (filterValue === "Approved") {
    return (
      getC2CSafeFinalApprovalStatus(row) === "Approved" ||
      stage === APPROVAL_STAGES.APPROVED ||
      /^Approved$/i.test(statusLabel)
    ) && !c2cP2PIsCompleted(row);
  }

  if (filterValue === "Process Completed") {
    return c2cP2PIsCompleted(row);
  }

  if (filterValue === "Rejected") {
    return c2cP2PIsRejected(row);
  }

  if (filterValue === "Failed") {
    return automationStatus === "Failed";
  }

  return [
    stage,
    statusLabel,
    displayStatus,
    conversionStatus,
    automationStatus,
    c2cP2PCompactStatus(row)
  ].some(function (value) {
    return (
      String(value || "") === filterValue ||
      String(value || "").indexOf(filterValue) !== -1
    );
  });
}

function c2cUserDisplayNameMarkup(value, fallback) {
  value = String(value || "").trim();
  fallback = String(fallback || "").trim();

  if (!value) {
    return escapeHtml(fallback || "Approver");
  }

  var displayName =
    c2cTimelineDisplayName(value) ||
    value;

  if (c2cIsUserDocumentId(value)) {
    return (
      '<span class="c2c-user-display-name" ' +
      'data-c2c-user-id="' + escapeHtml(value) + '" ' +
      'title="' + escapeHtml(value) + '">' +
      escapeHtml(displayName) +
      '</span>'
    );
  }

  return escapeHtml(displayName || fallback || value);
}

function c2cP2PActionLine(row) {
  row = row || {};

  if (c2cP2PIsRejected(row)) {
    var rejectedBy =
      row.rejected_by_name ||
      row.modified_by ||
      "Approver";

    var rejectedRole =
      row.rejected_by_role ||
      "Final Review";

    return `
      <div class="pkg-request-action-line is-rejected">
        <span>Rejected by</span>
        <strong>${c2cUserDisplayNameMarkup(rejectedBy, "Approver")}</strong>
        <em>${escapeHtml(rejectedRole)}</em>
      </div>
    `;
  }

  var approvedBy = "";
  var approvedRole = "";

  if (row.operations_coo__management_name) {
    approvedBy = row.operations_coo__management_name;
    approvedRole = "COO / Management";
  } else if (row.audit_team__corporate_team_name) {
    approvedBy = row.audit_team__corporate_team_name;
    approvedRole = "Audit Team";
  } else if (row.centre_manager_name) {
    approvedBy = row.centre_manager_name;
    approvedRole = "Centre Manager";
  }

  if (!approvedBy) return "";

  return `
    <div class="pkg-request-action-line">
      <span>Approved by</span>
      <strong>${c2cUserDisplayNameMarkup(approvedBy, "Approver")}</strong>
      <em>${escapeHtml(approvedRole)}</em>
    </div>
  `;
}

function c2cP2PInfoChip(label, value) {
  return `
    <div class="pkg-info-chip">
      <span>${escapeHtml(label)}</span>
      <strong>${escapeHtml(
        value === undefined || value === null || value === ""
          ? "-"
          : value
      )}</strong>
    </div>
  `;
}

function c2cP2PPartyCard(title, name, mobile, branch, cardClass) {
  return `
    <div class="pkg-flow-card ${escapeHtml(cardClass || "")}">
      <div class="pkg-flow-card-title">${escapeHtml(title)}</div>
      <div class="pkg-flow-card-value">${escapeHtml(name || "-")}</div>
      <div class="pkg-flow-card-sub">
        ${escapeHtml(mobile || "-")} · ${escapeHtml(branch || "-")}
      </div>
    </div>
