}

function c2cP2PBuildRequestCard(row, approvalMode, roleLabel) {
  row = row || {};

  var transferor =
    row.client_full_name ||
    row.name1 ||
    row.mobile_number ||
    "-";

  var transferee =
    row.transferee_full_name ||
    row.client_name ||
    row.phone_number ||
