          >
            ${escapeHtml(transferor)}
            <span class="c2c-flow-arrow">→</span>
            ${escapeHtml(transferee)}
          </div>

          <div class="pkg-request-doc-id">
            ${escapeHtml(row.name || "—")}
          </div>
        </div>

        ${
          approvalMode
            ? ""
