      </div>

      ${c2cP2PActionLine(row)}

      <div class="pkg-request-meta-row">
        <span>${escapeHtml(branchFlow)}</span>
        <span>Req. Dt: ${escapeHtml(requestDate)}</span>
      </div>

      ${
        !approvalMode && processInfo.label
          ? `
            <div style="margin-top:8px">
              <span
                class="pkg-process-time-chip ${escapeHtml(processInfo.cls)}"
                title="${escapeHtml(processInfo.title)}"
              >${escapeHtml(processInfo.label)}</span>
            </div>
          `
          : ""
      }

      <div class="pkg-request-source-grid">
        <div class="pkg-request-source-plan">
          <span>Transfer Type</span>
          <strong>${escapeHtml(row.transfer_type || "Not recorded")}</strong>
        </div>

        <div class="pkg-request-category-box">
          <span>${approvalMode ? "Pending With" : "Invoice(s)"}</span>
          <strong title="${escapeHtml(row.original_invoice__bill_numbers || "")}">
            ${escapeHtml(
              approvalMode
                ? (roleLabel || "Approver")
                : invoiceText
            )}
          </strong>
        </div>
