      <div class="pkg-request-amount-row">
        <div>
          <span>Total Paid</span>
          <strong>${escapeHtml(c2cP2PMoney(row.total_paid_amount))}</strong>
        </div>

        <div class="pkg-amount-arrow">→</div>

        <div>
          <span>Balance Amount</span>
          <strong>${escapeHtml(c2cP2PMoney(row.balance_amount))}</strong>
        </div>
