  `;
}


function renderAllRequestsPanel() {
  var statusElement = root.querySelector("#ag-status");
  var filterStatus = statusElement
    ? String(statusElement.value || "").trim()
    : "";

  var keyword = requestSearchInput
    ? String(requestSearchInput.value || "").trim()
    : "";

  var rows = getBranchFilteredC2CRequests()
    .filter(function (row) {
      return c2cP2PMatchesStatusFilter(
        row,
        filterStatus
      );
    })
    .filter(function (row) {
      return c2cP2PDoesRequestMatchSearch(
        row,
        keyword
      );
    });

  var listElement = root.querySelector("#ag-list");
  var detailElement = root.querySelector("#ag-detail");

  if (!listElement) return;

  var preserveExactDetail =
    !!(
      c2cPreserveAllRequestDetail &&
      c2cRoutedAllRequestName &&
      detailElement &&
      detailElement.dataset.docname ===
        c2cRoutedAllRequestName
    );

  if (!rows.length) {
    listElement.innerHTML = `
      <div class="pkg-detail-empty">
        ${
          keyword
            ? "No requests match your search."
            : "No requests found."
        }
      </div>
    `;

    if (requestPagination) {
      requestPagination.innerHTML = "";
    }

    if (
      detailElement &&
      !preserveExactDetail
    ) {
      detailElement.removeAttribute(
        "data-docname"
      );

      detailElement.innerHTML = `
        <div class="pkg-detail-empty">
          No request selected.
        </div>
      `;
    }

    return;
  }

  renderRequestListItems(rows);
}


function c2cRequestDetailRefreshKey(doc) {
  doc = doc || {};

  return [
    String(doc.modified || "").trim(),
    String(doc.approval_stage || "").trim(),
    String(doc.approval_display_status || "").trim(),
    String(doc.conversion_status || "").trim(),
    String(doc.automation_status || "").trim(),
    String(doc.final_approval_status || "").trim(),
    String(doc.centre_manager_decision || "").trim(),
    String(doc.audit_team_decision || "").trim(),
    String(doc.centre_manager_name || "").trim(),
    String(doc.centre_manager_date || "").trim(),
    String(doc.audit_team__corporate_team_name || "").trim(),
    String(doc.audit_team__corporate_team_date || "").trim(),
    String(doc.operations_coo__management_name || "").trim(),
    String(doc.operations_coo__management_date || "").trim(),
    String(doc.custom_centre_manager_action_datetime || "").trim(),
    String(doc.custom_audit_team_action_datetime || "").trim(),
    String(doc.custom_coo_management_action_datetime || "").trim(),
    Number(doc.package_transfer_applied || 0),
    Number(doc.created_transfer_ledger_count || 0)
  ].join("||");
}


function renderRequestListItems(rows) {
  var listElement = root.querySelector("#ag-list");
  var detailElement = root.querySelector("#ag-detail");

  if (!listElement) return;

  rows = rows || [];

  var total = rows.length;
  var totalPages = Math.max(
    1,
    Math.ceil(total / REQUESTS_PER_PAGE)
  );

  if (requestCurrentPage > totalPages) {
    requestCurrentPage = totalPages;
  }

  if (requestCurrentPage < 1) {
    requestCurrentPage = 1;
  }

  var start =
    (requestCurrentPage - 1) *
    REQUESTS_PER_PAGE;

  var pageRows = rows.slice(
    start,
    start + REQUESTS_PER_PAGE
  );

  listElement.innerHTML =
    pageRows.map(function (row) {
      return c2cP2PBuildRequestCard(
        row,
        false,
        ""
      );
    }).join("");

  function selectRequestCard(
    card,
    options
  ) {
    options = options || {};

    if (!card) return;

    listElement
      .querySelectorAll(".cpc-request-card")
      .forEach(function (item) {
        item.classList.remove("active");
        item.classList.remove("sel");
      });

    card.classList.add("active");
    card.classList.add("sel");

    var docname =
      card.dataset.docname || "";

    var row =
      (allRequests || []).find(
        function (item) {
          return item.name === docname;
        }
      );

    var exactDetailAlreadyOpen =
      !!(
        detailElement &&
        detailElement.dataset.docname ===
          docname
      );

    var currentDetailKey =
      detailElement
        ? String(detailElement.dataset.c2cDetailKey || "")
        : "";

    var latestRequestKey =
      c2cRequestDetailRefreshKey(row || {});

    var exactDetailIsFresh =
      exactDetailAlreadyOpen &&
      !!currentDetailKey &&
      currentDetailKey === latestRequestKey;

    /*
     * Do not preserve a stale right-side request detail merely because
     * the same request is selected. COO approval + After Save automation
     * can change status/snapshots while the document remains selected.
     * Re-fetch whenever the lightweight list state no longer matches the
     * detail panel state.
     */
    if (
      !options.keepExistingDetail ||
      !exactDetailIsFresh
    ) {
      renderC2CAllRequestDetail(
        docname,
        row
      );
    }
  }

  listElement
    .querySelectorAll(".cpc-request-card")
    .forEach(function (card) {
      card.addEventListener(
        "click",
        function () {
          var selectedName =
            card.dataset.docname || "";

          c2cRoutedAllRequestName =
            selectedName;

          c2cRoutedAllRequestDoc = null;
          c2cPreserveAllRequestDetail =
            false;

          selectRequestCard(card);
        }
      );
    });

  var preferredName =
    c2cRoutedAllRequestName ||
    (
      detailElement
        ? detailElement.dataset.docname
        : ""
    ) ||
    "";

  var preferredCard = preferredName
    ? listElement.querySelector(
        '.cpc-request-card[data-docname="' +
        cssEscapeC2CValue(preferredName) +
        '"]'
      )
    : null;

  if (preferredCard) {
    selectRequestCard(
      preferredCard,
      {
        keepExistingDetail:
          !!(
            detailElement &&
            detailElement.dataset.docname === preferredName &&
            String(detailElement.dataset.c2cDetailKey || "") ===
              c2cRequestDetailRefreshKey(
                (allRequests || []).find(function (item) {
                  return item.name === preferredName;
                }) || {}
              )
          )
      }
    );
  } else if (!c2cPreserveAllRequestDetail) {
    var firstCard =
      listElement.querySelector(
        ".cpc-request-card"
      );

    if (firstCard) {
      selectRequestCard(firstCard);
    }
  }

  if (!requestPagination) return;

  requestPagination.innerHTML = `
    <div class="pkg-pagination-info">
      Page ${requestCurrentPage} of ${totalPages}
      <span>${total} requests</span>
    </div>

    <div class="pkg-pagination-actions">
      <button
        type="button"
        class="pkg-page-btn"
        id="c2cP2PRequestPrev"
        ${requestCurrentPage <= 1 ? "disabled" : ""}
      >‹ Prev</button>

      <button
        type="button"
        class="pkg-page-btn"
        id="c2cP2PRequestNext"
        ${requestCurrentPage >= totalPages ? "disabled" : ""}
      >Next ›</button>
    </div>
  `;

  var previousButton =
    root.querySelector("#c2cP2PRequestPrev");

  var nextButton =
    root.querySelector("#c2cP2PRequestNext");

  if (previousButton) {
    previousButton.addEventListener(
      "click",
      function () {
        if (requestCurrentPage <= 1) return;

        c2cPreserveAllRequestDetail = false;
        requestCurrentPage--;
        renderRequestListItems(rows);
        listElement.scrollTop = 0;
      }
    );
  }

  if (nextButton) {
    nextButton.addEventListener(
      "click",
      function () {
        if (
          requestCurrentPage >= totalPages
        ) {
          return;
        }

        c2cPreserveAllRequestDetail = false;
        requestCurrentPage++;
        renderRequestListItems(rows);
        listElement.scrollTop = 0;
      }
    );
  }
}

function refreshC2CListItemStatus(doc) {
  if (!doc || !doc.name) return;

  var listElement = root.querySelector("#ag-list");
  if (!listElement) return;

  listElement
    .querySelectorAll(".cpc-request-card")
    .forEach(function (item) {
      if (item.dataset.docname !== doc.name) return;

      item.classList.add("active");
