      var statusPill = item.querySelector(".pkg-status-pill");

      if (statusPill) {
        statusPill.className =
          "pkg-status-pill " +
          c2cP2PStagePillClass(doc);

        statusPill.textContent =
          c2cP2PCompactStatus(doc);
      }
    });
}

