function c2cP2PRenderApprovalPagination(totalRows) {
  var paginationElement = root.querySelector(
    "#c2cApprovalPagination"
  );

  if (!paginationElement) return;

  var totalPages = Math.max(
    1,
    Math.ceil(
      Number(totalRows || 0) /
      C2C_P2P_APPROVAL_PER_PAGE
    )
  );

  if (!totalRows) {
    paginationElement.innerHTML = "";
    return;
  }

  if (c2cP2PApprovalPage > totalPages) {
    c2cP2PApprovalPage = totalPages;
  }

  if (c2cP2PApprovalPage < 1) {
    c2cP2PApprovalPage = 1;
  }

  paginationElement.innerHTML = `
    <div class="pkg-pagination-info">
      Page ${c2cP2PApprovalPage} of ${totalPages}
      <span>${totalRows} pending requests</span>
    </div>

    <div class="pkg-pagination-actions">
      <button
        type="button"
        class="pkg-page-btn"
        id="c2cP2PApprovalPrev"
        ${c2cP2PApprovalPage <= 1 ? "disabled" : ""}
      >‹ Prev</button>

      <button
        type="button"
        class="pkg-page-btn"
        id="c2cP2PApprovalNext"
        ${c2cP2PApprovalPage >= totalPages ? "disabled" : ""}
      >Next ›</button>
    </div>
  `;

  var previousButton = root.querySelector("#c2cP2PApprovalPrev");
  var nextButton = root.querySelector("#c2cP2PApprovalNext");

  if (previousButton) {
    previousButton.addEventListener("click", function () {
      if (c2cP2PApprovalPage <= 1) return;
      c2cP2PApprovalPage--;
      renderApprovalDashboard();

      var listElement = root.querySelector("#approval-list");
      if (listElement) listElement.scrollTop = 0;
    });
  }

  if (nextButton) {
    nextButton.addEventListener("click", function () {
      if (c2cP2PApprovalPage >= totalPages) return;
      c2cP2PApprovalPage++;
      renderApprovalDashboard();

      var listElement = root.querySelector("#approval-list");
      if (listElement) listElement.scrollTop = 0;
    });
  }
}


function renderApprovalDashboard() {
  var roleElement = root.querySelector("#approver-role");
  var role = roleElement
    ? String(
        roleElement.value ||
        "centre_manager"
      )
    : "centre_manager";

  var roleLabels = {
    centre_manager: "Centre Manager",
    audit_team: "Audit Team",
    operations_coo: "COO / Management"
  };

  var roleLabel =
    roleLabels[role] || role;

  /*
   * Approval Dashboard has no branch selector.
   * Audit / COO reviewers must classify every request already returned by
   * ERPNext permissions. Centre Manager remains branch-filtered.
   */
  var branchFilteredRows =
    (role === "audit_team" || role === "operations_coo")
      ? (allRequests || []).slice()
      : getBranchFilteredC2CRequests();

  if (!canC2CViewApprovalRole(role)) {
    if (
      typeof setC2CApprovalBadgeCount ===
      "function"
    ) {
      setC2CApprovalBadgeCount(0);
    }

    c2cPreserveApprovalDetail = false;
    c2cRoutedApprovalDoc = null;

    renderC2CApprovalAccessDenied(role);
    c2cP2PRenderApprovalPagination(0);
    return;
  }

  var allPending =
    branchFilteredRows.filter(
      function (doc) {
        if (!doc || !doc.name) return false;
        if (c2cP2PIsCompleted(doc)) return false;

        if (
          typeof isC2CAutomationFailed ===
            "function" &&
          isC2CAutomationFailed(doc)
        ) {
          return false;
        }

        /*
         * Do not pre-filter on c2cP2PIsRejected().
         * CM rejection is still Audit-pending and Audit rejection is still
         * COO-pending. getPendingRoleForC2CRequest() is the single source
         * of truth for whether this request belongs in the selected queue.
         */
        return (
          getPendingRoleForC2CRequest(doc) ===
          role
        );
      }
    );

  var approvalSearch =
    root.querySelector("#c2cApprovalSearch");

  var keyword = approvalSearch
    ? String(
        approvalSearch.value || ""
      ).trim()
    : "";

  var pendingRows =
    allPending.filter(function (row) {
      return c2cP2PDoesRequestMatchSearch(
        row,
        keyword
      );
    });

  void 0;

  var completedCount =
    branchFilteredRows.filter(
      function (row) {
        return c2cP2PIsCompleted(row);
      }
    ).length;

  var badge = root.querySelector("#nav-cnt");

  if (badge) {
    badge.textContent =
      String(allPending.length);

    badge.style.display =
      allPending.length
        ? "inline-block"
        : "none";
  }

  var tilesElement =
    root.querySelector("#approval-tiles");

  if (tilesElement) {
    tilesElement.innerHTML = `
      <div class="pkg-tile pkg-tile-n">
        <div class="pkg-tile-label">Pending My Approval</div>
        <div class="pkg-tile-val">${allPending.length}</div>
      </div>

      <div class="pkg-tile pkg-tile-g">
        <div class="pkg-tile-label">My SLA</div>
        <div class="pkg-tile-val">24 hrs</div>
      </div>

      <div class="pkg-tile pkg-tile-gr">
        <div class="pkg-tile-label">Process Completed</div>
        <div class="pkg-tile-val">${completedCount}</div>
      </div>
    `;
  }

  var listElement =
    root.querySelector("#approval-list");

  var detailElement =
    root.querySelector(
      "#approval-action-panel"
    );

  if (!listElement) return;

  var preserveExactDetail =
    !!(
      c2cPreserveApprovalDetail &&
      c2cRoutedApprovalName &&
      detailElement &&
      detailElement.dataset.docname ===
        c2cRoutedApprovalName
    );

  if (
    detailElement &&
    !preserveExactDetail
  ) {
    detailElement.removeAttribute(
      "data-docname"
    );

    detailElement.innerHTML = `
      <div class="pkg-detail-empty">
        Select a request to view approval details.
      </div>
    `;
  }

  if (!pendingRows.length) {
    listElement.innerHTML = `
      <div class="pkg-detail-empty">
        ${
          keyword
            ? "No pending approvals match your search."
            : "Nothing pending for " +
              escapeHtml(roleLabel) +
              "."
        }
      </div>
    `;

    c2cP2PRenderApprovalPagination(0);
    return;
  }

  var totalPages = Math.max(
    1,
    Math.ceil(
      pendingRows.length /
      C2C_P2P_APPROVAL_PER_PAGE
    )
  );

  if (
    c2cP2PApprovalPage > totalPages
  ) {
    c2cP2PApprovalPage = totalPages;
  }

  if (c2cP2PApprovalPage < 1) {
    c2cP2PApprovalPage = 1;
  }

  var start =
    (c2cP2PApprovalPage - 1) *
    C2C_P2P_APPROVAL_PER_PAGE;

  var pageRows = pendingRows.slice(
    start,
    start +
      C2C_P2P_APPROVAL_PER_PAGE
  );

  listElement.innerHTML =
    pageRows.map(function (row) {
      return c2cP2PBuildRequestCard(
        row,
        true,
        roleLabel
      );
    }).join("");

  listElement
    .querySelectorAll(
      ".cpc-approval-request-item"
    )
    .forEach(function (item) {
      item.addEventListener(
        "click",
        function () {
          listElement
            .querySelectorAll(
              ".cpc-approval-request-item"
            )
            .forEach(function (otherItem) {
              otherItem.classList.remove(
                "active"
              );

              otherItem.classList.remove(
                "sel"
              );
            });

          item.classList.add("active");
          item.classList.add("sel");

          c2cPreserveApprovalDetail = false;
          c2cRoutedApprovalName =
            item.dataset.docname || "";
          c2cRoutedApprovalDoc = null;

          openC2CApprovalActionPanelByName(
            item.dataset.docname || "",
            role,
            item
          );
        }
      );
    });

  if (c2cRoutedApprovalName) {
    var selectedItem =
      listElement.querySelector(
        '.cpc-approval-request-item' +
        '[data-docname="' +
        cssEscapeC2CValue(
          c2cRoutedApprovalName
        ) +
        '"]'
      );

    if (selectedItem) {
      selectedItem.classList.add("active");
      selectedItem.classList.add("sel");
    }
  }

  c2cP2PRenderApprovalPagination(
    pendingRows.length
  );
}

/* ============================================================
   C2C APPROVAL DETAIL — CURRENT STAGE PENDING DURATION
   Matches the P2P detail-header label, for example:
   "Audit Pending · 3h 2m"
   ============================================================ */
function c2cP2PHasClockTime(value) {
  value = String(value || "").trim();

  return /(?:T|\s)\d{1,2}:\d{2}(?::\d{2})?/.test(value);
}

function c2cP2PFirstValidDate(values) {
  values = values || [];

  for (var i = 0; i < values.length; i++) {
    var dateValue = c2cP2PParseDateTime(values[i]);
    if (dateValue) return dateValue;
  }

  return null;
}

function c2cP2PCurrentPendingStageInfo(row) {
  row = row || {};

  var compactStatus = c2cP2PCompactStatus(row);
  var stage = typeof getC2CApprovalStageValue === "function"
    ? String(getC2CApprovalStageValue(row) || "")
    : String(row.approval_stage || "");

  var statusText = [
    compactStatus,
    stage,
    row.approval_display_status,
    row.conversion_status
  ].filter(Boolean).join(" | ");

  var stageLabel = "";
  var pendingFrom = null;
  var pendingFromText = "";

  if (
    /COO|Management/i.test(statusText) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel = "COO Pending";

    pendingFrom = c2cP2PFirstValidDate([
      row.audit_team_approved_on,
      row.audit_team_approval_datetime,
      row.audit_team__corporate_team_datetime,
      c2cP2PHasClockTime(row.audit_team__corporate_team_date)
        ? row.audit_team__corporate_team_date
        : "",
      row.modified,
      row.creation
    ]);

    pendingFromText = "Pending since Audit Team decision";
  }
  else if (
    /Audit Team|Operations Manager|Operations Head/i.test(statusText) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel = "Audit Pending";

    pendingFrom = c2cP2PFirstValidDate([
      row.centre_manager_approved_on,
      row.centre_manager_approval_datetime,
      row.centre_manager_datetime,
      c2cP2PHasClockTime(row.centre_manager_date)
        ? row.centre_manager_date
        : "",
      row.modified,
      row.creation
    ]);

    pendingFromText = "Pending since Centre Manager decision";
  }
  else if (
    /Centre Manager|Branch Official|CM Pending/i.test(statusText) &&
    /Pending/i.test(statusText)
  ) {
    stageLabel = "CM Pending";

    pendingFrom = c2cP2PFirstValidDate([
      row.creation,
      row.date,
      row.modified
    ]);

    pendingFromText = "Pending since request submission";
  }

  if (!stageLabel || !pendingFrom) {
    return {
      text: compactStatus,
      duration: "",
      title: compactStatus
    };
  }

  var duration = c2cP2PFormatDuration(
    Math.max(Date.now() - pendingFrom.getTime(), 0)
  );

  return {
    text: stageLabel + (duration ? " · " + duration : ""),
    duration: duration,
    title:
      pendingFromText +
      " — " +
      c2cP2PFormatDateTime(pendingFrom)
  };
}

