function bindC2CP2PDashboardEnhancements() {
  var allSearch = root.querySelector("#requestSearchInput");
  var allClear = root.querySelector("#c2cAllRequestsSearchClear");
  var approvalSearch = root.querySelector("#c2cApprovalSearch");
  var approvalClear = root.querySelector("#c2cApprovalSearchClear");
  var approvalRole = root.querySelector("#approver-role");
  var branchFilter = root.querySelector("#requestBranchFilter");
  var refreshRequests = root.querySelector("#refreshRequestsBtn");
  var refreshApproval = root.querySelector("#refreshApprovalBtn");

  function updateClearButton(input, button) {
    if (!button || !input) return;
    button.style.display = input.value ? "inline-flex" : "none";
  }

  if (allSearch && allSearch.dataset.p2pUiBound !== "1") {
    allSearch.dataset.p2pUiBound = "1";

    allSearch.addEventListener("input", function () {
      requestCurrentPage = 1;
      updateClearButton(allSearch, allClear);
    });

    allSearch.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && allSearch.value) {
        allSearch.value = "";
        requestCurrentPage = 1;
        updateClearButton(allSearch, allClear);
        renderAllRequestsPanel();
      }
    });
  }

  if (allClear && allClear.dataset.p2pUiBound !== "1") {
    allClear.dataset.p2pUiBound = "1";

    allClear.addEventListener("click", function () {
      if (!allSearch) return;
      allSearch.value = "";
      requestCurrentPage = 1;
      updateClearButton(allSearch, allClear);
      renderAllRequestsPanel();
      allSearch.focus();
    });
  }

  if (approvalSearch && approvalSearch.dataset.p2pUiBound !== "1") {
    approvalSearch.dataset.p2pUiBound = "1";

    approvalSearch.addEventListener("input", function () {
      c2cP2PApprovalPage = 1;
      updateClearButton(approvalSearch, approvalClear);
      renderApprovalDashboard();
    });

    approvalSearch.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && approvalSearch.value) {
        approvalSearch.value = "";
        c2cP2PApprovalPage = 1;
        updateClearButton(approvalSearch, approvalClear);
        renderApprovalDashboard();
      }
    });
  }

  if (approvalClear && approvalClear.dataset.p2pUiBound !== "1") {
    approvalClear.dataset.p2pUiBound = "1";

    approvalClear.addEventListener("click", function () {
      if (!approvalSearch) return;
      approvalSearch.value = "";
      c2cP2PApprovalPage = 1;
      updateClearButton(approvalSearch, approvalClear);
      renderApprovalDashboard();
      approvalSearch.focus();
    });
  }

  if (approvalRole && approvalRole.dataset.p2pPageBound !== "1") {
    approvalRole.dataset.p2pPageBound = "1";
    approvalRole.addEventListener("change", function () {
      c2cP2PApprovalPage = 1;
    });
  }

  if (branchFilter && branchFilter.dataset.p2pPageBound !== "1") {
    branchFilter.dataset.p2pPageBound = "1";
    branchFilter.addEventListener("change", function () {
      requestCurrentPage = 1;
      c2cP2PApprovalPage = 1;
    });
  }

  if (refreshRequests && refreshRequests.dataset.p2pPageBound !== "1") {
    refreshRequests.dataset.p2pPageBound = "1";
    refreshRequests.addEventListener("click", function () {
      requestCurrentPage = 1;
    });
  }

  if (refreshApproval && refreshApproval.dataset.p2pPageBound !== "1") {
    refreshApproval.dataset.p2pPageBound = "1";
    refreshApproval.addEventListener("click", function () {
      c2cP2PApprovalPage = 1;
    });
  }

  updateClearButton(allSearch, allClear);
  updateClearButton(approvalSearch, approvalClear);
}


// ============================================================
// EMPLOYEE ID -> FULL EMPLOYEE NAME DISPLAY FIX
// Keeps the stored Employee link value (for example HR-EMP-00559)
// unchanged in the document, but replaces visible IDs with Employee.employee_name.
// ============================================================
var c2cEmployeeDisplayNameCache = Object.create(null);
var c2cEmployeeDisplayLookupPending = Object.create(null);
var c2cEmployeeDisplayHydrateTimer = null;
var c2cEmployeeDisplayObserver = null;

function c2cIsEmployeeDocumentId(value) {
  return /^(?:HR-EMP-|EMP-)[A-Z0-9-]+$/i.test(
    String(value || "").trim()
  );
}

function c2cExtractEmployeeIdsFromText(value) {
  var matches = String(value || "").match(
    /\b(?:HR-EMP-|EMP-)[A-Z0-9-]+\b/gi
  ) || [];

  var output = [];
  var seen = Object.create(null);

  matches.forEach(function (employeeId) {
    var key = String(employeeId || "").trim();
    var normalized = key.toUpperCase();

    if (!key || seen[normalized]) return;
    seen[normalized] = true;
    output.push(key);
  });

  return output;
}

function c2cReplaceEmployeeIdsInVisibleText(container) {
  container = container || root;
  if (!container || !document.createTreeWalker) return;

  var walker = document.createTreeWalker(
    container,
    NodeFilter.SHOW_TEXT,
    {
      acceptNode: function (node) {
        if (!node || !node.nodeValue) {
          return NodeFilter.FILTER_REJECT;
        }

        var parent = node.parentElement;
        if (!parent) return NodeFilter.FILTER_REJECT;

        if (
          parent.closest(
            "script, style, textarea, input, select, option, [contenteditable='true']"
          )
        ) {
          return NodeFilter.FILTER_REJECT;
        }

        return /\b(?:HR-EMP-|EMP-)[A-Z0-9-]+\b/i.test(node.nodeValue)
          ? NodeFilter.FILTER_ACCEPT
          : NodeFilter.FILTER_REJECT;
      }
    }
  );

  var textNodes = [];
  var currentNode = null;

  while ((currentNode = walker.nextNode())) {
    textNodes.push(currentNode);
  }

  textNodes.forEach(function (textNode) {
    var originalText = String(textNode.nodeValue || "");
    var replacedText = originalText.replace(
      /\b(?:HR-EMP-|EMP-)[A-Z0-9-]+\b/gi,
      function (employeeId) {
        return c2cEmployeeDisplayNameCache[employeeId] ||
          c2cEmployeeDisplayNameCache[String(employeeId).toUpperCase()] ||
          employeeId;
      }
    );

    if (replacedText !== originalText) {
      textNode.nodeValue = replacedText;
    }
  });
}

function c2cUpdateEmployeeLinkInputDisplay(container) {
  container = container || root;
  if (!container || !container.querySelectorAll) return;

  [
    "centre_manager_name",
    "operations_manager_name"
  ].forEach(function (fieldname) {
    container
      .querySelectorAll('[data-field="' + fieldname + '"]')
      .forEach(function (input) {
        var storedId = String(
          input.dataset.employeeId || input.value || ""
        ).trim();

        if (!c2cIsEmployeeDocumentId(storedId)) return;

        var displayName =
          c2cEmployeeDisplayNameCache[storedId] ||
          c2cEmployeeDisplayNameCache[storedId.toUpperCase()] ||
          "";

        if (!displayName) return;

        input.dataset.employeeId = storedId;
        input.value = displayName;
        input.title = storedId + " — " + displayName;
      });
  });
}

function c2cCollectVisibleEmployeeIds(container) {
  container = container || root;
  var employeeIds = [];
  var seen = Object.create(null);

  function addId(employeeId) {
    employeeId = String(employeeId || "").trim();
    if (!c2cIsEmployeeDocumentId(employeeId)) return;

    var normalized = employeeId.toUpperCase();
    if (seen[normalized]) return;

    seen[normalized] = true;
    employeeIds.push(employeeId);
  }

  if (container && document.createTreeWalker) {
    var walker = document.createTreeWalker(
      container,
      NodeFilter.SHOW_TEXT,
      null
    );

    var node = null;
    while ((node = walker.nextNode())) {
      c2cExtractEmployeeIdsFromText(node.nodeValue).forEach(addId);
    }
  }

  if (container && container.querySelectorAll) {
    [
      "centre_manager_name",
      "operations_manager_name"
    ].forEach(function (fieldname) {
      container
        .querySelectorAll('[data-field="' + fieldname + '"]')
        .forEach(function (input) {
          addId(input.dataset.employeeId || input.value || "");
        });
    });
  }

  return employeeIds;
}

function c2cFetchEmployeeDisplayNames(employeeIds, afterDone) {
  employeeIds = (employeeIds || []).filter(function (employeeId) {
    var normalized = String(employeeId || "").trim().toUpperCase();

    if (!normalized) return false;
    if (c2cEmployeeDisplayNameCache[normalized]) return false;
    if (c2cEmployeeDisplayLookupPending[normalized]) return false;

    c2cEmployeeDisplayLookupPending[normalized] = true;
    return true;
  });

  if (!employeeIds.length) {
    if (typeof afterDone === "function") afterDone();
    return;
  }

  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "Employee",
      fields: [
        "name",
        "employee_name",
        "first_name"
      ],
      filters: [
        ["Employee", "name", "in", employeeIds]
      ],
      limit_page_length: Math.max(employeeIds.length, 20)
    },
    callback: function (response) {
      var found = Object.create(null);

      (response.message || []).forEach(function (employee) {
        var employeeId = String(employee.name || "").trim();
        if (!employeeId) return;

        var displayName = String(
          employee.employee_name ||
          employee.first_name ||
          employee.name ||
          ""
        ).trim();

        var normalized = employeeId.toUpperCase();
        found[normalized] = true;

        c2cEmployeeDisplayNameCache[employeeId] = displayName;
        c2cEmployeeDisplayNameCache[normalized] = displayName;
        delete c2cEmployeeDisplayLookupPending[normalized];
      });

      employeeIds.forEach(function (employeeId) {
        var normalized = String(employeeId || "").trim().toUpperCase();
        if (!found[normalized]) {
          delete c2cEmployeeDisplayLookupPending[normalized];
        }
      });

      if (typeof afterDone === "function") afterDone();
    },
    error: function (error) {
      void 0;

      employeeIds.forEach(function (employeeId) {
        delete c2cEmployeeDisplayLookupPending[
          String(employeeId || "").trim().toUpperCase()
        ];
      });

      if (typeof afterDone === "function") afterDone();
    }
  });
}

function c2cHydrateEmployeeDisplayNames(container) {
  container = container || root;
  if (!container) return;

  var employeeIds = c2cCollectVisibleEmployeeIds(container);

  c2cReplaceEmployeeIdsInVisibleText(container);
  c2cUpdateEmployeeLinkInputDisplay(container);

  c2cFetchEmployeeDisplayNames(employeeIds, function () {
    c2cReplaceEmployeeIdsInVisibleText(container);
    c2cUpdateEmployeeLinkInputDisplay(container);
  });
}

function c2cScheduleEmployeeDisplayHydration(container) {
  clearTimeout(c2cEmployeeDisplayHydrateTimer);

  c2cEmployeeDisplayHydrateTimer = setTimeout(function () {
    c2cHydrateEmployeeDisplayNames(container || root);
  }, 80);
}

function initC2CEmployeeFullNameDisplayFix() {
  if (!root) return;

  c2cScheduleEmployeeDisplayHydration(root);

  if (
    typeof MutationObserver === "undefined" ||
    c2cEmployeeDisplayObserver
  ) {
    return;
  }

  c2cEmployeeDisplayObserver = new MutationObserver(function (mutations) {
    var shouldHydrate = mutations.some(function (mutation) {
      return mutation.type === "childList" || mutation.type === "characterData";
    });

    if (shouldHydrate) {
      c2cScheduleEmployeeDisplayHydration(root);
    }
  });

  c2cEmployeeDisplayObserver.observe(root, {
    childList: true,
    subtree: true,
    characterData: true
  });
}




// ============================================================
// USER ID / EMAIL -> FULL USER NAME IN APPROVAL TIMELINES
// Example: yaswanthkumaryy1234@gmail.com -> Yaswanth
// Stored owner / modified_by values are NOT changed.
// ============================================================
var c2cUserDisplayNameCache = Object.create(null);
var c2cUserDisplayLookupPending = Object.create(null);
var c2cUserDisplayHydrateTimer = null;
var c2cUserDisplayObserver = null;

function c2cIsUserDocumentId(value) {
  value = String(value || "").trim();
  if (!value) return false;

  return value === "Administrator" ||
    value === "Guest" ||
    /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value);
}

function c2cGetBootUserDisplayName(userId) {
  userId = String(userId || "").trim();
  if (!userId) return "";

  var normalized = userId.toLowerCase();

  try {
    if (
      typeof frappe !== "undefined" &&
      frappe.session &&
      String(frappe.session.user || "").toLowerCase() === normalized
    ) {
      var currentUser = (frappe.boot && frappe.boot.user) || {};
      var currentName = String(
        currentUser.full_name ||
        currentUser.fullname ||
        currentUser.first_name ||
        ""
      ).trim();

      if (currentName) {
        c2cUserDisplayNameCache[userId] = currentName;
        c2cUserDisplayNameCache[normalized] = currentName;
        return currentName;
      }
    }

    var userInfoMap = frappe.boot && frappe.boot.user_info;
    var info = userInfoMap && (userInfoMap[userId] || userInfoMap[normalized]);

    if (info) {
      var mappedName = String(
        info.fullname ||
        info.full_name ||
        info.first_name ||
        ""
      ).trim();

      if (mappedName) {
        c2cUserDisplayNameCache[userId] = mappedName;
        c2cUserDisplayNameCache[normalized] = mappedName;
        return mappedName;
      }
    }
  } catch (e) {}

  return "";
}

function c2cReplaceTimelineUserIds(container) {
  container = container || root;
  if (!container || !container.querySelectorAll) return;

  /* P2P-style timeline footer: exact person value lives in this span. */
  container.querySelectorAll(".pkg-timeline-person").forEach(function (personEl) {
    var originalUserId = String(
      personEl.dataset.c2cUserId || personEl.textContent || ""
    ).trim();

    if (!c2cIsUserDocumentId(originalUserId)) return;

    personEl.dataset.c2cUserId = originalUserId;

    var displayName =
      c2cUserDisplayNameCache[originalUserId] ||
      c2cUserDisplayNameCache[originalUserId.toLowerCase()] ||
      c2cGetBootUserDisplayName(originalUserId) ||
      "";

    if (!displayName) return;

    personEl.textContent = displayName;
    personEl.title = originalUserId + " — " + displayName;
  });

  /*
   * Generic user-name placeholders outside the timeline.
   * Used by Approval Override / final-table history metadata so stored
   * ERPNext User IDs (emails) are rendered as User.full_name as well.
   */
  container.querySelectorAll(".c2c-user-display-name").forEach(function (personEl) {
    var originalUserId = String(
      personEl.dataset.c2cUserId || personEl.textContent || ""
    ).trim();

    if (!c2cIsUserDocumentId(originalUserId)) return;

    personEl.dataset.c2cUserId = originalUserId;

    var displayName =
      c2cUserDisplayNameCache[originalUserId] ||
      c2cUserDisplayNameCache[originalUserId.toLowerCase()] ||
      c2cGetBootUserDisplayName(originalUserId) ||
      "";

    if (!displayName) return;

    personEl.textContent = displayName;
    personEl.title = originalUserId + " — " + displayName;
  });

  /* Legacy C2C timeline uses one combined meta line. */
  container.querySelectorAll(".cpc-timeline-meta").forEach(function (metaEl) {
    var text = String(metaEl.textContent || "");
    if (!text) return;

    var replaced = text.replace(
      /(?:Administrator|Guest|[^\s·]+@[^\s·]+\.[^\s·]+)/g,
      function (userId) {
        userId = String(userId || "").trim();
        var displayName =
          c2cUserDisplayNameCache[userId] ||
          c2cUserDisplayNameCache[userId.toLowerCase()] ||
          c2cGetBootUserDisplayName(userId) ||
          "";

        return displayName || userId;
      }
    );

    if (replaced !== text) metaEl.textContent = replaced;
  });
}

function c2cCollectTimelineUserIds(container) {
  container = container || root;
  var ids = [];
  var seen = Object.create(null);

  function add(userId) {
    userId = String(userId || "").trim();
    if (!c2cIsUserDocumentId(userId)) return;

    var normalized = userId.toLowerCase();
    if (seen[normalized]) return;
    seen[normalized] = true;
    ids.push(userId);
  }

  if (!container || !container.querySelectorAll) return ids;

  container.querySelectorAll(".pkg-timeline-person").forEach(function (personEl) {
    add(personEl.dataset.c2cUserId || personEl.textContent || "");
  });

  container.querySelectorAll(".c2c-user-display-name").forEach(function (personEl) {
    add(personEl.dataset.c2cUserId || personEl.textContent || "");
  });

  container.querySelectorAll(".cpc-timeline-meta").forEach(function (metaEl) {
    var text = String(metaEl.textContent || "");
    var matches = text.match(/(?:Administrator|Guest|[^\s·]+@[^\s·]+\.[^\s·]+)/g) || [];
    matches.forEach(add);
  });

  return ids;
}

function c2cFetchUserDisplayNames(userIds, afterDone) {
  userIds = (userIds || []).filter(function (userId) {
    userId = String(userId || "").trim();
    if (!userId) return false;

    var normalized = userId.toLowerCase();

    if (c2cGetBootUserDisplayName(userId)) return false;
    if (c2cUserDisplayNameCache[normalized]) return false;
    if (c2cUserDisplayLookupPending[normalized]) return false;

    c2cUserDisplayLookupPending[normalized] = true;
    return true;
  });

  if (!userIds.length) {
    if (typeof afterDone === "function") afterDone();
    return;
  }

  function clearPending() {
    userIds.forEach(function (userId) {
      delete c2cUserDisplayLookupPending[String(userId || "").toLowerCase()];
    });
  }

  function finish() {
    clearPending();
    if (typeof afterDone === "function") afterDone();
  }

  /* Preferred source: User.full_name */
  frappe.call({
    method: "frappe.client.get_list",
    args: {
      doctype: "User",
      fields: ["name", "full_name", "first_name"],
      filters: [["User", "name", "in", userIds]],
      limit_page_length: Math.max(userIds.length, 20)
    },
    callback: function (response) {
      var resolved = Object.create(null);

      (response.message || []).forEach(function (user) {
        var userId = String(user.name || "").trim();
        if (!userId) return;

        var displayName = String(
          user.full_name || user.first_name || user.name || ""
        ).trim();

        if (!displayName) return;

        var normalized = userId.toLowerCase();
        resolved[normalized] = true;
        c2cUserDisplayNameCache[userId] = displayName;
        c2cUserDisplayNameCache[normalized] = displayName;
      });

      var unresolved = userIds.filter(function (userId) {
        return !resolved[String(userId || "").toLowerCase()];
      });

      if (!unresolved.length) {
        finish();
        return;
      }

      /* Fallback for sites where User names are restricted: Employee.user_id. */
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Employee",
          fields: ["user_id", "employee_name", "first_name"],
          filters: [["Employee", "user_id", "in", unresolved]],
          limit_page_length: Math.max(unresolved.length, 20)
        },
        callback: function (employeeResponse) {
          (employeeResponse.message || []).forEach(function (employee) {
            var userId = String(employee.user_id || "").trim();
            if (!userId) return;

            var displayName = String(
              employee.employee_name || employee.first_name || userId
            ).trim();

            c2cUserDisplayNameCache[userId] = displayName;
            c2cUserDisplayNameCache[userId.toLowerCase()] = displayName;
          });

          finish();
        },
        error: finish
      });
    },
    error: function () {
      /* If User listing is blocked, try Employee directly. */
      frappe.call({
        method: "frappe.client.get_list",
        args: {
          doctype: "Employee",
          fields: ["user_id", "employee_name", "first_name"],
          filters: [["Employee", "user_id", "in", userIds]],
          limit_page_length: Math.max(userIds.length, 20)
        },
        callback: function (response) {
          (response.message || []).forEach(function (employee) {
            var userId = String(employee.user_id || "").trim();
            if (!userId) return;

            var displayName = String(
              employee.employee_name || employee.first_name || userId
            ).trim();

            c2cUserDisplayNameCache[userId] = displayName;
            c2cUserDisplayNameCache[userId.toLowerCase()] = displayName;
          });

          finish();
        },
        error: finish
      });
    }
  });
}

function c2cHydrateTimelineUserNames(container) {
  container = container || root;
  if (!container) return;

  c2cReplaceTimelineUserIds(container);

  var userIds = c2cCollectTimelineUserIds(container);

  c2cFetchUserDisplayNames(userIds, function () {
    c2cReplaceTimelineUserIds(container);
  });
}

function c2cScheduleTimelineUserNameHydration(container) {
  clearTimeout(c2cUserDisplayHydrateTimer);

  c2cUserDisplayHydrateTimer = setTimeout(function () {
    c2cHydrateTimelineUserNames(container || root);
  }, 60);
}

function initC2CTimelineUserFullNameDisplayFix() {
  if (!root) return;

  /* Seed current logged-in user immediately from boot whenever available. */
  try {
    if (frappe.session && frappe.session.user) {
      c2cGetBootUserDisplayName(frappe.session.user);
    }
  } catch (e) {}

  c2cScheduleTimelineUserNameHydration(root);

  if (
    typeof MutationObserver === "undefined" ||
    c2cUserDisplayObserver
  ) {
    return;
  }

  c2cUserDisplayObserver = new MutationObserver(function (mutations) {
    var shouldHydrate = mutations.some(function (mutation) {
      return mutation.type === "childList" || mutation.type === "characterData";
    });

    if (shouldHydrate) {
      c2cScheduleTimelineUserNameHydration(root);
    }
  });

  c2cUserDisplayObserver.observe(root, {
    childList: true,
    subtree: true,
    characterData: true
  });
}

/* ============================================================
   C2C DASHBOARD — MAXIMUM VIEWPORT HEIGHT + FIXED PAGINATION
   Keeps pagination visible while only the request/detail bodies scroll.
   ============================================================ */
var c2cDashboardHeightRaf = 0;
var c2cDashboardHeightResizeBound = false;
var c2cDashboardHeightObserver = null;

function syncC2CDashboardViewportHeights() {
  if (!root) return;

  if (c2cDashboardHeightRaf) {
    cancelAnimationFrame(c2cDashboardHeightRaf);
  }

  c2cDashboardHeightRaf = requestAnimationFrame(function () {
    c2cDashboardHeightRaf = 0;

    [
      { panel: "#mode-1", layout: ".cpc-p2p-all-layout" },
      { panel: "#mode-2", layout: ".cpc-p2p-approval-layout" }
    ].forEach(function (config) {
      var panel = root.querySelector(config.panel);
      if (!panel) return;

      var layout = panel.querySelector(config.layout);
      if (!layout) return;

      var panelStyle = window.getComputedStyle(panel);
      if (panelStyle.display === "none") return;

      var rect = layout.getBoundingClientRect();
      if (!rect || !Number.isFinite(rect.top)) return;

      /* Keep a small bottom breathing space above the browser edge. */
      var bottomGap = 18;
      var available = Math.floor(window.innerHeight - rect.top - bottomGap);

      /* On smaller screens retain a usable panel and allow page scrolling. */
      var resolvedHeight = Math.max(460, available);

      panel.style.setProperty(
        "--cpc-dashboard-height",
        resolvedHeight + "px"
      );
    });
  });
}

function scheduleC2CDashboardViewportHeights() {
  setTimeout(syncC2CDashboardViewportHeights, 0);
  setTimeout(syncC2CDashboardViewportHeights, 120);
}

function initC2CDashboardViewportHeightFix() {
  scheduleC2CDashboardViewportHeights();

  if (!c2cDashboardHeightResizeBound) {
    c2cDashboardHeightResizeBound = true;

    window.addEventListener(
      "resize",
      scheduleC2CDashboardViewportHeights
    );

    window.addEventListener(
      "orientationchange",
      scheduleC2CDashboardViewportHeights
    );

    root.addEventListener("click", function (event) {
      var tab = event.target.closest(".mnav, .pkg-tab, [data-tab]");
      if (tab) scheduleC2CDashboardViewportHeights();
    });
  }

  if (
    typeof ResizeObserver !== "undefined" &&
    !c2cDashboardHeightObserver
  ) {
    c2cDashboardHeightObserver = new ResizeObserver(function () {
      syncC2CDashboardViewportHeights();
    });

    var filterBars = root.querySelectorAll(
      "#mode-1 .cpc-p2p-fbar, #mode-2 .cpc-p2p-fbar, #approval-tiles"
    );

    filterBars.forEach(function (element) {
      c2cDashboardHeightObserver.observe(element);
    });
  }
}


/* ============================================================
   LIFE APPROVALS REPORT — RETURN AFTER APPROVAL
   Supports links opened with:
   ?tab=approval&role=...&request=...&return_to=/approvals-report-test
   ============================================================ */
function lifeC2CReturnToApprovalsReport(docname, action, role) {
  var returnTo = getC2CUrlParam("return_to");
  if (!returnTo) return;

  var targetUrl = null;
  try {
    targetUrl = new URL(returnTo, window.location.origin);
    if (targetUrl.origin !== window.location.origin) return;
  } catch (e) {
    return;
  }

  window.setTimeout(function () {
    var payload = {
      type: "LIFE_APPROVAL_RESULT",
      module: "C2C",
      request: String(docname || ""),
      action: String(action || ""),
      role: String(role || "")
    };

    try {
      if (window.opener && !window.opener.closed) {
        window.opener.postMessage(payload, window.location.origin);
        window.opener.focus();
        window.close();
        if (window.closed) return;
      }
    } catch (e) {
      void 0;
    }

    window.location.href = targetUrl.href;
  }, 700);
}

